settings_t g_settings = { ANGLE_RADIANS, true, 6, COMPLEX_OFF, false, STEP_ALL,
                          SOLVE_FULL_AUTO, METHOD_AUTO };
ce_float_t g_last_answer = 0;

static int g_failures = 0;
static unsigned long g_assertions = 0;

#define ASSERT_TRUE(cond, msg)                                                     \
    do {                                                                           \
        g_assertions++;                                                            \
        if (!(cond)) {                                                             \
            printf("[FAIL] %s\n", (msg));                                          \
            g_failures++;                                                          \
        }                                                                          \
    } while (0)

#define ASSERT_EQ_INT(expected, actual, msg)                                       \
    do {                                                                           \
        int exp__ = (int)(expected);                                               \
        int act__ = (int)(actual);                                                 \
        g_assertions++;                                                            \
        if (exp__ != act__) {                                                      \
            printf("[FAIL] %s (expected=%d actual=%d)\n", (msg), exp__, act__);   \
            g_failures++;                                                          \
        }                                                                          \
    } while (0)

#define ASSERT_EQ_U32(expected, actual, msg)                                       \
    do {                                                                           \
        unsigned long exp__ = (unsigned long)(expected);                           \
        unsigned long act__ = (unsigned long)(actual);                             \
        g_assertions++;                                                            \
        if (exp__ != act__) {                                                      \
            printf("[FAIL] %s (expected=%lu actual=%lu)\n",                        \
                   (msg), exp__, act__);                                           \
            g_failures++;                                                          \
        }                                                                          \
    } while (0)

#define FLAG_S 0x80u
#define FLAG_Z 0x40u
#define FLAG_H 0x10u
#define FLAG_PV 0x04u
#define FLAG_N 0x02u
#define FLAG_C 0x01u

static uint8_t cpu_reg_a(const ez80_cpu_state_t *cpu)
{
    return (uint8_t)((cpu->af >> 8) & 0xFFu);
}

static uint8_t cpu_reg_f(const ez80_cpu_state_t *cpu)
{
    return (uint8_t)(cpu->af & 0xFFu);
}

static uint16_t cpu_reg_pair16(uint32_t reg)
{
    return (uint16_t)(reg & 0xFFFFu);
}

static void cpu_set_reg_a(ez80_cpu_state_t *cpu, uint8_t value)
{
    cpu->af = (cpu->af & ~((uint32_t)0x0000FF00u)) | ((uint32_t)value << 8);
}

static void cpu_set_reg_b(ez80_cpu_state_t *cpu, uint8_t value)
{
    cpu->bc = (cpu->bc & ~((uint32_t)0x0000FF00u)) | ((uint32_t)value << 8);
}

static void cpu_set_reg_f(ez80_cpu_state_t *cpu, uint8_t value)
{
    cpu->af = (cpu->af & ~((uint32_t)0x000000FFu)) | (uint32_t)value;
}

static uint8_t test_cpu_get_reg8(const ez80_cpu_state_t *cpu, uint8_t reg)
{
    switch (reg & 0x07u) {
    case 0u: return (uint8_t)((cpu->bc >> 8) & 0xFFu);
    case 1u: return (uint8_t)(cpu->bc & 0xFFu);
    case 2u: return (uint8_t)((cpu->de >> 8) & 0xFFu);
    case 3u: return (uint8_t)(cpu->de & 0xFFu);
    case 4u: return (uint8_t)((cpu->hl >> 8) & 0xFFu);
    case 5u: return (uint8_t)(cpu->hl & 0xFFu);
    default: return cpu_reg_a(cpu);
    }
}

static void test_cpu_set_reg8(ez80_cpu_state_t *cpu, uint8_t reg, uint8_t value)
{
    switch (reg & 0x07u) {
    case 0u:
        cpu->bc = (cpu->bc & ~((uint32_t)0x0000FF00u)) | ((uint32_t)value << 8);
        break;
    case 1u:
        cpu->bc = (cpu->bc & ~((uint32_t)0x000000FFu)) | (uint32_t)value;
        break;
    case 2u:
        cpu->de = (cpu->de & ~((uint32_t)0x0000FF00u)) | ((uint32_t)value << 8);
        break;
    case 3u:
        cpu->de = (cpu->de & ~((uint32_t)0x000000FFu)) | (uint32_t)value;
        break;
    case 4u:
        cpu->hl = (cpu->hl & ~((uint32_t)0x0000FF00u)) | ((uint32_t)value << 8);
        break;
    case 5u:
        cpu->hl = (cpu->hl & ~((uint32_t)0x000000FFu)) | (uint32_t)value;
        break;
    default:
        cpu_set_reg_a(cpu, value);
        break;
    }
}

static int parity_even8(uint8_t value)
{
    value ^= (uint8_t)(value >> 4);
    value ^= (uint8_t)(value >> 2);
    value ^= (uint8_t)(value >> 1);
    return ((value & 0x01u) == 0u) ? 1 : 0;
}

static uint8_t reverse_bits8_test(uint8_t value)
{
    value = (uint8_t)(((value & 0xF0u) >> 4) | ((value & 0x0Fu) << 4));
    value = (uint8_t)(((value & 0xCCu) >> 2) | ((value & 0x33u) << 2));
    value = (uint8_t)(((value & 0xAAu) >> 1) | ((value & 0x55u) << 1));
    return value;
}

static uint8_t expected_flags_add8(uint8_t lhs, uint8_t rhs, uint8_t carry_in, uint8_t result)
{
    uint16_t wide = (uint16_t)lhs + (uint16_t)rhs + (uint16_t)carry_in;
    uint8_t flags = 0u;
    if ((result & 0x80u) != 0u) flags |= FLAG_S;
    if (result == 0u) flags |= FLAG_Z;
    if (((lhs & 0x0Fu) + (rhs & 0x0Fu) + carry_in) > 0x0Fu) flags |= FLAG_H;
    if (((~(lhs ^ rhs)) & (lhs ^ result) & 0x80u) != 0u) flags |= FLAG_PV;
    if (wide > 0xFFu) flags |= FLAG_C;
    return flags;
}

static uint8_t expected_flags_sub8(uint8_t lhs, uint8_t rhs, uint8_t carry_in, uint8_t result)
{
    uint16_t rhs_total = (uint16_t)rhs + (uint16_t)carry_in;
    uint8_t rhs_effective = (uint8_t)rhs_total;
    uint8_t flags = FLAG_N;
    if ((result & 0x80u) != 0u) flags |= FLAG_S;
    if (result == 0u) flags |= FLAG_Z;
    if ((uint8_t)(lhs & 0x0Fu) < (uint8_t)((rhs & 0x0Fu) + carry_in)) flags |= FLAG_H;
    if (((lhs ^ rhs_effective) & (lhs ^ result) & 0x80u) != 0u) flags |= FLAG_PV;
    if ((uint16_t)lhs < rhs_total) flags |= FLAG_C;
    return flags;
}

static uint8_t expected_flags_logic8(uint8_t result, int set_h)
{
    uint8_t flags = 0u;
    if ((result & 0x80u) != 0u) flags |= FLAG_S;
    if (result == 0u) flags |= FLAG_Z;
    if (set_h) flags |= FLAG_H;
    if (parity_even8(result)) flags |= FLAG_PV;
    return flags;
}

static uint8_t expected_flags_block_compare(uint8_t lhs,
                                            uint8_t rhs,
                                            uint16_t bc_after,
                                            uint8_t carry_in)
{
    uint8_t result = (uint8_t)(lhs - rhs);
    uint8_t flags = (carry_in != 0u) ? FLAG_C : 0u;
    flags |= FLAG_N;
    if ((result & 0x80u) != 0u) flags |= FLAG_S;
    if (result == 0u) flags |= FLAG_Z;
    if (((lhs ^ rhs ^ result) & 0x10u) != 0u) flags |= FLAG_H;
    if (bc_after != 0u) flags |= FLAG_PV;
    return flags;
}

static void assert_case_u8(const char *group,
                           size_t case_index,
                           const char *field,
                           uint8_t expected,
                           uint8_t actual)
{
    g_assertions++;
    if (expected != actual) {
        printf("[FAIL] %s case %lu %s (expected=0x%02X actual=0x%02X)\n",
               group,
               (unsigned long)case_index,
               field,
               (unsigned)expected,
               (unsigned)actual);
        g_failures++;
    }
}

static void assert_case_status(const char *group,
                               size_t case_index,
                               const char *field,
                               ez80_status_t expected,
                               ez80_status_t actual)
{
    g_assertions++;
    if (expected != actual) {
        printf("[FAIL] %s case %lu %s (expected=%d actual=%d)\n",
               group,
               (unsigned long)case_index,
               field,
               (int)expected,
               (int)actual);
        g_failures++;
    }
}

static uint32_t flash_sector_sample_addr(uint8_t sector, uint16_t offset)
{
    return ((uint32_t)sector * EZ80_FLASH_SECTOR_BYTES) + (uint32_t)offset;
}

static uint8_t flash_sector_pattern_value(uint8_t sector, size_t sample_index)
{
    uint32_t value = (((uint32_t)sector + 1u) * 17u) + (((uint32_t)sample_index + 3u) * 29u);
    return (uint8_t)((value % 0xFEu) + 1u);
}

static void assert_flash_byte_case(ez80_emulator_t *emu,
                                   const char *group,
                                   size_t case_index,
                                   uint32_t addr,
                                   uint8_t expected)
{
    uint8_t actual = 0u;
    ez80_status_t status = ez80_memory_read8(emu, addr, &actual);

    assert_case_status(group, case_index, "status", EZ80_OK, status);
    if (status == EZ80_OK) {
        assert_case_u8(group, case_index, "value", expected, actual);
    }
}

static ez80_status_t trigger_flash_erase_sector(ez80_emulator_t *emu,
                                                uint8_t sector,
                                                bool via_mmio)
{
    if (!via_mmio) {
        return ez80_emulator_flash_erase_sector(emu, sector);
    }
    return ez80_memory_write8(emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_SECTOR, sector);
}

static int create_temp_path(char *out_path, size_t cap)
{
    if (!out_path || cap < 8u) return 0;
#ifdef _MSC_VER
    return tmpnam_s(out_path, cap) == 0 ? 1 : 0;
#else
    {
        char *tmp = tmpnam(NULL);
        if (!tmp) return 0;
        strncpy(out_path, tmp, cap - 1u);
        out_path[cap - 1u] = '\0';
        return 1;
    }
#endif
}

static int write_temp_file(const uint8_t *bytes, size_t size, char *out_path, size_t cap)
{
    FILE *f;
    if (!bytes || !out_path) return 0;
    if (!create_temp_path(out_path, cap)) return 0;
    f = fopen(out_path, "wb");
    if (!f) return 0;
    if (size > 0u) {
        if (fwrite(bytes, 1u, size, f) != size) {
            fclose(f);
            remove(out_path);
            return 0;
        }
    }
    fclose(f);
    return 1;
}

static int write_temp_sparse_rom(const uint32_t *offsets,
                                 const uint8_t *values,
                                 size_t count,
                                 char *out_path,
                                 size_t cap)
{
    FILE *f;
    size_t i;

    if (!offsets || !values || !out_path) return 0;
    if (!create_temp_path(out_path, cap)) return 0;

    f = fopen(out_path, "wb");
    if (!f) return 0;

    if (fseek(f, (long)(EZ80_FLASH_TOTAL_BYTES - 1u), SEEK_SET) != 0) {
        fclose(f);
        remove(out_path);
        return 0;
    }
    if (fputc(0, f) == EOF) {
        fclose(f);
        remove(out_path);
        return 0;
    }

    for (i = 0u; i < count; i++) {
        if (offsets[i] >= EZ80_FLASH_TOTAL_BYTES) {
            fclose(f);
            remove(out_path);
            return 0;
        }
        if (fseek(f, (long)offsets[i], SEEK_SET) != 0) {
            fclose(f);
            remove(out_path);
            return 0;
        }
        if (fputc(values[i], f) == EOF) {
            fclose(f);
            remove(out_path);
            return 0;
        }
    }

    fclose(f);
    return 1;
}

static void inject_artifice_key_sequence(ez80_emulator_t *emu)
{
    ez80_status_t status;
    const uint8_t seq[] = {
        0x41u, /* 'A' */
        0x52u, /* 'R' */
        0x54u, /* 'T' */
        0x49u  /* 'I' */
    };
    size_t i;

    for (i = 0u; i < sizeof(seq); i++) {
        status = ez80_emulator_inject_key(emu, seq[i]);
        ASSERT_EQ_INT(EZ80_OK, status, "inject arTIfiCE key sequence byte");
    }
}

static ez80_status_t write_name_to_memory(ez80_emulator_t *emu, uint32_t addr, const char *name)
{
    size_t i;
    size_t len;
    ez80_status_t status;

    if (!emu || !name) return EZ80_ERR_INVALID_ARG;
    len = strlen(name);
    if (len == 0u || len > EZ80_OS_VAR_NAME_MAX) return EZ80_ERR_INVALID_ARG;
    for (i = 0u; i < len; i++) {
        status = ez80_memory_write8(emu, addr + (uint32_t)i, (uint8_t)name[i]);
        if (status != EZ80_OK) return status;
    }
    status = ez80_memory_write8(emu, addr + (uint32_t)len, 0u);
    return status;
}

static ez80_status_t write_bytes_to_memory(ez80_emulator_t *emu,
                                           uint32_t addr,
                                           const uint8_t *bytes,
                                           size_t size)
{
    size_t i;
    ez80_status_t status;

    if (!emu || (!bytes && size > 0u)) return EZ80_ERR_INVALID_ARG;

    for (i = 0u; i < size; i++) {
        status = ez80_memory_write8(emu, addr + (uint32_t)i, bytes[i]);
        if (status != EZ80_OK) return status;
    }

    return EZ80_OK;
}

static ez80_status_t read_bytes_from_memory(ez80_emulator_t *emu,
                                            uint32_t addr,
                                            uint8_t *bytes,
                                            size_t size)
{
    size_t i;
    ez80_status_t status;

    if (!emu || (!bytes && size > 0u)) return EZ80_ERR_INVALID_ARG;

    for (i = 0u; i < size; i++) {
        status = ez80_memory_read8(emu, addr + (uint32_t)i, &bytes[i]);
        if (status != EZ80_OK) return status;
    }

    return EZ80_OK;
}

static uint32_t read_mmio_u24(const ez80_emulator_t *emu, uint16_t offset)
{
    uint32_t b0;
    uint32_t b1;
    uint32_t b2;
    if (!emu || offset + 2u >= EZ80_MMIO_BYTES) return 0u;
    b0 = emu->memory.mmio[offset + 0u];
    b1 = emu->memory.mmio[offset + 1u];
    b2 = emu->memory.mmio[offset + 2u];
    return b0 | (b1 << 8) | (b2 << 16);
}

static uint32_t read_mmio_u32(const ez80_emulator_t *emu, uint16_t offset)
{
    uint32_t b0;
    uint32_t b1;
    uint32_t b2;
    uint32_t b3;
    if (!emu || offset + 3u >= EZ80_MMIO_BYTES) return 0u;
    b0 = emu->memory.mmio[offset + 0u];
    b1 = emu->memory.mmio[offset + 1u];
    b2 = emu->memory.mmio[offset + 2u];
    b3 = emu->memory.mmio[offset + 3u];
    return b0 | (b1 << 8) | (b2 << 16) | (b3 << 24);
}

static void read_active_program_name_mmio(const ez80_emulator_t *emu, char *out, size_t cap)
{
    size_t i;

    if (!out || cap == 0u) return;
    out[0] = '\0';
    if (!emu) return;

    for (i = 0u; i + 1u < cap && i <= EZ80_OS_VAR_NAME_MAX; i++) {
        out[i] = (char)emu->memory.mmio[EZ80_MMIO_REG_OS_ACTIVE_PROGRAM_NAME_0 + (uint16_t)i];
        if (out[i] == '\0') break;
    }
    out[(i + 1u < cap) ? i : (cap - 1u)] = '\0';
}

static ez80_status_t write_mmio_u24(ez80_emulator_t *emu, uint16_t offset, uint32_t value)
{
    ez80_status_t status;

    status = ez80_memory_write8(emu,
                                EZ80_MMIO_BASE + offset + 0u,
                                (uint8_t)(value & 0xFFu));
    if (status != EZ80_OK) return status;
    status = ez80_memory_write8(emu,
                                EZ80_MMIO_BASE + offset + 1u,
                                (uint8_t)((value >> 8) & 0xFFu));
    if (status != EZ80_OK) return status;
    return ez80_memory_write8(emu,
                              EZ80_MMIO_BASE + offset + 2u,
                              (uint8_t)((value >> 16) & 0xFFu));
}

static uint32_t test_crc32(const uint8_t *data, size_t size)
{
    uint32_t crc = 0xFFFFFFFFu;
    size_t i;
    uint8_t bit;
    if (!data) return 0u;
    for (i = 0u; i < size; i++) {
        crc ^= (uint32_t)data[i];
        for (bit = 0u; bit < 8u; bit++) {
            if ((crc & 1u) != 0u) {
                crc = (crc >> 1) ^ 0xEDB88320u;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc ^ 0xFFFFFFFFu;
}

static ez80_status_t write_lcd_color(ez80_emulator_t *emu, uint16_t color)
{
    ez80_status_t status;
    status = ez80_memory_write8(emu,
                                EZ80_PORT_BASE + EZ80_PORT_LCD_DATA,
                                (uint8_t)(color & 0x00FFu));
    if (status != EZ80_OK) {
        return status;
    }
    status = ez80_memory_write8(emu,
                                EZ80_PORT_BASE + EZ80_PORT_LCD_DATA,
                                (uint8_t)((color >> 8) & 0x00FFu));
    return status;
}

typedef struct {
    uint32_t read_count;
    uint32_t write_count;
    uint16_t last_read_port;
    uint16_t last_write_port;
    uint8_t read_value;
    uint8_t last_written_value;
} test_port_probe_t;

static ez80_status_t test_port_probe_read(ez80_emulator_t *emu,
                                          uint16_t port,
                                          uint8_t *out_value,
                                          void *user_data)
{
    test_port_probe_t *probe = (test_port_probe_t *)user_data;
    (void)emu;
    if (!probe || !out_value) return EZ80_ERR_INVALID_ARG;
    probe->read_count++;
    probe->last_read_port = port;
    *out_value = probe->read_value;
    return EZ80_OK;
}

static ez80_status_t test_port_probe_write(ez80_emulator_t *emu,
                                           uint16_t port,
                                           uint8_t value,
                                           void *user_data)
{
    test_port_probe_t *probe = (test_port_probe_t *)user_data;
    (void)emu;
    if (!probe) return EZ80_ERR_INVALID_ARG;
    probe->write_count++;
    probe->last_write_port = port;
    probe->last_written_value = value;
    return EZ80_OK;
}

static void test_decode_known_opcodes(void)
{
    ez80_instruction_t decoded;
    ez80_status_t status;
    uint8_t nop_stream[1] = { 0x00 };
    uint8_t halt_stream[1] = { 0x76 };
    uint8_t ld_stream[2] = { 0x3E, 0x2A };
    uint8_t inc_stream[1] = { 0x3C };
    uint8_t dec_stream[1] = { 0x3D };
    uint8_t xor_stream[1] = { 0xAF };
    uint8_t add_stream[2] = { 0xC6, 0x10 };
    uint8_t jr_stream[2] = { 0x18, 0x02 };
    uint8_t jp_stream[3] = { 0xC3, 0x34, 0x12 };
    uint8_t short_ld_stream[1] = { 0x3E };
    uint8_t short_add_stream[1] = { 0xC6 };
    uint8_t short_jr_stream[1] = { 0x18 };

    printf("[TEST] decode known opcode stubs\n");

    status = ez80_decode_instruction(nop_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode NOP status");
    ASSERT_EQ_INT(1, decoded.length, "decode NOP length");
    ASSERT_EQ_INT(4, decoded.cycles, "decode NOP cycles");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "NOP") == 0, "decode NOP mnemonic");

    status = ez80_decode_instruction(halt_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode HALT status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "HALT") == 0, "decode HALT mnemonic");

    status = ez80_decode_instruction(ld_stream, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD A,n status");
    ASSERT_EQ_INT(2, decoded.length, "decode LD A,n length");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LD") == 0, "decode LD mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A,0x2A") == 0, "decode LD operands");

    status = ez80_decode_instruction(inc_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode INC A status");
    ASSERT_EQ_INT(1, decoded.length, "decode INC A length");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "INC") == 0, "decode INC A mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A") == 0, "decode INC A operands");

    status = ez80_decode_instruction(dec_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode DEC A status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "DEC") == 0, "decode DEC A mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A") == 0, "decode DEC A operands");

    status = ez80_decode_instruction(xor_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode XOR A status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "XOR") == 0, "decode XOR A mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A") == 0, "decode XOR A operands");

    status = ez80_decode_instruction(add_stream, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode ADD A,n status");
    ASSERT_EQ_INT(2, decoded.length, "decode ADD A,n length");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "ADD") == 0, "decode ADD A,n mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A,0x10") == 0, "decode ADD A,n operands");

    status = ez80_decode_instruction(jr_stream, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode JR e status");
    ASSERT_EQ_INT(2, decoded.length, "decode JR e length");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "JR") == 0, "decode JR e mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "+2") == 0, "decode JR e operands");

    status = ez80_decode_instruction(jp_stream, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode JP nn status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "JP") == 0, "decode JP mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "0x1234") == 0, "decode JP operands");

    status = ez80_decode_instruction(short_ld_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short LD should fail as out of bounds");

    status = ez80_decode_instruction(short_add_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short ADD should fail as out of bounds");

    status = ez80_decode_instruction(short_jr_stream, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short JR should fail as out of bounds");
}

static void test_decode_extended_opcodes(void)
{
    ez80_instruction_t decoded;
    ez80_status_t status;
    uint8_t ld_b_n[2] = { 0x06, 0x99 };
    uint8_t ld_hl_b[1] = { 0x70 };
    uint8_t ld_a_hl[1] = { 0x7E };
    uint8_t ld_bc_nn[3] = { 0x01, 0x34, 0x12 };
    uint8_t ld_mem_a[3] = { 0x32, 0x20, 0x00 };
    uint8_t ld_a_mem[3] = { 0x3A, 0x20, 0x00 };
    uint8_t call_nn[3] = { 0xCD, 0x78, 0x56 };
    uint8_t ret[1] = { 0xC9 };
    uint8_t push_bc[1] = { 0xC5 };
    uint8_t pop_af[1] = { 0xF1 };
    uint8_t add_hl_bc[1] = { 0x09 };
    uint8_t inc_sp[1] = { 0x33 };
    uint8_t dec_hl[1] = { 0x2B };
    uint8_t out_n_a[2] = { 0xD3, 0x10 };
    uint8_t in_a_n[2] = { 0xDB, 0x10 };
    uint8_t jp_hl[1] = { 0xE9 };
    uint8_t ld_sp_hl[1] = { 0xF9 };
    uint8_t short_call[2] = { 0xCD, 0x34 };

    printf("[TEST] decode extended opcode scaffold\n");

    status = ez80_decode_instruction(ld_b_n, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD B,n status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LD") == 0, "decode LD B,n mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "B,0x99") == 0, "decode LD B,n operands");

    status = ez80_decode_instruction(ld_hl_b, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD (HL),B status");
    ASSERT_TRUE(strcmp(decoded.operands, "(HL),B") == 0, "decode LD (HL),B operands");

    status = ez80_decode_instruction(ld_a_hl, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD A,(HL) status");
    ASSERT_TRUE(strcmp(decoded.operands, "A,(HL)") == 0, "decode LD A,(HL) operands");

    status = ez80_decode_instruction(ld_bc_nn, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD BC,nn status");
    ASSERT_TRUE(strcmp(decoded.operands, "BC,0x1234") == 0, "decode LD BC,nn operands");

    status = ez80_decode_instruction(ld_mem_a, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD (nn),A status");
    ASSERT_TRUE(strcmp(decoded.operands, "(0x0020),A") == 0, "decode LD (nn),A operands");

    status = ez80_decode_instruction(ld_a_mem, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD A,(nn) status");
    ASSERT_TRUE(strcmp(decoded.operands, "A,(0x0020)") == 0, "decode LD A,(nn) operands");

    status = ez80_decode_instruction(call_nn, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode CALL nn status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "CALL") == 0, "decode CALL mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "0x5678") == 0, "decode CALL operands");

    status = ez80_decode_instruction(ret, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode RET status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "RET") == 0, "decode RET mnemonic");

    status = ez80_decode_instruction(push_bc, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode PUSH BC status");
    ASSERT_TRUE(strcmp(decoded.operands, "BC") == 0, "decode PUSH BC operands");

    status = ez80_decode_instruction(pop_af, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode POP AF status");
    ASSERT_TRUE(strcmp(decoded.operands, "AF") == 0, "decode POP AF operands");

    status = ez80_decode_instruction(add_hl_bc, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode ADD HL,BC status");
    ASSERT_TRUE(strcmp(decoded.operands, "HL,BC") == 0, "decode ADD HL,BC operands");

    status = ez80_decode_instruction(inc_sp, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode INC SP status");
    ASSERT_TRUE(strcmp(decoded.operands, "SP") == 0, "decode INC SP operands");

    status = ez80_decode_instruction(dec_hl, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode DEC HL status");
    ASSERT_TRUE(strcmp(decoded.operands, "HL") == 0, "decode DEC HL operands");

    status = ez80_decode_instruction(out_n_a, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode OUT (n),A status");
    ASSERT_TRUE(strcmp(decoded.operands, "(0x10),A") == 0, "decode OUT operands");

    status = ez80_decode_instruction(in_a_n, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode IN A,(n) status");
    ASSERT_TRUE(strcmp(decoded.operands, "A,(0x10)") == 0, "decode IN operands");

    status = ez80_decode_instruction(jp_hl, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode JP (HL) status");
    ASSERT_TRUE(strcmp(decoded.operands, "(HL)") == 0, "decode JP (HL) operands");

    status = ez80_decode_instruction(ld_sp_hl, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD SP,HL status");
    ASSERT_TRUE(strcmp(decoded.operands, "SP,HL") == 0, "decode LD SP,HL operands");

    status = ez80_decode_instruction(short_call, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short CALL should fail as out of bounds");
}

static void test_decode_prefixed_and_alu_opcodes(void)
{
    ez80_instruction_t decoded;
    ez80_status_t status;
    uint8_t add_a_b[1] = { 0x80 };
    uint8_t cp_hl[1] = { 0xBE };
    uint8_t sbc_a_n[2] = { 0xDE, 0x33 };
    uint8_t bit_3_hl[2] = { 0xCB, 0x5E };
    uint8_t adc_hl_sp[2] = { 0xED, 0x7A };
    uint8_t ldir[2] = { 0xED, 0xB0 };
    uint8_t inir[2] = { 0xED, 0xB2 };
    uint8_t outdr[2] = { 0xED, 0xBB };
    uint8_t ld_ix_nn[4] = { 0xDD, 0x21, 0x34, 0x12 };
    uint8_t ld_a_iy_disp[3] = { 0xFD, 0x7E, 0xFE };
    uint8_t ddcb_res_mem[4] = { 0xDD, 0xCB, 0xFE, 0x86 };
    uint8_t fdcb_set_b[4] = { 0xFD, 0xCB, 0x01, 0xC0 };
    uint8_t short_cb[1] = { 0xCB };
    uint8_t short_dd_disp_imm[3] = { 0xDD, 0x36, 0x04 };

    printf("[TEST] decode ALU + CB/ED/DD/FD prefix opcodes\n");

    status = ez80_decode_instruction(add_a_b, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode ADD A,B status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "ADD") == 0, "decode ADD A,B mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A,B") == 0, "decode ADD A,B operands");

    status = ez80_decode_instruction(cp_hl, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode CP (HL) status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "CP") == 0, "decode CP (HL) mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "(HL)") == 0, "decode CP (HL) operands");

    status = ez80_decode_instruction(sbc_a_n, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode SBC A,n status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "SBC") == 0, "decode SBC A,n mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A,0x33") == 0, "decode SBC A,n operands");

    status = ez80_decode_instruction(bit_3_hl, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode BIT 3,(HL) status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "BIT") == 0, "decode BIT 3,(HL) mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "3,(HL)") == 0, "decode BIT 3,(HL) operands");
    ASSERT_EQ_INT(12, decoded.cycles, "decode BIT (HL) cycles");

    status = ez80_decode_instruction(adc_hl_sp, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode ADC HL,SP status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "ADC") == 0, "decode ADC HL,SP mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "HL,SP") == 0, "decode ADC HL,SP operands");

    status = ez80_decode_instruction(ldir, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LDIR status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LDIR") == 0, "decode LDIR mnemonic");
    ASSERT_EQ_INT(21, decoded.cycles, "decode LDIR cycles");

    status = ez80_decode_instruction(inir, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode INIR status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "INIR") == 0, "decode INIR mnemonic");
    ASSERT_EQ_INT(21, decoded.cycles, "decode INIR cycles");

    status = ez80_decode_instruction(outdr, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode OUTDR status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "OUTDR") == 0, "decode OUTDR mnemonic");
    ASSERT_EQ_INT(21, decoded.cycles, "decode OUTDR cycles");

    status = ez80_decode_instruction(ld_ix_nn, 4u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD IX,nn status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LD") == 0, "decode LD IX,nn mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "IX,0x1234") == 0, "decode LD IX,nn operands");
    ASSERT_EQ_INT(4, decoded.length, "decode LD IX,nn length");

    status = ez80_decode_instruction(ld_a_iy_disp, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode LD A,(IY+d) status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LD") == 0, "decode LD A,(IY+d) mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "A,(IY-2)") == 0, "decode LD A,(IY+d) operands");

    status = ez80_decode_instruction(ddcb_res_mem, 4u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode DD CB RES status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "RES") == 0, "decode DD CB RES mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "0,(IX-2)") == 0, "decode DD CB RES operands");
    ASSERT_EQ_INT(4, decoded.length, "decode DD CB RES length");

    status = ez80_decode_instruction(fdcb_set_b, 4u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode FD CB SET status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "SET") == 0, "decode FD CB SET mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "0,(IY+1),B") == 0, "decode FD CB SET operands");
    ASSERT_EQ_INT(4, decoded.length, "decode FD CB SET length");

    status = ez80_decode_instruction(short_cb, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short CB should fail as out of bounds");

    status = ez80_decode_instruction(short_dd_disp_imm, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short DD LD (IX+d),n should fail as out of bounds");
}

static void test_decode_control_flow_and_interrupt_opcodes(void)
{
    ez80_instruction_t decoded;
    ez80_status_t status;
    uint8_t jr_nz[2] = { 0x20, 0xFE };
    uint8_t jp_pe[3] = { 0xEA, 0x34, 0x12 };
    uint8_t call_m[3] = { 0xFC, 0x78, 0x56 };
    uint8_t ret_nc[1] = { 0xD0 };
    uint8_t rst_18[1] = { 0xDF };
    uint8_t ex_af_af_alt[1] = { 0x08 };
    uint8_t djnz_back[2] = { 0x10, 0xFC };
    uint8_t exx[1] = { 0xD9 };
    uint8_t ex_sp_hl[1] = { 0xE3 };
    uint8_t ex_de_hl[1] = { 0xEB };
    uint8_t ex_sp_ix[2] = { 0xDD, 0xE3 };
    uint8_t ex_sp_iy[2] = { 0xFD, 0xE3 };
    uint8_t di[1] = { 0xF3 };
    uint8_t ei[1] = { 0xFB };
    uint8_t im_1[2] = { 0xED, 0x56 };
    uint8_t short_djnz[1] = { 0x10 };
    uint8_t short_jr_cond[1] = { 0x30 };
    uint8_t short_jp_cond[2] = { 0xFA, 0x10 };
    uint8_t short_call_cond[2] = { 0xDC, 0x20 };

    printf("[TEST] decode conditional control-flow + interrupt opcodes\n");

    status = ez80_decode_instruction(jr_nz, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode JR NZ,e status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "JR") == 0, "decode JR NZ,e mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "NZ,-2") == 0, "decode JR NZ,e operands");

    status = ez80_decode_instruction(jp_pe, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode JP PE,nn status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "JP") == 0, "decode JP PE,nn mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "PE,0x1234") == 0, "decode JP PE,nn operands");

    status = ez80_decode_instruction(call_m, 3u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode CALL M,nn status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "CALL") == 0, "decode CALL M,nn mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "M,0x5678") == 0, "decode CALL M,nn operands");

    status = ez80_decode_instruction(ret_nc, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode RET NC status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "RET") == 0, "decode RET NC mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "NC") == 0, "decode RET NC operands");

    status = ez80_decode_instruction(rst_18, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode RST 0x18 status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "RST") == 0, "decode RST 0x18 mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "0x18") == 0, "decode RST 0x18 operands");

    status = ez80_decode_instruction(ex_af_af_alt, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode EX AF,AF' status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "EX") == 0, "decode EX AF,AF' mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "AF,AF'") == 0, "decode EX AF,AF' operands");
    ASSERT_EQ_INT(4, decoded.cycles, "decode EX AF,AF' cycles");

    status = ez80_decode_instruction(djnz_back, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode DJNZ e status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "DJNZ") == 0, "decode DJNZ e mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "-4") == 0, "decode DJNZ e operands");
    ASSERT_EQ_INT(13, decoded.cycles, "decode DJNZ e cycles");

    status = ez80_decode_instruction(exx, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode EXX status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "EXX") == 0, "decode EXX mnemonic");
    ASSERT_EQ_INT(4, decoded.cycles, "decode EXX cycles");

    status = ez80_decode_instruction(ex_sp_hl, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode EX (SP),HL status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "EX") == 0, "decode EX (SP),HL mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "(SP),HL") == 0, "decode EX (SP),HL operands");
    ASSERT_EQ_INT(19, decoded.cycles, "decode EX (SP),HL cycles");

    status = ez80_decode_instruction(ex_de_hl, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode EX DE,HL status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "EX") == 0, "decode EX DE,HL mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "DE,HL") == 0, "decode EX DE,HL operands");
    ASSERT_EQ_INT(4, decoded.cycles, "decode EX DE,HL cycles");

    status = ez80_decode_instruction(ex_sp_ix, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode EX (SP),IX status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "EX") == 0, "decode EX (SP),IX mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "(SP),IX") == 0, "decode EX (SP),IX operands");
    ASSERT_EQ_INT(23, decoded.cycles, "decode EX (SP),IX cycles");

    status = ez80_decode_instruction(ex_sp_iy, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode EX (SP),IY status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "EX") == 0, "decode EX (SP),IY mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "(SP),IY") == 0, "decode EX (SP),IY operands");
    ASSERT_EQ_INT(23, decoded.cycles, "decode EX (SP),IY cycles");

    status = ez80_decode_instruction(di, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode DI status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "DI") == 0, "decode DI mnemonic");
    ASSERT_EQ_INT(4, decoded.cycles, "decode DI cycles");

    status = ez80_decode_instruction(ei, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode EI status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "EI") == 0, "decode EI mnemonic");
    ASSERT_EQ_INT(4, decoded.cycles, "decode EI cycles");

    status = ez80_decode_instruction(im_1, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode IM 1 status");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "IM") == 0, "decode IM 1 mnemonic");
    ASSERT_TRUE(strcmp(decoded.operands, "1") == 0, "decode IM 1 operands");

    status = ez80_decode_instruction(short_djnz, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short DJNZ should fail as out of bounds");

    status = ez80_decode_instruction(short_jr_cond, 1u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short JR cc should fail as out of bounds");

    status = ez80_decode_instruction(short_jp_cond, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short JP cc should fail as out of bounds");

    status = ez80_decode_instruction(short_call_cond, 2u, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode short CALL cc should fail as out of bounds");
}

