static void test_memory_model_access(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value;

    printf("[TEST] memory model read/write stubs\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "emulator init for memory model");

    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 17u, 0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "write RAM byte");
    value = 0u;
    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 17u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read RAM byte");
    ASSERT_EQ_INT(0xA5, value, "RAM round-trip value");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 3u, 0x7Fu);
    ASSERT_EQ_INT(EZ80_OK, status, "write port byte");
    value = 0u;
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 3u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read port byte");
    ASSERT_EQ_INT(0x7F, value, "port round-trip value");

    status = ez80_memory_write8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_LCD_STATUS, 0x42u);
    ASSERT_EQ_INT(EZ80_OK, status, "write MMIO byte");
    value = 0u;
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_LCD_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read MMIO byte");
    ASSERT_EQ_INT(0x42, value, "MMIO round-trip value");

    value = 0xAAu;
    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x20u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash reads in mapped window should succeed");
    ASSERT_EQ_INT(0x00, value, "uninitialized flash window bytes should read as zero");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE, 0x11u);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "flash writes should be rejected");

    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 17u + 0x01000000u, 0x3Cu);
    ASSERT_EQ_INT(EZ80_OK, status, "masked write with bit-24 set should alias into 24-bit address space");
    value = 0u;
    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 17u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "masked write aliased read should succeed");
    ASSERT_EQ_INT(0x3C, value, "masked write should land in canonical RAM address");

    value = 0u;
    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 17u + 0x01000000u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "masked read with bit-24 set should alias into 24-bit address space");
    ASSERT_EQ_INT(0x3C, value, "masked read should return canonical RAM byte");

    status = ez80_memory_read8(&emu, 0xABCDEFu, &value);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "out-of-range read should fail");
}

static void test_emulator_load_and_execute(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    ez80_run_result_t run_result;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[4] = { 0x3E, 0x2A, 0x00, 0x76 };

    printf("[TEST] emulator load + decode + execute stubs\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create temporary ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "emulator init before ROM load");

    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ROM load should succeed for valid file");
    ASSERT_TRUE(emu.rom_loaded, "ROM loaded flag should be true");
    ASSERT_EQ_U32(sizeof(rom_bytes), emu.memory.flash_bytes_loaded, "flash bytes loaded");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "get state after load");
    ASSERT_EQ_U32(0u, cpu.pc, "pc should start at zero");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,n");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LD") == 0, "first instruction should decode as LD");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "get state after LD");
    ASSERT_EQ_U32(2u, cpu.pc, "pc should advance by 2 after LD");
    ASSERT_EQ_INT(0x2A, (cpu.af >> 8) & 0xFFu, "register A should hold immediate value");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step NOP");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "NOP") == 0, "second instruction should decode as NOP");

    status = ez80_emulator_run_cycles(&emu, 20u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "run cycles through HALT");
    ASSERT_TRUE(run_result.cycles_executed > 0u, "run cycles should consume budget");
    ASSERT_TRUE(run_result.hit_halt, "run cycles should hit HALT");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "get state after run");
    ASSERT_TRUE(cpu.halted, "cpu halted flag should be set");
    ASSERT_EQ_U32(4u, cpu.pc, "pc should advance to HALT end");

    remove(rom_path);
}

