static void test_decode_ddfd_ed_prefix_ignore(void)
{
    ez80_instruction_t decoded;
    ez80_status_t status;
    uint8_t ddir_stream[] = { 0xDD, 0xED, 0xB0 };
    uint8_t fd_ed_stream[] = { 0xFD, 0xED, 0x30 };
    uint8_t short_stream[] = { 0xDD, 0xED };

    printf("[TEST] decode DD/FD + ED prefix-ignore support\n");

    memset(&decoded, 0, sizeof(decoded));
    status = ez80_decode_instruction(ddir_stream, sizeof(ddir_stream), &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode DD ED B0 should succeed");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LDIR") == 0, "DD ED B0 should decode as LDIR");
    ASSERT_EQ_INT(3, decoded.length, "DD ED B0 length should include ignored prefix");
    ASSERT_EQ_INT(25, decoded.cycles, "DD ED B0 cycles should include ignored-prefix timing");

    memset(&decoded, 0, sizeof(decoded));
    status = ez80_decode_instruction(fd_ed_stream, sizeof(fd_ed_stream), &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode FD ED 30 should succeed");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "LD") == 0, "FD ED 30 mnemonic should be LD");
    ASSERT_TRUE(strcmp(decoded.operands, "IY,(HL)") == 0, "FD ED 30 operands should mirror ED 30");
    ASSERT_EQ_INT(3, decoded.length, "FD ED 30 length should include ignored prefix");
    ASSERT_EQ_INT(14, decoded.cycles, "FD ED 30 cycles should include ignored-prefix penalty");

    memset(&decoded, 0, sizeof(decoded));
    status = ez80_decode_instruction(short_stream, sizeof(short_stream), &decoded);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "decode DD ED without inner opcode should OOB");
}

static void test_emulator_ddfd_ed_prefix_ignore_execution(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0x3E, 0x01,       /* LD A,1 */
        0xDD, 0xED, 0x44, /* ignored DD prefix + ED NEG */
        0x76              /* HALT */
    };

    printf("[TEST] emulator DD/FD + ED prefix-ignore execution semantics\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create DD/FD+ED prefix-ignore ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "DD/FD+ED execute init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "DD/FD+ED execute ROM load");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,1");
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step DD ED NEG");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after DD ED NEG");
    ASSERT_EQ_INT(0xFF, cpu_reg_a(&cpu), "DD ED NEG should execute inner ED NEG");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_C) != 0u, "DD ED NEG should preserve NEG carry semantics");
    ASSERT_EQ_U32(5u, cpu.pc, "DD ED NEG should advance PC by combined prefix+inner length");

    remove(rom_path);
}

static void test_emulator_flash_full_map_and_protection(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    char rom_path[L_tmpnam];
    uint8_t value = 0u;
    const uint32_t offsets[] = { 0x000010u, 0x100010u, 0x3B0028u };
    const uint8_t values[] = { 0x11u, 0x22u, 0x33u };

    printf("[TEST] emulator full flash map + protection gate modeling\n");

    ASSERT_TRUE(write_temp_sparse_rom(offsets, values, sizeof(offsets) / sizeof(offsets[0]),
                                      rom_path, sizeof(rom_path)),
                "create sparse 4MB ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "full-flash init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "full-flash ROM load");
    ASSERT_EQ_U32(EZ80_FLASH_TOTAL_BYTES, emu.memory.flash_bytes_loaded, "full ROM byte count should be 4MB");

    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x000010u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read low flash marker");
    ASSERT_EQ_INT(0x11, value, "low flash marker should match ROM");

    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x100010u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read high flash marker");
    ASSERT_EQ_INT(0x22, value, "high flash marker should match ROM");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x020010u, 0x44u);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "flash write should fail while lock bit is clear");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "set flash unlock port bit");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_UNLOCK_STATE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read flash unlock MMIO state");
    ASSERT_EQ_INT(1, value, "flash unlock MMIO state should reflect port bit");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x020010u, 0x44u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash write in writable page should succeed when unlocked");
    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x020010u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writable flash byte");
    ASSERT_EQ_INT(0x44, value, "flash write should persist in writable page");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x3B0028u, 0x99u);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "certificate flash write should fail without cert-write privilege");
    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x3B0028u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read certificate byte after blocked write");
    ASSERT_EQ_INT(0x33, value, "blocked certificate write should preserve original value");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x06u, 0x08u);
    ASSERT_EQ_INT(EZ80_OK, status, "set cert-write privilege port bit");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_CERT_WRITE_STATE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read cert-write MMIO state");
    ASSERT_EQ_INT(1, value, "cert-write MMIO state should reflect privilege bit");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x3B0028u, 0x99u);
    ASSERT_EQ_INT(EZ80_OK, status, "certificate write should succeed when privilege bit is set");
    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x3B0028u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read certificate byte after privileged write");
    ASSERT_EQ_INT(0x99, value, "privileged certificate write should persist");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x000010u, 0xAAu);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "boot page flash write should remain protected");
    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x000010u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read boot page byte after blocked write");
    ASSERT_EQ_INT(0x11, value, "boot page content should remain unchanged");

    remove(rom_path);
}

static void test_emulator_flash_sector_register_model(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint32_t offsets[] = { 0x000000u, 0x200010u };
    const uint8_t values[] = { 0x00u, 0xAAu };

    printf("[TEST] flash sector register modeling + OS profile protection levels\n");

    ASSERT_TRUE(write_temp_sparse_rom(offsets, values, sizeof(offsets) / sizeof(offsets[0]),
                                      rom_path, sizeof(rom_path)),
                "create sparse ROM for sector-register model test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "sector-register model init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "sector-register model ROM load");

    status = ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "sector-register model set OS 5.4");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_PROTECT_MODE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read flash protect mode in OS 5.4 profile");
    ASSERT_EQ_INT(EZ80_FLASH_PROTECT_MODE_PERMISSIVE,
                  value,
                  "OS 5.4 profile should expose permissive flash protection mode");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "enable flash unlock bit for sector-register writes");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x24u, 0x20u);
    ASSERT_EQ_INT(EZ80_OK, status, "select sector index 0x20");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_SECTOR_SELECT, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read selected flash sector");
    ASSERT_EQ_INT(0x20, value, "selected flash sector should mirror port write");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x25u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "protect selected flash sector");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_SECTOR_FLAGS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read flash sector flags after protect");
    ASSERT_TRUE((value & EZ80_FLASH_SECTOR_FLAG_PROTECTED) != 0u,
                "sector flags should mark selected sector protected");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x200010u, 0x55u);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS,
                  status,
                  "protected sector should reject flash writes");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash status after protected write");
    ASSERT_EQ_INT(EZ80_WRITEFLASH_STATUS_SECTOR_PROTECTED,
                  value,
                  "writeflash status should report sector-protected failure");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x25u, 0x02u);
    ASSERT_EQ_INT(EZ80_OK, status, "unprotect selected flash sector");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_SECTOR_FLAGS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read flash sector flags after unprotect");
    ASSERT_TRUE((value & EZ80_FLASH_SECTOR_FLAG_PROTECTED) == 0u,
                "sector flags should clear protected bit after unprotect");

    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x200010u, 0x55u);
    ASSERT_EQ_INT(EZ80_OK, status, "unprotected sector should allow writes");
    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x200010u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read flash byte after unprotected write");
    ASSERT_EQ_INT(0x55, value, "unprotected sector write should persist");

    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "sector-register model set OS 5.8");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_PROTECT_MODE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read flash protect mode in OS 5.8 profile");
    ASSERT_EQ_INT(EZ80_FLASH_PROTECT_MODE_LOCKED,
                  value,
                  "OS 5.8 profile should expose locked flash protection mode");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x24u, 0x3Bu);
    ASSERT_EQ_INT(EZ80_OK, status, "select certificate sector");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_SECTOR_FLAGS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read certificate-sector flags under OS 5.8");
    ASSERT_TRUE((value & EZ80_FLASH_SECTOR_FLAG_PROTECTED) != 0u,
                "certificate sector should remain protected under OS 5.8");
    ASSERT_TRUE((value & EZ80_FLASH_SECTOR_FLAG_OS_LOCKED) != 0u,
                "certificate sector should report OS-locked bit under OS 5.8");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x25u, 0x02u);
    ASSERT_EQ_INT(EZ80_OK, status, "attempt certificate-sector unprotect command under OS 5.8");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_SECTOR_FLAGS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "re-read certificate-sector flags after blocked unprotect");
    ASSERT_TRUE((value & EZ80_FLASH_SECTOR_FLAG_PROTECTED) != 0u,
                "OS-locked certificate sector should ignore unprotect command");

    remove(rom_path);
}

static void test_emulator_writeflashbyte_failure_modes(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_dngrade_attempt_result_t attempt;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint32_t offsets[] = {
        0x000000u,
        0x3BF037u,
        0x3BF038u,
        0x3BF039u
    };
    const uint8_t values[] = {
        0x00u,
        0x00u,
        0xFFu,
        0x05u
    };

    printf("[TEST] _WriteFlashByte-model failure modes (erase requirement + sector lock)\n");

    ASSERT_TRUE(write_temp_sparse_rom(offsets, values, sizeof(offsets) / sizeof(offsets[0]),
                                      rom_path, sizeof(rom_path)),
                "create sparse ROM for writeflashbyte failure-mode test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflashbyte failure-mode init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflashbyte failure-mode ROM load");
    status = ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflashbyte failure-mode set OS 5.4");

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_CERT_UNLOCK_THEN_WRITE,
                                                    0x3BF037u,
                                                    0xA6u,
                                                    0u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "simulate _WriteFlashByte-model write requiring erase");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_FAILURE,
                  attempt.attempt_status,
                  "_WriteFlashByte-model should fail when write requires erased bits");
    ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_FLASH_REQUIRES_ERASE,
                  attempt.failure_reason,
                  "failure reason should report erase-required condition");
    ASSERT_TRUE(attempt.write_attempted,
                "erase-required _WriteFlashByte-model path should still report attempted write");
    ASSERT_TRUE(!attempt.write_succeeded,
                "erase-required _WriteFlashByte-model path should not report success");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash status after erase-required attempt");
    ASSERT_EQ_INT(EZ80_WRITEFLASH_STATUS_REQUIRES_ERASE,
                  value,
                  "writeflash status should report erase-required failure");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_BEFORE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash-before byte after erase-required attempt");
    ASSERT_EQ_INT(0x00, value, "writeflash-before should reflect non-erased source byte");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_AFTER, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash-after byte after erase-required attempt");
    ASSERT_EQ_INT(0x00, value, "writeflash-after should remain unchanged on erase-required failure");

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_CERT_UNLOCK_THEN_WRITE,
                                                    0x3BF038u,
                                                    0xA6u,
                                                    0u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "simulate _WriteFlashByte-model write from erased byte");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_SUCCESS,
                  attempt.attempt_status,
                  "_WriteFlashByte-model should succeed when destination byte is erased");
    ASSERT_TRUE(attempt.write_succeeded,
                "erased-byte _WriteFlashByte-model path should report success");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash status after success");
    ASSERT_EQ_INT(EZ80_WRITEFLASH_STATUS_SUCCESS,
                  value,
                  "writeflash status should report success for erased-byte write");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_BEFORE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash-before byte after success");
    ASSERT_EQ_INT(0xFF, value, "writeflash-before should show erased source byte");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_AFTER, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash-after byte after success");
    ASSERT_EQ_INT(0xA6, value, "writeflash-after should match programmed byte on success");

    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflashbyte failure-mode set OS 5.8");
    emu.memory.ports[0x28u] = 0x09u;
    emu.memory.ports[0x06u] = 0x08u;

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_DIRECT_FLASH_WRITE,
                                                    0x3B0028u,
                                                    0x00u,
                                                    0u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "simulate _WriteFlashByte-model direct write under OS 5.8");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_FAILURE,
                  attempt.attempt_status,
                  "OS 5.8 writeflash path should fail on locked certificate sector");
    ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_FLASH_SECTOR_PROTECTED,
                  attempt.failure_reason,
                  "OS 5.8 writeflash path should report sector-protected failure");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_WRITEFLASH_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read writeflash status after OS 5.8 locked-sector failure");
    ASSERT_EQ_INT(EZ80_WRITEFLASH_STATUS_SECTOR_PROTECTED,
                  value,
                  "writeflash status should report sector-protected failure under OS 5.8");

    remove(rom_path);
}

static void test_emulator_os58_detection_and_artifice_key_entry(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint32_t offsets[] = {
        0x000000u,
        0x3BF037u,
        0x3BF038u,
        0x3BF039u
    };
    const uint8_t values[] = {
        0x76u,
        0x00u,
        0x08u,
        0x05u
    };

    printf("[TEST] emulator OS 5.8 detect + arTIfiCE key-sequence entry\n");

    ASSERT_TRUE(write_temp_sparse_rom(offsets, values, sizeof(offsets) / sizeof(offsets[0]),
                                      rom_path, sizeof(rom_path)),
                "create sparse ROM with OS 5.8 marker");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.8 detect init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.8 detect load ROM");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_OS_VERSION_MAJOR, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read OS major");
    ASSERT_EQ_INT(5, value, "OS major should detect as 5");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_OS_VERSION_MINOR, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read OS minor");
    ASSERT_EQ_INT(8, value, "OS minor should detect as 8");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_OS_VERSION_PATCH, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read OS patch");
    ASSERT_EQ_INT(0, value, "OS patch should detect as 0");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_NATIVE_UNSIGNED_EXEC_ALLOWED, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read unsigned execution flag before bypass");
    ASSERT_EQ_INT(0, value, "OS 5.8 should block unsigned execution before arTIfiCE bypass");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_NOT_IMPLEMENTED, status, "OS 5.8 should reject execution before bypass");

    inject_artifice_key_sequence(&emu);

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_ARTIFICE_BYPASS_ACTIVE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read arTIfiCE bypass flag");
    ASSERT_EQ_INT(1, value, "arTIfiCE bypass should be active after key sequence");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_ARTIFICE_ENTRY_METHOD, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read arTIfiCE entry method");
    ASSERT_EQ_INT(EZ80_ARTIFICE_ENTRY_KEY_SEQUENCE, value, "entry method should report key-sequence path");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.8 execution should proceed after arTIfiCE bypass");
    ASSERT_TRUE(emu.cpu.halted, "HALT instruction should execute after bypass activation");

    remove(rom_path);
}

static void test_emulator_artifice_memory_patch_entry(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint8_t rom_bytes[] = { 0x76u };

    printf("[TEST] emulator arTIfiCE memory-patch entry simulation\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ROM for arTIfiCE memory-patch entry test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "arTIfiCE memory-patch init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "arTIfiCE memory-patch load ROM");

    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "set OS version to 5.8 for memory-patch test");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_ERR_NOT_IMPLEMENTED, status, "OS 5.8 should block execution before memory patch bypass");

    status = ez80_emulator_apply_artifice_memory_patch(&emu,
                                                       EZ80_ARTIFICE_PATCH_ADDR + 1u,
                                                       EZ80_ARTIFICE_PATCH_MAGIC);
    ASSERT_EQ_INT(EZ80_OK, status, "non-matching memory patch write should still succeed as RAM write");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_ARTIFICE_BYPASS_ACTIVE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read bypass active flag after non-matching patch");
    ASSERT_EQ_INT(0, value, "non-matching memory patch should not activate bypass");

    status = ez80_emulator_apply_artifice_memory_patch(&emu,
                                                       EZ80_ARTIFICE_PATCH_ADDR,
                                                       EZ80_ARTIFICE_PATCH_MAGIC);
    ASSERT_EQ_INT(EZ80_OK, status, "apply matching arTIfiCE memory patch");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_ARTIFICE_BYPASS_ACTIVE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read bypass active flag after matching patch");
    ASSERT_EQ_INT(1, value, "matching memory patch should activate bypass");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_ARTIFICE_ENTRY_METHOD, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read entry method after matching patch");
    ASSERT_EQ_INT(EZ80_ARTIFICE_ENTRY_MEMORY_PATCH, value, "entry method should report memory-patch path");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "execution should proceed after memory-patch bypass");
    ASSERT_TRUE(emu.cpu.halted, "HALT should execute after memory-patch bypass");

    remove(rom_path);
}

static void test_emulator_dngrade_restrictions_os54_vs_os58(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint32_t offsets[] = {
        0x000000u,
        0x3BF037u,
        0x3BF038u,
        0x3BF039u
    };
    const uint8_t values[] = {
        0x00u,
        0xFFu,
        0x04u,
        0x05u
    };

    printf("[TEST] emulator DNGRADE restriction model: OS 5.4 native vs OS 5.8 arTIfiCE\n");

    ASSERT_TRUE(write_temp_sparse_rom(offsets, values, sizeof(offsets) / sizeof(offsets[0]),
                                      rom_path, sizeof(rom_path)),
                "create sparse ROM for DNGRADE restriction test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "DNGRADE restriction init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "DNGRADE restriction load ROM");

    status = ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "force OS 5.4 profile");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0x09u);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.4 should accept port 0x28 bit3 writes");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x28u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read unlock port value on OS 5.4");
    ASSERT_EQ_INT(0x09, value, "OS 5.4 should preserve requested unlock port bits");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x06u, 0x08u);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.4 should allow cert-write privilege bit");
    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x3BF037u, 0xA1u);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.4 should allow version-byte patch with unlock + cert-write");

    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "force OS 5.8 profile");
    inject_artifice_key_sequence(&emu);

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0x09u);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.8 write to unlock port should return OK but sanitize blocked bits");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x28u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read unlock port value on OS 5.8");
    ASSERT_EQ_INT(0x01, value, "OS 5.8 should block userland bit3 and keep bit0 only");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_LAST_FAILURE_REASON, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read DNGRADE failure reason after blocked bit3 write");
    ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_PORT28_BIT3_BLOCKED, value, "DNGRADE failure should identify blocked port28 bit3 write");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x06u, 0x08u);
    ASSERT_EQ_INT(EZ80_OK, status, "OS 5.8 cert-write privilege bit write should still be accepted");
    status = ez80_memory_write8(&emu, EZ80_FLASH_BASE + 0x3BF037u, 0xB2u);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "OS 5.8 should fail version-byte patch because bit3 gate remains locked");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_LAST_FAILURE_REASON, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read DNGRADE failure reason after blocked flash write");
    ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_OS58_PORT28_BIT3_REQUIRED, value, "DNGRADE failure should report OS 5.8 bit3 gate requirement");
    status = ez80_memory_read8(&emu, EZ80_FLASH_BASE + 0x3BF037u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read version byte after blocked OS 5.8 patch");
    ASSERT_EQ_INT(0xA1, value, "blocked OS 5.8 version patch should preserve prior OS 5.4 value");

    remove(rom_path);
}

static void test_emulator_os58_boot_port28_unlock_sequence_exposes_bit3_on_probe_read_only(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    uint8_t blocked = 0u;
    uint8_t unlock_state = 0u;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0x3E, 0x04,       /* LD A,0x04 */
        0xED, 0x6D,       /* LD MB,A */
        0xF3,             /* DI */
        0x18, 0x00,       /* JR $+2 */
        0xF3,             /* DI */
        0xED, 0x7E,       /* LD A,MB */
        0xED, 0x56,       /* IM 1 */
        0xED, 0x39, 0x28, /* OUT0 (0x28),A */
        0xED, 0x38, 0x28, /* IN0 A,(0x28) */
        0xCB, 0x57,       /* BIT 2,A */
        0xED, 0x38, 0x28, /* IN0 A,(0x28) */
        0xCB, 0x5F,       /* BIT 3,A */
        0x76              /* HALT */
    };

    printf("[TEST] OS 5.8 canonical boot unlock probe exposes port 0x28 bit3 on first read only\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create canonical boot unlock-sequence ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence ROM load");
    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence force OS 5.8 profile");
    inject_artifice_key_sequence(&emu);

    status = ez80_emulator_step(&emu, &decoded); /* LD A,0x04 */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step LD A,0x04");
    status = ez80_emulator_step(&emu, &decoded); /* LD MB,A */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step LD MB,A");
    status = ez80_emulator_step(&emu, &decoded); /* DI */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step DI #1");
    status = ez80_emulator_step(&emu, &decoded); /* JR $+2 */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step JR");
    status = ez80_emulator_step(&emu, &decoded); /* DI */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step DI #2");
    status = ez80_emulator_step(&emu, &decoded); /* LD A,MB */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step LD A,MB");
    status = ez80_emulator_step(&emu, &decoded); /* IM 1 */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step IM 1");
    status = ez80_emulator_step(&emu, &decoded); /* OUT0 (0x28),A */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step OUT0");

    status = ez80_emulator_step(&emu, &decoded); /* IN0 A,(0x28) */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step first IN0");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence get state after first IN0");
    ASSERT_EQ_INT(0x0C, cpu_reg_a(&cpu), "boot-sequence first probe read should expose port 0x28 bits 2|3");

    status = ez80_emulator_step(&emu, &decoded); /* BIT 2,A */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step BIT 2");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence get state after BIT 2");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) == 0u, "boot-sequence BIT 2 should clear Z");

    status = ez80_emulator_step(&emu, &decoded); /* IN0 A,(0x28) */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step second IN0");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence get state after second IN0");
    ASSERT_EQ_INT(0x04, cpu_reg_a(&cpu), "boot-sequence later read should fall back to raw port 0x28 bit2");

    status = ez80_emulator_step(&emu, &decoded); /* BIT 3,A */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step BIT 3");
    status = ez80_emulator_step(&emu, &decoded); /* HALT */
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence step HALT");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence get state");
    ASSERT_TRUE(cpu.halted, "boot-sequence CPU should halt");
    ASSERT_EQ_U32((uint32_t)sizeof(rom_bytes), cpu.pc, "boot-sequence PC should stop at HALT");
    ASSERT_EQ_INT(1, cpu.interrupt_mode, "boot-sequence should leave IM 1 selected");
    ASSERT_EQ_INT(0x04, cpu_reg_a(&cpu), "boot-sequence should leave A holding the raw port 0x28 value");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0u, "boot-sequence BIT 3 should set Z after the transient probe window");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x28u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence read unlock port");
    ASSERT_EQ_INT(0x04, value, "boot-sequence should store the raw port 0x28 value after the probe read");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_PORT28_BIT3_BLOCKED, &blocked);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence read bit3-block telemetry");
    ASSERT_EQ_INT(0x01, blocked, "boot-sequence should keep the OS 5.8 bit3 gate enabled");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_LAST_FAILURE_REASON, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence read DNGRADE failure reason");
    ASSERT_EQ_INT(0x00, value, "boot-sequence should not record a DNGRADE failure");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_UNLOCK_STATE, &unlock_state);
    ASSERT_EQ_INT(EZ80_OK, status, "boot-sequence read flash unlock state");
    ASSERT_EQ_INT(0x00, unlock_state, "boot-sequence should not fabricate port 0x28 bit0");

    remove(rom_path);
}

static void test_emulator_os58_high_address_unlock_sequence_does_not_set_bit3(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    uint8_t unlock_state = 0u;
    uint8_t blocked = 0u;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0x3E, 0x04,
        0xED, 0x6D,
        0xF3,
        0x18, 0x00,
        0xF3,
        0xED, 0x7E,
        0xED, 0x56,
        0xED, 0x39, 0x28,
        0xED, 0x38, 0x28,
        0xCB, 0x57,
        0xED, 0x38, 0x28,
        0xCB, 0x5F,
        0x76
    };
    uint32_t offsets[sizeof(rom_bytes)];
    uint8_t values[sizeof(rom_bytes)];
    size_t i;

    printf("[TEST] OS 5.8 high-address unlock sequence should not set port 0x28 bit3\n");

    for (i = 0u; i < sizeof(rom_bytes); i++) {
        offsets[i] = 0x020000u + (uint32_t)i;
        values[i] = rom_bytes[i];
    }

    ASSERT_TRUE(write_temp_sparse_rom(offsets, values, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create high-address unlock-sequence ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence ROM load");
    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence force OS 5.8 profile");
    inject_artifice_key_sequence(&emu);

    emu.cpu.pc = 0x020000u;
    memset(&run_result, 0, sizeof(run_result));
    status = ez80_emulator_run_cycles(&emu, 400u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence run");
    ASSERT_TRUE(run_result.hit_halt, "high-address sequence should still reach HALT");
    ASSERT_TRUE(!run_result.hit_breakpoint, "high-address sequence should not hit a breakpoint");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence get state");
    ASSERT_TRUE(cpu.halted, "high-address sequence CPU should halt");
    ASSERT_EQ_U32(0x020000u + (uint32_t)sizeof(rom_bytes), cpu.pc,
                  "high-address sequence PC should stop at HALT");
    ASSERT_EQ_INT(1, cpu.interrupt_mode, "high-address sequence should still set IM 1");
    ASSERT_EQ_INT(0x04, cpu_reg_a(&cpu), "high-address sequence should read back only bit2");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0u, "high-address sequence BIT 3 should leave Z set");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x28u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence read unlock port");
    ASSERT_EQ_INT(0x04, value, "high-address sequence should not gain port 0x28 bit3");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_PORT28_BIT3_BLOCKED, &blocked);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence read bit3-block telemetry");
    ASSERT_EQ_INT(0x01, blocked, "high-address sequence should still report the OS 5.8 bit3 gate");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_LAST_FAILURE_REASON, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence read DNGRADE failure reason");
    ASSERT_EQ_INT(0x00, value, "high-address sequence should not record a DNGRADE failure");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_UNLOCK_STATE, &unlock_state);
    ASSERT_EQ_INT(EZ80_OK, status, "high-address sequence read flash unlock state");
    ASSERT_EQ_INT(0x00, unlock_state, "high-address sequence should not fabricate port 0x28 bit0");

    remove(rom_path);
}

static void test_emulator_os58_boot_unlock_sequence_requires_exact_bytes(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    uint8_t blocked = 0u;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0x3E, 0x04,
        0xED, 0x6D,
        0xF3,
        0x18, 0x00,
        0x00,
        0xED, 0x7E,
        0xED, 0x56,
        0xED, 0x39, 0x28,
        0xED, 0x38, 0x28,
        0xCB, 0x57,
        0xED, 0x38, 0x28,
        0xCB, 0x5F,
        0x76
    };

    printf("[TEST] OS 5.8 boot unlock sequence requires the exact canonical byte stream\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create mismatched boot unlock-sequence ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence ROM load");
    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence force OS 5.8 profile");
    inject_artifice_key_sequence(&emu);

    memset(&run_result, 0, sizeof(run_result));
    status = ez80_emulator_run_cycles(&emu, 400u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence run");
    ASSERT_TRUE(run_result.hit_halt, "mismatched sequence should still reach HALT");
    ASSERT_TRUE(!run_result.hit_breakpoint, "mismatched sequence should not hit a breakpoint");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence get state");
    ASSERT_TRUE(cpu.halted, "mismatched sequence CPU should halt");
    ASSERT_EQ_U32((uint32_t)sizeof(rom_bytes), cpu.pc, "mismatched sequence PC should stop at HALT");
    ASSERT_EQ_INT(1, cpu.interrupt_mode, "mismatched sequence should still set IM 1");
    ASSERT_EQ_INT(0x04, cpu_reg_a(&cpu), "mismatched sequence should read back only bit2");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0u, "mismatched sequence BIT 3 should leave Z set");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x28u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence read unlock port");
    ASSERT_EQ_INT(0x04, value, "mismatched sequence should not gain port 0x28 bit3");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_PORT28_BIT3_BLOCKED, &blocked);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence read bit3-block telemetry");
    ASSERT_EQ_INT(0x01, blocked, "mismatched sequence should still report the OS 5.8 bit3 gate");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_LAST_FAILURE_REASON, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "mismatched sequence read DNGRADE failure reason");
    ASSERT_EQ_INT(0x00, value, "mismatched sequence should not record a DNGRADE failure");

    remove(rom_path);
}

static void test_emulator_flash_boot_command_wakes_halt_via_nmi(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    uint8_t main_bytes[] = {
        0x3E, 0x88,       /* LD A,0x88 */
        0xED, 0x39, 0x24, /* OUT0 (0x24),A */
        0x76,             /* HALT -> boot-command NMI should wake this */
        0x3E, 0x42,       /* LD A,0x42 */
        0x76              /* HALT */
    };
    uint8_t nmi_bytes[] = {
        0xED, 0x45        /* RETN */
    };
    uint32_t offsets[sizeof(main_bytes) + sizeof(nmi_bytes)];
    uint8_t values[sizeof(main_bytes) + sizeof(nmi_bytes)];
    size_t i;

    printf("[TEST] flash boot command wakes HALT via NMI\n");

    for (i = 0u; i < sizeof(main_bytes); i++) {
        offsets[i] = (uint32_t)i;
        values[i] = main_bytes[i];
    }
    for (i = 0u; i < sizeof(nmi_bytes); i++) {
        offsets[sizeof(main_bytes) + i] = 0x000066u + (uint32_t)i;
        values[sizeof(main_bytes) + i] = nmi_bytes[i];
    }

    ASSERT_TRUE(write_temp_sparse_rom(offsets,
                                      values,
                                      sizeof(main_bytes) + sizeof(nmi_bytes),
                                      rom_path,
                                      sizeof(rom_path)),
                "create flash boot-command NMI ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-nmi init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-nmi ROM load");
    status = ez80_emulator_enable_interrupts(&emu, true);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-nmi enable interrupts");

    memset(&run_result, 0, sizeof(run_result));
    status = ez80_emulator_run_cycles(&emu, 200u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-nmi run");
    ASSERT_TRUE(run_result.hit_halt, "flash-boot-nmi should reach the second HALT");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-nmi get state");
    ASSERT_TRUE(cpu.halted, "flash-boot-nmi CPU should halt after resuming");
    ASSERT_EQ_U32((uint32_t)sizeof(main_bytes), cpu.pc, "flash-boot-nmi PC should advance past second HALT");
    ASSERT_EQ_INT(0x42, cpu_reg_a(&cpu), "flash-boot-nmi should resume after the first HALT");
    ASSERT_EQ_U32(1u, emu.hw.nmi_count, "flash-boot-nmi should raise exactly one NMI");
    ASSERT_TRUE(!emu.hw.nmi_active, "flash-boot-nmi should clear active NMI state after RETN");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x3Du, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-nmi read status port 0x3D");
    ASSERT_EQ_INT(0x01, value & 0x03u, "flash-boot-nmi should latch a nonzero NMI status until acked");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_NMI_COUNT, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-nmi read NMI count MMIO");
    ASSERT_EQ_INT(0x01, value, "flash-boot-nmi MMIO should report one NMI");

    remove(rom_path);
}

static void test_emulator_flash_boot_nmi_status_is_acknowledged_via_port3e(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    uint8_t main_bytes[] = {
        0x3E, 0x88,
        0xED, 0x39, 0x24,
        0x76,
        0xED, 0x38, 0x3D, /* IN0 A,(0x3D) */
        0x76
    };
    uint8_t nmi_bytes[] = {
        0xED, 0x38, 0x3D, /* IN0 A,(0x3D) */
        0xE6, 0x03,       /* AND 0x03 */
        0xED, 0x39, 0x3E, /* OUT0 (0x3E),A */
        0xED, 0x45        /* RETN */
    };
    uint32_t offsets[sizeof(main_bytes) + sizeof(nmi_bytes)];
    uint8_t values[sizeof(main_bytes) + sizeof(nmi_bytes)];
    size_t i;

    printf("[TEST] flash boot NMI status is acknowledged via port 0x3E\n");

    for (i = 0u; i < sizeof(main_bytes); i++) {
        offsets[i] = (uint32_t)i;
        values[i] = main_bytes[i];
    }
    for (i = 0u; i < sizeof(nmi_bytes); i++) {
        offsets[sizeof(main_bytes) + i] = 0x000066u + (uint32_t)i;
        values[sizeof(main_bytes) + i] = nmi_bytes[i];
    }

    ASSERT_TRUE(write_temp_sparse_rom(offsets,
                                      values,
                                      sizeof(main_bytes) + sizeof(nmi_bytes),
                                      rom_path,
                                      sizeof(rom_path)),
                "create flash boot-command NMI-ack ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack ROM load");
    status = ez80_emulator_enable_interrupts(&emu, true);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack enable interrupts");

    memset(&run_result, 0, sizeof(run_result));
    status = ez80_emulator_run_cycles(&emu, 200u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack run");
    ASSERT_TRUE(run_result.hit_halt, "flash-boot-ack should reach the post-ack HALT");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack get state");
    ASSERT_TRUE(cpu.halted, "flash-boot-ack CPU should halt after reading the cleared status");
    ASSERT_EQ_U32((uint32_t)sizeof(main_bytes), cpu.pc, "flash-boot-ack PC should advance past final HALT");
    ASSERT_EQ_INT(0x00, cpu_reg_a(&cpu), "flash-boot-ack should observe a cleared status after ack");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0u, "flash-boot-ack final IN0 should set Z for cleared status");
    ASSERT_EQ_U32(1u, emu.hw.nmi_count, "flash-boot-ack should raise exactly one NMI");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x3Du, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack read status port 0x3D");
    ASSERT_EQ_INT(0x00, value & 0x03u, "flash-boot-ack should clear low status bits after port 0x3E ack");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + 0x3Eu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack read ack port 0x3E");
    ASSERT_EQ_INT(0x01, value & 0x03u, "flash-boot-ack should preserve the acknowledged status on port 0x3E");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_NMI_ACTIVE, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash-boot-ack read NMI active MMIO");
    ASSERT_EQ_INT(0x00, value, "flash-boot-ack MMIO should report no active NMI after RETN");

    remove(rom_path);
}

