/* ============================================================
 * run_cycles timing regression: DD ED terminal block-I/O timing
 * ============================================================ */
static void test_emulator_run_cycles_dd_prefix_ed_repeat_timing(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    ez80_status_t status;
    char rom_path[L_tmpnam];
    uint8_t value0 = 0u;
    uint8_t value1 = 0u;

    uint8_t rom_bytes[] = {
        0x01, 0x10, 0x01,       /* LD BC,0x0110       (10) */
        0x21, 0x00, 0x40,       /* LD HL,0x4000       (10) */
        0xDD, 0xED, 0xB2,       /* DD ED B2 (INIR)    (20 terminal with prefix) */
        0x76                    /* HALT               (4) */
    };

    printf("[TEST] emulator run_cycles DD ED terminal timing regression\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create run_cycles DD-ED repeat timing ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles DD-ED terminal timing init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles DD-ED terminal timing ROM load");

    emu.memory.ports[0x10] = 0x3Cu;

    status = ez80_emulator_run_cycles(&emu, 120u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles DD-ED terminal timing run");
    ASSERT_TRUE(run_result.hit_halt, "run_cycles DD-ED terminal timing should reach HALT");
    ASSERT_EQ_U32(44u, run_result.cycles_executed,
                  "run_cycles should use terminal timing for DD-prefixed ED repeat opcodes");

    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value0);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles DD-ED terminal read RAM[0x4000]");
    ASSERT_EQ_INT(0x3C, value0, "DD-prefixed INIR first transfer byte");
    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value1);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles DD-ED terminal read RAM[0x4001]");
    ASSERT_EQ_INT(0x00, value1, "DD-prefixed INIR with B=1 should not transfer a second byte");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles DD-ED terminal get state");
    ASSERT_EQ_INT(0x00, (cpu_reg_pair16(cpu.bc) >> 8) & 0xFFu,
                  "DD-prefixed INIR should finish with B decremented to zero");

    remove(rom_path);
}

/* ============================================================
 * run_cycles timing check: canonical ED extension sequence
 * ============================================================ */
static void test_emulator_run_cycles_ed_extension_timing(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    ez80_status_t status;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        0xDD, 0x21, 0x00, 0x10, /* LD IX,0x1000        (14) */
        0xFD, 0x21, 0x00, 0x20, /* LD IY,0x2000        (14) */
        0xED, 0x12, 0xFE,       /* LEA DE,IX-2         (6) */
        0xED, 0x03, 0x02,       /* LEA BC,IY+2         (6) */
        0xED, 0x22, 0x01,       /* LEA HL,IX+1         (6) */
        0xED, 0x32, 0x01,       /* LEA IX,IX+1         (6) */
        0xED, 0x30,             /* LD IY,(HL)          (10) */
        0xED, 0x31, 0x10,       /* OUT0 (0x10),0 alias (12) */
        0xED, 0x37,             /* LD IX,(HL)          (10) */
        0x76                    /* HALT                (4)  */
    };

    printf("[TEST] emulator run_cycles canonical ED extension timing check\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create run_cycles canonical ED extension timing ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles canonical ED timing init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles canonical ED timing ROM load");

    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x1001u, 0x34u),
                  "run_cycles canonical ED timing seed [0x1001] low");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x1002u, 0x12u),
                  "run_cycles canonical ED timing seed [0x1002] high");

    status = ez80_emulator_run_cycles(&emu, 200u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles canonical ED timing run");
    ASSERT_TRUE(run_result.hit_halt, "run_cycles canonical ED timing should reach HALT");
    ASSERT_EQ_U32(88u, run_result.cycles_executed,
                  "run_cycles should match documented cycle totals for canonical ED sequence");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "run_cycles canonical ED timing get state");
    ASSERT_EQ_INT(0x0FFE, cpu_reg_pair16(cpu.de), "LEA DE,IX-2 should produce DE=0x0FFE");
    ASSERT_EQ_INT(0x2002, cpu_reg_pair16(cpu.bc), "LEA BC,IY+2 should produce BC=0x2002");
    ASSERT_EQ_INT(0x1001, cpu_reg_pair16(cpu.hl), "LEA HL,IX+1 should produce HL=0x1001");
    ASSERT_EQ_INT(0x1234, cpu_reg_pair16(cpu.iy), "ED 30 should load IY=0x1234");
    ASSERT_EQ_INT(0x1234, cpu_reg_pair16(cpu.ix), "ED 37 should load IX=0x1234");
    ASSERT_EQ_INT(0x00, emu.memory.ports[0x10], "ED 31 alias should output zero to port 0x10");

    remove(rom_path);
}

/* ============================================================
 * Regression: indexed displacement wraps in 16-bit window
 * ============================================================ */
static void test_emulator_indexed_displacement_wraparound_regression(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        0xDD, 0x21, 0x00, 0x00, /* LD IX,0x0000 */
        0x3E, 0xA5,             /* LD A,0xA5 */
        0xDD, 0x77, 0xFF,       /* LD (IX-1),A -> wraps to 0xFFFF */
        0x3E, 0x00,             /* LD A,0x00 */
        0xDD, 0x7E, 0xFF,       /* LD A,(IX-1) */
        0xDD, 0x21, 0xFF, 0xFF, /* LD IX,0xFFFF */
        0x3E, 0x5A,             /* LD A,0x5A */
        0xDD, 0x77, 0x01,       /* LD (IX+1),A -> wraps to 0x0000 */
        0x3E, 0x00,             /* LD A,0x00 */
        0xDD, 0x7E, 0x01,       /* LD A,(IX+1) */
        0x76                    /* HALT */
    };

    printf("[TEST] emulator indexed displacement wraparound regression\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create indexed displacement wraparound ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "indexed wrap init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "indexed wrap ROM load");

    /* LD IX,0x0000 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IX,0x0000");

    /* LD A,0xA5 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,0xA5");

    /* LD (IX-1),A */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD (IX-1),A");

    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0xFFFFu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read wrapped store at RAM+0xFFFF");
    ASSERT_EQ_INT(0xA5, value, "wrapped (IX-1) store should land at RAM+0xFFFF");

    /* LD A,0x00 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,0x00 before wrapped load");

    /* LD A,(IX-1) */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,(IX-1)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xA5, cpu_reg_a(&cpu), "wrapped (IX-1) load should read RAM+0xFFFF");

    /* LD IX,0xFFFF */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IX,0xFFFF");

    /* LD A,0x5A */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,0x5A");

    /* LD (IX+1),A */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD (IX+1),A");

    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x0000u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read wrapped store at RAM+0x0000");
    ASSERT_EQ_INT(0x5A, value, "wrapped (IX+1) store should land at RAM+0x0000");

    /* LD A,0x00 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,0x00 before +1 load");

    /* LD A,(IX+1) */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,(IX+1)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x5A, cpu_reg_a(&cpu), "wrapped (IX+1) load should read RAM+0x0000");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step HALT after indexed wrap regression");

    remove(rom_path);
}

/* ============================================================
 * IXH/IXL edge cases: overflow, zero, sign
 * ============================================================ */
static void test_emulator_ixiy_half_reg_edge_cases(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        /* IXH wrap: INC from 0xFF -> 0x00 (Z set, H set) */
        0xDD, 0x26, 0xFF,     /* LD IXH,0xFF */
        0xDD, 0x24,           /* INC IXH -> 0x00 */

        /* IXL wrap: DEC from 0x00 -> 0xFF (S set, H set) */
        0xDD, 0x2E, 0x00,     /* LD IXL,0x00 */
        0xDD, 0x2D,           /* DEC IXL -> 0xFF */

        /* IXH overflow: INC from 0x7F -> 0x80 (PV set) */
        0xDD, 0x26, 0x7F,     /* LD IXH,0x7F */
        0xDD, 0x24,           /* INC IXH -> 0x80 (overflow) */

        /* IXL underflow: DEC from 0x80 -> 0x7F (PV set) */
        0xDD, 0x2E, 0x80,     /* LD IXL,0x80 */
        0xDD, 0x2D,           /* DEC IXL -> 0x7F (overflow) */

        /* ALU: CP IXH (compare without storing) */
        0x3E, 0x80,           /* LD A,0x80 */
        0xDD, 0x26, 0x80,     /* LD IXH,0x80 */
        0xDD, 0xBC,           /* CP IXH (A==IXH -> Z set) */

        /* ALU: XOR IXL */
        0xDD, 0x2E, 0xFF,     /* LD IXL,0xFF */
        0xDD, 0xAD,           /* XOR IXL (0x80^0xFF=0x7F) */

        0x76                  /* HALT */
    };

    printf("[TEST] emulator IXH/IXL edge cases (overflow, wrap, ALU)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create IXH edge ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "IXH edge init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "IXH edge ROM load");

    /* LD IXH,0xFF */
    ez80_emulator_step(&emu, &decoded);
    /* INC IXH -> 0x00 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INC IXH (0xFF)");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x00, (cpu.ix >> 8) & 0xFF, "IXH 0xFF+1=0x00");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0, "INC IXH wrap: Z set");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_H) != 0, "INC IXH wrap: H set");

    /* LD IXL,0x00 */
    ez80_emulator_step(&emu, &decoded);
    /* DEC IXL -> 0xFF */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step DEC IXL (0x00)");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xFF, cpu.ix & 0xFF, "IXL 0x00-1=0xFF");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_S) != 0, "DEC IXL wrap: S set");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_H) != 0, "DEC IXL wrap: H set");

    /* LD IXH,0x7F */
    ez80_emulator_step(&emu, &decoded);
    /* INC IXH -> 0x80 (overflow) */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INC IXH (0x7F)");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x80, (cpu.ix >> 8) & 0xFF, "IXH 0x7F+1=0x80");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_PV) != 0, "INC IXH overflow: PV set");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_S) != 0, "INC IXH overflow: S set");

    /* LD IXL,0x80 */
    ez80_emulator_step(&emu, &decoded);
    /* DEC IXL -> 0x7F (overflow) */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step DEC IXL (0x80)");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x7F, cpu.ix & 0xFF, "IXL 0x80-1=0x7F");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_PV) != 0, "DEC IXL overflow: PV set");

    /* LD A,0x80 */
    ez80_emulator_step(&emu, &decoded);
    /* LD IXH,0x80 */
    ez80_emulator_step(&emu, &decoded);
    /* CP IXH: A==IXH -> Z set */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step CP IXH");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x80, cpu_reg_a(&cpu), "CP should not modify A");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0, "CP IXH: A==IXH -> Z set");

    /* LD IXL,0xFF */
    ez80_emulator_step(&emu, &decoded);
    /* XOR IXL: 0x80^0xFF=0x7F */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step XOR IXL");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x7F, cpu_reg_a(&cpu), "XOR IXL: 0x80^0xFF=0x7F");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) == 0, "XOR IXL: non-zero, Z clear");

    /* HALT */
    ez80_emulator_step(&emu, &decoded);

    remove(rom_path);
}

/* ============================================================
 * Existing DAA H-flag bug audit + CCF behavior
 * ============================================================ */
static void test_emulator_daa_ccf_flag_audit(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        /* DAA after ADD: 0x09 + 0x01 = 0x0A -> DAA -> 0x10 */
        0x3E, 0x09,           /* LD A,0x09 */
        0xC6, 0x01,           /* ADD A,0x01 -> A=0x0A */
        0x27,                 /* DAA -> A=0x10 (BCD adjust) */

        /* DAA after SUB: 0x10 - 0x01 = 0x0F (N set) -> DAA -> 0x09 */
        0xD6, 0x01,           /* SUB 0x01 -> A=0x0F, N set */
        0x27,                 /* DAA -> A=0x09 */

        /* CCF: toggle carry */
        0x37,                 /* SCF (C=1) */
        0x3F,                 /* CCF (C=0, H should reflect old C) */
        0x3F,                 /* CCF (C=1, H=0) */

        0x76                  /* HALT */
    };

    printf("[TEST] emulator DAA + CCF flag audit\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create DAA/CCF ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "DAA/CCF init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "DAA/CCF ROM load");

    /* LD A,0x09 */
    ez80_emulator_step(&emu, &decoded);
    /* ADD A,0x01 -> 0x0A */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x0A, cpu_reg_a(&cpu), "ADD: 0x09+0x01=0x0A");

    /* DAA -> 0x10 (BCD correction for low nibble > 9) */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step DAA after ADD");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x10, cpu_reg_a(&cpu), "DAA: 0x0A -> 0x10");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_N) == 0, "DAA after ADD: N clear");

    /* SUB 0x01 -> 0x0F */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x0F, cpu_reg_a(&cpu), "SUB: 0x10-0x01=0x0F");

    /* DAA -> 0x09 (BCD after subtract) */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step DAA after SUB");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x09, cpu_reg_a(&cpu), "DAA after SUB: 0x0F -> 0x09");

    /* SCF -> C=1 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_C) != 0, "SCF: C set");

    /* CCF -> C=0, H=(old C)=1 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_C) == 0, "CCF: C toggled to 0");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_H) != 0, "CCF: H reflects old C=1");

    /* CCF -> C=1, H=(old C)=0 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_C) != 0, "CCF: C toggled to 1");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_H) == 0, "CCF: H reflects old C=0");

    /* HALT */
    ez80_emulator_step(&emu, &decoded);

    remove(rom_path);
}

/* ============================================================
 * eZ80 pair load/store extensions + DD/FD prefix-ignore fallback
 * ============================================================ */
static void test_emulator_pair_load_store_and_ddfd_prefix_ignore(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        0x21, 0x00, 0x40,     /* LD HL,0x4000 */
        0xED, 0x07,           /* LD BC,(HL) */
        0xED, 0x0F,           /* LD (HL),BC */
        0xED, 0x30,           /* LD IY,(HL) */
        0xED, 0x37,           /* LD IX,(HL) */
        0xDD, 0x21, 0x10, 0x40, /* LD IX,0x4010 */
        0xED, 0x3E,           /* LD (HL),IX */
        0xED, 0x3F,           /* LD (HL),IY */
        0xFD, 0x21, 0x20, 0x40, /* LD IY,0x4020 */
        0xDD, 0x07, 0x00,     /* LD BC,(IX+0) */
        0xDD, 0x0F, 0x02,     /* LD (IX+2),BC */
        0xDD, 0x31, 0x02,     /* LD IX,(IX+2) */
        0xDD, 0x3E, 0x04,     /* LD (IX+4),IY */
        0xFD, 0x37, 0xF0,     /* LD IX,(IY-16) */
        0x3E, 0x10,           /* LD A,0x10 */
        0xDD, 0x3C,           /* INC A (prefix-ignored alias) */
        0xFD, 0x47,           /* LD B,A (prefix-ignored alias) */
        0x76                  /* HALT */
    };

    printf("[TEST] emulator pair load/store extensions + DD/FD prefix-ignore aliases\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create pair-load/store + prefix-ignore ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "pair+prefix init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "pair+prefix ROM load");

    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4000u, 0x34u), "seed [0x4000] low");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4001u, 0x12u), "seed [0x4001] high");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4010u, 0x78u), "seed [0x4010] low");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4011u, 0x56u), "seed [0x4011] high");

    status = ez80_emulator_step(&emu, &decoded); /* LD HL,0x4000 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD HL,0x4000");

    status = ez80_emulator_step(&emu, &decoded); /* ED 07 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD BC,(HL)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after LD BC,(HL)");
    ASSERT_EQ_INT(0x1234, cpu_reg_pair16(cpu.bc), "LD BC,(HL) should load 0x1234");

    status = ez80_emulator_step(&emu, &decoded); /* ED 0F */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD (HL),BC");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value), "read [0x4000] after ED 0F");
    ASSERT_EQ_INT(0x34, value, "ED 0F low-byte store");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value), "read [0x4001] after ED 0F");
    ASSERT_EQ_INT(0x12, value, "ED 0F high-byte store");

    status = ez80_emulator_step(&emu, &decoded); /* ED 30 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IY,(HL)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after ED 30");
    ASSERT_EQ_INT(0x1234, cpu_reg_pair16(cpu.iy), "ED 30 should load IY=0x1234");

    status = ez80_emulator_step(&emu, &decoded); /* ED 37 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IX,(HL)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after ED 37");
    ASSERT_EQ_INT(0x1234, cpu_reg_pair16(cpu.ix), "ED 37 should load IX=0x1234");

    status = ez80_emulator_step(&emu, &decoded); /* LD IX,0x4010 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IX,0x4010");

    status = ez80_emulator_step(&emu, &decoded); /* ED 3E */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD (HL),IX");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value), "read [0x4000] after ED 3E");
    ASSERT_EQ_INT(0x10, value, "ED 3E low-byte store from IX");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value), "read [0x4001] after ED 3E");
    ASSERT_EQ_INT(0x40, value, "ED 3E high-byte store from IX");

    status = ez80_emulator_step(&emu, &decoded); /* ED 3F */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD (HL),IY");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value), "read [0x4000] after ED 3F");
    ASSERT_EQ_INT(0x34, value, "ED 3F low-byte store from IY");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value), "read [0x4001] after ED 3F");
    ASSERT_EQ_INT(0x12, value, "ED 3F high-byte store from IY");

    status = ez80_emulator_step(&emu, &decoded); /* LD IY,0x4020 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IY,0x4020");

    status = ez80_emulator_step(&emu, &decoded); /* DD 07 00 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD BC,(IX+0)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after DD 07");
    ASSERT_EQ_INT(0x5678, cpu_reg_pair16(cpu.bc), "DD 07 should load BC=0x5678");

    status = ez80_emulator_step(&emu, &decoded); /* DD 0F 02 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD (IX+2),BC");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4012u, &value), "read [0x4012] low after DD 0F");
    ASSERT_EQ_INT(0x78, value, "DD 0F low-byte store");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4013u, &value), "read [0x4013] high after DD 0F");
    ASSERT_EQ_INT(0x56, value, "DD 0F high-byte store");

    status = ez80_emulator_step(&emu, &decoded); /* DD 31 02 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IX,(IX+2)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after DD 31");
    ASSERT_EQ_INT(0x5678, cpu_reg_pair16(cpu.ix), "DD 31 should load IX=0x5678");

    status = ez80_emulator_step(&emu, &decoded); /* DD 3E 04 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD (IX+4),IY");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x567Cu, &value), "read [0x567C] low after DD 3E");
    ASSERT_EQ_INT(0x20, value, "DD 3E low-byte store from IY");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x567Du, &value), "read [0x567D] high after DD 3E");
    ASSERT_EQ_INT(0x40, value, "DD 3E high-byte store from IY");

    status = ez80_emulator_step(&emu, &decoded); /* FD 37 F0 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD IX,(IY-16)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after FD 37");
    ASSERT_EQ_INT(0x5678, cpu_reg_pair16(cpu.ix), "FD 37 should cross-load IX from (IY-16)");

    status = ez80_emulator_step(&emu, &decoded); /* LD A,0x10 */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD A,0x10");
    status = ez80_emulator_step(&emu, &decoded); /* DD 3C */
    ASSERT_EQ_INT(EZ80_OK, status, "step DD 3C prefix-ignore INC A");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after DD 3C");
    ASSERT_EQ_INT(0x11, cpu_reg_a(&cpu), "DD 3C should behave as INC A");

    status = ez80_emulator_step(&emu, &decoded); /* FD 47 */
    ASSERT_EQ_INT(EZ80_OK, status, "step FD 47 prefix-ignore LD B,A");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "state after FD 47");
    ASSERT_EQ_INT(0x11, (cpu.bc >> 8) & 0xFFu, "FD 47 should behave as LD B,A");

    status = ez80_emulator_step(&emu, &decoded); /* HALT */
    ASSERT_EQ_INT(EZ80_OK, status, "step HALT after pair+prefix test");

    remove(rom_path);
}

static void test_emulator_adl_multibyte_pair_load_store(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        0x21, 0x00, 0x40, 0x00,       /* LD HL,0x004000 */
        0xED, 0x07,                   /* LD BC,(HL) */
        0xED, 0x30,                   /* LD IY,(HL) */
        0xED, 0x37,                   /* LD IX,(HL) */
        0xDD, 0x21, 0x44, 0x55, 0x66, /* LD IX,0x665544 */
        0xFD, 0x21, 0x77, 0x88, 0x99, /* LD IY,0x998877 */
        0xED, 0x0F,                   /* LD (HL),BC */
        0xED, 0x3E,                   /* LD (HL),IX */
        0xED, 0x3F,                   /* LD (HL),IY */
        0xDD, 0x21, 0x10, 0x40, 0x00, /* LD IX,0x004010 */
        0xFD, 0x21, 0x77, 0x88, 0x99, /* LD IY,0x998877 */
        0xDD, 0x07, 0x00,             /* LD BC,(IX+0) */
        0xDD, 0x0F, 0x03,             /* LD (IX+3),BC */
        0xDD, 0x3E, 0x06,             /* LD (IX+6),IY */
        0xDD, 0x31, 0x03,             /* LD IX,(IX+3) */
        0x76
    };

    printf("[TEST] emulator ADL multibyte pair/index load-store width\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL multibyte pair-load/store ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair ROM load");

    emu.cpu.adl_mode = true;
    emu.cpu.adl_encoding = true;

    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4000u, 0x12u), "seed ADL [0x4000]");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4001u, 0x34u), "seed ADL [0x4001]");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4002u, 0x56u), "seed ADL [0x4002]");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4010u, 0xABu), "seed ADL [0x4010]");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4011u, 0xCDu), "seed ADL [0x4011]");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4012u, 0xEFu), "seed ADL [0x4012]");

    status = ez80_emulator_step(&emu, &decoded); /* LD HL,0x004000 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD HL");

    status = ez80_emulator_step(&emu, &decoded); /* LD BC,(HL) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD BC,(HL)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair state after LD BC,(HL)");
    ASSERT_EQ_U32(0x563412u, cpu.bc, "ADL LD BC,(HL) should load 24-bit BC");

    status = ez80_emulator_step(&emu, &decoded); /* LD IY,(HL) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD IY,(HL)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair state after LD IY,(HL)");
    ASSERT_EQ_U32(0x563412u, cpu.iy, "ADL LD IY,(HL) should load 24-bit IY");

    status = ez80_emulator_step(&emu, &decoded); /* LD IX,(HL) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD IX,(HL)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair state after LD IX,(HL)");
    ASSERT_EQ_U32(0x563412u, cpu.ix, "ADL LD IX,(HL) should load 24-bit IX");

    status = ez80_emulator_step(&emu, &decoded); /* LD IX,0x665544 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD IX,0x665544");
    status = ez80_emulator_step(&emu, &decoded); /* LD IY,0x998877 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD IY,0x998877");

    status = ez80_emulator_step(&emu, &decoded); /* LD (HL),BC */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD (HL),BC");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4002u, &value), "read ADL [0x4002] after BC store");
    ASSERT_EQ_INT(0x56, value, "ADL LD (HL),BC should store third byte");

    status = ez80_emulator_step(&emu, &decoded); /* LD (HL),IX */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD (HL),IX");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value), "read ADL [0x4000] after IX store");
    ASSERT_EQ_INT(0x44, value, "ADL LD (HL),IX low byte");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value), "read ADL [0x4001] after IX store");
    ASSERT_EQ_INT(0x55, value, "ADL LD (HL),IX middle byte");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4002u, &value), "read ADL [0x4002] after IX store");
    ASSERT_EQ_INT(0x66, value, "ADL LD (HL),IX high byte");

    status = ez80_emulator_step(&emu, &decoded); /* LD (HL),IY */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD (HL),IY");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value), "read ADL [0x4000] after IY store");
    ASSERT_EQ_INT(0x77, value, "ADL LD (HL),IY low byte");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value), "read ADL [0x4001] after IY store");
    ASSERT_EQ_INT(0x88, value, "ADL LD (HL),IY middle byte");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4002u, &value), "read ADL [0x4002] after IY store");
    ASSERT_EQ_INT(0x99, value, "ADL LD (HL),IY high byte");

    status = ez80_emulator_step(&emu, &decoded); /* LD IX,0x004010 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD IX,0x004010");
    status = ez80_emulator_step(&emu, &decoded); /* LD IY,0x998877 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step reload IY");

    status = ez80_emulator_step(&emu, &decoded); /* LD BC,(IX+0) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD BC,(IX+0)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair state after LD BC,(IX+0)");
    ASSERT_EQ_U32(0xEFCDABu, cpu.bc, "ADL DD 07 should load 24-bit BC");

    status = ez80_emulator_step(&emu, &decoded); /* LD (IX+3),BC */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD (IX+3),BC");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4015u, &value), "read ADL [0x4015] after DD 0F");
    ASSERT_EQ_INT(0xEF, value, "ADL DD 0F should store third byte");

    status = ez80_emulator_step(&emu, &decoded); /* LD (IX+6),IY */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD (IX+6),IY");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4016u, &value), "read ADL [0x4016] after DD 3E");
    ASSERT_EQ_INT(0x77, value, "ADL DD 3E low byte");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4017u, &value), "read ADL [0x4017] after DD 3E");
    ASSERT_EQ_INT(0x88, value, "ADL DD 3E middle byte");
    ASSERT_EQ_INT(EZ80_OK, ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4018u, &value), "read ADL [0x4018] after DD 3E");
    ASSERT_EQ_INT(0x99, value, "ADL DD 3E high byte");

    status = ez80_emulator_step(&emu, &decoded); /* LD IX,(IX+3) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step LD IX,(IX+3)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair state after LD IX,(IX+3)");
    ASSERT_EQ_U32(0xEFCDABu, cpu.ix, "ADL DD 31 should load 24-bit IX");

    status = ez80_emulator_step(&emu, &decoded); /* HALT */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL multibyte pair step HALT");

    remove(rom_path);
}

/* ============================================================
 * ADD IX,IX / ADD IY,IY regression — must double the index
 * register, not add HL to it
 * ============================================================ */
static void test_emulator_add_index_self(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        0xDD, 0x21, 0x00, 0x10,   /* LD IX,0x1000 */
        0x21, 0xFF, 0xFF,         /* LD HL,0xFFFF (different from IX) */
        0xDD, 0x29,               /* ADD IX,IX -> should give 0x2000, NOT IX+HL */

        0xFD, 0x21, 0x80, 0x20,   /* LD IY,0x2080 */
        0x21, 0x00, 0x00,         /* LD HL,0x0000 */
        0xFD, 0x29,               /* ADD IY,IY -> should give 0x4100, NOT IY+HL */

        /* Edge: ADD IX,IX with carry-generating value */
        0xDD, 0x21, 0x00, 0x80,   /* LD IX,0x8000 */
        0xDD, 0x29,               /* ADD IX,IX -> 0x0000, carry set */

        0x76                      /* HALT */
    };

    printf("[TEST] emulator ADD IX,IX / ADD IY,IY self-add regression\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADD index self ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADD IX,IX init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADD IX,IX ROM load");

    /* LD IX,0x1000 */
    ez80_emulator_step(&emu, &decoded);
    /* LD HL,0xFFFF */
    ez80_emulator_step(&emu, &decoded);
    /* ADD IX,IX */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step ADD IX,IX");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x2000, cpu_reg_pair16(cpu.ix), "ADD IX,IX: 0x1000+0x1000=0x2000");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_C) == 0, "ADD IX,IX: no carry");

    /* LD IY,0x2080 */
    ez80_emulator_step(&emu, &decoded);
    /* LD HL,0x0000 */
    ez80_emulator_step(&emu, &decoded);
    /* ADD IY,IY */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step ADD IY,IY");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x4100, cpu_reg_pair16(cpu.iy), "ADD IY,IY: 0x2080+0x2080=0x4100");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_C) == 0, "ADD IY,IY: no carry");

    /* LD IX,0x8000 */
    ez80_emulator_step(&emu, &decoded);
    /* ADD IX,IX -> 0x0000, carry set */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step ADD IX,IX overflow");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x0000, cpu_reg_pair16(cpu.ix), "ADD IX,IX: 0x8000+0x8000=0x0000");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_C) != 0, "ADD IX,IX overflow: carry set");

    /* HALT */
    ez80_emulator_step(&emu, &decoded);
    remove(rom_path);
}

/* ============================================================
 * eZ80 extended block I/O: INIM, OTIM, INI2, OTI2
 * ============================================================ */
static void test_emulator_ez80_block_io_increment(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        /* Setup: B=3, C=0x10, HL=0x2000 */
        0x06, 0x03,               /* LD B,3 */
        0x0E, 0x10,               /* LD C,0x10 */
        0x21, 0x00, 0x20,         /* LD HL,0x2000 */

        /* INIM: IN (C)->(HL), HL++, C++, B-- */
        0xED, 0x82,               /* INIM */

        /* OTIM: (HL)->OUT (C), HL++, C++, B-- */
        0xED, 0x83,               /* OTIM */

        /* INI2: IN (C)->(HL), HL++, B-- (C unchanged) */
        0xED, 0x84,               /* INI2 */

        /* OTI2: (HL)->OUT (C), HL++, B-- (C unchanged) */
        0x06, 0x02,               /* LD B,2 */
        0xED, 0x85,               /* OTI2 */

        0x76                      /* HALT */
    };

    printf("[TEST] emulator eZ80 INIM/OTIM/INI2/OTI2 block I/O\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create eZ80 block I/O incr ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 block IO incr init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 block IO incr ROM load");

    /* Seed port 0x10 with test data */
    emu.memory.ports[0x10] = 0xAA;
    emu.memory.ports[0x11] = 0xBB;
    emu.memory.ports[0x12] = 0xCC;
    /* Seed RAM at 0x2001 for OTIM/OTI2 */
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2001u, 0xDD);

    /* LD B,3; LD C,0x10; LD HL,0x2000 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);

    /* INIM: reads port 0x10 (0xAA) -> (HL=0x2000), HL->0x2001, C->0x11, B->2 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INIM");
    ez80_emulator_get_state(&emu, &cpu);
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x2000u, &value);
    ASSERT_EQ_INT(0xAA, value, "INIM: port 0x10 data -> (0x2000)");
    ASSERT_EQ_INT(0x2001, cpu_reg_pair16(cpu.hl), "INIM: HL incremented to 0x2001");
    ASSERT_EQ_INT(0x11, cpu.bc & 0xFF, "INIM: C incremented to 0x11");
    ASSERT_EQ_INT(0x02, (cpu.bc >> 8) & 0xFF, "INIM: B decremented to 2");

    /* OTIM: reads (HL=0x2001)=0xDD -> OUT port 0x11, HL->0x2002, C->0x12, B->1 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTIM");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xDD, emu.memory.ports[0x11], "OTIM: (0x2001) -> port 0x11");
    ASSERT_EQ_INT(0x2002, cpu_reg_pair16(cpu.hl), "OTIM: HL incremented to 0x2002");
    ASSERT_EQ_INT(0x12, cpu.bc & 0xFF, "OTIM: C incremented to 0x12");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFF, "OTIM: B decremented to 1");

    /* INI2: reads port 0x12 (0xCC) -> (HL=0x2002), HL->0x2003, C stays 0x12, B->0 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INI2");
    ez80_emulator_get_state(&emu, &cpu);
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x2002u, &value);
    ASSERT_EQ_INT(0xCC, value, "INI2: port 0x12 data -> (0x2002)");
    ASSERT_EQ_INT(0x2003, cpu_reg_pair16(cpu.hl), "INI2: HL incremented to 0x2003");
    ASSERT_EQ_INT(0x12, cpu.bc & 0xFF, "INI2: C unchanged at 0x12");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFF, "INI2: B decremented to 0");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0, "INI2: Z set when B==0");

    /* LD B,2; OTI2: reads (HL=0x2003), out to port, HL++, B-- */
    ez80_emulator_step(&emu, &decoded);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2003u, 0xEE);
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTI2");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xEE, emu.memory.ports[0x12], "OTI2: (0x2003) -> port 0x12");
    ASSERT_EQ_INT(0x2004, cpu_reg_pair16(cpu.hl), "OTI2: HL incremented to 0x2004");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFF, "OTI2: B decremented to 1");

    /* HALT */
    ez80_emulator_step(&emu, &decoded);
    remove(rom_path);
}

/* ============================================================
 * eZ80 extended block I/O: INDM, OTDM, IND2, OTD2
 * ============================================================ */
static void test_emulator_ez80_block_io_decrement(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        /* Setup: B=3, C=0x20, HL=0x3000 */
        0x06, 0x03,               /* LD B,3 */
        0x0E, 0x20,               /* LD C,0x20 */
        0x21, 0x00, 0x30,         /* LD HL,0x3000 */

        /* INDM: IN (C)->(HL), HL--, C--, B-- */
        0xED, 0x8A,               /* INDM */

        /* OTDM: (HL)->OUT (C), HL--, C--, B-- */
        0xED, 0x8B,               /* OTDM */

        /* IND2: IN (C)->(HL), HL--, B-- (C unchanged) */
        0xED, 0x8C,               /* IND2 */

        /* OTD2: (HL)->OUT (C), HL--, B-- (C unchanged) */
        0x06, 0x02,               /* LD B,2 */
        0xED, 0x8D,               /* OTD2 */

        0x76                      /* HALT */
    };

    printf("[TEST] emulator eZ80 INDM/OTDM/IND2/OTD2 block I/O\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create eZ80 block I/O decr ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 block IO decr init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 block IO decr ROM load");

    /* Seed ports */
    emu.memory.ports[0x20] = 0x11;
    emu.memory.ports[0x1F] = 0x22;
    emu.memory.ports[0x1E] = 0x33;
    /* Seed RAM for OTDM/OTD2 */
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2FFFu, 0x44);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2FFEu, 0x55);

    /* LD B,3; LD C,0x20; LD HL,0x3000 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);

    /* INDM: reads port 0x20 (0x11) -> (HL=0x3000), HL->0x2FFF, C->0x1F, B->2 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INDM");
    ez80_emulator_get_state(&emu, &cpu);
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x3000u, &value);
    ASSERT_EQ_INT(0x11, value, "INDM: port 0x20 data -> (0x3000)");
    ASSERT_EQ_INT(0x2FFF, cpu_reg_pair16(cpu.hl), "INDM: HL decremented to 0x2FFF");
    ASSERT_EQ_INT(0x1F, cpu.bc & 0xFF, "INDM: C decremented to 0x1F");
    ASSERT_EQ_INT(0x02, (cpu.bc >> 8) & 0xFF, "INDM: B decremented to 2");

    /* OTDM: reads (HL=0x2FFF)=0x44 -> OUT port 0x1F, HL->0x2FFE, C->0x1E, B->1 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTDM");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x44, emu.memory.ports[0x1F], "OTDM: (0x2FFF) -> port 0x1F");
    ASSERT_EQ_INT(0x2FFE, cpu_reg_pair16(cpu.hl), "OTDM: HL decremented to 0x2FFE");
    ASSERT_EQ_INT(0x1E, cpu.bc & 0xFF, "OTDM: C decremented to 0x1E");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFF, "OTDM: B decremented to 1");

    /* IND2: reads port 0x1E (0x33) -> (HL=0x2FFE), HL->0x2FFD, C stays 0x1E, B->0 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step IND2");
    ez80_emulator_get_state(&emu, &cpu);
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x2FFEu, &value);
    ASSERT_EQ_INT(0x33, value, "IND2: port 0x1E data -> (0x2FFE)");
    ASSERT_EQ_INT(0x2FFD, cpu_reg_pair16(cpu.hl), "IND2: HL decremented to 0x2FFD");
    ASSERT_EQ_INT(0x1E, cpu.bc & 0xFF, "IND2: C unchanged at 0x1E");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFF, "IND2: B decremented to 0");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0, "IND2: Z set when B==0");

    /* LD B,2; OTD2 */
    ez80_emulator_step(&emu, &decoded);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2FFDu, 0x77);
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTD2");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x77, emu.memory.ports[0x1E], "OTD2: (0x2FFD) -> port 0x1E");
    ASSERT_EQ_INT(0x2FFC, cpu_reg_pair16(cpu.hl), "OTD2: HL decremented to 0x2FFC");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFF, "OTD2: B decremented to 1");

    /* HALT */
    ez80_emulator_step(&emu, &decoded);
    remove(rom_path);
}

/* ============================================================
 * eZ80 ED A4/A5/AC/AD/B4/B5/BC/BD block I/O aliases + wraparound edges
 * ============================================================ */
static void test_emulator_ez80_block_io_out2_aliases(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        0xED, 0xA4,               /* OUTI2 (single) */
        0xED, 0xAC,               /* OUTD2 (single) */
        0xED, 0xB4,               /* OTI2R (repeat) */
        0xED, 0xBC,               /* OTD2R (repeat) */
        0xED, 0xA5,               /* OTI2 alias (single) */
        0xED, 0xAD,               /* OTD2 alias (single) */
        0xED, 0xB5,               /* OTI2R alias (repeat) */
        0xED, 0xBD,               /* OTD2R alias (repeat) */
        0x76                      /* HALT */
    };

    printf("[TEST] emulator eZ80 OUTI2/OUTD2/OTI2R/OTD2R aliases (A4/A5/AC/AD/B4/B5/BC/BD) + wraparound\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create eZ80 OUTI2 alias ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 OUTI2 alias init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 OUTI2 alias ROM load");

    /* OUTI2 (A4): C wraps 0xFF -> 0x00, B decrements, HL increments */
    emu.cpu.bc = 0x000001FFu;
    emu.cpu.hl = 0x00002200u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2200u, 0x55u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OUTI2 source byte");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OUTI2 (ED A4)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OUTI2 get state");
    ASSERT_EQ_INT(0x55, emu.memory.ports[0xFF], "OUTI2: writes source byte to port 0xFF");
    ASSERT_EQ_INT(0x2201, cpu_reg_pair16(cpu.hl), "OUTI2: HL increments");
    ASSERT_EQ_INT(0x00, cpu.bc & 0xFFu, "OUTI2: C wraps to 0x00");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OUTI2: B decrements to 0");
    ASSERT_EQ_U32(0x000002u, cpu.pc, "OUTI2: PC advances to next opcode");

    /* OUTD2 (AC): C wraps 0x00 -> 0xFF, B decrements, HL decrements */
    emu.cpu.bc = 0x00000100u;
    emu.cpu.hl = 0x00002300u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2300u, 0x66u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OUTD2 source byte");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OUTD2 (ED AC)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OUTD2 get state");
    ASSERT_EQ_INT(0x66, emu.memory.ports[0x00], "OUTD2: writes source byte to port 0x00");
    ASSERT_EQ_INT(0x22FF, cpu_reg_pair16(cpu.hl), "OUTD2: HL decrements");
    ASSERT_EQ_INT(0xFF, cpu.bc & 0xFFu, "OUTD2: C wraps to 0xFF");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OUTD2: B decrements to 0");
    ASSERT_EQ_U32(0x000004u, cpu.pc, "OUTD2: PC advances to next opcode");

    /* OTI2R (B4): repeat path when B!=0, then fall through when B==0 */
    emu.cpu.bc = 0x000002FFu;
    emu.cpu.hl = 0x00002400u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2400u, 0xA1u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTI2R source byte 0");
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2401u, 0xA2u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTI2R source byte 1");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTI2R iter1 (ED B4)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTI2R iter1 get state");
    ASSERT_EQ_INT(0xA1, emu.memory.ports[0xFF], "OTI2R iter1: writes first byte to port 0xFF");
    ASSERT_EQ_INT(0x2401, cpu_reg_pair16(cpu.hl), "OTI2R iter1: HL increments");
    ASSERT_EQ_INT(0x00, cpu.bc & 0xFFu, "OTI2R iter1: C wraps to 0x00");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFFu, "OTI2R iter1: B decrements to 1");
    ASSERT_EQ_U32(0x000004u, cpu.pc, "OTI2R iter1: repeats at same PC");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTI2R iter2 (ED B4)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTI2R iter2 get state");
    ASSERT_EQ_INT(0xA2, emu.memory.ports[0x00], "OTI2R iter2: writes second byte to port 0x00");
    ASSERT_EQ_INT(0x2402, cpu_reg_pair16(cpu.hl), "OTI2R iter2: HL increments again");
    ASSERT_EQ_INT(0x01, cpu.bc & 0xFFu, "OTI2R iter2: C increments to 0x01");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OTI2R iter2: B decrements to 0");
    ASSERT_EQ_U32(0x000006u, cpu.pc, "OTI2R iter2: falls through when B==0");

    /* OTD2R (BC): repeat path when B!=0, then fall through when B==0 */
    emu.cpu.bc = 0x00000200u;
    emu.cpu.hl = 0x00002501u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2501u, 0xB1u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTD2R source byte 0");
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2500u, 0xB2u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTD2R source byte 1");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTD2R iter1 (ED BC)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTD2R iter1 get state");
    ASSERT_EQ_INT(0xB1, emu.memory.ports[0x00], "OTD2R iter1: writes first byte to port 0x00");
    ASSERT_EQ_INT(0x2500, cpu_reg_pair16(cpu.hl), "OTD2R iter1: HL decrements");
    ASSERT_EQ_INT(0xFF, cpu.bc & 0xFFu, "OTD2R iter1: C wraps to 0xFF");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFFu, "OTD2R iter1: B decrements to 1");
    ASSERT_EQ_U32(0x000006u, cpu.pc, "OTD2R iter1: repeats at same PC");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTD2R iter2 (ED BC)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTD2R iter2 get state");
    ASSERT_EQ_INT(0xB2, emu.memory.ports[0xFF], "OTD2R iter2: writes second byte to port 0xFF");
    ASSERT_EQ_INT(0x24FF, cpu_reg_pair16(cpu.hl), "OTD2R iter2: HL decrements again");
    ASSERT_EQ_INT(0xFE, cpu.bc & 0xFFu, "OTD2R iter2: C decrements to 0xFE");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OTD2R iter2: B decrements to 0");
    ASSERT_EQ_U32(0x000008u, cpu.pc, "OTD2R iter2: falls through when B==0");

    /* OTI2 alias (A5): same semantics as OTI2 */
    emu.cpu.bc = 0x0000017Fu;
    emu.cpu.hl = 0x00002600u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2600u, 0xC1u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTI2 alias source byte");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTI2 alias (ED A5)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTI2 alias get state");
    ASSERT_EQ_INT(0xC1, emu.memory.ports[0x7F], "OTI2 alias: writes source byte to port 0x7F");
    ASSERT_EQ_INT(0x2601, cpu_reg_pair16(cpu.hl), "OTI2 alias: HL increments");
    ASSERT_EQ_INT(0x7F, cpu.bc & 0xFFu, "OTI2 alias: C unchanged");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OTI2 alias: B decrements to 0");
    ASSERT_EQ_U32(0x00000Au, cpu.pc, "OTI2 alias: PC advances to next opcode");

    /* OTD2 alias (AD): same semantics as OTD2 */
    emu.cpu.bc = 0x00000100u;
    emu.cpu.hl = 0x00002602u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2602u, 0xC2u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTD2 alias source byte");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTD2 alias (ED AD)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTD2 alias get state");
    ASSERT_EQ_INT(0xC2, emu.memory.ports[0x00], "OTD2 alias: writes source byte to port 0x00");
    ASSERT_EQ_INT(0x2601, cpu_reg_pair16(cpu.hl), "OTD2 alias: HL decrements");
    ASSERT_EQ_INT(0x00, cpu.bc & 0xFFu, "OTD2 alias: C unchanged");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OTD2 alias: B decrements to 0");
    ASSERT_EQ_U32(0x00000Cu, cpu.pc, "OTD2 alias: PC advances to next opcode");

    /* OTI2R alias (B5): repeat path then fall-through */
    emu.cpu.bc = 0x000002FEu;
    emu.cpu.hl = 0x00002700u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2700u, 0xD1u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTI2R alias source byte 0");
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2701u, 0xD2u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTI2R alias source byte 1");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTI2R alias iter1 (ED B5)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTI2R alias iter1 get state");
    ASSERT_EQ_INT(0xD1, emu.memory.ports[0xFE], "OTI2R alias iter1: writes first byte to port 0xFE");
    ASSERT_EQ_INT(0x2701, cpu_reg_pair16(cpu.hl), "OTI2R alias iter1: HL increments");
    ASSERT_EQ_INT(0xFE, cpu.bc & 0xFFu, "OTI2R alias iter1: C unchanged at 0xFE");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFFu, "OTI2R alias iter1: B decrements to 1");
    ASSERT_EQ_U32(0x00000Cu, cpu.pc, "OTI2R alias iter1: repeats at same PC");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTI2R alias iter2 (ED B5)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTI2R alias iter2 get state");
    ASSERT_EQ_INT(0xD2, emu.memory.ports[0xFE], "OTI2R alias iter2: writes second byte to port 0xFE");
    ASSERT_EQ_INT(0x2702, cpu_reg_pair16(cpu.hl), "OTI2R alias iter2: HL increments");
    ASSERT_EQ_INT(0xFE, cpu.bc & 0xFFu, "OTI2R alias iter2: C unchanged at 0xFE");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OTI2R alias iter2: B decrements to 0");
    ASSERT_EQ_U32(0x00000Eu, cpu.pc, "OTI2R alias iter2: falls through when B==0");

    /* OTD2R alias (BD): repeat path then fall-through */
    emu.cpu.bc = 0x00000201u;
    emu.cpu.hl = 0x00002801u;
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2801u, 0xE1u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTD2R alias source byte 0");
    status = ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x2800u, 0xE2u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed OTD2R alias source byte 1");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTD2R alias iter1 (ED BD)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTD2R alias iter1 get state");
    ASSERT_EQ_INT(0xE1, emu.memory.ports[0x01], "OTD2R alias iter1: writes first byte to port 0x01");
    ASSERT_EQ_INT(0x2800, cpu_reg_pair16(cpu.hl), "OTD2R alias iter1: HL decrements");
    ASSERT_EQ_INT(0x01, cpu.bc & 0xFFu, "OTD2R alias iter1: C unchanged at 0x01");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFFu, "OTD2R alias iter1: B decrements to 1");
    ASSERT_EQ_U32(0x00000Eu, cpu.pc, "OTD2R alias iter1: repeats at same PC");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTD2R alias iter2 (ED BD)");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "OTD2R alias iter2 get state");
    ASSERT_EQ_INT(0xE2, emu.memory.ports[0x01], "OTD2R alias iter2: writes second byte to port 0x01");
    ASSERT_EQ_INT(0x27FF, cpu_reg_pair16(cpu.hl), "OTD2R alias iter2: HL decrements");
    ASSERT_EQ_INT(0x01, cpu.bc & 0xFFu, "OTD2R alias iter2: C unchanged at 0x01");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFFu, "OTD2R alias iter2: B decrements to 0");
    ASSERT_EQ_U32(0x000010u, cpu.pc, "OTD2R alias iter2: falls through when B==0");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step HALT after OUT2 alias tests");

    remove(rom_path);
}

/* ============================================================
 * eZ80 repeat block I/O: INIMR, OTIMR, INI2R, OTI2R,
 *                         INDMR, OTDMR, IND2R, OTD2R
 * ============================================================ */
static void test_emulator_ez80_block_io_repeat(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        /* INIMR test: B=2, C=0x30, HL=0x5000 */
        0x06, 0x02,               /* LD B,2 */
        0x0E, 0x30,               /* LD C,0x30 */
        0x21, 0x00, 0x50,         /* LD HL,0x5000 */
        0xED, 0x92,               /* INIMR — repeat until B==0 */

        /* OTIMR test: B=2, C=0x40, HL=0x6000 */
        0x06, 0x02,               /* LD B,2 */
        0x0E, 0x40,               /* LD C,0x40 */
        0x21, 0x00, 0x60,         /* LD HL,0x6000 */
        0xED, 0x93,               /* OTIMR — repeat until B==0 */

        /* INDMR test: B=2, C=0x52, HL=0x7002 */
        0x06, 0x02,               /* LD B,2 */
        0x0E, 0x52,               /* LD C,0x52 */
        0x21, 0x02, 0x70,         /* LD HL,0x7002 */
        0xED, 0x9A,               /* INDMR — repeat until B==0 */

        /* INI2R test: B=2, C=0x60, HL=0x8000 */
        0x06, 0x02,               /* LD B,2 */
        0x0E, 0x60,               /* LD C,0x60 */
        0x21, 0x00, 0x80,         /* LD HL,0x8000 */
        0xED, 0x94,               /* INI2R — repeat until B==0 */

        0x76                      /* HALT */
    };

    printf("[TEST] emulator eZ80 repeat block I/O (INIMR/OTIMR/INDMR/INI2R)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create eZ80 repeat block I/O ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 repeat IO init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "eZ80 repeat IO ROM load");

    /* Seed ports for input ops */
    emu.memory.ports[0x30] = 0xA1;
    emu.memory.ports[0x31] = 0xA2;
    emu.memory.ports[0x52] = 0xB1;
    emu.memory.ports[0x51] = 0xB2;
    emu.memory.ports[0x60] = 0xC1;
    /* Seed RAM for output ops */
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x6000u, 0xD1);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x6001u, 0xD2);

    /* LD B,2; LD C,0x30; LD HL,0x5000 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);

    /* INIMR iteration 1: reads port 0x30 (0xA1) -> (0x5000), HL->0x5001, C->0x31, B->1 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INIMR iter 1");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x5001, cpu_reg_pair16(cpu.hl), "INIMR iter1: HL=0x5001");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFF, "INIMR iter1: B=1");
    ASSERT_EQ_INT(0x31, cpu.bc & 0xFF, "INIMR iter1: C=0x31");
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x5000u, &value);
    ASSERT_EQ_INT(0xA1, value, "INIMR iter1: data correct");

    /* INIMR iteration 2: reads port 0x31 (0xA2) -> (0x5001), HL->0x5002, C->0x32, B->0 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INIMR iter 2");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x5002, cpu_reg_pair16(cpu.hl), "INIMR iter2: HL=0x5002");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFF, "INIMR iter2: B=0");
    ASSERT_EQ_INT(0x32, cpu.bc & 0xFF, "INIMR iter2: C=0x32");
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x5001u, &value);
    ASSERT_EQ_INT(0xA2, value, "INIMR iter2: data correct");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0, "INIMR done: Z set");

    /* LD B,2; LD C,0x40; LD HL,0x6000 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);

    /* OTIMR iteration 1: reads (0x6000)=0xD1 -> OUT port 0x40, HL->0x6001, C->0x41, B->1 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTIMR iter 1");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xD1, emu.memory.ports[0x40], "OTIMR iter1: data to port 0x40");
    ASSERT_EQ_INT(0x6001, cpu_reg_pair16(cpu.hl), "OTIMR iter1: HL=0x6001");
    ASSERT_EQ_INT(0x41, cpu.bc & 0xFF, "OTIMR iter1: C=0x41");

    /* OTIMR iteration 2: reads (0x6001)=0xD2 -> OUT port 0x41, HL->0x6002, C->0x42, B->0 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step OTIMR iter 2");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xD2, emu.memory.ports[0x41], "OTIMR iter2: data to port 0x41");
    ASSERT_EQ_INT(0x6002, cpu_reg_pair16(cpu.hl), "OTIMR iter2: HL=0x6002");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFF, "OTIMR done: B=0");

    /* LD B,2; LD C,0x52; LD HL,0x7002 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);

    /* INDMR iteration 1: reads port 0x52 (0xB1) -> (0x7002), HL->0x7001, C->0x51, B->1 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INDMR iter 1");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x7001, cpu_reg_pair16(cpu.hl), "INDMR iter1: HL=0x7001");
    ASSERT_EQ_INT(0x51, cpu.bc & 0xFF, "INDMR iter1: C=0x51");
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x7002u, &value);
    ASSERT_EQ_INT(0xB1, value, "INDMR iter1: data correct");

    /* INDMR iteration 2: reads port 0x51 (0xB2) -> (0x7001), HL->0x7000, C->0x50, B->0 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INDMR iter 2");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x7000, cpu_reg_pair16(cpu.hl), "INDMR iter2: HL=0x7000");
    ASSERT_EQ_INT(0x50, cpu.bc & 0xFF, "INDMR iter2: C=0x50");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFF, "INDMR done: B=0");

    /* LD B,2; LD C,0x60; LD HL,0x8000 */
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);
    ez80_emulator_step(&emu, &decoded);

    /* INI2R iteration 1: reads port 0x60 (0xC1) -> (0x8000), HL->0x8001, C unchanged, B->1 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INI2R iter 1");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x8001, cpu_reg_pair16(cpu.hl), "INI2R iter1: HL=0x8001");
    ASSERT_EQ_INT(0x60, cpu.bc & 0xFF, "INI2R iter1: C unchanged");
    ASSERT_EQ_INT(0x01, (cpu.bc >> 8) & 0xFF, "INI2R iter1: B=1");

    /* INI2R iteration 2: reads port 0x60 again -> (0x8001), HL->0x8002, B->0 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step INI2R iter 2");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0x8002, cpu_reg_pair16(cpu.hl), "INI2R iter2: HL=0x8002");
    ASSERT_EQ_INT(0x00, (cpu.bc >> 8) & 0xFF, "INI2R done: B=0");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0, "INI2R done: Z set");

    /* HALT */
    ez80_emulator_step(&emu, &decoded);
    remove(rom_path);
}

/* ============================================================
 * eZ80 ED C2/C3/CA/CB: INIRX, OTIRX, INDRX, OTDRX
 * ============================================================ */
static void test_emulator_ez80_block_io_x_ops(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    printf("[TEST] emulator eZ80 INIRX/OTIRX/INDRX/OTDRX block I/O\n");

    {
        uint8_t rom_bytes[] = { 0xED, 0xC2, 0x76 };
        ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                    "create INIRX ROM file");
        status = ez80_emulator_init(&emu);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX init");
        status = ez80_emulator_load_rom(&emu, rom_path);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX ROM load");

        emu.cpu.bc = 0x0002u;
        emu.cpu.de = 0x0020u;
        emu.cpu.hl = 0x4000u;
        cpu_set_reg_f(&emu.cpu, (uint8_t)(FLAG_S | FLAG_H | FLAG_PV | FLAG_C));
        emu.memory.ports[0x20] = 0x80u;

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX step 1");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX get state after step 1");
        ASSERT_EQ_U32(0x0001u, cpu_reg_pair16(cpu.bc), "INIRX step1: BC decrements");
        ASSERT_EQ_U32(0x4001u, cpu_reg_pair16(cpu.hl), "INIRX step1: HL increments");
        ASSERT_EQ_U32(0x000000u, cpu.pc, "INIRX step1: repeats at same PC when BC!=0");
        status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX step1: read RAM[0x4000]");
        ASSERT_EQ_INT(0x80, value, "INIRX step1: transferred byte");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX step 2");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX get state after step 2");
        ASSERT_EQ_U32(0x0000u, cpu_reg_pair16(cpu.bc), "INIRX step2: BC reaches zero");
        ASSERT_EQ_U32(0x4002u, cpu_reg_pair16(cpu.hl), "INIRX step2: HL increments again");
        ASSERT_EQ_U32(0x000002u, cpu.pc, "INIRX step2: falls through when BC==0");
        status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX step2: read RAM[0x4001]");
        ASSERT_EQ_INT(0x80, value, "INIRX step2: transferred byte");
        ASSERT_EQ_INT((FLAG_S | FLAG_Z | FLAG_H | FLAG_PV | FLAG_N | FLAG_C),
                      cpu_reg_f(&cpu),
                      "INIRX flags should preserve S/H/PV/C and update Z/N");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "INIRX HALT");
        remove(rom_path);
    }

    {
        uint8_t rom_bytes[] = { 0xED, 0xC3, 0x76 };
        ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                    "create OTIRX ROM file");
        status = ez80_emulator_init(&emu);
        ASSERT_EQ_INT(EZ80_OK, status, "OTIRX init");
        status = ez80_emulator_load_rom(&emu, rom_path);
        ASSERT_EQ_INT(EZ80_OK, status, "OTIRX ROM load");

        emu.cpu.bc = 0x0002u;
        emu.cpu.de = 0x0020u;
        emu.cpu.hl = 0x4000u;
        cpu_set_reg_f(&emu.cpu, (uint8_t)(FLAG_S | FLAG_H | FLAG_PV | FLAG_C));
        ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4000u, 0x31u);
        ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4001u, 0x32u);

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "OTIRX step 1");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "OTIRX get state after step 1");
        ASSERT_EQ_INT(0x31, emu.memory.ports[0x20], "OTIRX step1: first byte to port");
        ASSERT_EQ_U32(0x0001u, cpu_reg_pair16(cpu.bc), "OTIRX step1: BC decrements");
        ASSERT_EQ_U32(0x4001u, cpu_reg_pair16(cpu.hl), "OTIRX step1: HL increments");
        ASSERT_EQ_U32(0x000000u, cpu.pc, "OTIRX step1: repeats at same PC when BC!=0");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "OTIRX step 2");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "OTIRX get state after step 2");
        ASSERT_EQ_INT(0x32, emu.memory.ports[0x20], "OTIRX step2: second byte to same port");
        ASSERT_EQ_U32(0x0000u, cpu_reg_pair16(cpu.bc), "OTIRX step2: BC reaches zero");
        ASSERT_EQ_U32(0x4002u, cpu_reg_pair16(cpu.hl), "OTIRX step2: HL increments again");
        ASSERT_EQ_U32(0x000002u, cpu.pc, "OTIRX step2: falls through when BC==0");
        ASSERT_EQ_INT((FLAG_S | FLAG_Z | FLAG_H | FLAG_PV | FLAG_C),
                      cpu_reg_f(&cpu),
                      "OTIRX flags should preserve S/H/PV/C and clear N for bit7=0 data");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "OTIRX HALT");
        remove(rom_path);
    }

    {
        uint8_t rom_bytes[] = { 0xED, 0xCA, 0x76 };
        ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                    "create INDRX ROM file");
        status = ez80_emulator_init(&emu);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX init");
        status = ez80_emulator_load_rom(&emu, rom_path);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX ROM load");

        emu.cpu.bc = 0x0002u;
        emu.cpu.de = 0x0020u;
        emu.cpu.hl = 0x4001u;
        cpu_set_reg_f(&emu.cpu, (uint8_t)(FLAG_S | FLAG_H | FLAG_PV | FLAG_C));
        emu.memory.ports[0x20] = 0x7Fu;

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX step 1");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX get state after step 1");
        ASSERT_EQ_U32(0x0001u, cpu_reg_pair16(cpu.bc), "INDRX step1: BC decrements");
        ASSERT_EQ_U32(0x4000u, cpu_reg_pair16(cpu.hl), "INDRX step1: HL decrements");
        ASSERT_EQ_U32(0x000000u, cpu.pc, "INDRX step1: repeats at same PC when BC!=0");
        status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4001u, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX step1: read RAM[0x4001]");
        ASSERT_EQ_INT(0x7F, value, "INDRX step1: transferred byte");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX step 2");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX get state after step 2");
        ASSERT_EQ_U32(0x0000u, cpu_reg_pair16(cpu.bc), "INDRX step2: BC reaches zero");
        ASSERT_EQ_U32(0x3FFFu, cpu_reg_pair16(cpu.hl), "INDRX step2: HL decrements again");
        ASSERT_EQ_U32(0x000002u, cpu.pc, "INDRX step2: falls through when BC==0");
        status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX step2: read RAM[0x4000]");
        ASSERT_EQ_INT(0x7F, value, "INDRX step2: transferred byte");
        ASSERT_EQ_INT((FLAG_S | FLAG_Z | FLAG_H | FLAG_PV | FLAG_C),
                      cpu_reg_f(&cpu),
                      "INDRX flags should preserve S/H/PV/C and clear N for bit7=0 data");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "INDRX HALT");
        remove(rom_path);
    }

    {
        uint8_t rom_bytes[] = { 0xED, 0xCB, 0x76 };
        ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                    "create OTDRX ROM file");
        status = ez80_emulator_init(&emu);
        ASSERT_EQ_INT(EZ80_OK, status, "OTDRX init");
        status = ez80_emulator_load_rom(&emu, rom_path);
        ASSERT_EQ_INT(EZ80_OK, status, "OTDRX ROM load");

        emu.cpu.bc = 0x0002u;
        emu.cpu.de = 0x0020u;
        emu.cpu.hl = 0x4001u;
        cpu_set_reg_f(&emu.cpu, (uint8_t)(FLAG_S | FLAG_H | FLAG_PV | FLAG_C));
        ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4001u, 0xF1u);
        ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x4000u, 0x81u);

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "OTDRX step 1");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "OTDRX get state after step 1");
        ASSERT_EQ_INT(0xF1, emu.memory.ports[0x20], "OTDRX step1: first byte to port");
        ASSERT_EQ_U32(0x0001u, cpu_reg_pair16(cpu.bc), "OTDRX step1: BC decrements");
        ASSERT_EQ_U32(0x4000u, cpu_reg_pair16(cpu.hl), "OTDRX step1: HL decrements");
        ASSERT_EQ_U32(0x000000u, cpu.pc, "OTDRX step1: repeats at same PC when BC!=0");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "OTDRX step 2");
        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "OTDRX get state after step 2");
        ASSERT_EQ_INT(0x81, emu.memory.ports[0x20], "OTDRX step2: second byte to same port");
        ASSERT_EQ_U32(0x0000u, cpu_reg_pair16(cpu.bc), "OTDRX step2: BC reaches zero");
        ASSERT_EQ_U32(0x3FFFu, cpu_reg_pair16(cpu.hl), "OTDRX step2: HL decrements again");
        ASSERT_EQ_U32(0x000002u, cpu.pc, "OTDRX step2: falls through when BC==0");
        ASSERT_EQ_INT((FLAG_S | FLAG_Z | FLAG_H | FLAG_PV | FLAG_N | FLAG_C),
                      cpu_reg_f(&cpu),
                      "OTDRX flags should preserve S/H/PV/C and update Z/N");

        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "OTDRX HALT");
        remove(rom_path);
    }
}

/* ============================================================
 * Regression: block I/O flags preserve S/H/PV/C and update Z/N
 * ============================================================ */
static void test_emulator_block_io_flag_preservation(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    uint8_t rom_bytes[] = {
        0x06, 0x01,       /* LD B,1 */
        0x0E, 0x10,       /* LD C,0x10 */
        0x21, 0x00, 0x40, /* LD HL,0x4000 */
        0xED, 0xA2,       /* INI */
        0x76              /* HALT */
    };

    printf("[TEST] emulator block I/O flag preservation regression\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create block I/O flag regression ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression ROM load");

    emu.memory.ports[0x10] = 0x80u;
    cpu_set_reg_f(&emu.cpu, (uint8_t)(FLAG_S | FLAG_H | FLAG_PV | FLAG_C));

    status = ez80_emulator_step(&emu, &decoded); /* LD B,1 */
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression step LD B");
    status = ez80_emulator_step(&emu, &decoded); /* LD C,0x10 */
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression step LD C");
    status = ez80_emulator_step(&emu, &decoded); /* LD HL,0x4000 */
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression step LD HL");
    status = ez80_emulator_step(&emu, &decoded); /* INI */
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression step INI");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression get state");
    ASSERT_EQ_U32(0x0010u, cpu_reg_pair16(cpu.bc), "INI should decrement BC from 0x0110 to 0x0010");
    ASSERT_EQ_U32(0x4001u, cpu_reg_pair16(cpu.hl), "INI should increment HL");
    ASSERT_EQ_INT((FLAG_S | FLAG_Z | FLAG_H | FLAG_PV | FLAG_N | FLAG_C),
                  cpu_reg_f(&cpu),
                  "INI flags should preserve S/H/PV/C and set Z/N from transfer");
    status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x4000u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "INI transferred byte RAM read");
    ASSERT_EQ_INT(0x80, value, "INI should store transferred port byte");

    status = ez80_emulator_step(&emu, &decoded); /* HALT */
    ASSERT_EQ_INT(EZ80_OK, status, "block I/O flag regression HALT");
    remove(rom_path);
}

/* ============================================================
 * Regression: stack overflow/underflow must not partially mutate
 * ============================================================ */
static void test_emulator_stack_atomic_boundary_failures(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];

    printf("[TEST] emulator stack overflow/underflow atomic boundary failures\n");

    {
        uint8_t rom_bytes[] = {
            0x21, 0x01, 0x00, /* LD HL,0x0001 */
            0xF9,             /* LD SP,HL -> 0xD00001 */
            0x01, 0x34, 0x12, /* LD BC,0x1234 */
            0xC5,             /* PUSH BC (should fail: second byte out of bounds) */
            0x76
        };

        ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                    "create stack push-boundary ROM");
        status = ez80_emulator_init(&emu);
        ASSERT_EQ_INT(EZ80_OK, status, "stack push-boundary init");
        status = ez80_emulator_load_rom(&emu, rom_path);
        ASSERT_EQ_INT(EZ80_OK, status, "stack push-boundary ROM load");

        ez80_emulator_step(&emu, &decoded); /* LD HL */
        ez80_emulator_step(&emu, &decoded); /* LD SP,HL */
        ez80_emulator_step(&emu, &decoded); /* LD BC */
        status = ez80_emulator_step(&emu, &decoded); /* PUSH BC */
        ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "PUSH BC should fail atomically at RAM boundary");

        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "stack push-boundary get state");
        ASSERT_EQ_U32(0xD00001u, cpu.sp, "failed PUSH must preserve SP");
        ASSERT_EQ_U32(0x000007u, cpu.pc, "failed PUSH must keep PC at faulting opcode");
        status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x0000u, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "stack push-boundary RAM read");
        ASSERT_EQ_INT(0x00, value, "failed PUSH must not partially write first byte");

        remove(rom_path);
    }

    {
        uint8_t rom_bytes[] = {
            0xC1, /* POP BC (should fail: high byte read out of bounds) */
            0x76
        };

        ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                    "create stack pop-boundary ROM");
        status = ez80_emulator_init(&emu);
        ASSERT_EQ_INT(EZ80_OK, status, "stack pop-boundary init");
        status = ez80_emulator_load_rom(&emu, rom_path);
        ASSERT_EQ_INT(EZ80_OK, status, "stack pop-boundary ROM load");

        emu.cpu.sp = EZ80_LCD_RAM_BASE + EZ80_LCD_RAM_BYTES - 1u; /* 0xD657FF: second pop byte out of range */
        emu.cpu.bc = 0u;
        status = ez80_memory_write8(&emu, emu.cpu.sp, 0xAAu);
        ASSERT_EQ_INT(EZ80_OK, status, "stack pop-boundary seed byte");

        status = ez80_emulator_step(&emu, &decoded); /* POP BC */
        ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "POP BC should fail atomically at RAM boundary");

        status = ez80_emulator_get_state(&emu, &cpu);
        ASSERT_EQ_INT(EZ80_OK, status, "stack pop-boundary get state");
        ASSERT_EQ_U32(EZ80_LCD_RAM_BASE + EZ80_LCD_RAM_BYTES - 1u, cpu.sp, "failed POP must preserve SP");
        ASSERT_EQ_U32(0x000000u, cpu.pc, "failed POP must keep PC at faulting opcode");
        ASSERT_EQ_U32(0x0000u, cpu_reg_pair16(cpu.bc), "failed POP must preserve BC");
        status = ez80_memory_read8(&emu, EZ80_LCD_RAM_BASE + EZ80_LCD_RAM_BYTES - 1u, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "stack pop-boundary verify source byte");
        ASSERT_EQ_INT(0xAA, value, "failed POP must not mutate source memory");

        remove(rom_path);
    }
}

