/* ============================================================
 * Decode test: ADD IX,IX / ADD IY,IY disassembly
 * ============================================================ */
static void test_decode_add_index_self(void)
{
    ez80_instruction_t instr;
    ez80_status_t status;

    printf("[TEST] decode ADD IX,IX / ADD IY,IY disassembly\n");

    {
        uint8_t stream[] = { 0xDD, 0x29 };
        memset(&instr, 0, sizeof(instr));
        status = ez80_decode_instruction(stream, sizeof(stream), &instr);
        ASSERT_EQ_INT(EZ80_OK, status, "decode DD 29 status");
        ASSERT_TRUE(strcmp(instr.mnemonic, "ADD") == 0, "decode DD 29 mnemonic");
        ASSERT_TRUE(strcmp(instr.operands, "IX,IX") == 0, "decode DD 29 operands: IX,IX not IX,HL");
    }

    {
        uint8_t stream[] = { 0xFD, 0x29 };
        memset(&instr, 0, sizeof(instr));
        status = ez80_decode_instruction(stream, sizeof(stream), &instr);
        ASSERT_EQ_INT(EZ80_OK, status, "decode FD 29 status");
        ASSERT_TRUE(strcmp(instr.mnemonic, "ADD") == 0, "decode FD 29 mnemonic");
        ASSERT_TRUE(strcmp(instr.operands, "IY,IY") == 0, "decode FD 29 operands: IY,IY not IY,HL");
    }

    /* ADD IX,BC (DD 09) should still show BC */
    {
        uint8_t stream[] = { 0xDD, 0x09 };
        memset(&instr, 0, sizeof(instr));
        status = ez80_decode_instruction(stream, sizeof(stream), &instr);
        ASSERT_EQ_INT(EZ80_OK, status, "decode DD 09 status");
        ASSERT_TRUE(strcmp(instr.operands, "IX,BC") == 0, "decode DD 09 operands: IX,BC");
    }

    /* ADD IX,SP (DD 39) should still show SP */
    {
        uint8_t stream[] = { 0xDD, 0x39 };
        memset(&instr, 0, sizeof(instr));
        status = ez80_decode_instruction(stream, sizeof(stream), &instr);
        ASSERT_EQ_INT(EZ80_OK, status, "decode DD 39 status");
        ASSERT_TRUE(strcmp(instr.operands, "IX,SP") == 0, "decode DD 39 operands: IX,SP");
    }
}

typedef struct {
    uint8_t alias_op;
    uint8_t canonical_op;
    const char *mnemonic;
} ed_alias_case_t;

static ez80_status_t init_single_ed_fixture(ez80_emulator_t *emu, uint8_t ed_op)
{
    ez80_status_t status = ez80_emulator_init(emu);
    if (status != EZ80_OK) {
        return status;
    }

    emu->rom_loaded = true;
    memset(emu->memory.flash_window, 0, sizeof(emu->memory.flash_window));
    emu->memory.flash_window[0] = 0xEDu;
    emu->memory.flash_window[1] = ed_op;
    emu->memory.flash_window[2] = 0x5Au;
    emu->memory.flash_window[3] = 0x76u;

    emu->cpu.pc = 0u;
    emu->cpu.af = ((uint32_t)0x5Au << 8) | (uint32_t)FLAG_C;
    emu->cpu.bc = 0x000110u; /* B=0x01, C=0x10: no repeat loop on first step */
    emu->cpu.de = 0x000210u;
    emu->cpu.hl = 0x0002000u;
    emu->cpu.ix = 0x0003456u;
    emu->cpu.iy = 0x0004567u;

    emu->memory.ram[0x1FFFu] = 0x11u;
    emu->memory.ram[0x2000u] = 0x22u;
    emu->memory.ram[0x2001u] = 0x33u;
    emu->memory.ram[0x2002u] = 0x44u;
    emu->memory.ports[0x10u] = 0xA5u;
    emu->memory.ports[0x11u] = 0x5Au;
    emu->memory.ports[0x12u] = 0xC3u;
    return EZ80_OK;
}

/* ============================================================
 * ED gap coverage: implemented alias matrix should behave as
 * canonical equivalents for decode + single-step execution.
 * ============================================================ */
static void test_emulator_ed_gap_alias_matrix(void)
{
    static const ed_alias_case_t k_cases[] = {
        { 0x06u, 0x07u, "LD" },   { 0x0Eu, 0x0Fu, "LD" },
        { 0x16u, 0x17u, "LD" },   { 0x1Eu, 0x1Fu, "LD" },
        { 0x26u, 0x27u, "LD" },   { 0x2Eu, 0x2Fu, "LD" },
        { 0x80u, 0x82u, "INIM" }, { 0x81u, 0x83u, "OTIM" },
        { 0x86u, 0x84u, "INI2" }, { 0x87u, 0x85u, "OTI2" },
        { 0x88u, 0x8Au, "INDM" }, { 0x89u, 0x8Bu, "OTDM" },
        { 0x8Eu, 0x8Cu, "IND2" }, { 0x8Fu, 0x8Du, "OTD2" },
        { 0x90u, 0x92u, "INIMR" }, { 0x91u, 0x93u, "OTIMR" },
        { 0x96u, 0x94u, "INI2R" }, { 0x97u, 0x95u, "OTI2R" },
        { 0x98u, 0x9Au, "INDMR" }, { 0x99u, 0x9Bu, "OTDMR" },
        { 0x9Eu, 0x9Cu, "IND2R" }, { 0x9Fu, 0x9Du, "OTD2R" },
        { 0xA6u, 0x85u, "OTI2" }, { 0xA7u, 0x85u, "OTI2" },
        { 0xAEu, 0x8Du, "OTD2" }, { 0xAFu, 0x8Du, "OTD2" },
        { 0xB6u, 0x95u, "OTI2R" }, { 0xB7u, 0x95u, "OTI2R" },
        { 0xBEu, 0x9Du, "OTD2R" }, { 0xBFu, 0x9Du, "OTD2R" }
    };
    size_t i;
    static ez80_emulator_t alias_emu;
    static ez80_emulator_t canonical_emu;

    printf("[TEST] emulator ED gap alias matrix equivalence\n");

    for (i = 0u; i < (sizeof(k_cases) / sizeof(k_cases[0])); i++) {
        ez80_instruction_t alias_decoded;
        ez80_instruction_t canonical_decoded;
        ez80_status_t status;
        char msg[160];

        memset(&alias_decoded, 0, sizeof(alias_decoded));
        memset(&canonical_decoded, 0, sizeof(canonical_decoded));

        status = init_single_ed_fixture(&alias_emu, k_cases[i].alias_op);
        ASSERT_EQ_INT(EZ80_OK, status, "init alias fixture");
        status = init_single_ed_fixture(&canonical_emu, k_cases[i].canonical_op);
        ASSERT_EQ_INT(EZ80_OK, status, "init canonical fixture");

        status = ez80_emulator_step(&alias_emu, &alias_decoded);
        (void)snprintf(msg, sizeof(msg),
                       "step ED alias 0x%02X should execute",
                       (unsigned)k_cases[i].alias_op);
        ASSERT_EQ_INT(EZ80_OK, status, msg);

        status = ez80_emulator_step(&canonical_emu, &canonical_decoded);
        (void)snprintf(msg, sizeof(msg),
                       "step ED canonical 0x%02X should execute",
                       (unsigned)k_cases[i].canonical_op);
        ASSERT_EQ_INT(EZ80_OK, status, msg);

        (void)snprintf(msg, sizeof(msg),
                       "decode mnemonic for ED alias 0x%02X",
                       (unsigned)k_cases[i].alias_op);
        ASSERT_TRUE(strcmp(alias_decoded.mnemonic, k_cases[i].mnemonic) == 0, msg);

        (void)snprintf(msg, sizeof(msg),
                       "decode mnemonic parity alias 0x%02X vs canonical 0x%02X",
                       (unsigned)k_cases[i].alias_op,
                       (unsigned)k_cases[i].canonical_op);
        ASSERT_TRUE(strcmp(alias_decoded.mnemonic, canonical_decoded.mnemonic) == 0, msg);

        (void)snprintf(msg, sizeof(msg),
                       "decoded length parity alias 0x%02X",
                       (unsigned)k_cases[i].alias_op);
        ASSERT_EQ_INT(canonical_decoded.length, alias_decoded.length, msg);

        (void)snprintf(msg, sizeof(msg),
                       "decoded cycle parity alias 0x%02X",
                       (unsigned)k_cases[i].alias_op);
        ASSERT_EQ_INT(canonical_decoded.cycles, alias_decoded.cycles, msg);

        (void)snprintf(msg, sizeof(msg),
                       "CPU state parity alias 0x%02X canonical 0x%02X",
                       (unsigned)k_cases[i].alias_op,
                       (unsigned)k_cases[i].canonical_op);
        ASSERT_TRUE(memcmp(&alias_emu.cpu, &canonical_emu.cpu, sizeof(alias_emu.cpu)) == 0, msg);

        (void)snprintf(msg, sizeof(msg),
                       "RAM parity alias 0x%02X canonical 0x%02X",
                       (unsigned)k_cases[i].alias_op,
                       (unsigned)k_cases[i].canonical_op);
        ASSERT_TRUE(memcmp(alias_emu.memory.ram,
                           canonical_emu.memory.ram,
                           sizeof(alias_emu.memory.ram)) == 0, msg);

        (void)snprintf(msg, sizeof(msg),
                       "PORT parity alias 0x%02X canonical 0x%02X",
                       (unsigned)k_cases[i].alias_op,
                       (unsigned)k_cases[i].canonical_op);
        ASSERT_TRUE(memcmp(alias_emu.memory.ports,
                           canonical_emu.memory.ports,
                           sizeof(alias_emu.memory.ports)) == 0, msg);

        (void)snprintf(msg, sizeof(msg),
                       "MMIO parity alias 0x%02X canonical 0x%02X",
                       (unsigned)k_cases[i].alias_op,
                       (unsigned)k_cases[i].canonical_op);
        ASSERT_TRUE(memcmp(alias_emu.memory.mmio,
                           canonical_emu.memory.mmio,
                           sizeof(alias_emu.memory.mmio)) == 0, msg);
    }
}

/* ============================================================
 * ED gap coverage: implemented NOP-compatible slots should
 * decode as NOP and preserve machine state (except PC advance).
 * ============================================================ */
static void test_emulator_ed_gap_nop_matrix(void)
{
    static const uint8_t k_nop_ops[] = {
        0x05u, 0x0Du, 0x15u, 0x1Au, 0x1Bu, 0x1Du, 0x25u, 0x2Au, 0x2Bu, 0x2Du,
        0x35u, 0x36u, 0x3Du,
        0xC0u, 0xC1u, 0xC4u, 0xC5u, 0xC6u, 0xC8u, 0xC9u, 0xCCu, 0xCDu, 0xCEu, 0xCFu,
        0xD0u, 0xD1u, 0xD2u, 0xD3u, 0xD4u, 0xD5u, 0xD6u, 0xD8u, 0xD9u, 0xDAu, 0xDBu,
        0xDCu, 0xDDu, 0xDEu, 0xDFu,
        0xE0u, 0xE1u, 0xE2u, 0xE3u, 0xE4u, 0xE5u, 0xE6u, 0xE7u, 0xE8u, 0xE9u, 0xEAu,
        0xEBu, 0xECu, 0xEDu, 0xEEu, 0xEFu,
        0xF0u, 0xF1u, 0xF2u, 0xF3u, 0xF4u, 0xF5u, 0xF6u, 0xF7u, 0xF8u, 0xF9u, 0xFAu,
        0xFBu, 0xFCu, 0xFDu, 0xFEu
    };
    size_t i;
    static ez80_emulator_t emu;

    printf("[TEST] emulator ED gap NOP matrix decode/execute stability\n");

    for (i = 0u; i < (sizeof(k_nop_ops) / sizeof(k_nop_ops[0])); i++) {
        ez80_instruction_t decoded;
        ez80_cpu_state_t before_cpu;
        ez80_status_t status;
        uint8_t before_ram_1fff;
        uint8_t before_ram_2000;
        uint8_t before_ram_2001;
        uint8_t before_port_10;
        uint8_t before_port_11;
        uint8_t before_mmio_10;
        uint8_t before_mmio_11;
        uint8_t stream[3];
        char msg[160];

        memset(&decoded, 0, sizeof(decoded));

        status = init_single_ed_fixture(&emu, k_nop_ops[i]);
        ASSERT_EQ_INT(EZ80_OK, status, "init NOP fixture");

        stream[0] = 0xEDu;
        stream[1] = k_nop_ops[i];
        stream[2] = 0x5Au;
        status = ez80_decode_instruction(stream, sizeof(stream), &decoded);
        (void)snprintf(msg, sizeof(msg),
                       "decode ED NOP-compatible opcode 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_EQ_INT(EZ80_OK, status, msg);

        (void)snprintf(msg, sizeof(msg),
                       "decode mnemonic NOP for ED 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_TRUE(strcmp(decoded.mnemonic, "NOP") == 0, msg);

        (void)snprintf(msg, sizeof(msg),
                       "decode cycle count for ED 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_EQ_INT(8, decoded.cycles, msg);

        before_cpu = emu.cpu;
        before_ram_1fff = emu.memory.ram[0x1FFFu];
        before_ram_2000 = emu.memory.ram[0x2000u];
        before_ram_2001 = emu.memory.ram[0x2001u];
        before_port_10 = emu.memory.ports[0x10u];
        before_port_11 = emu.memory.ports[0x11u];
        before_mmio_10 = emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_PORT];
        before_mmio_11 = emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_VALUE];

        status = ez80_emulator_step(&emu, &decoded);
        (void)snprintf(msg, sizeof(msg),
                       "execute ED NOP-compatible opcode 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_EQ_INT(EZ80_OK, status, msg);

        (void)snprintf(msg, sizeof(msg),
                       "ED NOP-compatible PC advance for 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_EQ_U32(2u, emu.cpu.pc, msg);

        before_cpu.pc = 2u;
        (void)snprintf(msg, sizeof(msg),
                       "ED NOP-compatible CPU stability for 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_TRUE(memcmp(&before_cpu, &emu.cpu, sizeof(before_cpu)) == 0, msg);

        (void)snprintf(msg, sizeof(msg),
                       "ED NOP-compatible RAM stability for 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_TRUE(before_ram_1fff == emu.memory.ram[0x1FFFu] &&
                    before_ram_2000 == emu.memory.ram[0x2000u] &&
                    before_ram_2001 == emu.memory.ram[0x2001u], msg);

        (void)snprintf(msg, sizeof(msg),
                       "ED NOP-compatible PORT stability for 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_TRUE(before_port_10 == emu.memory.ports[0x10u] &&
                    before_port_11 == emu.memory.ports[0x11u], msg);

        (void)snprintf(msg, sizeof(msg),
                       "ED NOP-compatible MMIO stability for 0x%02X",
                       (unsigned)k_nop_ops[i]);
        ASSERT_TRUE(before_mmio_10 == emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_PORT] &&
                    before_mmio_11 == emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_VALUE], msg);
    }
}

/* ============================================================
 * Multi-prefix edge: DD/FD prefix-ignore path should honor new
 * ED NOP-compatible slots with proper decode + execute timing.
 * ============================================================ */
static void test_decode_execute_ddfd_ed_nop_alias_prefix_ignore(void)
{
    ez80_instruction_t decoded;
    ez80_status_t status;
    ez80_emulator_t emu;
    ez80_cpu_state_t cpu_before;
    uint8_t stream_dd[] = { 0xDDu, 0xEDu, 0xC0u };
    uint8_t stream_fd[] = { 0xFDu, 0xEDu, 0xE0u };

    printf("[TEST] DD/FD+ED prefix-ignore with ED NOP-compatible aliases\n");

    memset(&decoded, 0, sizeof(decoded));
    status = ez80_decode_instruction(stream_dd, sizeof(stream_dd), &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode DD ED C0");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "NOP") == 0, "DD ED C0 should decode as NOP");
    ASSERT_EQ_INT(3, decoded.length, "DD ED C0 length");
    ASSERT_EQ_INT(12, decoded.cycles, "DD ED C0 cycles include ignored-prefix penalty");

    status = ez80_decode_instruction(stream_fd, sizeof(stream_fd), &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "decode FD ED E0");
    ASSERT_TRUE(strcmp(decoded.mnemonic, "NOP") == 0, "FD ED E0 should decode as NOP");
    ASSERT_EQ_INT(3, decoded.length, "FD ED E0 length");
    ASSERT_EQ_INT(12, decoded.cycles, "FD ED E0 cycles include ignored-prefix penalty");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "DD/FD+ED NOP execute init");
    emu.rom_loaded = true;
    memset(emu.memory.flash_window, 0, sizeof(emu.memory.flash_window));
    emu.memory.flash_window[0] = 0xDDu;
    emu.memory.flash_window[1] = 0xEDu;
    emu.memory.flash_window[2] = 0xC0u;
    emu.memory.flash_window[3] = 0xFDu;
    emu.memory.flash_window[4] = 0xEDu;
    emu.memory.flash_window[5] = 0xE0u;
    emu.cpu.af = ((uint32_t)0x7Eu << 8) | (uint32_t)(FLAG_S | FLAG_C);
    cpu_before = emu.cpu;

    status = ez80_emulator_step(&emu, &decoded); /* DD ED C0 */
    ASSERT_EQ_INT(EZ80_OK, status, "step DD ED C0");
    ASSERT_EQ_U32(3u, emu.cpu.pc, "DD ED C0 should advance by 3 bytes");
    cpu_before.pc = 3u;
    ASSERT_TRUE(memcmp(&cpu_before, &emu.cpu, sizeof(cpu_before)) == 0, "DD ED C0 should be state-neutral");

    cpu_before = emu.cpu;
    status = ez80_emulator_step(&emu, &decoded); /* FD ED E0 */
    ASSERT_EQ_INT(EZ80_OK, status, "step FD ED E0");
    ASSERT_EQ_U32(6u, emu.cpu.pc, "FD ED E0 should advance by 3 bytes");
    cpu_before.pc = 6u;
    ASSERT_TRUE(memcmp(&cpu_before, &emu.cpu, sizeof(cpu_before)) == 0, "FD ED E0 should be state-neutral");
}

/* ============================================================
 * Regression: JP (HL)/(IX)/(IY) in Z80 mode must apply MBASE
 * page mapping; ADL mode remains direct 24-bit.
 * ============================================================ */
static void test_emulator_z80_mbase_indirect_jp_mapping(void)
{
    ez80_emulator_t emu;
    ez80_instruction_t decoded;
    ez80_status_t status;

    printf("[TEST] Z80-mode MBASE mapping for JP (HL)/(IX)/(IY)\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "JP(HL) mapping init");
    emu.rom_loaded = true;
    memset(emu.memory.flash_window, 0, sizeof(emu.memory.flash_window));
    emu.memory.flash_window[0] = 0xE9u; /* JP (HL) */
    emu.cpu.adl_mode = false;
    emu.cpu.mbase_reg = 0xD0u;
    emu.cpu.hl = 0x00001234u;
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step JP (HL) in Z80 mode");
    ASSERT_EQ_U32(0xD01234u, emu.cpu.pc, "JP (HL) should map through MBASE in Z80 mode");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "JP(IX) mapping init");
    emu.rom_loaded = true;
    memset(emu.memory.flash_window, 0, sizeof(emu.memory.flash_window));
    emu.memory.flash_window[0] = 0xDDu;
    emu.memory.flash_window[1] = 0xE9u; /* JP (IX) */
    emu.cpu.adl_mode = false;
    emu.cpu.mbase_reg = 0xD0u;
    emu.cpu.ix = 0x00005678u;
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step JP (IX) in Z80 mode");
    ASSERT_EQ_U32(0xD05678u, emu.cpu.pc, "JP (IX) should map through MBASE in Z80 mode");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "JP(IY) mapping init");
    emu.rom_loaded = true;
    memset(emu.memory.flash_window, 0, sizeof(emu.memory.flash_window));
    emu.memory.flash_window[0] = 0xFDu;
    emu.memory.flash_window[1] = 0xE9u; /* JP (IY) */
    emu.cpu.adl_mode = false;
    emu.cpu.mbase_reg = 0xD0u;
    emu.cpu.iy = 0x00009ABCu;
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step JP (IY) in Z80 mode");
    ASSERT_EQ_U32(0xD09ABCu, emu.cpu.pc, "JP (IY) should map through MBASE in Z80 mode");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "JP(HL) ADL mapping init");
    emu.rom_loaded = true;
    memset(emu.memory.flash_window, 0, sizeof(emu.memory.flash_window));
    emu.memory.flash_window[0] = 0xE9u; /* JP (HL) */
    emu.cpu.adl_mode = true;
    emu.cpu.hl = 0x00ABCDEFu;
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step JP (HL) in ADL mode");
    ASSERT_EQ_U32(0x00ABCDEFu, emu.cpu.pc, "JP (HL) should remain direct 24-bit in ADL mode");
}

static void test_emulator_tios_bcall_home_graph_mmio(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    char line[EZ80_HOME_COLS + 1u];
    uint8_t pixel = 0u;
    uint8_t mmio_value = 0u;
    uint16_t lcd_color = 0u;

    printf("[TEST] TI-OS bcall home/graph and MMIO dispatch\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "TI-OS bcall init");

    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall HomeClear");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'A', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall HomePutC A");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'B', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall HomePutC B");
    status = ez80_emulator_home_get_line(&emu, 0u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "read homescreen line after bcall puts");
    ASSERT_TRUE(line[0] == 'A' && line[1] == 'B', "homescreen buffer should contain AB at row 0");

    status = ez80_emulator_bcall(&emu, EZ80_BCALL_GRAPH_CLEAR, 0u, 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall GraphClear");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_GRAPH_PLOT, 12u, 34u, 0x7Fu, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall GraphPlot");
    status = ez80_emulator_graph_get_pixel(&emu, 12u, 34u, &pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "read graph pixel after plot");
    ASSERT_EQ_INT(0x7F, pixel, "graph pixel should match plotted color");

    status = ez80_emulator_bcall(&emu, EZ80_BCALL_GRAPH_RENDER_TO_LCD, 0u, 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall GraphRenderToLcd");
    status = ez80_emulator_lcd_get_pixel(&emu, 12u, 34u, &lcd_color);
    ASSERT_EQ_INT(EZ80_OK, status, "read LCD pixel after graph render");
    ASSERT_EQ_INT(0x7BEF, lcd_color, "LCD pixel should match rendered graph shade conversion");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_LCD_STATUS, &mmio_value);
    ASSERT_EQ_INT(EZ80_OK, status, "read LCD MMIO status");
    ASSERT_EQ_INT(0x01, mmio_value, "LCD MMIO status should indicate ready after graph render");

    emu.memory.mmio[EZ80_MMIO_REG_BCALL_VECTOR_LO] = (uint8_t)(EZ80_BCALL_HOME_PUTC & 0xFFu);
    emu.memory.mmio[EZ80_MMIO_REG_BCALL_VECTOR_HI] = (uint8_t)((EZ80_BCALL_HOME_PUTC >> 8) & 0xFFu);
    emu.memory.mmio[EZ80_MMIO_REG_BCALL_ARG0_0] = (uint8_t)'Z';
    status = ez80_memory_write8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_BCALL_EXECUTE, 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "MMIO bcall execute write");
    status = ez80_emulator_home_get_line(&emu, 0u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "read homescreen line after MMIO bcall");
    ASSERT_TRUE(line[2] == 'Z', "MMIO-dispatched bcall should append Z on homescreen");
    ASSERT_EQ_INT(EZ80_OK, emu.memory.mmio[EZ80_MMIO_REG_BCALL_STATUS], "MMIO bcall status should be ok");
}

static void test_emulator_tios_os_var_and_program_swap(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t real_payload[] = { 0x3F, 0x80, 0x00, 0x00 };
    uint8_t read_buffer[16];
    size_t read_size = 0u;
    ez80_os_var_info_t info;
    size_t i;
    static const char *program_names[9] = {
        "CALCENG", "CEALG", "CECALC", "CELIMS", "CEMAT",
        "CESTPRB", "CEFIN", "CEGRPH", "CELSCX"
    };
    const size_t program_count = sizeof(program_names) / sizeof(program_names[0]);
    char program_paths[9][260];
    uint8_t program_bytes[9][64];

    printf("[TEST] TI-OS OS var management and archive/RAM program swapping\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "OS var init");

    status = ez80_emulator_os_var_write(&emu,
                                        "ANS",
                                        EZ80_OS_VAR_REAL,
                                        real_payload,
                                        sizeof(real_payload),
                                        false);
    ASSERT_EQ_INT(EZ80_OK, status, "write REAL OS var");

    status = ez80_emulator_os_var_read(&emu,
                                       "ANS",
                                       EZ80_OS_VAR_REAL,
                                       read_buffer,
                                       sizeof(read_buffer),
                                       &read_size);
    ASSERT_EQ_INT(EZ80_OK, status, "read REAL OS var");
    ASSERT_EQ_INT((int)sizeof(real_payload), (int)read_size, "REAL OS var read size");
    ASSERT_TRUE(memcmp(real_payload, read_buffer, sizeof(real_payload)) == 0, "REAL OS var payload round-trip");

    status = ez80_emulator_os_var_get_info(&emu, "ANS", EZ80_OS_VAR_REAL, &info);
    ASSERT_EQ_INT(EZ80_OK, status, "get REAL OS var info");
    ASSERT_TRUE(info.exists, "REAL OS var info should report exists");
    ASSERT_EQ_INT(EZ80_OS_VAR_REAL, info.type, "REAL OS var info type");

    for (i = 0u; i < program_count; i++) {
        size_t j;
        for (j = 0u; j < sizeof(program_bytes[i]); j++) {
            program_bytes[i][j] = (uint8_t)((i * 17u + j) & 0xFFu);
        }
        ASSERT_TRUE(write_temp_file(program_bytes[i],
                                    sizeof(program_bytes[i]),
                                    program_paths[i],
                                    sizeof(program_paths[i])) != 0,
                    "create temp module program file");

        status = ez80_emulator_load_program_file(&emu, program_names[i], program_paths[i], true);
        ASSERT_EQ_INT(EZ80_OK, status, "load archived module program");

        status = ez80_emulator_os_var_get_info(&emu, program_names[i], EZ80_OS_VAR_PROGRAM, &info);
        ASSERT_EQ_INT(EZ80_OK, status, "get program var info after load");
        ASSERT_TRUE(info.archived, "loaded program should be archived");
        ASSERT_TRUE(!info.loaded_in_ram, "loaded program should not yet be in RAM");

        status = ez80_emulator_archive_program_to_ram(&emu, program_names[i]);
        ASSERT_EQ_INT(EZ80_OK, status, "archive->RAM program swap");
        status = ez80_emulator_os_var_get_info(&emu, program_names[i], EZ80_OS_VAR_PROGRAM, &info);
        ASSERT_EQ_INT(EZ80_OK, status, "program info after archive->RAM");
        ASSERT_TRUE(info.loaded_in_ram, "program should be in RAM after archive->RAM");

        status = ez80_emulator_return_program_to_archive(&emu, program_names[i]);
        ASSERT_EQ_INT(EZ80_OK, status, "RAM->archive program swap");
        status = ez80_emulator_os_var_get_info(&emu, program_names[i], EZ80_OS_VAR_PROGRAM, &info);
        ASSERT_EQ_INT(EZ80_OK, status, "program info after RAM->archive");
        ASSERT_TRUE(!info.loaded_in_ram, "program should not remain in RAM after return");
    }

    for (i = 0u; i < program_count; i++) {
        if (program_paths[i][0] != '\0') {
            remove(program_paths[i]);
        }
    }
}

static void test_emulator_tios_bcall_var_info_and_launcher_dispatch(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_os_var_info_t info;
    char rom_path[L_tmpnam];
    char program_path[L_tmpnam];
    char line[EZ80_HOME_COLS + 1u];
    uint8_t rom_bytes[] = { 0x00u };
    uint8_t module_bytes[] = { 0x3Eu, 0x2Au, 0x76u, 0x55u, 0xAAu };
    uint8_t info_bytes[EZ80_OS_VAR_INFO_BYTES];
    uint8_t value = 0u;
    uint32_t ram_addr = 0u;
    uint32_t archive_addr = 0u;
    uint32_t result = 0u;
    uint32_t crc = test_crc32(module_bytes, sizeof(module_bytes));
    size_t i;

    printf("[TEST] TI-OS bcall var-info + launcher dispatch + RAM execution\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create tiny ROM for launcher-dispatch test");
    ASSERT_TRUE(write_temp_file(module_bytes, sizeof(module_bytes), program_path, sizeof(program_path)),
                "create module payload for launcher-dispatch test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "launcher-dispatch init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "launcher-dispatch load ROM");

    status = ez80_emulator_load_program_file(&emu, "CECALC", program_path, true);
    ASSERT_EQ_INT(EZ80_OK, status, "load archived module for launcher dispatch");
    status = write_name_to_memory(&emu, EZ80_RAM_BASE + 0x0100u, "CECALC");
    ASSERT_EQ_INT(EZ80_OK, status, "write module name to emulated RAM for bcall args");

    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_PROGRAM_LAUNCH,
                                 EZ80_RAM_BASE + 0x0100u,
                                 0u,
                                 0u,
                                 0u,
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall ProgramLaunch");
    ram_addr = result;
    ASSERT_TRUE(ram_addr >= EZ80_RAM_BASE, "ProgramLaunch should return RAM execution address");

    emu.cpu.pc = ram_addr;
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "execute launched module LD A,n from RAM");
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "execute launched module HALT from RAM");
    ASSERT_EQ_INT(0x2A, cpu_reg_a(&emu.cpu), "launched module should set A=0x2A");
    ASSERT_TRUE(emu.cpu.halted, "launched module should halt after execution");

    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_VAR_GET_INFO,
                                 EZ80_RAM_BASE + 0x0100u,
                                 EZ80_OS_VAR_PROGRAM,
                                 EZ80_RAM_BASE + 0x0120u,
                                 EZ80_OS_VAR_INFO_BYTES,
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall VarGetInfo for launched module");
    ASSERT_EQ_U32(sizeof(module_bytes), result, "VarGetInfo result should report module size");
    for (i = 0u; i < EZ80_OS_VAR_INFO_BYTES; i++) {
        status = ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x0120u + (uint32_t)i, &info_bytes[i]);
        ASSERT_EQ_INT(EZ80_OK, status, "read VarGetInfo payload byte");
    }
    ASSERT_EQ_INT(1, info_bytes[0], "VarGetInfo exists byte");
    ASSERT_EQ_INT(1, info_bytes[1], "VarGetInfo archived byte");
    ASSERT_EQ_INT(1, info_bytes[2], "VarGetInfo loaded-in-RAM byte");
    ASSERT_EQ_INT(EZ80_OS_VAR_PROGRAM, info_bytes[3], "VarGetInfo type byte");
    ASSERT_EQ_U32(sizeof(module_bytes),
                  ((uint32_t)info_bytes[4] | ((uint32_t)info_bytes[5] << 8) | ((uint32_t)info_bytes[6] << 16)),
                  "VarGetInfo size bytes");

    ASSERT_EQ_INT('C', emu.memory.mmio[EZ80_MMIO_REG_OS_ACTIVE_PROGRAM_NAME_0],
                  "active-program MMIO name byte 0");
    ASSERT_EQ_INT('E', emu.memory.mmio[EZ80_MMIO_REG_OS_ACTIVE_PROGRAM_NAME_1],
                  "active-program MMIO name byte 1");
    ASSERT_EQ_INT('C', emu.memory.mmio[EZ80_MMIO_REG_OS_ACTIVE_PROGRAM_NAME_2],
                  "active-program MMIO name byte 2");
    ASSERT_EQ_INT(1u, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_LAUNCH_COUNT_0), "launch count should increment");
    ASSERT_EQ_U32(ram_addr, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_ACTIVE_PROGRAM_RAM_0),
                  "active-program RAM MMIO should match launch result");

    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_PROGRAM_FINISH,
                                 0u,
                                 0u,
                                 0u,
                                 0u,
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "bcall ProgramFinish with active-module shortcut");
    archive_addr = result;
    ASSERT_TRUE(archive_addr > 0u, "ProgramFinish should return archive address");

    status = ez80_emulator_os_var_get_info(&emu, "CECALC", EZ80_OS_VAR_PROGRAM, &info);
    ASSERT_EQ_INT(EZ80_OK, status, "get program info after ProgramFinish");
    ASSERT_TRUE(!info.loaded_in_ram, "ProgramFinish should return module to archive");
    ASSERT_EQ_INT(0, emu.memory.mmio[EZ80_MMIO_REG_OS_ACTIVE_PROGRAM_NAME_0],
                  "active-program MMIO name should clear after ProgramFinish");
    ASSERT_EQ_U32(2u, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_SWAP_COUNT_0),
                  "swap count should include launch and finish");
    ASSERT_EQ_U32(crc, read_mmio_u32(&emu, EZ80_MMIO_REG_OS_LAST_SWAP_ARCHIVE_CRC_0),
                  "archive CRC MMIO should match module payload CRC");
    ASSERT_EQ_U32(crc, read_mmio_u32(&emu, EZ80_MMIO_REG_OS_LAST_SWAP_RAM_CRC_0),
                  "RAM CRC MMIO should match module payload CRC");

    status = ez80_emulator_home_get_line(&emu, 1u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "read homescreen launch line");
    ASSERT_TRUE(strncmp(line, "RUN: CECALC", 11u) == 0, "homescreen should record launcher dispatch");
    status = ez80_emulator_home_get_line(&emu, 2u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "read homescreen finish line");
    ASSERT_TRUE(strncmp(line, "DONE: CECALC", 12u) == 0, "homescreen should record module finish");

    remove(program_path);
    remove(rom_path);
}

static void test_emulator_runtime_hardening_expansion(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_run_result_t run_result;
    ez80_os_var_info_t info;
    ez80_screen_text_state_t state;
    char rom_path[L_tmpnam];
    char program_path_a[L_tmpnam];
    char program_path_b[L_tmpnam];
    char line[EZ80_HOME_COLS + 1u];
    char active_name[EZ80_OS_VAR_NAME_MAX + 1u];
    char ascii[2048];
    uint32_t ascii_len = 0u;
    uint32_t result = 0u;
    uint32_t ram_addr = 0u;
    uint8_t pending = 0u;
    uint8_t roundtrip[32];
    const uint8_t rom_bytes[] = { 0x00u };
    const uint8_t module_a[] = { 0x3Eu, 0x31u, 0x76u };
    const uint8_t module_b[] = { 0x3Eu, 0x47u, 0x76u };
    const uint8_t payload_a[] = "SHOW=1;PREC=6";
    const uint8_t payload_b[] = "SHOW=0;PREC=4";
    const uint32_t name_addr = EZ80_RAM_BASE + 0x0100u;
    const uint32_t put_addr = EZ80_RAM_BASE + 0x0200u;
    const uint32_t get_addr = EZ80_RAM_BASE + 0x0240u;
    size_t i;

    printf("[TEST] runtime hardening expansion: BCALL vars, launcher, LCD, keypad, timer\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "runtime hardening: create ROM file");
    ASSERT_TRUE(write_temp_file(module_a, sizeof(module_a), program_path_a, sizeof(program_path_a)),
                "runtime hardening: create module A file");
    ASSERT_TRUE(write_temp_file(module_b, sizeof(module_b), program_path_b, sizeof(program_path_b)),
                "runtime hardening: create module B file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: load ROM");
    status = ez80_emulator_load_program_file(&emu, "CEALG", program_path_a, true);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: load archived CEALG");
    status = ez80_emulator_load_program_file(&emu, "CEGRPH", program_path_b, true);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: load archived CEGRPH");

    /* The scaffold models AppVar persistence through the string-var path. */
    status = write_name_to_memory(&emu, name_addr, "CESETTNG");
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: write AppVar name");
    status = write_bytes_to_memory(&emu, put_addr, payload_a, sizeof(payload_a) - 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: seed AppVar payload A");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_VAR_PUT,
                                 name_addr,
                                 EZ80_OS_VAR_STRING | 0x100u,
                                 put_addr,
                                 (uint32_t)(sizeof(payload_a) - 1u),
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: bcall VarPut payload A");
    ASSERT_EQ_U32(sizeof(payload_a) - 1u, result, "runtime hardening: VarPut payload A size");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_VAR_GET,
                                 name_addr,
                                 EZ80_OS_VAR_STRING,
                                 get_addr,
                                 (uint32_t)(sizeof(payload_a) - 1u),
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: bcall VarGet payload A");
    ASSERT_EQ_U32(sizeof(payload_a) - 1u, result, "runtime hardening: VarGet payload A size");
    status = read_bytes_from_memory(&emu, get_addr, roundtrip, sizeof(payload_a) - 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read back payload A");
    ASSERT_TRUE(memcmp(roundtrip, payload_a, sizeof(payload_a) - 1u) == 0,
                "runtime hardening: payload A round-trips through BCALL var I/O");
    status = ez80_emulator_os_var_get_info(&emu, "CESETTNG", EZ80_OS_VAR_STRING, &info);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: AppVar info after payload A");
    ASSERT_TRUE(info.exists, "runtime hardening: AppVar exists after first save");
    ASSERT_TRUE(info.archived, "runtime hardening: AppVar stays archived");
    ASSERT_EQ_INT(EZ80_OS_VAR_STRING, info.type, "runtime hardening: AppVar scaffold type");
    ASSERT_EQ_U32(sizeof(payload_a) - 1u, info.size_bytes, "runtime hardening: AppVar size A");

    status = write_bytes_to_memory(&emu, put_addr, payload_b, sizeof(payload_b) - 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: seed AppVar payload B");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_VAR_PUT,
                                 name_addr,
                                 EZ80_OS_VAR_STRING | 0x100u,
                                 put_addr,
                                 (uint32_t)(sizeof(payload_b) - 1u),
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: bcall VarPut payload B");
    ASSERT_EQ_U32(sizeof(payload_b) - 1u, result, "runtime hardening: VarPut payload B size");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_VAR_GET,
                                 name_addr,
                                 EZ80_OS_VAR_STRING,
                                 get_addr,
                                 (uint32_t)(sizeof(payload_b) - 1u),
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: bcall VarGet payload B");
    status = read_bytes_from_memory(&emu, get_addr, roundtrip, sizeof(payload_b) - 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read back payload B");
    ASSERT_TRUE(memcmp(roundtrip, payload_b, sizeof(payload_b) - 1u) == 0,
                "runtime hardening: payload B overwrites previous AppVar contents");
    status = ez80_emulator_os_var_get_info(&emu, "CESETTNG", EZ80_OS_VAR_STRING, &info);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: AppVar info after payload B");
    ASSERT_EQ_U32(sizeof(payload_b) - 1u, info.size_bytes, "runtime hardening: AppVar size B");

    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: homescreen clear");
    for (i = 0u; i < 5u; i++) {
        status = ez80_emulator_bcall(&emu,
                                     EZ80_BCALL_HOME_PUTC,
                                     (uint32_t)"READY"[i],
                                     0u,
                                     0u,
                                     0u,
                                     NULL);
        ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: homescreen READY write");
    }
    status = ez80_emulator_home_get_line(&emu, 0u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read READY homescreen line");
    ASSERT_TRUE(strncmp(line, "READY", 5u) == 0, "runtime hardening: READY line persists");
    status = ez80_emulator_lcd_to_ascii(&emu, ascii, sizeof(ascii), &ascii_len);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: lcd_to_ascii after READY");
    ASSERT_TRUE(ascii_len > 0u, "runtime hardening: ascii render length non-zero");
    ASSERT_TRUE(strncmp(ascii, "READY", 5u) == 0, "runtime hardening: ascii render shows READY");

    status = write_name_to_memory(&emu, name_addr, "CEALG");
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: write CEALG launch name");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_PROGRAM_LAUNCH,
                                 name_addr,
                                 0u,
                                 0u,
                                 0u,
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: launch CEALG");
    ram_addr = result;
    read_active_program_name_mmio(&emu, active_name, sizeof(active_name));
    ASSERT_TRUE(strcmp(active_name, "CEALG") == 0, "runtime hardening: active program name shows CEALG");
    emu.cpu.halted = false;
    emu.cpu.pc = ram_addr;
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: CEALG LD A,n step");
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: CEALG HALT step");
    ASSERT_EQ_INT(0x31, cpu_reg_a(&emu.cpu), "runtime hardening: CEALG leaves expected A value");
    ASSERT_TRUE(emu.cpu.halted, "runtime hardening: CEALG halts");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_PROGRAM_FINISH,
                                 0u,
                                 0u,
                                 0u,
                                 0u,
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: finish CEALG");
    read_active_program_name_mmio(&emu, active_name, sizeof(active_name));
    ASSERT_TRUE(active_name[0] == '\0', "runtime hardening: active program clears after CEALG finish");

    status = write_name_to_memory(&emu, name_addr, "CEGRPH");
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: write CEGRPH launch name");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_PROGRAM_LAUNCH,
                                 name_addr,
                                 0u,
                                 0u,
                                 0u,
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: launch CEGRPH");
    ram_addr = result;
    read_active_program_name_mmio(&emu, active_name, sizeof(active_name));
    ASSERT_TRUE(strcmp(active_name, "CEGRPH") == 0, "runtime hardening: active program name shows CEGRPH");
    emu.cpu.halted = false;
    emu.cpu.pc = ram_addr;
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: CEGRPH LD A,n step");
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: CEGRPH HALT step");
    ASSERT_EQ_INT(0x47, cpu_reg_a(&emu.cpu), "runtime hardening: CEGRPH leaves expected A value");
    ASSERT_TRUE(emu.cpu.halted, "runtime hardening: CEGRPH halts");
    status = ez80_emulator_bcall(&emu,
                                 EZ80_BCALL_PROGRAM_FINISH,
                                 0u,
                                 0u,
                                 0u,
                                 0u,
                                 &result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: finish CEGRPH");

    ASSERT_EQ_U32(2u, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_LAUNCH_COUNT_0),
                  "runtime hardening: launch count covers both programs");
    ASSERT_EQ_U32(4u, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_SWAP_COUNT_0),
                  "runtime hardening: swap count covers launch+finish cycles");

    status = ez80_emulator_home_get_line(&emu, 0u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read homescreen row0");
    ASSERT_TRUE(strncmp(line, "READY", 5u) == 0, "runtime hardening: row0 stays READY");
    status = ez80_emulator_home_get_line(&emu, 1u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read homescreen row1");
    ASSERT_TRUE(strncmp(line, "RUN: CEALG", 10u) == 0, "runtime hardening: row1 records CEALG launch");
    status = ez80_emulator_home_get_line(&emu, 2u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read homescreen row2");
    ASSERT_TRUE(strncmp(line, "DONE: CEALG", 11u) == 0, "runtime hardening: row2 records CEALG finish");
    status = ez80_emulator_home_get_line(&emu, 3u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read homescreen row3");
    ASSERT_TRUE(strncmp(line, "RUN: CEGRPH", 11u) == 0, "runtime hardening: row3 records CEGRPH launch");
    status = ez80_emulator_home_get_line(&emu, 4u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read homescreen row4");
    ASSERT_TRUE(strncmp(line, "DONE: CEGRPH", 12u) == 0, "runtime hardening: row4 records CEGRPH finish");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: get screen text state");
    ASSERT_TRUE(state.homescreen_active, "runtime hardening: screen state homescreen active");
    ASSERT_TRUE(strncmp(state.visible_lines[0], "READY", 5u) == 0,
                "runtime hardening: screen state row0 shows READY");
    ASSERT_TRUE(strncmp(state.visible_lines[4], "DONE: CEGRPH", 12u) == 0,
                "runtime hardening: screen state row4 shows CEGRPH completion");

    status = ez80_emulator_release_all_keys(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: release all keys before keypad test");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_ACK, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: clear pending IRQs before keypad test");
    emu.hw.kbd_irq_on_keypress = true;
    status = ez80_emulator_inject_key(&emu, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: inject key 0x00");
    status = ez80_emulator_inject_key(&emu, 0x09u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: inject key 0x09");
    status = ez80_emulator_inject_key(&emu, 0x12u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: inject key 0x12");
    ASSERT_TRUE((emu.hw.keypad_rows[0] & 0x01u) == 0u, "runtime hardening: row0 bit0 clears");
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x02u) == 0u, "runtime hardening: row1 bit1 clears");
    ASSERT_TRUE((emu.hw.keypad_rows[2] & 0x04u) == 0u, "runtime hardening: row2 bit2 clears");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_KEYPAD) != 0u,
                "runtime hardening: keypad sequence raises IRQ");
    status = ez80_emulator_release_key(&emu, 0x09u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: release middle keypad key");
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x02u) != 0u, "runtime hardening: released key bit restores");
    ASSERT_TRUE((emu.hw.keypad_rows[0] & 0x01u) == 0u, "runtime hardening: first pressed key stays active");
    ASSERT_TRUE((emu.hw.keypad_rows[2] & 0x04u) == 0u, "runtime hardening: third pressed key stays active");
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: screen state after keypad sequence");
    ASSERT_TRUE(strncmp(state.visible_lines[0], "READY", 5u) == 0,
                "runtime hardening: keypad sequence preserves READY text");
    ASSERT_TRUE(strncmp(state.visible_lines[4], "DONE: CEGRPH", 12u) == 0,
                "runtime hardening: keypad sequence preserves completion text");
    status = ez80_emulator_release_all_keys(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: release all keys after keypad sequence");
    for (i = 0u; i < 8u; i++) {
        ASSERT_EQ_INT(0xFF, emu.hw.keypad_rows[i], "runtime hardening: all keypad rows restore high");
    }
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_ACK, EZ80_IRQ_SOURCE_KEYPAD);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: ack keypad IRQ");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_PENDING, &pending);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read IRQ pending after keypad ack");
    ASSERT_TRUE((pending & EZ80_IRQ_SOURCE_KEYPAD) == 0u,
                "runtime hardening: keypad IRQ clears after ack");

    status = ez80_emulator_set_timer_prescaler(&emu, 0u, EZ80_TIMER_PRESCALER_1);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: set timer0 prescaler");
    status = ez80_emulator_set_timer_reload(&emu, 0u, 0x1234u);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: set timer0 reload");
    emu.hw.timer0_control = EZ80_TIMER_CONTROL_ENABLE |
                            EZ80_TIMER_CONTROL_IRQ_ENABLE |
                            EZ80_TIMER_CONTROL_RELOAD;
    emu.hw.timer0_counter = 0xFFFEu;
    emu.cpu.halted = false;
    emu.cpu.pc = 0u;
    status = ez80_emulator_run_cycles(&emu, 32u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: run cycles for timer overflow");
    ASSERT_TRUE(run_result.cycles_executed > 0u, "runtime hardening: timer run executes cycles");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_TIMER0) != 0u,
                "runtime hardening: timer overflow raises IRQ");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_PENDING, &pending);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read timer IRQ pending");
    ASSERT_TRUE((pending & EZ80_IRQ_SOURCE_TIMER0) != 0u,
                "runtime hardening: timer IRQ visible through port");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_ACK, EZ80_IRQ_SOURCE_TIMER0);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: ack timer IRQ");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_PENDING, &pending);
    ASSERT_EQ_INT(EZ80_OK, status, "runtime hardening: read timer IRQ pending after ack");
    ASSERT_TRUE((pending & EZ80_IRQ_SOURCE_TIMER0) == 0u,
                "runtime hardening: timer IRQ clears from port after ack");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_TIMER0) == 0u,
                "runtime hardening: timer IRQ clears from hardware after ack");

    remove(program_path_a);
    remove(program_path_b);
    remove(rom_path);
}

static void test_emulator_tios_archive_integrity_detection(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_os_var_info_t info;
    uint8_t module_bytes[] = { 0x3Eu, 0x44u, 0x76u, 0x12u, 0x34u };
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    char program_path[L_tmpnam];
    uint8_t rom_bytes[] = { 0x00u };

    printf("[TEST] archive->RAM integrity detection on archived payload corruption\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ROM for archive integrity test");
    ASSERT_TRUE(write_temp_file(module_bytes, sizeof(module_bytes), program_path, sizeof(program_path)),
                "create module payload for archive integrity test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "archive integrity init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "archive integrity load ROM");

    status = ez80_emulator_load_program_file(&emu, "CEINTG", program_path, true);
    ASSERT_EQ_INT(EZ80_OK, status, "load archived module for integrity test");
    status = ez80_emulator_os_var_get_info(&emu, "CEINTG", EZ80_OS_VAR_PROGRAM, &info);
    ASSERT_EQ_INT(EZ80_OK, status, "get module info before integrity corruption");
    ASSERT_TRUE(info.archived, "integrity test module should be archived");
    ASSERT_TRUE(info.archive_addr > 0u, "integrity test module should have archive address");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "enable flash unlock before archive corruption injection");
    status = ez80_memory_write8(&emu, info.archive_addr + 1u, 0x99u);
    ASSERT_EQ_INT(EZ80_OK, status, "inject archive corruption byte");

    status = ez80_emulator_launch_program(&emu, "CEINTG", NULL);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS,
                  status,
                  "archive->RAM launch should fail when archived payload CRC mismatches");
    ASSERT_EQ_INT(EZ80_OS_SWAP_FAILURE_INTEGRITY,
                  emu.memory.mmio[EZ80_MMIO_REG_OS_LAST_SWAP_FAILURE],
                  "integrity mismatch should surface through swap-failure MMIO code");

    status = ez80_memory_read8(&emu, info.archive_addr + 1u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read corrupted archive byte for sanity");
    ASSERT_EQ_INT(0x99, value, "archive corruption byte should persist for diagnostic visibility");

    remove(program_path);
    remove(rom_path);
}

static void test_emulator_tios_multi_module_rapid_swap_pressure_integrity(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    uint8_t rom_bytes[] = { 0x00u };
    char rom_path[L_tmpnam];
    size_t i;
    size_t cycle;
    uint32_t ram_addr = 0u;
    uint32_t archive_addr = 0u;
    uint32_t launch_count = 0u;
    uint32_t swap_count = 0u;
    uint32_t swap_fail_count = 0u;
    uint32_t archive_crc = 0u;
    uint32_t ram_crc = 0u;
    size_t module_size = 12288u; /* 12KB each: first 8 fill the 96KB swap RAM pool */
    uint8_t *module_bytes = NULL;
    static const char *program_names[9] = {
        "CALCENG", "CEALG", "CECALC", "CELIMS", "CEMAT",
        "CESTPRB", "CEFIN", "CEGRPH", "CELSCX"
    };
    const size_t program_count = sizeof(program_names) / sizeof(program_names[0]);
    char program_paths[9][260];
    uint8_t persisted_value;

    printf("[TEST] multi-module rapid archive<->RAM swap pressure + integrity\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create tiny ROM for multi-module swap stress test");
    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "multi-module swap init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "multi-module swap load ROM");

    module_bytes = (uint8_t *)malloc(module_size);
    ASSERT_TRUE(module_bytes != NULL, "allocate module payload buffer");
    if (!module_bytes) {
        remove(rom_path);
        return;
    }

    for (i = 0u; i < program_count; i++) {
        size_t j;
        for (j = 0u; j < module_size; j++) {
            module_bytes[j] = (uint8_t)((i * 31u + j) & 0xFFu);
        }
        module_bytes[0] = 0x3Eu;
        module_bytes[1] = (uint8_t)(0x20u + i);
        module_bytes[2] = 0x76u;
        ASSERT_TRUE(write_temp_file(module_bytes, module_size, program_paths[i], sizeof(program_paths[i])),
                    "create per-module swap stress payload");
        status = ez80_emulator_load_program_file(&emu, program_names[i], program_paths[i], true);
        ASSERT_EQ_INT(EZ80_OK, status, "load module payload into archive pool");
    }

    for (i = 0u; i < program_count; i++) {
        status = ez80_emulator_launch_program(&emu, program_names[i], &ram_addr);
        if (i < 8u) {
            ASSERT_EQ_INT(EZ80_OK, status, "launch module while RAM pool has capacity");
            emu.cpu.halted = false;
            emu.cpu.pc = ram_addr;
            status = ez80_emulator_step(&emu, &decoded);
            ASSERT_EQ_INT(EZ80_OK, status, "execute launched module LD A,n");
            status = ez80_emulator_step(&emu, &decoded);
            ASSERT_EQ_INT(EZ80_OK, status, "execute launched module HALT");
            ASSERT_EQ_INT((int)(0x20u + i), cpu_reg_a(&emu.cpu), "module launch should load module-specific ID into A");
            status = ez80_memory_write8(&emu, ram_addr + 4u, (uint8_t)(0x80u + i));
            ASSERT_EQ_INT(EZ80_OK, status, "mutate module RAM payload before return-to-archive");
            status = ez80_emulator_finish_program(&emu, program_names[i], &archive_addr);
            ASSERT_EQ_INT(EZ80_OK, status, "finish launched module");
            ASSERT_TRUE(archive_addr > 0u, "finish should return archive location");

            status = ez80_emulator_launch_program(&emu, program_names[i], &ram_addr);
            ASSERT_EQ_INT(EZ80_OK, status, "relaunch module after archive round-trip");
            status = ez80_memory_read8(&emu, ram_addr + 4u, &persisted_value);
            ASSERT_EQ_INT(EZ80_OK, status, "read persisted RAM byte after round-trip");
            ASSERT_EQ_INT((int)(0x80u + i), persisted_value, "round-trip should preserve module payload mutation");
            status = ez80_emulator_finish_program(&emu, program_names[i], &archive_addr);
            ASSERT_EQ_INT(EZ80_OK, status, "finish relaunched module");
        } else {
            ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "launch should fail once 96KB RAM pool is saturated");
            ASSERT_EQ_INT(EZ80_OS_SWAP_FAILURE_RAM_CAPACITY,
                          emu.memory.mmio[EZ80_MMIO_REG_OS_LAST_SWAP_FAILURE],
                          "swap failure reason should report RAM-capacity pressure");
        }
    }

    for (cycle = 0u; cycle < 64u; cycle++) {
        i = cycle % 8u;
        status = ez80_emulator_launch_program(&emu, program_names[i], &ram_addr);
        ASSERT_EQ_INT(EZ80_OK, status, "rapid-cycle launch among loaded modules");
        status = ez80_memory_write8(&emu, ram_addr + 5u, (uint8_t)(cycle & 0xFFu));
        ASSERT_EQ_INT(EZ80_OK, status, "rapid-cycle mutate module payload");
        status = ez80_emulator_finish_program(&emu, program_names[i], &archive_addr);
        ASSERT_EQ_INT(EZ80_OK, status, "rapid-cycle finish module");
    }

    launch_count = read_mmio_u24(&emu, EZ80_MMIO_REG_OS_LAUNCH_COUNT_0);
    swap_count = read_mmio_u24(&emu, EZ80_MMIO_REG_OS_SWAP_COUNT_0);
    swap_fail_count = read_mmio_u24(&emu, EZ80_MMIO_REG_OS_SWAP_FAIL_COUNT_0);
    archive_crc = read_mmio_u32(&emu, EZ80_MMIO_REG_OS_LAST_SWAP_ARCHIVE_CRC_0);
    ram_crc = read_mmio_u32(&emu, EZ80_MMIO_REG_OS_LAST_SWAP_RAM_CRC_0);

    ASSERT_EQ_U32(80u, launch_count, "launch count should include initial and rapid-cycle launches");
    ASSERT_EQ_U32(160u, swap_count, "swap count should include each archive->RAM and RAM->archive success");
    ASSERT_EQ_U32(1u, swap_fail_count, "swap failure count should record saturated-RAM launch failure");
    ASSERT_EQ_U32(archive_crc, ram_crc, "last swap archive/RAM CRC telemetry should agree");
    ASSERT_TRUE(archive_crc != 0u, "last swap CRC should be non-zero after payload mutations");

    for (i = 0u; i < program_count; i++) {
        if (program_paths[i][0] != '\0') {
            remove(program_paths[i]);
        }
    }
    free(module_bytes);
    remove(rom_path);
}

static void test_emulator_tios_launch_finish_screen_state_sequence(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_screen_text_state_t state;
    uint8_t rom_bytes[] = { 0x00u };
    uint8_t calceng_bytes[] = { 0x3Eu, 0x41u, 0x76u };
    uint8_t cecalc_bytes[] = { 0x3Eu, 0x52u, 0x76u };
    char rom_path[L_tmpnam];
    char calceng_path[L_tmpnam];
    char cecalc_path[L_tmpnam];
    uint32_t ram_addr = 0u;
    uint32_t archive_addr = 0u;

    printf("[TEST] launch/finish screen-state sequencing across active programs\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ROM for screen-state sequence");
    ASSERT_TRUE(write_temp_file(calceng_bytes, sizeof(calceng_bytes), calceng_path, sizeof(calceng_path)),
                "create CALCENG payload for screen-state sequence");
    ASSERT_TRUE(write_temp_file(cecalc_bytes, sizeof(cecalc_bytes), cecalc_path, sizeof(cecalc_path)),
                "create CECALC payload for screen-state sequence");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence load ROM");
    status = ez80_emulator_load_program_file(&emu, "CALCENG", calceng_path, true);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence load CALCENG");
    status = ez80_emulator_load_program_file(&emu, "CECALC", cecalc_path, true);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence load CECALC");

    status = ez80_emulator_launch_program(&emu, "CALCENG", &ram_addr);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence launch CALCENG");
    ASSERT_TRUE(ram_addr >= EZ80_RAM_BASE, "screen-state sequence CALCENG launch returns RAM");
    ASSERT_TRUE(strcmp(emu.os.active_program_name, "CALCENG") == 0,
                "screen-state sequence CALCENG becomes active");

    status = ez80_emulator_finish_program(&emu, NULL, &archive_addr);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence finish active CALCENG");
    ASSERT_TRUE(archive_addr > 0u, "screen-state sequence finish returns archive address");

    status = ez80_emulator_launch_program(&emu, "CECALC", &ram_addr);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence launch CECALC");
    ASSERT_TRUE(strcmp(emu.os.active_program_name, "CECALC") == 0,
                "screen-state sequence CECALC becomes active");
    ASSERT_EQ_U32(ram_addr, emu.os.active_program_ram_addr,
                  "screen-state sequence active RAM address tracks launch");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence capture during active handoff");
    ASSERT_TRUE(state.homescreen_active, "screen-state sequence homescreen overlay is active");
    ASSERT_EQ_INT(2, state.step_line_count, "screen-state sequence prior run/done rows become steps");
    ASSERT_TRUE(strncmp(state.step_lines[0], "RUN: CALCENG", 12u) == 0,
                "screen-state sequence first step line captures first launch");
    ASSERT_TRUE(strncmp(state.step_lines[1], "DONE: CALCENG", 13u) == 0,
                "screen-state sequence second step line captures first finish");
    ASSERT_TRUE(strncmp(state.input_line, "RUN: CECALC", 11u) == 0,
                "screen-state sequence current input line captures active launch");
    ASSERT_TRUE(strncmp(state.visible_lines[state.cursor_row], "RUN: CECALC", 11u) == 0,
                "screen-state sequence visible cursor row matches input line");

    status = ez80_emulator_finish_program(&emu, NULL, &archive_addr);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence finish active CECALC");
    ASSERT_TRUE(emu.os.active_program_name[0] == '\0',
                "screen-state sequence active program clears after finish");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "screen-state sequence capture after final finish");
    ASSERT_EQ_INT(3, state.step_line_count, "screen-state sequence latest run row becomes a step");
    ASSERT_TRUE(strncmp(state.step_lines[2], "RUN: CECALC", 11u) == 0,
                "screen-state sequence third step line captures second launch");
    ASSERT_TRUE(strncmp(state.input_line, "DONE: CECALC", 12u) == 0,
                "screen-state sequence final input line captures second finish");
    ASSERT_EQ_U32(2u, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_LAUNCH_COUNT_0),
                  "screen-state sequence launch count tracks both launches");
    ASSERT_EQ_U32(4u, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_SWAP_COUNT_0),
                  "screen-state sequence swap count tracks launch/finish pairs");

    remove(cecalc_path);
    remove(calceng_path);
    remove(rom_path);
}

static void test_emulator_tios_split_module_dispatch_matrix(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    uint8_t rom_bytes[] = { 0x00u };
    char rom_path[L_tmpnam];
    char program_paths[8][260];
    char active_name[9];
    uint32_t ram_addr = 0u;
    uint32_t archive_addr = 0u;
    size_t i;
    struct {
        const char *name;
        uint8_t id;
    } modules[] = {
        { "CEALG", 0x31u },
        { "CECALC", 0x32u },
        { "CELIMS", 0x33u },
        { "CEMAT", 0x34u },
        { "CESTPRB", 0x35u },
        { "CEFIN", 0x36u },
        { "CEGRPH", 0x37u },
        { "CELSCX", 0x38u }
    };

    printf("[TEST] split-module launch/finish matrix across archived programs\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create tiny ROM for split-module dispatch matrix");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "split-module matrix init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "split-module matrix ROM load");

    memset(program_paths, 0, sizeof(program_paths));
    for (i = 0u; i < sizeof(modules) / sizeof(modules[0]); i++) {
        uint8_t module_bytes[] = { 0x3Eu, modules[i].id, 0x76u };
        ez80_os_var_info_t info;

        ASSERT_TRUE(write_temp_file(module_bytes,
                                    sizeof(module_bytes),
                                    program_paths[i],
                                    sizeof(program_paths[i])),
                    "create split-module payload");

        status = ez80_emulator_load_program_file(&emu, modules[i].name, program_paths[i], true);
        ASSERT_EQ_INT(EZ80_OK, status, "load split-module payload");

        status = ez80_emulator_os_var_get_info(&emu, modules[i].name, EZ80_OS_VAR_PROGRAM, &info);
        ASSERT_EQ_INT(EZ80_OK, status, "split-module info after load");
        ASSERT_TRUE(info.archived, "split-module payload should start archived");
        ASSERT_TRUE(!info.loaded_in_ram, "split-module payload should not start in RAM");

        status = ez80_emulator_launch_program(&emu, modules[i].name, &ram_addr);
        ASSERT_EQ_INT(EZ80_OK, status, "split-module launch");
        ASSERT_TRUE(ram_addr >= EZ80_RAM_BASE, "split-module launch returns RAM address");

        status = ez80_emulator_os_var_get_info(&emu, modules[i].name, EZ80_OS_VAR_PROGRAM, &info);
        ASSERT_EQ_INT(EZ80_OK, status, "split-module info after launch");
        ASSERT_TRUE(info.loaded_in_ram, "split-module should be loaded in RAM after launch");
        ASSERT_EQ_U32(ram_addr, read_mmio_u24(&emu, EZ80_MMIO_REG_OS_ACTIVE_PROGRAM_RAM_0),
                      "active-program RAM MMIO should match launched module");
        read_active_program_name_mmio(&emu, active_name, sizeof(active_name));
        ASSERT_TRUE(strcmp(active_name, modules[i].name) == 0,
                    "active-program MMIO name should match launched module");

        emu.cpu.halted = false;
        emu.cpu.pc = ram_addr;
        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "split-module execute LD A,n");
        status = ez80_emulator_step(&emu, &decoded);
        ASSERT_EQ_INT(EZ80_OK, status, "split-module execute HALT");
        ASSERT_EQ_INT((int)modules[i].id, cpu_reg_a(&emu.cpu),
                      "split-module payload should publish module-specific ID");

        status = ez80_emulator_finish_program(&emu, modules[i].name, &archive_addr);
        ASSERT_EQ_INT(EZ80_OK, status, "split-module finish");
        ASSERT_TRUE(archive_addr > 0u, "split-module finish returns archive address");

        status = ez80_emulator_os_var_get_info(&emu, modules[i].name, EZ80_OS_VAR_PROGRAM, &info);
        ASSERT_EQ_INT(EZ80_OK, status, "split-module info after finish");
        ASSERT_TRUE(!info.loaded_in_ram, "split-module should return to archive after finish");
        read_active_program_name_mmio(&emu, active_name, sizeof(active_name));
        ASSERT_TRUE(active_name[0] == '\0', "active-program MMIO name should clear after finish");
    }

    ASSERT_EQ_U32((uint32_t)(sizeof(modules) / sizeof(modules[0])),
                  read_mmio_u24(&emu, EZ80_MMIO_REG_OS_LAUNCH_COUNT_0),
                  "split-module launch count should match module matrix");
    ASSERT_EQ_U32((uint32_t)(2u * (sizeof(modules) / sizeof(modules[0]))),
                  read_mmio_u24(&emu, EZ80_MMIO_REG_OS_SWAP_COUNT_0),
                  "split-module swap count should include launch+finish for each module");

    for (i = 0u; i < sizeof(modules) / sizeof(modules[0]); i++) {
        if (program_paths[i][0] != '\0') {
            remove(program_paths[i]);
        }
    }
    remove(rom_path);
}

static void test_emulator_os_version_matrix_launcher_gate(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t rom_bytes[] = { 0x00u };
    uint8_t module_bytes[] = { 0x3Eu, 0x11u, 0x76u };
    char rom_path[L_tmpnam];
    char module_path[L_tmpnam];
    uint32_t ram_addr = 0u;
    uint32_t archive_addr = 0u;
    size_t i;
    struct {
        uint8_t major;
        uint8_t minor;
        uint8_t patch;
        bool native_allowed;
    } profiles[] = {
        { 5u, 3u, 0u, true },
        { 5u, 5u, 0u, false },
        { 5u, 6u, 0u, false },
        { 5u, 7u, 0u, false },
        { 5u, 8u, 0u, false }
    };

    printf("[TEST] OS-version matrix launcher gating (5.3/5.5/5.6/5.7/5.8)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create tiny ROM for OS matrix test");
    ASSERT_TRUE(write_temp_file(module_bytes, sizeof(module_bytes), module_path, sizeof(module_path)),
                "create module payload for OS matrix test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "OS matrix init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "OS matrix load ROM");
    status = ez80_emulator_load_program_file(&emu, "CEALG", module_path, true);
    ASSERT_EQ_INT(EZ80_OK, status, "OS matrix load module");

    for (i = 0u; i < sizeof(profiles) / sizeof(profiles[0]); i++) {
        status = ez80_emulator_set_os_version(&emu,
                                              profiles[i].major,
                                              profiles[i].minor,
                                              profiles[i].patch);
        ASSERT_EQ_INT(EZ80_OK, status, "set OS profile for matrix row");
        ASSERT_EQ_INT(profiles[i].native_allowed ? 1 : 0,
                      emu.memory.mmio[EZ80_MMIO_REG_NATIVE_UNSIGNED_EXEC_ALLOWED],
                      "native unsigned execution MMIO should match OS profile");

        status = ez80_emulator_launch_program(&emu, "CEALG", &ram_addr);
        if (profiles[i].native_allowed) {
            ASSERT_EQ_INT(EZ80_OK, status, "OS profile allowing native execution should launch module");
            status = ez80_emulator_finish_program(&emu, "CEALG", &archive_addr);
            ASSERT_EQ_INT(EZ80_OK, status, "finish module after native-launch matrix row");
        } else {
            ASSERT_EQ_INT(EZ80_ERR_NOT_IMPLEMENTED, status, "locked OS profile should block module launch pre-artifice");
            inject_artifice_key_sequence(&emu);
            status = ez80_emulator_launch_program(&emu, "CEALG", &ram_addr);
            ASSERT_EQ_INT(EZ80_OK, status, "artifice bypass should permit module launch on locked OS profile");
            status = ez80_emulator_finish_program(&emu, "CEALG", &archive_addr);
            ASSERT_EQ_INT(EZ80_OK, status, "finish module after artifice-enabled launch");
        }
    }

    remove(module_path);
    remove(rom_path);
}

static void test_emulator_dngrade_v4_cycle_matrix(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_dngrade_attempt_result_t attempt;
    uint8_t strategy_order[3] = {
        EZ80_DNGRADE_STRATEGY_DIRECT_FLASH_WRITE,
        EZ80_DNGRADE_STRATEGY_PORT28_UNLOCK_THEN_WRITE,
        EZ80_DNGRADE_STRATEGY_CERT_UNLOCK_THEN_WRITE
    };
    uint32_t target_addr = 0x020123u;
    uint8_t value = 0u;
    size_t cycle;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = { 0x00u };

    printf("[TEST] DNGRADE v4.0 cycle matrix (strategy cycling + no-hang budgets)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create tiny ROM for DNGRADE v4 cycle matrix");
    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "DNGRADE v4 matrix init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "DNGRADE v4 matrix load ROM");

    status = ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "DNGRADE v4 matrix set OS 5.4");
    for (cycle = 0u; cycle < 30u; cycle++) {
        uint8_t strategy = strategy_order[cycle % 3u];
        status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0u);
        ASSERT_EQ_INT(EZ80_OK, status, "reset unlock port before OS 5.4 DNGRADE cycle");
        status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x06u, 0u);
        ASSERT_EQ_INT(EZ80_OK, status, "reset protect port before OS 5.4 DNGRADE cycle");
        status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                        strategy,
                                                        target_addr,
                                                        0x00u,
                                                        256u,
                                                        256u,
                                                        &attempt);
        ASSERT_EQ_INT(EZ80_OK, status, "simulate DNGRADE v4 cycle on OS 5.4");
        ASSERT_TRUE(attempt.cycles_executed <= 256u, "OS 5.4 cycle should stay within no-hang budget");
        if (strategy == EZ80_DNGRADE_STRATEGY_DIRECT_FLASH_WRITE) {
            ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_FAILURE,
                          attempt.attempt_status,
                          "direct-write strategy should fail without explicit unlock");
            ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_FLASH_NOT_UNLOCKED,
                          attempt.failure_reason,
                          "direct-write failure reason should report unlock requirement");
        } else {
            ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_SUCCESS,
                          attempt.attempt_status,
                          "unlock-based strategies should succeed on OS 5.4");
            ASSERT_TRUE(attempt.write_succeeded, "successful OS 5.4 strategy should write target flash byte");
        }
    }

    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "DNGRADE v4 matrix set OS 5.8");
    inject_artifice_key_sequence(&emu);
    for (cycle = 0u; cycle < 30u; cycle++) {
        uint8_t strategy = strategy_order[cycle % 3u];
        status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0u);
        ASSERT_EQ_INT(EZ80_OK, status, "reset unlock port before OS 5.8 DNGRADE cycle");
        status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x06u, 0u);
        ASSERT_EQ_INT(EZ80_OK, status, "reset protect port before OS 5.8 DNGRADE cycle");
        status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                        strategy,
                                                        target_addr,
                                                        0x00u,
                                                        256u,
                                                        256u,
                                                        &attempt);
        ASSERT_EQ_INT(EZ80_OK, status, "simulate DNGRADE v4 cycle on OS 5.8");
        ASSERT_TRUE(attempt.cycles_executed <= 256u, "OS 5.8 cycle should stay within no-hang budget");
        ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_FAILURE,
                      attempt.attempt_status,
                      "all modeled DNGRADE strategies should fail on OS 5.8");
        if (strategy == EZ80_DNGRADE_STRATEGY_DIRECT_FLASH_WRITE) {
            ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_FLASH_NOT_UNLOCKED,
                          attempt.failure_reason,
                          "direct-write on OS 5.8 should fail before unlock");
        } else {
            ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_OS58_PORT28_BIT3_REQUIRED,
                          attempt.failure_reason,
                          "unlock-based OS 5.8 strategies should fail on bit3 gate requirement");
        }
    }

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_CERT_UNLOCK_THEN_WRITE,
                                                    target_addr,
                                                    0xEEu,
                                                    24u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "simulate timeout-bounded DNGRADE v4 attempt");
    ASSERT_TRUE(attempt.timed_out, "timeout-bounded DNGRADE v4 attempt should set timeout");
    ASSERT_TRUE(!attempt.watchdog_reset, "timeout-bounded DNGRADE v4 attempt should not set watchdog reset");
    ASSERT_TRUE(attempt.cycles_executed <= 24u, "timeout-bounded attempt should not exceed timeout cycles");

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_CERT_UNLOCK_THEN_WRITE,
                                                    target_addr,
                                                    0xEFu,
                                                    0u,
                                                    16u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "simulate watchdog-bounded DNGRADE v4 attempt");
    ASSERT_TRUE(!attempt.timed_out, "watchdog-bounded DNGRADE v4 attempt should not set timeout");
    ASSERT_TRUE(attempt.watchdog_reset, "watchdog-bounded DNGRADE v4 attempt should set watchdog reset");
    ASSERT_TRUE(attempt.cycles_executed <= 16u, "watchdog-bounded attempt should not exceed watchdog cycles");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_DNGRADE_LAST_ATTEMPT_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read DNGRADE MMIO status after v4 watchdog case");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_FAILURE, value, "v4 watchdog case should report failure status in MMIO");

    remove(rom_path);
}

static void test_emulator_adl_block_transfer_width(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint8_t rom_bytes[] = {
        0xEDu, 0xB0u, /* LDIR */
        0x76u         /* HALT */
    };

    printf("[TEST] ADL-width block transfer semantics for LDIR\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ROM for ADL-width LDIR test");
    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width LDIR init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width LDIR ROM load");

    emu.cpu.adl_mode = true;
    emu.cpu.pc = 0x000000u;
    emu.cpu.hl = 0xD0FFFEu;
    emu.cpu.de = 0xD1FFFEu;
    emu.cpu.bc = 0x000003u;

    status = ez80_memory_write8(&emu, 0xD0FFFEu, 0x11u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed ADL LDIR source byte 0");
    status = ez80_memory_write8(&emu, 0xD0FFFFu, 0x22u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed ADL LDIR source byte 1");
    status = ez80_memory_write8(&emu, 0xD10000u, 0x33u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed ADL LDIR source byte 2");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LDIR step 1");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LDIR state after step 1");
    ASSERT_EQ_U32(0x000000u, cpu.pc, "LDIR step 1 should repeat at same PC while BC!=0");
    ASSERT_EQ_U32(0xD0FFFFu, cpu.hl, "ADL LDIR step 1 should increment full 24-bit HL");
    ASSERT_EQ_U32(0xD1FFFFu, cpu.de, "ADL LDIR step 1 should increment full 24-bit DE");
    ASSERT_EQ_U32(0x000002u, cpu.bc, "ADL LDIR step 1 should decrement BC to 2");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LDIR step 2");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LDIR state after step 2");
    ASSERT_EQ_U32(0x000000u, cpu.pc, "LDIR step 2 should still repeat at same PC while BC!=0");
    ASSERT_EQ_U32(0xD10000u, cpu.hl, "ADL LDIR step 2 should cross 0xD0FFFF->0xD10000");
    ASSERT_EQ_U32(0xD20000u, cpu.de, "ADL LDIR step 2 should cross 0xD1FFFF->0xD20000");
    ASSERT_EQ_U32(0x000001u, cpu.bc, "ADL LDIR step 2 should decrement BC to 1");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LDIR step 3");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LDIR state after step 3");
    ASSERT_EQ_U32(0x000002u, cpu.pc, "LDIR step 3 should fall through when BC reaches 0");
    ASSERT_EQ_U32(0xD10001u, cpu.hl, "ADL LDIR step 3 should preserve 24-bit HL increment");
    ASSERT_EQ_U32(0xD20001u, cpu.de, "ADL LDIR step 3 should preserve 24-bit DE increment");
    ASSERT_EQ_U32(0x000000u, cpu.bc, "ADL LDIR step 3 should decrement BC to 0");

    status = ez80_memory_read8(&emu, 0xD1FFFEu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read ADL LDIR dest byte 0");
    ASSERT_EQ_INT(0x11, value, "ADL LDIR dest byte 0 should match source");
    status = ez80_memory_read8(&emu, 0xD1FFFFu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read ADL LDIR dest byte 1");
    ASSERT_EQ_INT(0x22, value, "ADL LDIR dest byte 1 should match source");
    status = ez80_memory_read8(&emu, 0xD20000u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read ADL LDIR dest byte 2");
    ASSERT_EQ_INT(0x33, value, "ADL LDIR dest byte 2 should match source");

    remove(rom_path);
}

static void test_emulator_adl_block_io_b_counter_width(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint8_t rom_bytes[] = {
        0xEDu, 0x82u, /* INIM */
        0xEDu, 0x83u, /* OTIM */
        0x76u         /* HALT */
    };

    printf("[TEST] ADL-width HL behavior for eZ80 block-I/O B-counter ops\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ROM for ADL-width block-I/O B-counter test");
    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width block-I/O B-counter init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width block-I/O B-counter ROM load");

    emu.cpu.adl_mode = true;
    emu.cpu.pc = 0x000000u;
    emu.cpu.hl = 0xD0FFFFu;
    emu.cpu.bc = 0xAB0210u; /* upper BC byte should remain intact */
    emu.memory.ports[0x10u] = 0x5Au;

    status = ez80_memory_write8(&emu, 0xD00000u, 0x4Cu);
    ASSERT_EQ_INT(EZ80_OK, status, "seed wrapped-page sentinel for ADL block-I/O B-counter test");
    status = ez80_memory_write8(&emu, 0xD10000u, 0xA7u);
    ASSERT_EQ_INT(EZ80_OK, status, "seed cross-page source byte for ADL block-I/O B-counter test");

    status = ez80_emulator_step(&emu, &decoded); /* INIM */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL block-I/O B-counter step INIM");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL block-I/O B-counter state after INIM");
    ASSERT_EQ_U32(0x000002u, cpu.pc, "INIM should advance to OTIM opcode");
    ASSERT_EQ_U32(0xD10000u, cpu.hl, "INIM should increment full 24-bit HL across page boundary");
    ASSERT_EQ_U32(0xAB0111u, cpu.bc, "INIM should decrement B, increment C, and preserve upper BC byte");
    status = ez80_memory_read8(&emu, 0xD0FFFFu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read INIM transfer destination at 0xD0FFFF");
    ASSERT_EQ_INT(0x5A, value, "INIM should write port value to cross-page source location");

    status = ez80_emulator_step(&emu, &decoded); /* OTIM */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL block-I/O B-counter step OTIM");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL block-I/O B-counter state after OTIM");
    ASSERT_EQ_U32(0x000004u, cpu.pc, "OTIM should advance to HALT opcode");
    ASSERT_EQ_U32(0xD10001u, cpu.hl, "OTIM should preserve full 24-bit HL increment");
    ASSERT_EQ_U32(0xAB0012u, cpu.bc, "OTIM should decrement B to zero and keep upper BC byte");
    ASSERT_EQ_INT(0xA7, emu.memory.ports[0x11u], "OTIM should source byte from 0xD10000, not wrapped page");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0u, "OTIM should set Z when B reaches zero");

    status = ez80_emulator_step(&emu, &decoded); /* HALT */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL block-I/O B-counter HALT");

    remove(rom_path);
}

static void test_emulator_adl_block_io_x_counter_width(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint8_t rom_bytes[] = {
        0xEDu, 0xC2u, /* INIRX */
        0x76u         /* HALT */
    };

    printf("[TEST] ADL-width BC/HL behavior for eZ80 INIRX repeat counter\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ROM for ADL-width INIRX counter test");
    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width INIRX counter init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width INIRX counter ROM load");

    emu.cpu.adl_mode = true;
    emu.cpu.pc = 0x000000u;
    emu.cpu.bc = 0x010001u;
    emu.cpu.de = 0x000020u;
    emu.cpu.hl = 0xD0FFFFu;
    emu.memory.ports[0x20u] = 0x66u;

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width INIRX counter step 1");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width INIRX counter state after step 1");
    ASSERT_EQ_U32(0x000000u, cpu.pc, "INIRX should remain on repeat opcode while BC upper bytes remain nonzero");
    ASSERT_EQ_U32(0x010000u, cpu.bc, "INIRX should decrement full 24-bit BC in ADL mode");
    ASSERT_EQ_U32(0xD10000u, cpu.hl, "INIRX should increment full 24-bit HL across page boundary");
    status = ez80_memory_read8(&emu, 0xD0FFFFu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read INIRX step1 destination at 0xD0FFFF");
    ASSERT_EQ_INT(0x66, value, "INIRX step1 should transfer port byte");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width INIRX counter step 2");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL-width INIRX counter state after step 2");
    ASSERT_EQ_U32(0x000000u, cpu.pc, "INIRX should continue repeating with BC=0x00FFFF");
    ASSERT_EQ_U32(0x00FFFFu, cpu.bc, "INIRX should preserve upper-count continuation in ADL mode");
    ASSERT_EQ_U32(0xD10001u, cpu.hl, "INIRX should keep 24-bit HL progression on repeat");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) == 0u, "INIRX should keep Z clear while BC remains nonzero");
    status = ez80_memory_read8(&emu, 0xD10000u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read INIRX step2 destination at 0xD10000");
    ASSERT_EQ_INT(0x66, value, "INIRX step2 should transfer port byte");

    remove(rom_path);
}

static void test_emulator_adl_vs_z80_stack_widths(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0x31, 0x00, 0x80, /* LD SP,0x8000 */
        0xCD, 0x08, 0x00, /* CALL 0x0008 */
        0x76,             /* HALT */
        0x00,             /* padding */
        0xC9              /* RET */
    };

    printf("[TEST] ADL vs Z80 stack width semantics for CALL/RET\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL/Z80 stack-width ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL stack-width init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL stack-width ROM load");

    status = ez80_emulator_step(&emu, &decoded); /* LD SP,0x8000 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL stack-width step LD SP");
    status = ez80_emulator_step(&emu, &decoded); /* CALL 0x0008 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL stack-width step CALL");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL stack-width get state after CALL");
    ASSERT_EQ_U32(0x000008u, cpu.pc, "ADL CALL should branch to target");
    ASSERT_EQ_U32(0xD37FFDu, cpu.sp, "ADL CALL should push a 24-bit return address");
    status = ez80_memory_read8(&emu, 0xD37FFDu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL CALL read return-byte0");
    ASSERT_EQ_INT(0x06, value, "ADL CALL return-byte0 should be low byte");
    status = ez80_memory_read8(&emu, 0xD37FFEu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL CALL read return-byte1");
    ASSERT_EQ_INT(0x00, value, "ADL CALL return-byte1 should be middle byte");
    status = ez80_memory_read8(&emu, 0xD37FFFu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL CALL read return-byte2");
    ASSERT_EQ_INT(0x00, value, "ADL CALL return-byte2 should be high byte");

    status = ez80_emulator_step(&emu, &decoded); /* RET */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL stack-width step RET");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL stack-width get state after RET");
    ASSERT_EQ_U32(0x000006u, cpu.pc, "ADL RET should restore full return address");
    ASSERT_EQ_U32(0xD38000u, cpu.sp, "ADL RET should restore SP after 24-bit pop");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 stack-width init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 stack-width ROM load");
    emu.cpu.adl_mode = false;

    status = ez80_emulator_step(&emu, &decoded); /* LD SP,0x8000 */
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 stack-width step LD SP");
    status = ez80_emulator_step(&emu, &decoded); /* CALL 0x0008 */
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 stack-width step CALL");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 stack-width get state after CALL");
    ASSERT_EQ_U32(0x000008u, cpu.pc, "Z80 CALL should branch to target");
    ASSERT_EQ_U32(0xD37FFEu, cpu.sp, "Z80 CALL should push a 16-bit return address");
    status = ez80_memory_read8(&emu, 0xD37FFEu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 CALL read return-byte0");
    ASSERT_EQ_INT(0x06, value, "Z80 CALL return-byte0 should be low byte");
    status = ez80_memory_read8(&emu, 0xD37FFFu, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 CALL read return-byte1");
    ASSERT_EQ_INT(0x00, value, "Z80 CALL return-byte1 should be high byte");

    status = ez80_emulator_step(&emu, &decoded); /* RET */
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 stack-width step RET");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "Z80 stack-width get state after RET");
    ASSERT_EQ_U32(0x000006u, cpu.pc, "Z80 RET should restore 16-bit return address");
    ASSERT_EQ_U32(0xD38000u, cpu.sp, "Z80 RET should restore SP after 16-bit pop");

    remove(rom_path);
}

static void test_emulator_memory_mapped_lcd_and_keypad(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint16_t pixel = 0u;
    uint8_t value = 0u;

    printf("[TEST] memory-mapped LCD (0xD40000) and keypad (0xF50000) regions\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "memory-mapped LCD/keypad init");

    status = ez80_memory_write8(&emu, EZ80_LCD_RAM_BASE + 0u, 0x34u);
    ASSERT_EQ_INT(EZ80_OK, status, "write LCD low byte via mapped memory");
    status = ez80_memory_write8(&emu, EZ80_LCD_RAM_BASE + 1u, 0x12u);
    ASSERT_EQ_INT(EZ80_OK, status, "write LCD high byte via mapped memory");
    status = ez80_emulator_lcd_get_pixel(&emu, 0u, 0u, &pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "read LCD pixel after mapped-memory write");
    ASSERT_EQ_INT(0x1234, pixel, "mapped LCD bytes should update pixel color");

    status = ez80_memory_read8(&emu, EZ80_LCD_RAM_BASE + 0u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read LCD low byte via mapped memory");
    ASSERT_EQ_INT(0x34, value, "mapped LCD low byte should match written value");
    status = ez80_memory_read8(&emu, EZ80_LCD_RAM_BASE + 1u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read LCD high byte via mapped memory");
    ASSERT_EQ_INT(0x12, value, "mapped LCD high byte should match written value");

    status = ez80_memory_write8(&emu, EZ80_LCD_RAM_BASE + EZ80_LCD_RAM_BYTES, 0xAAu);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "write beyond mapped LCD range should fail");

    status = ez80_memory_read8(&emu, EZ80_KEYPAD_MMIO_BASE + EZ80_KEYPAD_REG_SCAN_MODE_0, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read keypad scan mode register");
    ASSERT_EQ_INT(0xC0, value, "keypad scan mode default low byte");
    status = ez80_memory_read8(&emu, EZ80_KEYPAD_MMIO_BASE + EZ80_KEYPAD_REG_SCAN_CFG_0, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read keypad scan config register");
    ASSERT_EQ_INT(0x08, value, "keypad scan config default rows");

    status = ez80_emulator_inject_key(&emu, 0x09u); /* row=1 col=1 */
    ASSERT_EQ_INT(EZ80_OK, status, "inject key for mapped keypad test");
    status = ez80_memory_read8(&emu, EZ80_KEYPAD_MMIO_BASE + EZ80_KEYPAD_REG_ROW0_LO + 2u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read keypad row1 state low byte");
    ASSERT_TRUE((value & 0x02u) == 0u, "keypad row1 bit1 should clear after key injection");

    status = ez80_memory_read8(&emu, EZ80_KEYPAD_MMIO_BASE + EZ80_KEYPAD_REG_IRQ_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read keypad IRQ status");
    ASSERT_TRUE((value & 0x01u) != 0u, "keypad IRQ status should assert after key injection");

    status = ez80_memory_write8(&emu, EZ80_KEYPAD_MMIO_BASE + EZ80_KEYPAD_REG_IRQ_STATUS, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "ack keypad IRQ through mapped register");
    status = ez80_memory_read8(&emu, EZ80_KEYPAD_MMIO_BASE + EZ80_KEYPAD_REG_IRQ_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read keypad IRQ status after ack");
    ASSERT_EQ_INT(0x00, value, "keypad IRQ status should clear after ack");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_PENDING, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read IRQ pending after keypad ack");
    ASSERT_TRUE((value & EZ80_IRQ_SOURCE_KEYPAD) == 0u, "keypad IRQ pending bit should clear after mapped ack");
}

static void test_emulator_system_mmio_shadow_window(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value = 0u;
    const uint32_t flash_wait_addr = EZ80_SYSTEM_MMIO_BASE + 0x0305u;
    const uint32_t boot_blob_addr = EZ80_SYSTEM_MMIO_BASE + 0x0830u;
    const uint32_t upper_addr = EZ80_SYSTEM_MMIO_BASE + EZ80_SYSTEM_MMIO_BYTES - 1u;
    const uint32_t telemetry_addr = EZ80_MMIO_BASE + 0x01FFu;

    printf("[TEST] system MMIO shadow window (0xE00000-0xE00FFF)\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO init");

    status = ez80_memory_read8(&emu, flash_wait_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO flash-wait read default");
    ASSERT_EQ_INT(0x00, value, "system MMIO window should start cleared");

    status = ez80_memory_write8(&emu, flash_wait_addr, 0x03u);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO flash-wait write");
    status = ez80_memory_read8(&emu, flash_wait_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO flash-wait readback");
    ASSERT_EQ_INT(0x03, value, "system MMIO flash-wait register should roundtrip");

    status = ez80_memory_write8(&emu, boot_blob_addr, 0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO boot-blob low write");
    status = ez80_memory_write8(&emu, boot_blob_addr + 3u, 0x5Au);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO boot-blob high write");
    status = ez80_memory_read8(&emu, boot_blob_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO boot-blob low readback");
    ASSERT_EQ_INT(0xA5, value, "system MMIO boot-blob low byte should persist");
    status = ez80_memory_read8(&emu, boot_blob_addr + 3u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO boot-blob high readback");
    ASSERT_EQ_INT(0x5A, value, "system MMIO boot-blob high byte should persist");

    status = ez80_memory_write8(&emu, upper_addr, 0xCCu);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO upper-bound write");
    status = ez80_memory_read8(&emu, upper_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO upper-bound read");
    ASSERT_EQ_INT(0xCC, value, "system MMIO upper bound should roundtrip");

    status = ez80_memory_write8(&emu, telemetry_addr, 0x7Bu);
    ASSERT_EQ_INT(EZ80_OK, status, "telemetry MMIO write remains accessible");
    status = ez80_memory_read8(&emu, telemetry_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "telemetry MMIO read remains accessible");
    ASSERT_EQ_INT(0x7B, value, "telemetry MMIO should stay independent from system MMIO");
    status = ez80_memory_read8(&emu, boot_blob_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system MMIO read after telemetry write");
    ASSERT_EQ_INT(0xA5, value, "telemetry MMIO writes must not alias system MMIO shadow");

    status = ez80_memory_read8(&emu, EZ80_SYSTEM_MMIO_BASE + EZ80_SYSTEM_MMIO_BYTES, &value);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "system MMIO read just past upper bound should fail");
    status = ez80_memory_write8(&emu, EZ80_SYSTEM_MMIO_BASE + EZ80_SYSTEM_MMIO_BYTES, 0x11u);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "system MMIO write just past upper bound should fail");
}

static void test_emulator_boot_blob_system_mmio_sequence(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0xED, 0x38, 0x28,             /* IN0 A,(0x28) */
        0xCB, 0x57,                   /* BIT 2,A */
        0xDD, 0x21, 0x00, 0x08, 0xE0, /* LD IX,0xE00800 */
        0x21, 0x04, 0xB4, 0x0E,       /* LD HL,0x0EB404 */
        0x3E, 0x1F,                   /* LD A,0x1F */
        0xDD, 0x2F, 0x30,             /* LD (IX+0x30),HL */
        0xDD, 0x77, 0x33,             /* LD (IX+0x33),A */
        0x3E, 0x33,                   /* LD A,0x33 */
        0xDD, 0x77, 0x21,             /* LD (IX+0x21),A */
        0xAF,                         /* XOR A */
        0xDD, 0x77, 0x10,             /* LD (IX+0x10),A */
        0x76                          /* HALT */
    };

    printf("[TEST] boot blob sequence can write 0xE008xx system MMIO window\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create system-MMIO boot blob ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob ROM load");
    emu.cpu.adl_mode = true;
    emu.cpu.adl_encoding = true;

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + 0x28u, 0x0Cu);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob seed port 0x28");

    memset(&run_result, 0, sizeof(run_result));
    status = ez80_emulator_run_cycles(&emu, 400u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob run");
    ASSERT_TRUE(run_result.hit_halt, "system-MMIO boot blob should reach HALT");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob get state");
    ASSERT_TRUE(cpu.halted, "system-MMIO boot blob CPU should halt cleanly");
    ASSERT_EQ_U32((uint32_t)sizeof(rom_bytes), cpu.pc, "system-MMIO boot blob PC should stop at HALT");

    status = ez80_memory_read8(&emu, EZ80_SYSTEM_MMIO_BASE + 0x0830u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob read address byte 0");
    ASSERT_EQ_INT(0x04, value, "system-MMIO boot blob should store HL low byte at +0x30");
    status = ez80_memory_read8(&emu, EZ80_SYSTEM_MMIO_BASE + 0x0831u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob read address byte 1");
    ASSERT_EQ_INT(0xB4, value, "system-MMIO boot blob should store HL middle byte at +0x31");
    status = ez80_memory_read8(&emu, EZ80_SYSTEM_MMIO_BASE + 0x0832u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob read address byte 2");
    ASSERT_EQ_INT(0x0E, value, "system-MMIO boot blob should store HL high byte at +0x32");
    status = ez80_memory_read8(&emu, EZ80_SYSTEM_MMIO_BASE + 0x0833u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob read byte +0x33");
    ASSERT_EQ_INT(0x1F, value, "system-MMIO boot blob should store A at +0x33");
    status = ez80_memory_read8(&emu, EZ80_SYSTEM_MMIO_BASE + 0x0821u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob read byte +0x21");
    ASSERT_EQ_INT(0x33, value, "system-MMIO boot blob should store second A value at +0x21");
    status = ez80_memory_read8(&emu, EZ80_SYSTEM_MMIO_BASE + 0x0810u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "system-MMIO boot blob read byte +0x10");
    ASSERT_EQ_INT(0x00, value, "system-MMIO boot blob should clear +0x10 via XOR A");

    remove(rom_path);
}

static void test_emulator_lcd_framebuffer_write_index_span(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint16_t lcd_pixel = 0u;
    uint32_t i;
    const uint16_t first_color = 0x1234u;
    const uint16_t filler_color = 0x0000u;
    const uint16_t span_color = 0xABCDu;
    const uint16_t span_x = (uint16_t)(65536u % EZ80_GRAPH_WIDTH);
    const uint16_t span_y = (uint16_t)(65536u / EZ80_GRAPH_WIDTH);

    printf("[TEST] LCD framebuffer write index spans full 320x240 range\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test init");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_LCD_COMMAND, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test clear command");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_LCD_COMMAND, 0x2Cu);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test memory-write command");

    status = write_lcd_color(&emu, first_color);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test write first pixel");
    for (i = 1u; i <= 65535u; i++) {
        status = write_lcd_color(&emu, filler_color);
        if (status != EZ80_OK) {
            break;
        }
    }
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test write filler pixels through index 65535");
    status = write_lcd_color(&emu, span_color);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test write pixel at index 65536");

    status = ez80_emulator_lcd_get_pixel(&emu, 0u, 0u, &lcd_pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test read first pixel");
    ASSERT_EQ_INT(first_color, lcd_pixel, "LCD span test should preserve pixel 0 after index 65536 write");

    status = ez80_emulator_lcd_get_pixel(&emu, span_x, span_y, &lcd_pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test read pixel at index 65536");
    ASSERT_EQ_INT(span_color, lcd_pixel, "LCD span test should write color at index 65536");

    status = ez80_emulator_lcd_get_pixel(&emu, EZ80_GRAPH_WIDTH - 1u, EZ80_GRAPH_HEIGHT - 1u, &lcd_pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "LCD span test read last LCD pixel");
    ASSERT_EQ_INT(0x0000, lcd_pixel, "LCD span test should not touch final LCD pixel");
}

static void test_emulator_mmio_hardware_stub_ports(void)
{
    ez80_emulator_t emu;
    ez80_instruction_t decoded;
    ez80_run_result_t run_result;
    ez80_status_t status;
    uint8_t value = 0u;
    uint8_t rtc_before = 0u;
    uint8_t rtc_after = 0u;

    printf("[TEST] MMIO hardware stub ports (keypad/lcd/usb/timer/rtc/irq)\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "MMIO hardware init");
    emu.rom_loaded = true;
    memset(emu.memory.flash_window, 0, sizeof(emu.memory.flash_window));
    emu.memory.flash_window[0] = 0x00u; /* NOP */
    emu.memory.flash_window[1] = 0xC3u; /* JP 0000 */
    emu.memory.flash_window[2] = 0x00u;
    emu.memory.flash_window[3] = 0x00u;

    status = ez80_emulator_inject_key(&emu, 0x09u); /* row=1 col=1 */
    ASSERT_EQ_INT(EZ80_OK, status, "inject keypad key");
    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_KEYPAD_ROW_SELECT,
                                (uint8_t)~(uint8_t)(1u << 1));
    ASSERT_EQ_INT(EZ80_OK, status, "write keypad row select");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_KEYPAD_DATA, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read keypad matrix data");
    ASSERT_TRUE((value & 0x02u) == 0u, "keypad matrix data should show pressed key bit cleared");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_CONTROL, EZ80_USB_CONTROL_ENABLE);
    ASSERT_EQ_INT(EZ80_OK, status, "write USB control enable");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_RX, 0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "inject USB RX byte");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read USB status");
    ASSERT_TRUE((value & EZ80_USB_STATUS_RX_READY) != 0u, "USB status should show RX ready");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_TIMER0_COUNTER_LO, 0xFCu);
    ASSERT_EQ_INT(EZ80_OK, status, "seed timer0 low");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_TIMER0_COUNTER_HI, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "seed timer0 high");
    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_TIMER0_CONTROL,
                                EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE);
    ASSERT_EQ_INT(EZ80_OK, status, "enable timer0 with IRQ");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_SECONDS, &rtc_before);
    ASSERT_EQ_INT(EZ80_OK, status, "read RTC seconds before run");

    status = ez80_emulator_run_cycles(&emu, 40000u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "run cycles for hardware stub timing");
    ASSERT_TRUE(run_result.cycles_executed > 0u, "run_cycles should execute timer-driving cycles");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_PENDING, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read IRQ pending after timer overflow");
    ASSERT_TRUE((value & EZ80_IRQ_SOURCE_TIMER0) != 0u, "timer0 overflow should raise IRQ pending bit");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_ACK, EZ80_IRQ_SOURCE_TIMER0);
    ASSERT_EQ_INT(EZ80_OK, status, "ack timer0 IRQ");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_PENDING, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read IRQ pending after ack");
    ASSERT_TRUE((value & EZ80_IRQ_SOURCE_TIMER0) == 0u, "timer0 IRQ pending bit should clear after ack");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_SECONDS, &rtc_after);
    ASSERT_EQ_INT(EZ80_OK, status, "read RTC seconds after run");
    ASSERT_TRUE(rtc_after != rtc_before, "RTC seconds should advance after cycle-driven run");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "single step after MMIO hardware exercise");
}

static void test_mmio_write_hardware_controls(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint16_t pixel = 0u;
    uint8_t last_out_port_lo;
    uint8_t last_out_port_hi;
    uint8_t last_out_value;

    printf("[TEST] MMIO writes drive keypad/LCD/USB/timer/RTC/IRQ hardware state\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio hardware-control init");

    status = ez80_emulator_inject_key(&emu, 0x09u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio hardware-control inject key");

    last_out_port_lo = emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_PORT];
    last_out_port_hi = emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_PORT_HI];
    last_out_value = emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_VALUE];

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_KEYPAD_ROW_MASK,
                                (uint8_t)~(uint8_t)(1u << 1));
    ASSERT_EQ_INT(EZ80_OK, status, "mmio write keypad row mask");
    ASSERT_EQ_INT((int)((uint8_t)~(uint8_t)(1u << 1)),
                  emu.hw.keypad_row_select,
                  "mmio keypad row-select updates hardware");
    ASSERT_TRUE((emu.memory.mmio[EZ80_MMIO_REG_HW_KEYPAD_DATA] & 0x02u) == 0u,
                "mmio keypad data reflects injected key");

    status = ez80_memory_write8(&emu, EZ80_LCD_RAM_BASE + 0u, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio seed lcd low byte");
    status = ez80_memory_write8(&emu, EZ80_LCD_RAM_BASE + 1u, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio seed lcd high byte");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_LCD_COMMAND,
                                0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd clear command");
    status = ez80_emulator_lcd_get_pixel(&emu, 0u, 0u, &pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd clear readback");
    ASSERT_EQ_INT(0x0000u, pixel, "mmio lcd clear resets framebuffer");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_LCD_WRITE_INDEX_LO,
                                0x34u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd write-index lo");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_LCD_WRITE_INDEX_HI,
                                0x12u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd write-index hi");
    ASSERT_EQ_U32(0x1234u, emu.hw.lcd_write_index, "mmio lcd write index updates hardware");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_LCD_COMMAND,
                                0x2Cu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd memory-write command");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_LCD_DATA,
                                0x34u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd data low");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_LCD_DATA,
                                0x12u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd data high");
    status = ez80_emulator_lcd_get_pixel(&emu, 0u, 0u, &pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio lcd pixel readback");
    ASSERT_EQ_INT(0x1234u, pixel, "mmio lcd data writes pixel");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_USB_CONTROL,
                                EZ80_USB_CONTROL_ENABLE | EZ80_USB_CONTROL_LOOPBACK);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio usb control");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_USB_CONNECTED,
                                1u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio usb connected");
    ASSERT_TRUE(emu.hw.usb_connected, "mmio usb connected flag");
    ASSERT_EQ_INT(EZ80_USB_CONTROL_ENABLE | EZ80_USB_CONTROL_LOOPBACK,
                  emu.hw.usb_control,
                  "mmio usb control updates hardware");
    ASSERT_TRUE((emu.hw.gpio[EZ80_GPIO_USB_PORT].data & EZ80_GPIO_USB_DETECT_BIT) != 0u,
                "mmio usb connected updates detect GPIO");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_TIMER0_LO,
                                0x78u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio timer0 low");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_TIMER0_HI,
                                0x56u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio timer0 high");
    ASSERT_EQ_U32(0x5678u, emu.hw.timer0_counter, "mmio timer counter updates hardware");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_RTC_SECONDS,
                                59u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio rtc seconds");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_RTC_MINUTES,
                                58u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio rtc minutes");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_RTC_HOURS,
                                23u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio rtc hours");
    ASSERT_EQ_U32((23u * 60u * 60u) + (58u * 60u) + 59u,
                  emu.hw.rtc_seconds_of_day,
                  "mmio rtc writes rebuild seconds-of-day");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_IRQ_MASK,
                                EZ80_IRQ_SOURCE_TIMER0 | EZ80_IRQ_SOURCE_DMA);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio irq mask");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_IRQ_PENDING,
                                EZ80_IRQ_SOURCE_TIMER0 | EZ80_IRQ_SOURCE_DMA);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio irq pending");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_TIMER0 | EZ80_IRQ_SOURCE_DMA,
                  emu.hw.irq_mask,
                  "mmio irq mask updates hardware");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_TIMER0 | EZ80_IRQ_SOURCE_DMA,
                  emu.hw.irq_pending,
                  "mmio irq pending updates hardware");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_TIMER0_PRESCALER,
                                EZ80_TIMER_PRESCALER_64);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio timer prescaler");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_TIMER0_RELOAD_LO,
                                0xCDu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio timer reload lo");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_TIMER0_RELOAD_HI,
                                0xABu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio timer reload hi");
    ASSERT_EQ_INT(EZ80_TIMER_PRESCALER_64,
                  emu.hw.timer0_prescaler,
                  "mmio timer prescaler updates hardware");
    ASSERT_EQ_U32(0xABCDu, emu.hw.timer0_reload, "mmio timer reload updates hardware");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_BACKLIGHT_STATE,
                                0u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio backlight off");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_BATTERY_LEVEL,
                                42u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio battery level");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_BATTERY_LEVEL,
                                200u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio invalid battery level ignored");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_POWER_STATE,
                                2u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio power state");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_TRACE_ENABLED,
                                1u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio trace enable");
    ASSERT_TRUE(!emu.hw.backlight_on, "mmio backlight updates hardware");
    ASSERT_EQ_INT(42u, emu.hw.battery_level, "mmio invalid battery write leaves previous level");
    ASSERT_EQ_INT(2u, emu.hw.power_state, "mmio power state updates hardware");
    ASSERT_TRUE(emu.hw.trace_enabled, "mmio trace enable updates hardware");

    ASSERT_EQ_INT(last_out_port_lo,
                  emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_PORT],
                  "mmio hardware writes do not mutate IO trace port lo");
    ASSERT_EQ_INT(last_out_port_hi,
                  emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_PORT_HI],
                  "mmio hardware writes do not mutate IO trace port hi");
    ASSERT_EQ_INT(last_out_value,
                  emu.memory.mmio[EZ80_MMIO_REG_LAST_OUT_VALUE],
                  "mmio hardware writes do not mutate IO trace value");
}

static void test_usb_loopback_fifo_and_mmio(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value = 0u;

    printf("[TEST] USB controller loopback FIFO + MMIO telemetry\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback init");

    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_USB_CONTROL,
                                EZ80_USB_CONTROL_ENABLE |
                                EZ80_USB_CONTROL_RX_IRQ_ENABLE |
                                EZ80_USB_CONTROL_LOOPBACK);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback enable");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_TX, 0x11u);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback write tx 0x11");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_TX, 0x22u);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback write tx 0x22");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback read status");
    ASSERT_TRUE((value & EZ80_USB_STATUS_RX_READY) != 0u,
                "usb loopback status should expose RX ready");
    ASSERT_TRUE((value & EZ80_USB_STATUS_LOOPBACK) != 0u,
                "usb loopback status should expose loopback mode");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_USB) != 0u,
                "usb loopback RX event should raise USB IRQ");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_USB_TX_COUNT_LO, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback mmio tx count lo");
    ASSERT_EQ_INT(2, value, "usb loopback total tx bytes should be 2");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_USB_RX_COUNT_LO, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback mmio rx count lo");
    ASSERT_EQ_INT(2, value, "usb loopback total rx bytes should be 2");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_USB_RX_LEVEL, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback mmio rx level");
    ASSERT_EQ_INT(2, value, "usb loopback RX level should be 2");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_USB_LAST_TX, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback mmio last tx");
    ASSERT_EQ_INT(0x22, value, "usb loopback last tx byte should match latest write");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_RX, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback read first rx byte");
    ASSERT_EQ_INT(0x11, value, "usb loopback first rx byte");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_RX, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback read second rx byte");
    ASSERT_EQ_INT(0x22, value, "usb loopback second rx byte");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_USB_RX_LEVEL, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback mmio rx level after drain");
    ASSERT_EQ_INT(0, value, "usb loopback RX level should drain to zero");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb loopback read status after drain");
    ASSERT_TRUE((value & EZ80_USB_STATUS_RX_READY) == 0u,
                "usb loopback status should clear RX ready after drain");
}

static void test_usb_reset_and_overrun(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value = 0u;
    uint32_t i;

    printf("[TEST] USB controller reset + overrun handling\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "usb reset init");

    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_USB_CONTROL,
                                EZ80_USB_CONTROL_ENABLE | EZ80_USB_CONTROL_RX_IRQ_ENABLE);
    ASSERT_EQ_INT(EZ80_OK, status, "usb reset enable");

    for (i = 0u; i < EZ80_USB_FIFO_SIZE; i++) {
        status = ez80_memory_write8(&emu,
                                    EZ80_PORT_BASE + EZ80_PORT_USB_RX,
                                    (uint8_t)(i & 0xFFu));
        ASSERT_EQ_INT(EZ80_OK, status, "usb reset fill rx fifo");
    }
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_RX, 0xEEu);
    ASSERT_EQ_INT(EZ80_OK, status, "usb reset overflow write");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb reset read status after overflow");
    ASSERT_TRUE((value & EZ80_USB_STATUS_OVERRUN) != 0u,
                "usb reset status should expose overrun");
    ASSERT_EQ_U32(EZ80_USB_FIFO_SIZE, emu.hw.usb_rx_count,
                  "usb reset RX FIFO should cap at FIFO size");

    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_USB_CONTROL,
                                EZ80_USB_CONTROL_ENABLE | EZ80_USB_CONTROL_RESET);
    ASSERT_EQ_INT(EZ80_OK, status, "usb reset controller");

    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb reset read status after reset");
    ASSERT_TRUE((value & EZ80_USB_STATUS_OVERRUN) == 0u,
                "usb reset should clear overrun");
    ASSERT_TRUE((value & EZ80_USB_STATUS_RX_READY) == 0u,
                "usb reset should clear RX ready");
    ASSERT_TRUE((value & EZ80_USB_STATUS_TX_READY) != 0u,
                "usb reset should restore TX ready");
    ASSERT_EQ_U32(0u, emu.hw.usb_rx_count, "usb reset should clear RX FIFO");
    ASSERT_EQ_U32(0u, emu.hw.usb_tx_count, "usb reset should clear TX FIFO");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_USB) == 0u,
                "usb reset should clear USB IRQ pending");
}

static void test_usb_connection_state_and_tx_drain_irq(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    uint8_t value = 0u;

    printf("[TEST] USB controller connection state + TX drain IRQ\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain init");

    status = ez80_emulator_usb_set_connected(&emu, false);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain disconnect");
    ASSERT_TRUE((emu.hw.gpio[EZ80_GPIO_USB_PORT].data & EZ80_GPIO_USB_DETECT_BIT) == 0u,
                "usb drain disconnect should clear USB detect GPIO");

    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_USB_CONTROL,
                                EZ80_USB_CONTROL_ENABLE | EZ80_USB_CONTROL_TX_IRQ_ENABLE);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain enable while disconnected");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_TX, 0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain write while disconnected");
    ASSERT_EQ_U32(0u, emu.hw.usb_total_tx_bytes,
                  "usb drain disconnected write should not queue TX bytes");

    status = ez80_emulator_usb_set_connected(&emu, true);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain reconnect");
    ASSERT_TRUE((emu.hw.gpio[EZ80_GPIO_USB_PORT].data & EZ80_GPIO_USB_DETECT_BIT) != 0u,
                "usb drain reconnect should set USB detect GPIO");

    emu.rom_loaded = true;
    memset(emu.memory.flash_window, 0, sizeof(emu.memory.flash_window));
    emu.memory.flash_window[0] = 0x00u;
    emu.memory.flash_window[1] = 0xC3u;
    emu.memory.flash_window[2] = 0x00u;
    emu.memory.flash_window[3] = 0x00u;

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_TX, 0x5Au);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain write while connected");
    ASSERT_EQ_U32(1u, emu.hw.usb_total_tx_bytes,
                  "usb drain connected write should queue TX bytes");
    ASSERT_EQ_U32(1u, emu.hw.usb_tx_count, "usb drain TX FIFO level before run");

    memset(&run_result, 0, sizeof(run_result));
    status = ez80_emulator_run_cycles(&emu, 512u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain run cycles");
    ASSERT_EQ_U32(0u, emu.hw.usb_tx_count, "usb drain should flush TX FIFO");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_USB) != 0u,
                "usb drain empty transition should raise USB IRQ");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_USB_CONNECTED, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain mmio connected");
    ASSERT_EQ_INT(1, value, "usb drain mmio connected flag");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_IRQ_ACK, EZ80_IRQ_SOURCE_USB);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain ack USB IRQ");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_STATUS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "usb drain status after ack");
    ASSERT_TRUE((value & EZ80_USB_STATUS_IRQ_PENDING) == 0u,
                "usb drain status should clear IRQ pending after ack");
}

/* ===== ADL-encoding (24-bit immediate/address) tests ===== */

static void test_emulator_adl_encoding_ld_rr_nn(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];
    /* ADL encoding: LD rr,mmnn uses 3-byte immediate (4-byte instruction) */
    uint8_t rom_bytes[] = {
        0x01, 0x56, 0x34, 0x12,   /* LD BC,0x123456 */
        0x11, 0xEF, 0xCD, 0xAB,   /* LD DE,0xABCDEF */
        0x21, 0x78, 0x56, 0x34,   /* LD HL,0x345678 */
        0x31, 0x00, 0x80, 0xD3,   /* LD SP,0xD38000 */
        0x76                      /* HALT */
    };

    printf("[TEST] ADL-encoding LD rr,mmnn (3-byte immediate)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL LD rr ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD rr init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD rr ROM load");
    emu.cpu.adl_encoding = true;

    /* LD BC,0x123456 — 4 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD BC step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD BC length should be 4");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x123456u, cpu.bc, "ADL LD BC value");
    ASSERT_EQ_U32(4u, cpu.pc, "ADL LD BC advances PC by 4");

    /* LD DE,0xABCDEF — 4 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD DE step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD DE length should be 4");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xABCDEFu, cpu.de, "ADL LD DE value");
    ASSERT_EQ_U32(8u, cpu.pc, "ADL LD DE advances PC by 4");

    /* LD HL,0x345678 — 4 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD HL step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD HL length should be 4");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x345678u, cpu.hl, "ADL LD HL value");
    ASSERT_EQ_U32(12u, cpu.pc, "ADL LD HL advances PC by 4");

    /* LD SP,0xD38000 — 4 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD SP step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD SP length should be 4");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xD38000u, cpu.sp, "ADL LD SP value");
    ASSERT_EQ_U32(16u, cpu.pc, "ADL LD SP advances PC by 4");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD rr HALT step");
    ASSERT_EQ_U32(1u, decoded.length, "ADL HALT length");

    remove(rom_path);
}

static void test_emulator_adl_encoding_jp_call_ret(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    /* ADL encoding: JP/CALL use 3-byte target */
    uint8_t rom_bytes[] = {
        0x31, 0x00, 0x80, 0xD3,   /* 0x00: LD SP,0xD38000 */
        0xC3, 0x08, 0x00, 0x00,   /* 0x04: JP 0x000008 */
        0xCD, 0x10, 0x00, 0x00,   /* 0x08: CALL 0x000010 */
        0x76,                     /* 0x0C: HALT */
        0x00, 0x00, 0x00,         /* padding */
        0xC9                      /* 0x10: RET */
    };

    printf("[TEST] ADL-encoding JP/CALL/RET (3-byte targets)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL JP/CALL ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL JP/CALL init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL JP/CALL ROM load");
    emu.cpu.adl_encoding = true;

    /* LD SP,0xD38000 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL JP/CALL step LD SP");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD SP,mmnn length");

    /* JP 0x000008 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL JP step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL JP length should be 4");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x000008u, cpu.pc, "ADL JP target");

    /* CALL 0x000010 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL CALL step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL CALL length should be 4");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x000010u, cpu.pc, "ADL CALL target");
    /* Return address 0x00000C pushed (3 bytes in ADL mode) */
    ASSERT_EQ_U32(0xD37FFDu, cpu.sp, "ADL CALL pushes 3-byte return addr");
    status = ez80_memory_read8(&emu, 0xD37FFDu, &value);
    ASSERT_EQ_INT(0x0C, value, "ADL CALL return-addr low byte");
    status = ez80_memory_read8(&emu, 0xD37FFEu, &value);
    ASSERT_EQ_INT(0x00, value, "ADL CALL return-addr mid byte");
    status = ez80_memory_read8(&emu, 0xD37FFFu, &value);
    ASSERT_EQ_INT(0x00, value, "ADL CALL return-addr high byte");

    /* RET */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL RET step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x00000Cu, cpu.pc, "ADL RET returns to correct addr");
    ASSERT_EQ_U32(0xD38000u, cpu.sp, "ADL RET restores SP");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL JP/CALL HALT");

    remove(rom_path);
}

static void test_emulator_adl_encoding_ld_nn_a_and_ld_a_nn(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    /* LD (mmnn),A and LD A,(mmnn) with 3-byte addresses */
    uint8_t rom_bytes[] = {
        0x3E, 0xAB,               /* LD A,0xAB */
        0x32, 0x30, 0x00, 0xD0,   /* LD (0xD00030),A */
        0x3E, 0x00,               /* LD A,0x00 — clear A */
        0x3A, 0x30, 0x00, 0xD0,   /* LD A,(0xD00030) — reload from RAM */
        0x76                      /* HALT */
    };

    printf("[TEST] ADL-encoding LD (mmnn),A / LD A,(mmnn)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL LD (nn),A ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),A init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),A ROM load");
    emu.cpu.adl_encoding = true;

    /* LD A,0xAB */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD A,imm step");
    ASSERT_EQ_U32(2u, decoded.length, "ADL LD A,imm length");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xAB, cpu_reg_a(&cpu), "ADL A should be 0xAB");

    /* LD (0xD00030),A — 4 bytes in ADL encoding */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),A step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD (nn),A length should be 4");

    /* Verify byte was written to physical RAM */
    status = ez80_memory_read8(&emu, 0xD00030u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),A read back");
    ASSERT_EQ_INT(0xAB, value, "ADL LD (nn),A should store A at mapped address");

    /* LD A,0x00 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD A,0 step");

    /* LD A,(0xD00030) — 4 bytes in ADL encoding */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD A,(nn) step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD A,(nn) length should be 4");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(0xAB, cpu_reg_a(&cpu), "ADL LD A,(nn) should reload stored value");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),A HALT");

    remove(rom_path);
}

static void test_emulator_adl_encoding_ld_nn_hl_and_ld_hl_nn(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t b0 = 0u;
    uint8_t b1 = 0u;
    uint8_t b2 = 0u;
    char rom_path[L_tmpnam];
    /* LD (mmnn),HL and LD HL,(mmnn) with 3-byte addresses, 3-byte values */
    uint8_t rom_bytes[] = {
        0x21, 0x78, 0x56, 0x34,   /* LD HL,0x345678 */
        0x22, 0x40, 0x00, 0xD0,   /* LD (0xD00040),HL — 4 bytes, stores 3 bytes */
        0x21, 0x00, 0x00, 0x00,   /* LD HL,0x000000 — clear HL */
        0x2A, 0x40, 0x00, 0xD0,   /* LD HL,(0xD00040) — reload 3 bytes */
        0x76                      /* HALT */
    };

    printf("[TEST] ADL-encoding LD (mmnn),HL / LD HL,(mmnn)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL LD (nn),HL ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),HL init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),HL ROM load");
    emu.cpu.adl_encoding = true;

    /* LD HL,0x345678 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD HL step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x345678u, cpu.hl, "ADL HL should be 0x345678");

    /* LD (0xD00040),HL — stores 3 bytes (HL is 24-bit in ADL encoding) */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),HL step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD (nn),HL length");

    /* Verify 3 bytes written to physical RAM */
    status = ez80_memory_read8(&emu, 0xD00040u, &b0);
    ASSERT_EQ_INT(0x78, b0, "ADL LD (nn),HL byte 0");
    status = ez80_memory_read8(&emu, 0xD00041u, &b1);
    ASSERT_EQ_INT(0x56, b1, "ADL LD (nn),HL byte 1");
    status = ez80_memory_read8(&emu, 0xD00042u, &b2);
    ASSERT_EQ_INT(0x34, b2, "ADL LD (nn),HL byte 2");

    /* LD HL,0x000000 — clear HL */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD HL clear step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x000000u, cpu.hl, "ADL HL should be cleared");

    /* LD HL,(0xD00040) — loads 3 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD HL,(nn) step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL LD HL,(nn) length");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x345678u, cpu.hl, "ADL LD HL,(nn) should reload full 24-bit value");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD (nn),HL HALT");

    remove(rom_path);
}

static void test_emulator_adl_encoding_inc_dec_add_hl(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0x21, 0xFF, 0xFF, 0x00,   /* LD HL,0x00FFFF */
        0x23,                     /* INC HL — should wrap to 0x010000 in 24-bit */
        0x2B,                     /* DEC HL — back to 0x00FFFF */
        0x11, 0x02, 0x00, 0x00,   /* LD DE,0x000002 */
        0x19,                     /* ADD HL,DE — 0x00FFFF + 2 = 0x010001 in 24-bit */
        0x01, 0xFF, 0xFF, 0xFF,   /* LD BC,0xFFFFFF */
        0x03,                     /* INC BC — should wrap to 0x000000 in 24-bit */
        0x76                      /* HALT */
    };

    printf("[TEST] ADL-encoding INC/DEC/ADD HL (24-bit width)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL INC/DEC ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL INC/DEC init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL INC/DEC ROM load");
    emu.cpu.adl_encoding = true;

    /* LD HL,0x00FFFF */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD HL step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x00FFFFu, cpu.hl, "ADL HL initial");

    /* INC HL — 24-bit: 0x00FFFF -> 0x010000 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL INC HL step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x010000u, cpu.hl, "ADL INC HL should wrap to 0x010000");

    /* DEC HL — 24-bit: 0x010000 -> 0x00FFFF */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DEC HL step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x00FFFFu, cpu.hl, "ADL DEC HL should go back to 0x00FFFF");

    /* LD DE,0x000002 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD DE step");

    /* ADD HL,DE — 24-bit: 0x00FFFF + 2 = 0x010001 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ADD HL,DE step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x010001u, cpu.hl, "ADL ADD HL,DE should give 0x010001");

    /* LD BC,0xFFFFFF */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD BC step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xFFFFFFu, cpu.bc, "ADL BC should be 0xFFFFFF");

    /* INC BC — 24-bit wrap: 0xFFFFFF -> 0x000000 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL INC BC step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x000000u, cpu.bc, "ADL INC BC should wrap to 0x000000");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL INC/DEC HALT");

    remove(rom_path);
}

static void test_emulator_adl_encoding_ed_sbc_adc_hl(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[] = {
        0x21, 0x00, 0x00, 0x01,   /* LD HL,0x010000 */
        0x01, 0x01, 0x00, 0x00,   /* LD BC,0x000001 */
        0xED, 0x42,               /* SBC HL,BC — HL=0x010000-0x000001=0x00FFFF (24-bit) */
        0x11, 0x01, 0x00, 0x01,   /* LD DE,0x010001 */
        0xED, 0x5A,               /* ADC HL,DE — HL=0x00FFFF+0x010001=0x020000 (24-bit, no carry) */
        0x76                      /* HALT */
    };

    printf("[TEST] ADL-encoding ED SBC/ADC HL,ss (24-bit)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL SBC/ADC ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL SBC/ADC init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL SBC/ADC ROM load");
    emu.cpu.adl_encoding = true;
    /* Clear carry flag for SBC */
    emu.cpu.af &= ~((uint32_t)FLAG_C);

    /* LD HL,0x010000 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD HL step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x010000u, cpu.hl, "ADL HL should be 0x010000");

    /* LD BC,0x000001 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD BC step");

    /* SBC HL,BC — 24-bit: 0x010000 - 0x000001 = 0x00FFFF */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL SBC HL,BC step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x00FFFFu, cpu.hl, "ADL SBC HL,BC should give 0x00FFFF");
    /* Note: flag computation for 24-bit SBC/ADC still uses 16-bit flag helpers;
     * carry flag may be inaccurate for operands crossing the 16-bit boundary.
     * That is a known limitation tracked separately from this ADL encoding pass. */

    /* LD DE,0x010001 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD DE step");

    /* Clear carry before ADC so result is deterministic */
    emu.cpu.af &= ~((uint32_t)FLAG_C);

    /* ADC HL,DE — 24-bit: 0x00FFFF + 0x010001 + 0(carry) = 0x020000 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ADC HL,DE step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x020000u, cpu.hl, "ADL ADC HL,DE should give 0x020000");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL SBC/ADC HALT");

    remove(rom_path);
}

static void test_emulator_adl_encoding_ed_ld_nn_ss(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t b0 = 0u;
    uint8_t b1 = 0u;
    uint8_t b2 = 0u;
    char rom_path[L_tmpnam];
    /* ED LD (mmnn),BC and ED LD DE,(mmnn) with 3-byte addresses */
    uint8_t rom_bytes[] = {
        0x01, 0x78, 0x56, 0x34,   /* LD BC,0x345678 */
        0xED, 0x43, 0x50, 0x00, 0xD0, /* ED LD (0xD00050),BC — 5 bytes */
        0xED, 0x5B, 0x50, 0x00, 0xD0, /* ED LD DE,(0xD00050) — 5 bytes */
        0x76                          /* HALT */
    };

    printf("[TEST] ADL-encoding ED LD (mmnn),ss / LD ss,(mmnn)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL ED LD ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ED LD init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ED LD ROM load");
    emu.cpu.adl_encoding = true;

    /* LD BC,0x345678 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ED LD BC step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x345678u, cpu.bc, "ADL BC value");

    /* ED LD (0xD00050),BC — 5 bytes in ADL encoding */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ED LD (nn),BC step");
    ASSERT_EQ_U32(5u, decoded.length, "ADL ED LD (nn),BC length should be 5");

    /* Verify 3 bytes written to physical RAM */
    status = ez80_memory_read8(&emu, 0xD00050u, &b0);
    ASSERT_EQ_INT(0x78, b0, "ADL ED LD (nn),BC byte 0");
    status = ez80_memory_read8(&emu, 0xD00051u, &b1);
    ASSERT_EQ_INT(0x56, b1, "ADL ED LD (nn),BC byte 1");
    status = ez80_memory_read8(&emu, 0xD00052u, &b2);
    ASSERT_EQ_INT(0x34, b2, "ADL ED LD (nn),BC byte 2");

    /* ED LD DE,(0xD00050) — 5 bytes in ADL encoding */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ED LD DE,(nn) step");
    ASSERT_EQ_U32(5u, decoded.length, "ADL ED LD DE,(nn) length should be 5");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x345678u, cpu.de, "ADL ED LD DE,(nn) should load full 24-bit value");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL ED LD HALT");

    remove(rom_path);
}

static void test_emulator_adl_encoding_dd_ix_ops(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t b0 = 0u;
    uint8_t b1 = 0u;
    uint8_t b2 = 0u;
    char rom_path[L_tmpnam];
    /* DD prefix: LD IX,mmnn; LD (mmnn),IX; LD IX,(mmnn); ADD IX,BC; INC IX; DEC IX */
    uint8_t rom_bytes[] = {
        0xDD, 0x21, 0xEF, 0xCD, 0xAB, /* DD LD IX,0xABCDEF — 5 bytes */
        0xDD, 0x22, 0x60, 0x00, 0xD0,  /* DD LD (0xD00060),IX — 5 bytes */
        0xDD, 0x21, 0x00, 0x00, 0x00,  /* DD LD IX,0x000000 — clear */
        0xDD, 0x2A, 0x60, 0x00, 0xD0,  /* DD LD IX,(0xD00060) — reload */
        0x01, 0x11, 0x00, 0x00,        /* LD BC,0x000011 */
        0xDD, 0x09,                    /* DD ADD IX,BC — 24-bit add */
        0xDD, 0x23,                    /* DD INC IX — 24-bit increment */
        0xDD, 0x2B,                    /* DD DEC IX — 24-bit decrement */
        0x76                           /* HALT */
    };

    printf("[TEST] ADL-encoding DD IX ops (LD/store/add/inc/dec 24-bit)\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL DD IX ROM file");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD IX init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD IX ROM load");
    emu.cpu.adl_encoding = true;

    /* DD LD IX,0xABCDEF — 5 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD LD IX step");
    ASSERT_EQ_U32(5u, decoded.length, "ADL DD LD IX length should be 5");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xABCDEFu, cpu.ix, "ADL IX should be 0xABCDEF");

    /* DD LD (0xD00060),IX — 5 bytes, stores 3 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD LD (nn),IX step");
    ASSERT_EQ_U32(5u, decoded.length, "ADL DD LD (nn),IX length should be 5");

    /* Verify 3 bytes in physical RAM */
    status = ez80_memory_read8(&emu, 0xD00060u, &b0);
    ASSERT_EQ_INT(0xEF, b0, "ADL DD LD (nn),IX byte 0");
    status = ez80_memory_read8(&emu, 0xD00061u, &b1);
    ASSERT_EQ_INT(0xCD, b1, "ADL DD LD (nn),IX byte 1");
    status = ez80_memory_read8(&emu, 0xD00062u, &b2);
    ASSERT_EQ_INT(0xAB, b2, "ADL DD LD (nn),IX byte 2");

    /* DD LD IX,0x000000 — clear IX */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD LD IX clear step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x000000u, cpu.ix, "ADL IX should be cleared");

    /* DD LD IX,(0xD00060) — reload 3 bytes */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD LD IX,(nn) step");
    ASSERT_EQ_U32(5u, decoded.length, "ADL DD LD IX,(nn) length should be 5");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xABCDEFu, cpu.ix, "ADL DD LD IX,(nn) should reload 0xABCDEF");

    /* LD BC,0x000011 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL LD BC step");

    /* DD ADD IX,BC — 24-bit: 0xABCDEF + 0x000011 = 0xABCE00 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD ADD IX,BC step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xABCE00u, cpu.ix, "ADL ADD IX,BC should give 0xABCE00");

    /* DD INC IX — 24-bit: 0xABCE00 -> 0xABCE01 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD INC IX step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xABCE01u, cpu.ix, "ADL INC IX should give 0xABCE01");

    /* DD DEC IX — 24-bit: 0xABCE01 -> 0xABCE00 */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD DEC IX step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xABCE00u, cpu.ix, "ADL DEC IX should give 0xABCE00");

    /* HALT */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL DD IX HALT");

    remove(rom_path);
}

static void test_emulator_adl_absolute_immediate_uses_physical_addresses(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;
    ez80_cpu_state_t cpu;
    uint8_t value = 0u;
    uint8_t rom_bytes[0x90];
    char rom_path[L_tmpnam];

    memset(rom_bytes, 0x00, sizeof(rom_bytes));
    rom_bytes[0x00] = 0x3Au; rom_bytes[0x01] = 0x80u; rom_bytes[0x02] = 0x00u; rom_bytes[0x03] = 0x00u; /* LD A,(0x000080) */
    rom_bytes[0x04] = 0xFEu; rom_bytes[0x05] = 0x55u;                                         /* CP 0x55 */
    rom_bytes[0x06] = 0x28u; rom_bytes[0x07] = 0x01u;                                         /* JR Z,+1 */
    rom_bytes[0x08] = 0xC7u;                                                                   /* RST 0x00 */
    rom_bytes[0x09] = 0xEDu; rom_bytes[0x0A] = 0x4Bu; rom_bytes[0x0B] = 0x81u; rom_bytes[0x0C] = 0x00u; rom_bytes[0x0D] = 0x00u; /* LD BC,(0x000081) */
    rom_bytes[0x0E] = 0x2Au; rom_bytes[0x0F] = 0x84u; rom_bytes[0x10] = 0x00u; rom_bytes[0x11] = 0x00u; /* LD HL,(0x000084) */
    rom_bytes[0x12] = 0xDDu; rom_bytes[0x13] = 0x2Au; rom_bytes[0x14] = 0x87u; rom_bytes[0x15] = 0x00u; rom_bytes[0x16] = 0x00u; /* LD IX,(0x000087) */
    rom_bytes[0x17] = 0x3Eu; rom_bytes[0x18] = 0xAAu;                                         /* LD A,0xAA */
    rom_bytes[0x19] = 0x32u; rom_bytes[0x1A] = 0x30u; rom_bytes[0x1B] = 0x00u; rom_bytes[0x1C] = 0xD0u; /* LD (0xD00030),A */
    rom_bytes[0x1D] = 0x3Eu; rom_bytes[0x1E] = 0x00u;                                         /* LD A,0x00 */
    rom_bytes[0x1F] = 0x3Au; rom_bytes[0x20] = 0x30u; rom_bytes[0x21] = 0x00u; rom_bytes[0x22] = 0xD0u; /* LD A,(0xD00030) */
    rom_bytes[0x23] = 0x21u; rom_bytes[0x24] = 0x78u; rom_bytes[0x25] = 0x56u; rom_bytes[0x26] = 0x34u; /* LD HL,0x345678 */
    rom_bytes[0x27] = 0x22u; rom_bytes[0x28] = 0x40u; rom_bytes[0x29] = 0x00u; rom_bytes[0x2A] = 0xD0u; /* LD (0xD00040),HL */
    rom_bytes[0x2B] = 0x21u; rom_bytes[0x2C] = 0x00u; rom_bytes[0x2D] = 0x00u; rom_bytes[0x2E] = 0x00u; /* LD HL,0x000000 */
    rom_bytes[0x2F] = 0x2Au; rom_bytes[0x30] = 0x40u; rom_bytes[0x31] = 0x00u; rom_bytes[0x32] = 0xD0u; /* LD HL,(0xD00040) */
    rom_bytes[0x33] = 0xEDu; rom_bytes[0x34] = 0x43u; rom_bytes[0x35] = 0x50u; rom_bytes[0x36] = 0x00u; rom_bytes[0x37] = 0xD0u; /* LD (0xD00050),BC */
    rom_bytes[0x38] = 0xEDu; rom_bytes[0x39] = 0x5Bu; rom_bytes[0x3A] = 0x50u; rom_bytes[0x3B] = 0x00u; rom_bytes[0x3C] = 0xD0u; /* LD DE,(0xD00050) */
    rom_bytes[0x3D] = 0xDDu; rom_bytes[0x3E] = 0x22u; rom_bytes[0x3F] = 0x60u; rom_bytes[0x40] = 0x00u; rom_bytes[0x41] = 0xD0u; /* LD (0xD00060),IX */
    rom_bytes[0x42] = 0xDDu; rom_bytes[0x43] = 0x21u; rom_bytes[0x44] = 0x00u; rom_bytes[0x45] = 0x00u; rom_bytes[0x46] = 0x00u; /* LD IX,0x000000 */
    rom_bytes[0x47] = 0xDDu; rom_bytes[0x48] = 0x2Au; rom_bytes[0x49] = 0x60u; rom_bytes[0x4A] = 0x00u; rom_bytes[0x4B] = 0xD0u; /* LD IX,(0xD00060) */
    rom_bytes[0x4C] = 0x76u;                                                                   /* HALT */
    rom_bytes[0x80] = 0x55u;
    rom_bytes[0x81] = 0x11u; rom_bytes[0x82] = 0x22u; rom_bytes[0x83] = 0x33u;
    rom_bytes[0x84] = 0x44u; rom_bytes[0x85] = 0x55u; rom_bytes[0x86] = 0x66u;
    rom_bytes[0x87] = 0x77u; rom_bytes[0x88] = 0x88u; rom_bytes[0x89] = 0x99u;

    printf("[TEST] ADL absolute immediates use physical 24-bit addresses\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ADL physical-address regression ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address ROM load");
    emu.cpu.adl_mode = true;
    emu.cpu.adl_encoding = true;

    status = ez80_emulator_step(&emu, &decoded); /* LD A,(0x000080) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD A,(flash) step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL physical-address LD A,(flash) length");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after LD A,(flash)");
    ASSERT_EQ_INT(0x55, cpu_reg_a(&cpu), "ADL physical-address low flash byte should load into A");
    ASSERT_EQ_U32(0x000004u, cpu.pc, "ADL physical-address PC advances after flash load");

    status = ez80_emulator_step(&emu, &decoded); /* CP 0x55 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address CP step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after CP");
    ASSERT_TRUE((cpu_reg_f(&cpu) & FLAG_Z) != 0u, "ADL physical-address CP should set Z");
    ASSERT_EQ_INT(0x55, cpu_reg_a(&cpu), "ADL physical-address CP should preserve A");

    status = ez80_emulator_step(&emu, &decoded); /* JR Z,+1 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address JR step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after JR");
    ASSERT_EQ_U32(0x000009u, cpu.pc, "ADL physical-address JR should skip RST 0x00");

    status = ez80_emulator_step(&emu, &decoded); /* LD BC,(0x000081) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD BC,(flash) step");
    ASSERT_EQ_U32(5u, decoded.length, "ADL physical-address LD BC,(flash) length");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after LD BC,(flash)");
    ASSERT_EQ_U32(0x332211u, cpu.bc, "ADL physical-address BC should load full 24-bit flash value");

    status = ez80_emulator_step(&emu, &decoded); /* LD HL,(0x000084) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD HL,(flash) step");
    ASSERT_EQ_U32(4u, decoded.length, "ADL physical-address LD HL,(flash) length");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after LD HL,(flash)");
    ASSERT_EQ_U32(0x665544u, cpu.hl, "ADL physical-address HL should load full 24-bit flash value");

    status = ez80_emulator_step(&emu, &decoded); /* LD IX,(0x000087) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD IX,(flash) step");
    ASSERT_EQ_U32(5u, decoded.length, "ADL physical-address LD IX,(flash) length");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after LD IX,(flash)");
    ASSERT_EQ_U32(0x998877u, cpu.ix, "ADL physical-address IX should load full 24-bit flash value");

    status = ez80_emulator_step(&emu, &decoded); /* LD A,0xAA */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD A,imm step");
    status = ez80_emulator_step(&emu, &decoded); /* LD (0xD00030),A */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD (RAM),A step");
    status = ez80_memory_read8(&emu, 0xD00030u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address RAM byte readback");
    ASSERT_EQ_INT(0xAA, value, "ADL physical-address RAM byte should store A");

    status = ez80_emulator_step(&emu, &decoded); /* LD A,0x00 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address clear A step");
    status = ez80_emulator_step(&emu, &decoded); /* LD A,(0xD00030) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD A,(RAM) step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after LD A,(RAM)");
    ASSERT_EQ_INT(0xAA, cpu_reg_a(&cpu), "ADL physical-address RAM byte should reload into A");

    status = ez80_emulator_step(&emu, &decoded); /* LD HL,0x345678 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD HL,imm step");
    status = ez80_emulator_step(&emu, &decoded); /* LD (0xD00040),HL */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD (RAM),HL step");
    status = ez80_memory_read8(&emu, 0xD00040u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM HL byte 0");
    ASSERT_EQ_INT(0x78, value, "ADL physical-address RAM HL byte 0");
    status = ez80_memory_read8(&emu, 0xD00041u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM HL byte 1");
    ASSERT_EQ_INT(0x56, value, "ADL physical-address RAM HL byte 1");
    status = ez80_memory_read8(&emu, 0xD00042u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM HL byte 2");
    ASSERT_EQ_INT(0x34, value, "ADL physical-address RAM HL byte 2");

    status = ez80_emulator_step(&emu, &decoded); /* LD HL,0x000000 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address clear HL step");
    status = ez80_emulator_step(&emu, &decoded); /* LD HL,(0xD00040) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address LD HL,(RAM) step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after LD HL,(RAM)");
    ASSERT_EQ_U32(0x345678u, cpu.hl, "ADL physical-address HL should reload full 24-bit RAM value");

    status = ez80_emulator_step(&emu, &decoded); /* ED LD (0xD00050),BC */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address ED LD (RAM),BC step");
    status = ez80_memory_read8(&emu, 0xD00050u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM BC byte 0");
    ASSERT_EQ_INT(0x11, value, "ADL physical-address RAM BC byte 0");
    status = ez80_memory_read8(&emu, 0xD00051u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM BC byte 1");
    ASSERT_EQ_INT(0x22, value, "ADL physical-address RAM BC byte 1");
    status = ez80_memory_read8(&emu, 0xD00052u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM BC byte 2");
    ASSERT_EQ_INT(0x33, value, "ADL physical-address RAM BC byte 2");

    status = ez80_emulator_step(&emu, &decoded); /* ED LD DE,(0xD00050) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address ED LD DE,(RAM) step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after ED LD DE,(RAM)");
    ASSERT_EQ_U32(0x332211u, cpu.de, "ADL physical-address DE should reload full 24-bit RAM value");

    status = ez80_emulator_step(&emu, &decoded); /* DD LD (0xD00060),IX */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address DD LD (RAM),IX step");
    status = ez80_memory_read8(&emu, 0xD00060u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM IX byte 0");
    ASSERT_EQ_INT(0x77, value, "ADL physical-address RAM IX byte 0");
    status = ez80_memory_read8(&emu, 0xD00061u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM IX byte 1");
    ASSERT_EQ_INT(0x88, value, "ADL physical-address RAM IX byte 1");
    status = ez80_memory_read8(&emu, 0xD00062u, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address read RAM IX byte 2");
    ASSERT_EQ_INT(0x99, value, "ADL physical-address RAM IX byte 2");

    status = ez80_emulator_step(&emu, &decoded); /* DD LD IX,0x000000 */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address clear IX step");
    status = ez80_emulator_step(&emu, &decoded); /* DD LD IX,(0xD00060) */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address DD LD IX,(RAM) step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address state after DD LD IX,(RAM)");
    ASSERT_EQ_U32(0x998877u, cpu.ix, "ADL physical-address IX should reload full 24-bit RAM value");

    status = ez80_emulator_step(&emu, &decoded); /* HALT */
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address HALT step");
    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "ADL physical-address final state");
    ASSERT_TRUE(cpu.halted, "ADL physical-address program should halt");

    remove(rom_path);
}

static void test_emulator_adl_decode_instruction_lengths(void)
{
    ez80_instruction_t out;
    ez80_status_t status;

    printf("[TEST] ADL decode instruction length adjustments\n");

    /* LD BC,nn in Z80 mode: 3 bytes */
    {
        uint8_t bytes[] = { 0x01, 0x34, 0x12 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), false, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode LD BC,nn Z80 status");
        ASSERT_EQ_U32(3u, out.length, "decode LD BC,nn Z80 length");
    }

    /* LD BC,mmnn in ADL mode: 4 bytes */
    {
        uint8_t bytes[] = { 0x01, 0x56, 0x34, 0x12 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode LD BC,mmnn ADL status");
        ASSERT_EQ_U32(4u, out.length, "decode LD BC,mmnn ADL length");
    }

    /* JP nn Z80: 3 bytes */
    {
        uint8_t bytes[] = { 0xC3, 0x00, 0x10 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), false, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode JP nn Z80 status");
        ASSERT_EQ_U32(3u, out.length, "decode JP nn Z80 length");
    }

    /* JP mmnn ADL: 4 bytes */
    {
        uint8_t bytes[] = { 0xC3, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode JP mmnn ADL status");
        ASSERT_EQ_U32(4u, out.length, "decode JP mmnn ADL length");
    }

    /* CALL nn Z80: 3 bytes */
    {
        uint8_t bytes[] = { 0xCD, 0x00, 0x10 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), false, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode CALL nn Z80 status");
        ASSERT_EQ_U32(3u, out.length, "decode CALL nn Z80 length");
    }

    /* CALL mmnn ADL: 4 bytes */
    {
        uint8_t bytes[] = { 0xCD, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode CALL mmnn ADL status");
        ASSERT_EQ_U32(4u, out.length, "decode CALL mmnn ADL length");
    }

    /* LD (nn),A Z80: 3 bytes */
    {
        uint8_t bytes[] = { 0x32, 0x20, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), false, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode LD (nn),A Z80 status");
        ASSERT_EQ_U32(3u, out.length, "decode LD (nn),A Z80 length");
    }

    /* LD (mmnn),A ADL: 4 bytes */
    {
        uint8_t bytes[] = { 0x32, 0x20, 0x00, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode LD (mmnn),A ADL status");
        ASSERT_EQ_U32(4u, out.length, "decode LD (mmnn),A ADL length");
    }

    /* ED LD (nn),BC Z80: 4 bytes */
    {
        uint8_t bytes[] = { 0xED, 0x43, 0x00, 0x10 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), false, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode ED LD (nn),BC Z80 status");
        ASSERT_EQ_U32(4u, out.length, "decode ED LD (nn),BC Z80 length");
    }

    /* ED LD (mmnn),BC ADL: 5 bytes */
    {
        uint8_t bytes[] = { 0xED, 0x43, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode ED LD (mmnn),BC ADL status");
        ASSERT_EQ_U32(5u, out.length, "decode ED LD (mmnn),BC ADL length");
    }

    /* DD LD IX,nn Z80: 4 bytes */
    {
        uint8_t bytes[] = { 0xDD, 0x21, 0x00, 0x10 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), false, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode DD LD IX,nn Z80 status");
        ASSERT_EQ_U32(4u, out.length, "decode DD LD IX,nn Z80 length");
    }

    /* DD LD IX,mmnn ADL: 5 bytes */
    {
        uint8_t bytes[] = { 0xDD, 0x21, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode DD LD IX,mmnn ADL status");
        ASSERT_EQ_U32(5u, out.length, "decode DD LD IX,mmnn ADL length");
    }

    /* NOP should NOT change length in ADL mode */
    {
        uint8_t bytes[] = { 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode NOP ADL status");
        ASSERT_EQ_U32(1u, out.length, "decode NOP ADL length should still be 1");
    }

    /* LD A,imm should NOT change length in ADL mode */
    {
        uint8_t bytes[] = { 0x3E, 0xAB };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode LD A,imm ADL status");
        ASSERT_EQ_U32(2u, out.length, "decode LD A,imm ADL length should still be 2");
    }

    /* HALT should NOT change length in ADL mode */
    {
        uint8_t bytes[] = { 0x76 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode HALT ADL status");
        ASSERT_EQ_U32(1u, out.length, "decode HALT ADL length should still be 1");
    }

    /* JP cc,nn (conditional): JP NZ,mmnn ADL: 4 bytes */
    {
        uint8_t bytes[] = { 0xC2, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode JP NZ,mmnn ADL status");
        ASSERT_EQ_U32(4u, out.length, "decode JP NZ,mmnn ADL length");
    }

    /* CALL cc,nn (conditional): CALL Z,mmnn ADL: 4 bytes */
    {
        uint8_t bytes[] = { 0xCC, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode CALL Z,mmnn ADL status");
        ASSERT_EQ_U32(4u, out.length, "decode CALL Z,mmnn ADL length");
    }

    /* LD HL,(nn) Z80: 3 bytes */
    {
        uint8_t bytes[] = { 0x2A, 0x00, 0x10 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), false, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode LD HL,(nn) Z80 status");
        ASSERT_EQ_U32(3u, out.length, "decode LD HL,(nn) Z80 length");
    }

    /* LD HL,(mmnn) ADL: 4 bytes */
    {
        uint8_t bytes[] = { 0x2A, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode LD HL,(mmnn) ADL status");
        ASSERT_EQ_U32(4u, out.length, "decode LD HL,(mmnn) ADL length");
    }

    /* FD LD IY,mmnn ADL: 5 bytes */
    {
        uint8_t bytes[] = { 0xFD, 0x21, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode FD LD IY,mmnn ADL status");
        ASSERT_EQ_U32(5u, out.length, "decode FD LD IY,mmnn ADL length");
    }

    /* ED LD SP,(mmnn) ADL: 5 bytes */
    {
        uint8_t bytes[] = { 0xED, 0x7B, 0x00, 0x10, 0x00 };
        status = ez80_decode_instruction_adl(bytes, sizeof(bytes), true, &out);
        ASSERT_EQ_INT(EZ80_OK, status, "decode ED LD SP,(mmnn) ADL status");
        ASSERT_EQ_U32(5u, out.length, "decode ED LD SP,(mmnn) ADL length");
    }
}

/* ================================================================
 * PASS 23 TESTS: 8xp parser, interrupt dispatch, breakpoints, CLI
 * ================================================================ */

/* RAM pool where program execution is allowed */
#define TEST_RAM_EXEC_BASE (EZ80_RAM_BASE + 0x20000u)
#define TEST_RAM_EXEC_OFFSET 0x20000u

static void test_8xp_parse_valid(void)
{
    /*
     * Build a synthetic .8xp file in memory and parse it.
     * Format: 55-byte header + variable entry + 2-byte checksum.
     */
    uint8_t file_buf[128];
    ez80_8xp_parsed_t parsed;
    ez80_status_t status;
    uint16_t checksum;
    size_t pos;
    uint8_t program_data[] = { 0xC3, 0x00, 0x10, 0x00 }; /* JP 0x001000 */
    uint16_t data_len;

    printf("[TEST] 8xp parse valid synthetic file\n");

    memset(file_buf, 0, sizeof(file_buf));

    /* Header: signature */
    memcpy(file_buf, "**TI83F*", 8);
    file_buf[8] = 0x1A;
    file_buf[9] = 0x0A;
    file_buf[10] = 0x00;
    /* Comment at offset 11, 42 bytes (zero-filled) */
    memcpy(file_buf + 11, "TestProgram", 11);

    /* Variable entry:
     * 2 bytes: entry header (0x0D, 0x00)
     * 2 bytes: data length (program data size + 2 for size prefix)
     * 1 byte: type (0x05 = program)
     * 8 bytes: name "TESTPROG"
     * 1 byte: version (0x00)
     * 1 byte: flags (0x00)
     * 2 bytes: data length again
     * 2 bytes: size prefix (little-endian)
     * N bytes: program data
     */
    data_len = (uint16_t)(sizeof(program_data) + 2u); /* +2 for size prefix */
    pos = 55u; /* after header */

    file_buf[pos++] = 0x0D; /* entry header */
    file_buf[pos++] = 0x00;
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);       /* data length lo */
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF); /* data length hi */
    file_buf[pos++] = 0x05; /* type: program */
    memcpy(file_buf + pos, "TESTPROG", 8); pos += 8;
    file_buf[pos++] = 0x00; /* version */
    file_buf[pos++] = 0x00; /* flags */
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);       /* data length lo */
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF); /* data length hi */
    /* Size prefix (= sizeof(program_data)) */
    file_buf[pos++] = (uint8_t)(sizeof(program_data) & 0xFF);
    file_buf[pos++] = (uint8_t)((sizeof(program_data) >> 8) & 0xFF);
    /* Program data */
    memcpy(file_buf + pos, program_data, sizeof(program_data));
    pos += sizeof(program_data);

    /* Data section length at offset 53 = total var entry bytes */
    {
        uint16_t section_len = (uint16_t)(pos - 55u);
        file_buf[53] = (uint8_t)(section_len & 0xFF);
        file_buf[54] = (uint8_t)((section_len >> 8) & 0xFF);
    }

    /* Checksum at end: sum of all bytes from offset 55 to pos-1 */
    {
        uint32_t sum = 0;
        size_t j;
        for (j = 55u; j < pos; j++) {
            sum += file_buf[j];
        }
        checksum = (uint16_t)(sum & 0xFFFF);
    }
    file_buf[pos++] = (uint8_t)(checksum & 0xFF);
    file_buf[pos++] = (uint8_t)((checksum >> 8) & 0xFF);

    /* Parse it */
    status = ez80_8xp_parse(file_buf, pos, &parsed);
    ASSERT_EQ_INT(EZ80_OK, status, "8xp parse valid status");
    ASSERT_EQ_U32(1u, parsed.var_entry_count, "8xp parse valid var_entry_count");
    ASSERT_TRUE(parsed.checksum_valid, "8xp parse valid checksum");
    ASSERT_EQ_INT(0x05, parsed.entries[0].type_id, "8xp parse valid type");
    ASSERT_TRUE(memcmp(parsed.entries[0].name, "TESTPROG", 8) == 0, "8xp parse valid name");
    ASSERT_EQ_U32(sizeof(program_data), parsed.entries[0].program_data_size, "8xp parse valid data size");
    ASSERT_TRUE(parsed.entries[0].program_data != NULL, "8xp parse valid data pointer");
    ASSERT_EQ_INT(0xC3, parsed.entries[0].program_data[0], "8xp parse valid data[0]");
    ASSERT_EQ_INT(sizeof(program_data), parsed.entries[0].program_size, "8xp parse valid program_size");
}

static void test_8xp_parse_bad_signature(void)
{
    uint8_t file_buf[80];
    ez80_8xp_parsed_t parsed;
    ez80_status_t status;

    printf("[TEST] 8xp parse bad signature\n");

    memset(file_buf, 0, sizeof(file_buf));
    memcpy(file_buf, "BADHEAD!", 8); /* wrong signature */
    file_buf[8] = 0x1A;
    file_buf[9] = 0x0A;
    file_buf[10] = 0x00;

    status = ez80_8xp_parse(file_buf, sizeof(file_buf), &parsed);
    ASSERT_EQ_INT(EZ80_ERR_ROM_FORMAT, status, "8xp bad signature returns ROM_FORMAT");
}

