static void test_8xp_type_name(void)
{
    printf("[TEST] 8xp type name lookup\n");

    ASSERT_TRUE(strcmp(ez80_8xp_type_name(0x05), "Program") == 0, "type 0x05 = Program");
    ASSERT_TRUE(strcmp(ez80_8xp_type_name(0x06), "ProtectedProgram") == 0, "type 0x06 = ProtectedProgram");
    ASSERT_TRUE(strcmp(ez80_8xp_type_name(0x15), "AppVar") == 0, "type 0x15 = AppVar");
    ASSERT_TRUE(strcmp(ez80_8xp_type_name(0x00), "Real") == 0, "type 0x00 = Real");
    ASSERT_TRUE(strcmp(ez80_8xp_type_name(0xFE), "Unknown") == 0, "type 0xFE = Unknown");
}

static void test_8xp_load_into_emulator(void)
{
    /*
     * Build a synthetic .8xp, parse it, then load into the emulator.
     * Verify the program appears in the OS var table.
     */
    uint8_t file_buf[128];
    ez80_8xp_parsed_t parsed;
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_os_var_info_t info;
    uint16_t checksum;
    size_t pos;
    uint8_t program_data[] = { 0x3E, 0x42, 0x76 }; /* LD A,0x42; HALT */
    uint16_t data_len;

    printf("[TEST] 8xp load into emulator\n");

    /* Build file */
    memset(file_buf, 0, sizeof(file_buf));
    memcpy(file_buf, "**TI83F*", 8);
    file_buf[8] = 0x1A; file_buf[9] = 0x0A; file_buf[10] = 0x00;

    data_len = (uint16_t)(sizeof(program_data) + 2u);
    pos = 55u;

    file_buf[pos++] = 0x0D; file_buf[pos++] = 0x00;
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF);
    file_buf[pos++] = 0x05; /* program */
    memcpy(file_buf + pos, "CALCENG\0", 8); pos += 8;
    file_buf[pos++] = 0x00; file_buf[pos++] = 0x00;
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF);
    file_buf[pos++] = (uint8_t)(sizeof(program_data) & 0xFF);
    file_buf[pos++] = (uint8_t)((sizeof(program_data) >> 8) & 0xFF);
    memcpy(file_buf + pos, program_data, sizeof(program_data));
    pos += sizeof(program_data);

    {
        uint16_t section_len = (uint16_t)(pos - 55u);
        file_buf[53] = (uint8_t)(section_len & 0xFF);
        file_buf[54] = (uint8_t)((section_len >> 8) & 0xFF);
    }
    {
        uint32_t sum = 0;
        size_t j;
        for (j = 55u; j < pos; j++) sum += file_buf[j];
        checksum = (uint16_t)(sum & 0xFFFF);
    }
    file_buf[pos++] = (uint8_t)(checksum & 0xFF);
    file_buf[pos++] = (uint8_t)((checksum >> 8) & 0xFF);

    /* Parse */
    status = ez80_8xp_parse(file_buf, pos, &parsed);
    ASSERT_EQ_INT(EZ80_OK, status, "8xp load parse status");

    /* Init emulator and load */
    ez80_emulator_init(&emu);
    emu.rom_loaded = true; /* fake ROM for testing */

    status = ez80_8xp_load_into_emulator(&emu, &parsed, 0, true);
    ASSERT_EQ_INT(EZ80_OK, status, "8xp load into emu status");

    /* Verify the var exists */
    status = ez80_emulator_os_var_get_info(&emu, "CALCENG", EZ80_OS_VAR_PROGRAM, &info);
    ASSERT_EQ_INT(EZ80_OK, status, "8xp loaded var get_info status");
    ASSERT_TRUE(info.exists, "8xp loaded var exists");
    ASSERT_TRUE(info.archived, "8xp loaded var is archived");
    ASSERT_EQ_U32(sizeof(program_data), info.size_bytes, "8xp loaded var size");
}

static void test_8xp_checksum_mismatch(void)
{
    uint8_t file_buf[128];
    ez80_8xp_parsed_t parsed;
    ez80_status_t status;
    size_t pos;
    uint8_t program_data[] = { 0x00 };
    uint16_t data_len;

    printf("[TEST] 8xp parse checksum mismatch\n");

    memset(file_buf, 0, sizeof(file_buf));
    memcpy(file_buf, "**TI83F*", 8);
    file_buf[8] = 0x1A; file_buf[9] = 0x0A; file_buf[10] = 0x00;

    data_len = (uint16_t)(sizeof(program_data) + 2u);
    pos = 55u;
    file_buf[pos++] = 0x0D; file_buf[pos++] = 0x00;
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF);
    file_buf[pos++] = 0x05;
    memcpy(file_buf + pos, "BADCHK\0\0", 8); pos += 8;
    file_buf[pos++] = 0x00; file_buf[pos++] = 0x00;
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF);
    file_buf[pos++] = (uint8_t)(sizeof(program_data) & 0xFF);
    file_buf[pos++] = (uint8_t)((sizeof(program_data) >> 8) & 0xFF);
    memcpy(file_buf + pos, program_data, sizeof(program_data));
    pos += sizeof(program_data);

    {
        uint16_t section_len = (uint16_t)(pos - 55u);
        file_buf[53] = (uint8_t)(section_len & 0xFF);
        file_buf[54] = (uint8_t)((section_len >> 8) & 0xFF);
    }

    /* Write WRONG checksum */
    file_buf[pos++] = 0xFF;
    file_buf[pos++] = 0xFF;

    status = ez80_8xp_parse(file_buf, pos, &parsed);
    ASSERT_EQ_INT(EZ80_OK, status, "8xp bad checksum still parses OK");
    ASSERT_TRUE(!parsed.checksum_valid, "8xp bad checksum detected");
    ASSERT_EQ_U32(1u, parsed.var_entry_count, "8xp bad checksum still has entries");
}

static void test_8xp_appvar_type(void)
{
    uint8_t file_buf[128];
    ez80_8xp_parsed_t parsed;
    ez80_status_t status;
    size_t pos;
    uint8_t data[] = { 0x01, 0x02, 0x03, 0x04 };
    uint16_t data_len, checksum;

    printf("[TEST] 8xp parse AppVar type\n");

    memset(file_buf, 0, sizeof(file_buf));
    memcpy(file_buf, "**TI83F*", 8);
    file_buf[8] = 0x1A; file_buf[9] = 0x0A; file_buf[10] = 0x00;

    data_len = (uint16_t)(sizeof(data) + 2u);
    pos = 55u;
    file_buf[pos++] = 0x0D; file_buf[pos++] = 0x00;
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF);
    file_buf[pos++] = 0x15; /* AppVar */
    memcpy(file_buf + pos, "CESTATE\0", 8); pos += 8;
    file_buf[pos++] = 0x00;
    file_buf[pos++] = 0x80; /* archived flag */
    file_buf[pos++] = (uint8_t)(data_len & 0xFF);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFF);
    file_buf[pos++] = (uint8_t)(sizeof(data) & 0xFF);
    file_buf[pos++] = (uint8_t)((sizeof(data) >> 8) & 0xFF);
    memcpy(file_buf + pos, data, sizeof(data));
    pos += sizeof(data);

    {
        uint16_t section_len = (uint16_t)(pos - 55u);
        file_buf[53] = (uint8_t)(section_len & 0xFF);
        file_buf[54] = (uint8_t)((section_len >> 8) & 0xFF);
    }
    {
        uint32_t sum = 0;
        size_t j;
        for (j = 55u; j < pos; j++) sum += file_buf[j];
        checksum = (uint16_t)(sum & 0xFFFF);
    }
    file_buf[pos++] = (uint8_t)(checksum & 0xFF);
    file_buf[pos++] = (uint8_t)((checksum >> 8) & 0xFF);

    status = ez80_8xp_parse(file_buf, pos, &parsed);
    ASSERT_EQ_INT(EZ80_OK, status, "8xp AppVar parse status");
    ASSERT_EQ_INT(0x15, parsed.entries[0].type_id, "8xp AppVar type id");
    ASSERT_TRUE(memcmp(parsed.entries[0].name, "CESTATE", 7) == 0, "8xp AppVar name");
    ASSERT_EQ_INT(0x80, parsed.entries[0].flags, "8xp AppVar archived flag");
    ASSERT_EQ_U32(sizeof(data), parsed.entries[0].program_data_size, "8xp AppVar data size");
}

static void test_interrupt_dispatch_im1(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] Interrupt dispatch IM 1\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.interrupt_mode = 1u;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.adl_mode = true;

    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x76u; /* HALT */

    /* HALT at RST 38h in flash */
    emu.memory.flash_window[0x38] = 0x76u;

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_KEYPAD;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_KEYPAD);

    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "IM1 run status");
    ASSERT_TRUE(result.hit_halt, "IM1 halted in ISR");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "IM1 one interrupt serviced");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_KEYPAD, emu.hw.last_irq_source, "IM1 source is keypad");
    ASSERT_EQ_U32(0x0038u, emu.hw.last_irq_vector_addr, "IM1 vector = 0x38");
    ASSERT_TRUE(!emu.cpu.iff1, "IM1 IFF1 disabled after dispatch");
    /* HALT advances PC past itself before setting halted flag */
    ASSERT_EQ_U32(0x0039u, emu.cpu.pc & 0xFFFFFFu, "IM1 PC at ISR HALT+1");
}

static void test_interrupt_dispatch_im2(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;
    uint32_t isr_addr;
    uint32_t vector_table_addr;

    printf("[TEST] Interrupt dispatch IM 2 vectored\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.interrupt_mode = 2u;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.adl_mode = false; /* Z80 mode */

    /* Execute from flash (where fetch is always allowed) */
    emu.cpu.pc = 0x0100u;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.memory.flash_window[0x100] = 0x76u; /* HALT */

    /* I = 0x00, vector table at flash 0x0000 */
    emu.cpu.i_reg = 0x00u;
    emu.cpu.i_reg16 = 0x0000u;

    /* TIMER0 vector offset = 0x02. ISR at 0x0020 in flash */
    isr_addr = 0x0020u;
    emu.memory.flash_window[0x02] = (uint8_t)(isr_addr & 0xFF);
    emu.memory.flash_window[0x03] = (uint8_t)((isr_addr >> 8) & 0xFF);
    emu.memory.flash_window[0x20] = 0x76u; /* HALT at ISR */

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_TIMER0;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_TIMER0);

    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "IM2 run status");
    ASSERT_TRUE(result.hit_halt, "IM2 halted in ISR");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "IM2 one interrupt serviced");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_TIMER0, emu.hw.last_irq_source, "IM2 source is timer0");

    vector_table_addr = 0x0002u;
    ASSERT_EQ_U32(vector_table_addr, emu.hw.last_irq_vector_addr, "IM2 vector table addr");
    ASSERT_EQ_U32(isr_addr + 1u, emu.cpu.pc & 0xFFFFu, "IM2 PC past ISR HALT");
}

