static void test_breakpoint_basic(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] Breakpoint basic hit\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;

    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.cpu.adl_mode = true;

    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 0u] = 0x00u; /* NOP */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 1u] = 0x00u; /* NOP */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 2u] = 0x00u; /* NOP */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 3u] = 0x76u; /* HALT */

    status = ez80_emulator_add_breakpoint(&emu, TEST_RAM_EXEC_BASE + 2u);
    ASSERT_EQ_INT(EZ80_OK, status, "add breakpoint status");

    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "breakpoint run status");
    ASSERT_TRUE(result.hit_breakpoint, "breakpoint hit");
    ASSERT_TRUE(!result.hit_halt, "breakpoint not halted");
    ASSERT_EQ_U32(TEST_RAM_EXEC_BASE + 2u, emu.cpu.pc & 0xFFFFFFu, "breakpoint PC");
}

