static void test_key_release(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;

    printf("[TEST] Key release\n");

    ez80_emulator_init(&emu);

    /* Inject key: sets bit low in keypad_rows */
    status = ez80_emulator_inject_key(&emu, 0x09u); /* row 1, col 1 */
    ASSERT_EQ_INT(EZ80_OK, status, "key inject status");
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x02u) == 0u, "key pressed (bit low)");

    /* Release key: sets bit high */
    status = ez80_emulator_release_key(&emu, 0x09u);
    ASSERT_EQ_INT(EZ80_OK, status, "key release status");
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x02u) != 0u, "key released (bit high)");
}

