static void test_lcd_to_ascii_homescreen_overlay(void)
{
    ez80_emulator_t emu;
    char buf[2048];
    uint32_t len = 0u;
    ez80_status_t status;

    printf("[TEST] LCD to ASCII homescreen overlay\n");

    ez80_emulator_init(&emu);

    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd_to_ascii home clear");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'H', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd_to_ascii home putc H");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'I', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd_to_ascii home putc I");

    status = ez80_emulator_lcd_to_ascii(&emu, buf, sizeof(buf), &len);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd_to_ascii home overlay status");
    ASSERT_EQ_U32(41u * 24u, len, "lcd_to_ascii home overlay length");
    ASSERT_EQ_INT('H', buf[0], "lcd_to_ascii home overlay first char");
    ASSERT_EQ_INT('I', buf[1], "lcd_to_ascii home overlay second char");
    ASSERT_EQ_INT(' ', buf[26], "lcd_to_ascii home overlay pads row to 40 columns");
}

static void test_screen_text_state_homescreen_steps(void)
{
    ez80_emulator_t emu;
    ez80_screen_text_state_t state;
    ez80_status_t status;

    printf("[TEST] Screen text state captures homescreen/input/steps\n");

    ez80_emulator_init(&emu);

    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state home clear");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'S', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state row0 putc S");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'1', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state row0 putc 1");

    emu.os.home_row = 1u;
    emu.os.home_col = 0u;
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'S', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state row1 putc S");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'2', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state row1 putc 2");

    emu.os.home_row = 2u;
    emu.os.home_col = 0u;
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'x', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state row2 putc x");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'^', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state row2 putc ^");
    status = ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'2', 0u, 0u, 0u, NULL);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state row2 putc 2");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "screen state get status");
    ASSERT_TRUE(state.homescreen_active, "screen state homescreen_active");
    ASSERT_EQ_INT(2, state.cursor_row, "screen state cursor row");
    ASSERT_EQ_INT(3, state.cursor_col, "screen state cursor col");
    ASSERT_TRUE(strncmp(state.input_line, "x^2", 3u) == 0,
                "screen state input line should capture current entry");
    ASSERT_EQ_INT(2, state.step_line_count, "screen state step line count");
    ASSERT_TRUE(strncmp(state.step_lines[0], "S1", 2u) == 0,
                "screen state first step line");
    ASSERT_TRUE(strncmp(state.step_lines[1], "S2", 2u) == 0,
                "screen state second step line");
    ASSERT_TRUE(strncmp(state.visible_lines[2], "x^2", 3u) == 0,
                "screen state visible line for current input");
    ASSERT_TRUE(state.ascii[0] == 'S', "screen state ascii should reflect homescreen text");
}

static void test_lcd_write_png_basic(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    char png_path[L_tmpnam];
    FILE *png_file = NULL;
    uint8_t header[24];
    size_t bytes_read;

    printf("[TEST] LCD PNG screenshot export\n");

    ez80_emulator_init(&emu);
    status = ez80_memory_write8(&emu, EZ80_LCD_RAM_BASE + 0u, 0x34u);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd png write pixel low");
    status = ez80_memory_write8(&emu, EZ80_LCD_RAM_BASE + 1u, 0x12u);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd png write pixel high");

    ASSERT_TRUE(create_temp_path(png_path, sizeof(png_path)),
                "lcd png create temp path");
    status = ez80_emulator_lcd_write_png(&emu, png_path);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd png write status");

    png_file = fopen(png_path, "rb");
    ASSERT_TRUE(png_file != NULL, "lcd png open output");
    if (!png_file) {
        remove(png_path);
        return;
    }

    memset(header, 0, sizeof(header));
    bytes_read = fread(header, 1u, sizeof(header), png_file);
    fclose(png_file);
    remove(png_path);

    ASSERT_TRUE(bytes_read == sizeof(header), "lcd png read header bytes");
    ASSERT_EQ_INT(0x89, header[0], "lcd png signature byte 0");
    ASSERT_EQ_INT('P', header[1], "lcd png signature byte 1");
    ASSERT_EQ_INT('N', header[2], "lcd png signature byte 2");
    ASSERT_EQ_INT('G', header[3], "lcd png signature byte 3");
    ASSERT_EQ_INT('I', header[12], "lcd png IHDR type byte 0");
    ASSERT_EQ_INT('H', header[13], "lcd png IHDR type byte 1");
    ASSERT_EQ_INT('D', header[14], "lcd png IHDR type byte 2");
    ASSERT_EQ_INT('R', header[15], "lcd png IHDR type byte 3");
    ASSERT_EQ_INT(0x00, header[16], "lcd png width byte 0");
    ASSERT_EQ_INT(0x00, header[17], "lcd png width byte 1");
    ASSERT_EQ_INT(0x01, header[18], "lcd png width byte 2");
    ASSERT_EQ_INT(0x40, header[19], "lcd png width byte 3");
    ASSERT_EQ_INT(0x00, header[20], "lcd png height byte 0");
    ASSERT_EQ_INT(0x00, header[21], "lcd png height byte 1");
    ASSERT_EQ_INT(0x00, header[22], "lcd png height byte 2");
    ASSERT_EQ_INT(0xF0, header[23], "lcd png height byte 3");
}

static void test_interrupt_priority_order(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] Interrupt priority order (keypad > timer0)\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.interrupt_mode = 1u;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.adl_mode = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x76u;

    emu.memory.flash_window[0x38] = 0x76u;

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_KEYPAD | EZ80_IRQ_SOURCE_TIMER0;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_KEYPAD);
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_TIMER0);

    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "priority run status");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_KEYPAD, emu.hw.last_irq_source, "keypad serviced first");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_TIMER0) != 0u, "timer0 still pending");
}

static void test_interrupt_priority_full_chain(void)
{
    static const uint8_t expected_order[] = {
        EZ80_IRQ_SOURCE_KEYPAD,
        EZ80_IRQ_SOURCE_TIMER0,
        EZ80_IRQ_SOURCE_TIMER1,
        EZ80_IRQ_SOURCE_USB,
        EZ80_IRQ_SOURCE_DMA,
        EZ80_IRQ_SOURCE_SPI,
        EZ80_IRQ_SOURCE_I2C,
        EZ80_IRQ_SOURCE_UART
    };
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;
    size_t i;

    printf("[TEST] Interrupt priority order across all IRQ sources\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.interrupt_mode = 1u;
    emu.cpu.adl_mode = true;
    emu.memory.flash_window[0x38] = 0x76u;

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_IRQ_MASK,
                                0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "full-chain write IRQ mask");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_HW_IRQ_PENDING,
                                0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "full-chain write IRQ pending");

    for (i = 0u; i < sizeof(expected_order) / sizeof(expected_order[0]); i++) {
        memset(&result, 0, sizeof(result));
        emu.cpu.pc = TEST_RAM_EXEC_BASE;
        emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
        emu.cpu.iff1 = true;
        emu.cpu.iff2 = true;
        emu.cpu.halted = true;

        status = ez80_emulator_run_cycles(&emu, 100u, &result);
        ASSERT_EQ_INT(EZ80_OK, status, "full-chain run status");
        ASSERT_TRUE(result.hit_halt, "full-chain should halt in IM1 vector");
        ASSERT_EQ_INT(expected_order[i], emu.hw.last_irq_source, "full-chain source order");
        ASSERT_EQ_U32((uint32_t)(i + 1u),
                      emu.hw.total_interrupts_serviced,
                      "full-chain interrupt count");
        ASSERT_TRUE((emu.hw.irq_pending & expected_order[i]) == 0u,
                    "full-chain serviced source clears pending bit");
    }

    ASSERT_EQ_INT(0u,
                  emu.memory.mmio[EZ80_MMIO_REG_HW_IRQ_PENDING],
                  "full-chain MMIO pending clears after all services");
}

static void test_interrupt_extended_sources_im1(void)
{
    typedef struct {
        uint8_t source;
        const char *name;
    } irq_case_t;
    static const irq_case_t cases[] = {
        { EZ80_IRQ_SOURCE_DMA, "DMA" },
        { EZ80_IRQ_SOURCE_SPI, "SPI" },
        { EZ80_IRQ_SOURCE_I2C, "I2C" },
        { EZ80_IRQ_SOURCE_UART, "UART" }
    };
    size_t i;

    printf("[TEST] Interrupt dispatch IM 1 for DMA/SPI/I2C/UART\n");

    for (i = 0u; i < sizeof(cases) / sizeof(cases[0]); i++) {
        ez80_emulator_t emu;
        ez80_run_result_t result;
        ez80_status_t status;
        char message[96];

        ez80_emulator_init(&emu);
        emu.rom_loaded = true;
        ez80_emulator_enable_interrupts(&emu, true);

        emu.cpu.interrupt_mode = 1u;
        emu.cpu.iff1 = true;
        emu.cpu.iff2 = true;
        emu.cpu.adl_mode = true;
        emu.cpu.pc = TEST_RAM_EXEC_BASE;
        emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
        emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x76u;
        emu.memory.flash_window[0x38] = 0x76u;

        emu.hw.irq_mask = cases[i].source;
        ez80_emulator_raise_interrupt(&emu, cases[i].source);

        status = ez80_emulator_run_cycles(&emu, 100u, &result);
        snprintf(message, sizeof(message), "%s IM1 run status", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);
        snprintf(message, sizeof(message), "%s IM1 halted in ISR", cases[i].name);
        ASSERT_TRUE(result.hit_halt, message);
        snprintf(message, sizeof(message), "%s IM1 source", cases[i].name);
        ASSERT_EQ_INT(cases[i].source, emu.hw.last_irq_source, message);
        snprintf(message, sizeof(message), "%s IM1 serviced", cases[i].name);
        ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, message);
        snprintf(message, sizeof(message), "%s IM1 vector", cases[i].name);
        ASSERT_EQ_U32(0x0038u, emu.hw.last_irq_vector_addr, message);
        snprintf(message, sizeof(message), "%s IM1 clears pending", cases[i].name);
        ASSERT_TRUE((emu.hw.irq_pending & cases[i].source) == 0u, message);
    }
}

static void test_interrupt_dispatch_uart_im2(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;
    uint32_t isr_addr;

    printf("[TEST] Interrupt dispatch IM 2 for UART vector\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.interrupt_mode = 2u;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.adl_mode = false;
    emu.cpu.pc = 0x0100u;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.cpu.i_reg = 0x00u;
    emu.cpu.i_reg16 = 0x0000u;
    emu.memory.flash_window[0x100] = 0x76u;

    isr_addr = 0x0060u;
    emu.memory.flash_window[EZ80_IRQ_VECTOR_OFFSET_UART] = (uint8_t)(isr_addr & 0xFFu);
    emu.memory.flash_window[EZ80_IRQ_VECTOR_OFFSET_UART + 1u] = (uint8_t)((isr_addr >> 8) & 0xFFu);
    emu.memory.flash_window[isr_addr] = 0x76u;

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_UART;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_UART);

    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "UART IM2 run status");
    ASSERT_TRUE(result.hit_halt, "UART IM2 halted in ISR");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "UART IM2 one interrupt serviced");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_UART, emu.hw.last_irq_source, "UART IM2 source is uart");
    ASSERT_EQ_U32(EZ80_IRQ_VECTOR_OFFSET_UART, emu.hw.last_irq_vector_addr, "UART IM2 vector table addr");
    ASSERT_EQ_U32(isr_addr + 1u, emu.cpu.pc & 0xFFFFu, "UART IM2 PC past ISR HALT");
}

static void test_interrupt_im2_adl_mode(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;
    uint32_t isr_addr;

    printf("[TEST] IM 2 interrupt in ADL mode (24-bit vectors)\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.interrupt_mode = 2u;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.adl_mode = true;

    /* Execute HALT from executable RAM pool */
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x76u; /* HALT */

    /* I16 = 0x0000, vector table at flash 0x000000.
     * Timer0 offset = 0x02, ISR addr at flash[0x02..0x04] (3 bytes in ADL). */
    emu.cpu.i_reg16 = 0x0000u;
    emu.cpu.i_reg = 0x00u;

    /* ISR at executable RAM pool + 0x100 */
    isr_addr = TEST_RAM_EXEC_BASE + 0x0100u;
    emu.memory.flash_window[0x02] = (uint8_t)(isr_addr & 0xFF);
    emu.memory.flash_window[0x03] = (uint8_t)((isr_addr >> 8) & 0xFF);
    emu.memory.flash_window[0x04] = (uint8_t)((isr_addr >> 16) & 0xFF);

    /* HALT at ISR */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 0x0100u] = 0x76u;

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_TIMER0;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_TIMER0);

    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "IM2 ADL run status");
    ASSERT_TRUE(result.hit_halt, "IM2 ADL halted");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "IM2 ADL serviced");
    ASSERT_EQ_U32(EZ80_IRQ_VECTOR_OFFSET_TIMER0,
                  emu.hw.last_irq_vector_addr, "IM2 ADL vector addr");
    ASSERT_EQ_U32(isr_addr + 1u, emu.cpu.pc & 0xFFFFFFu, "IM2 ADL PC past ISR HALT");
}

/* ---- Pass 24: ADL 24-bit flag fidelity tests ---- */

static void test_adl_sbc_hl_24bit_flags(void)
{
    ez80_emulator_t emu;
    ez80_cpu_state_t cpu;
    ez80_instruction_t decoded;
    ez80_status_t status;
    char rom_path[260];
    static uint8_t rom_bytes[EZ80_FLASH_TOTAL_BYTES];
    uint8_t flags;

    /* SBC HL,DE in ADL mode: 0x800000 - 0x000001 = 0x7FFFFF
     * Sign flag should be CLEAR (bit 23 = 0), no carry */
    uint8_t code[] = {
        0x21, 0x00, 0x00, 0x80,   /* LD HL,0x800000 (24-bit) */
        0x11, 0x01, 0x00, 0x00,   /* LD DE,0x000001 (24-bit) */
        0x37,                      /* SCF */
        0x3F,                      /* CCF (clear carry) */
        0xED, 0x52,                /* SBC HL,DE */
        0x76                       /* HALT */
    };

    printf("[TEST] ADL SBC HL,ss 24-bit flag computation\n");

    memset(rom_bytes, 0, sizeof(rom_bytes));
    memcpy(rom_bytes, code, sizeof(code));
    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create adl sbc flags ROM");

    ez80_emulator_init(&emu);
    ez80_emulator_load_rom(&emu, rom_path);
    emu.cpu.adl_mode = true;
    emu.cpu.adl_encoding = true;

    /* Step through all instructions */
    status = ez80_emulator_step(&emu, &decoded); /* LD HL */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD HL");
    status = ez80_emulator_step(&emu, &decoded); /* LD DE */
    ASSERT_EQ_INT(EZ80_OK, status, "step LD DE");
    status = ez80_emulator_step(&emu, &decoded); /* SCF */
    ASSERT_EQ_INT(EZ80_OK, status, "step SCF");
    status = ez80_emulator_step(&emu, &decoded); /* CCF */
    ASSERT_EQ_INT(EZ80_OK, status, "step CCF");
    status = ez80_emulator_step(&emu, &decoded); /* SBC HL,DE */
    ASSERT_EQ_INT(EZ80_OK, status, "step SBC HL,DE");

    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x7FFFFFu, cpu.hl, "ADL SBC result = 0x7FFFFF");
    flags = (uint8_t)(cpu.af & 0xFFu);
    ASSERT_TRUE((flags & FLAG_S) == 0u, "ADL SBC S flag clear (bit 23 = 0)");
    ASSERT_TRUE((flags & FLAG_Z) == 0u, "ADL SBC Z flag clear (non-zero result)");
    ASSERT_TRUE((flags & FLAG_N) != 0u, "ADL SBC N flag set (subtraction)");
    ASSERT_TRUE((flags & FLAG_C) == 0u, "ADL SBC C flag clear (no borrow)");
    /* Overflow: 0x800000 - 0x000001 = 0x7FFFFF, sign changed -> PV set */
    ASSERT_TRUE((flags & FLAG_PV) != 0u, "ADL SBC PV flag set (overflow: sign changed)");

    remove(rom_path);
}

static void test_adl_adc_hl_24bit_flags(void)
{
    ez80_emulator_t emu;
    ez80_cpu_state_t cpu;
    ez80_instruction_t decoded;
    ez80_status_t status;
    char rom_path[260];
    static uint8_t rom_bytes[EZ80_FLASH_TOTAL_BYTES];
    uint8_t flags;

    /* ADC HL,DE in ADL mode: 0x7FFFFF + 0x000001 = 0x800000
     * Sign flag should be SET (bit 23 = 1), PV set (overflow) */
    uint8_t code[] = {
        0x21, 0xFF, 0xFF, 0x7F,   /* LD HL,0x7FFFFF (24-bit) */
        0x11, 0x01, 0x00, 0x00,   /* LD DE,0x000001 (24-bit) */
        0x37,                      /* SCF */
        0x3F,                      /* CCF (clear carry) */
        0xED, 0x5A,                /* ADC HL,DE */
        0x76                       /* HALT */
    };

    printf("[TEST] ADL ADC HL,ss 24-bit flag computation\n");

    memset(rom_bytes, 0, sizeof(rom_bytes));
    memcpy(rom_bytes, code, sizeof(code));
    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create adl adc flags ROM");

    ez80_emulator_init(&emu);
    ez80_emulator_load_rom(&emu, rom_path);
    emu.cpu.adl_mode = true;
    emu.cpu.adl_encoding = true;

    status = ez80_emulator_step(&emu, &decoded); /* LD HL */
    status = ez80_emulator_step(&emu, &decoded); /* LD DE */
    status = ez80_emulator_step(&emu, &decoded); /* SCF */
    status = ez80_emulator_step(&emu, &decoded); /* CCF */
    status = ez80_emulator_step(&emu, &decoded); /* ADC HL,DE */
    ASSERT_EQ_INT(EZ80_OK, status, "step ADC HL,DE");

    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x800000u, cpu.hl, "ADL ADC result = 0x800000");
    flags = (uint8_t)(cpu.af & 0xFFu);
    ASSERT_TRUE((flags & FLAG_S) != 0u, "ADL ADC S flag set (bit 23 = 1)");
    ASSERT_TRUE((flags & FLAG_Z) == 0u, "ADL ADC Z flag clear (non-zero)");
    ASSERT_TRUE((flags & FLAG_N) == 0u, "ADL ADC N flag clear (addition)");
    ASSERT_TRUE((flags & FLAG_C) == 0u, "ADL ADC C flag clear (no carry out of 24 bits)");
    ASSERT_TRUE((flags & FLAG_PV) != 0u, "ADL ADC PV flag set (overflow: sign changed)");

    remove(rom_path);
}

static void test_adl_sbc_hl_24bit_carry_overflow(void)
{
    ez80_emulator_t emu;
    ez80_cpu_state_t cpu;
    ez80_instruction_t decoded;
    ez80_status_t status;
    char rom_path[260];
    static uint8_t rom_bytes[EZ80_FLASH_TOTAL_BYTES];
    uint8_t flags;

    /* ADC HL,DE in ADL mode: 0xFFFFFF + 0x000001 = 0x000000 (carry out, zero)
     * SBC HL,DE: 0x000000 - 0x000001 = 0xFFFFFF (borrow, sign set) */
    uint8_t code[] = {
        /* Part 1: ADC with carry out */
        0x21, 0xFF, 0xFF, 0xFF,   /* LD HL,0xFFFFFF */
        0x11, 0x01, 0x00, 0x00,   /* LD DE,0x000001 */
        0x37,                      /* SCF */
        0x3F,                      /* CCF */
        0xED, 0x5A,                /* ADC HL,DE -> 0x000000, C=1 */
        /* Part 2: SBC with borrow */
        0x21, 0x00, 0x00, 0x00,   /* LD HL,0x000000 */
        0x37,                      /* SCF */
        0x3F,                      /* CCF */
        0xED, 0x52,                /* SBC HL,DE -> 0xFFFFFF, C=1 */
        0x76                       /* HALT */
    };

    printf("[TEST] ADL SBC/ADC HL 24-bit carry and overflow matrix\n");

    memset(rom_bytes, 0, sizeof(rom_bytes));
    memcpy(rom_bytes, code, sizeof(code));
    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create adl carry ROM");

    ez80_emulator_init(&emu);
    ez80_emulator_load_rom(&emu, rom_path);
    emu.cpu.adl_mode = true;
    emu.cpu.adl_encoding = true;

    /* Execute part 1 */
    ez80_emulator_step(&emu, &decoded); /* LD HL */
    ez80_emulator_step(&emu, &decoded); /* LD DE */
    ez80_emulator_step(&emu, &decoded); /* SCF */
    ez80_emulator_step(&emu, &decoded); /* CCF */
    status = ez80_emulator_step(&emu, &decoded); /* ADC HL,DE */
    ASSERT_EQ_INT(EZ80_OK, status, "carry ADC step");

    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0x000000u, cpu.hl, "ADC carry result = 0");
    flags = (uint8_t)(cpu.af & 0xFFu);
    ASSERT_TRUE((flags & FLAG_Z) != 0u, "ADC carry Z flag set");
    ASSERT_TRUE((flags & FLAG_C) != 0u, "ADC carry C flag set (overflow past 24 bits)");
    ASSERT_TRUE((flags & FLAG_S) == 0u, "ADC carry S flag clear");

    /* Execute part 2 */
    ez80_emulator_step(&emu, &decoded); /* LD HL */
    ez80_emulator_step(&emu, &decoded); /* SCF */
    ez80_emulator_step(&emu, &decoded); /* CCF */
    status = ez80_emulator_step(&emu, &decoded); /* SBC HL,DE */
    ASSERT_EQ_INT(EZ80_OK, status, "borrow SBC step");

    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_U32(0xFFFFFFu, cpu.hl, "SBC borrow result = 0xFFFFFF");
    flags = (uint8_t)(cpu.af & 0xFFu);
    ASSERT_TRUE((flags & FLAG_S) != 0u, "SBC borrow S flag set (bit 23 = 1)");
    ASSERT_TRUE((flags & FLAG_C) != 0u, "SBC borrow C flag set");
    ASSERT_TRUE((flags & FLAG_Z) == 0u, "SBC borrow Z flag clear");

    remove(rom_path);
}

/* ---- Pass 24: EI delay tests ---- */

static void test_ei_delay_one_instruction(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    /*
     * EI ; NOP ; HALT
     * With a pending interrupt, the NOP should execute before the interrupt
     * fires (EI delay = 1 instruction).
     */
    uint8_t code[] = {
        0xFB,       /* EI */
        0x00,       /* NOP */
        0x76        /* HALT */
    };

    printf("[TEST] EI delays interrupt by one instruction\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.adl_mode = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.cpu.interrupt_mode = 1u;
    emu.cpu.iff1 = false;
    emu.cpu.iff2 = false;

    /* Place code in RAM */
    memcpy(&emu.memory.ram[TEST_RAM_EXEC_OFFSET], code, sizeof(code));

    /* RST 38h handler = HALT */
    emu.memory.flash_window[0x38] = 0x76u;

    /* Raise an interrupt before executing */
    emu.hw.irq_mask = EZ80_IRQ_SOURCE_KEYPAD;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_KEYPAD);

    /* Run with enough cycles */
    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "ei delay run status");

    /* The NOP should have executed (PC advanced past it) before interrupt fired.
     * After EI+NOP, interrupt fires, PC goes to 0x38 (HALT there). */
    ASSERT_TRUE(result.hit_halt, "should halt (at ISR or after interrupt)");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "interrupt serviced after EI+NOP");
}

static void test_ei_delay_does_not_block_second_instruction(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    /*
     * EI ; NOP ; NOP ; HALT
     * Interrupt should fire after the first NOP (delay is only 1 instruction).
     * The second NOP should NOT execute before the interrupt fires.
     */
    uint8_t code[] = {
        0xFB,       /* EI */
        0x00,       /* NOP (delayed) */
        0x00,       /* NOP (should not run before IRQ) */
        0x76        /* HALT */
    };

    printf("[TEST] EI delay does not block second instruction\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.adl_mode = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.cpu.interrupt_mode = 1u;
    emu.cpu.iff1 = false;
    emu.cpu.iff2 = false;

    memcpy(&emu.memory.ram[TEST_RAM_EXEC_OFFSET], code, sizeof(code));

    /* ISR returns immediately: EI; RETI */
    emu.memory.flash_window[0x38] = 0xFBu; /* EI */
    emu.memory.flash_window[0x39] = 0xED; /* RETI */
    emu.memory.flash_window[0x3A] = 0x4Du;

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_KEYPAD;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_KEYPAD);

    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "ei delay second run status");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "interrupt serviced");
    ASSERT_TRUE(result.hit_halt, "should reach HALT after ISR return");
}

static void test_ei_di_ei_sequence(void)
{
    ez80_emulator_t emu;
    ez80_cpu_state_t cpu;
    ez80_instruction_t decoded;
    ez80_status_t status;
    char rom_path[260];
    static uint8_t rom_bytes[EZ80_FLASH_TOTAL_BYTES];

    /* EI; DI; EI; HALT - verify flip-flop toggling */
    uint8_t code[] = {
        0xFB,       /* EI */
        0xF3,       /* DI */
        0xFB,       /* EI */
        0x76        /* HALT */
    };

    printf("[TEST] EI/DI/EI sequence\n");

    memset(rom_bytes, 0, sizeof(rom_bytes));
    memcpy(rom_bytes, code, sizeof(code));
    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create ei_di ROM");

    ez80_emulator_init(&emu);
    ez80_emulator_load_rom(&emu, rom_path);

    /* EI */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step EI 1");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_TRUE(cpu.iff1 && cpu.iff2, "EI sets IFFs");
    ASSERT_TRUE(cpu.ei_pending, "EI sets ei_pending");

    /* DI */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step DI");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_TRUE(!cpu.iff1 && !cpu.iff2, "DI clears IFFs");

    /* EI */
    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "step EI 2");
    ez80_emulator_get_state(&emu, &cpu);
    ASSERT_TRUE(cpu.iff1 && cpu.iff2, "EI 2 sets IFFs");

    remove(rom_path);
}

/* ---- Pass 24: Watchpoint tests ---- */

static void test_watchpoint_write_basic(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    /* LD (HL),A should trigger a write watchpoint */
    uint8_t code[] = {
        0x3E, 0x42,                   /* LD A,0x42 */
        0x21, 0x00, 0x10, 0x00,       /* LD HL,0x001000 (maps to RAM) */
        0x77,                          /* LD (HL),A */
        0x76                           /* HALT */
    };

    printf("[TEST] Watchpoint write basic\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    emu.cpu.adl_mode = true;
    emu.cpu.adl_encoding = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    memcpy(&emu.memory.ram[TEST_RAM_EXEC_OFFSET], code, sizeof(code));

    /* Set a write watchpoint on RAM address 0xD01000 */
    status = ez80_emulator_add_watchpoint(&emu, EZ80_RAM_BASE + 0x1000u, 1u, EZ80_WATCHPOINT_WRITE);
    ASSERT_EQ_INT(EZ80_OK, status, "add write watchpoint");
    ASSERT_EQ_U32(1u, emu.watchpoint_count, "watchpoint count = 1");

    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "watchpoint run status");
    ASSERT_TRUE(result.hit_watchpoint, "write watchpoint triggered");
    ASSERT_EQ_U32(EZ80_RAM_BASE + 0x1000u, result.watchpoint_addr, "watchpoint addr correct");
    ASSERT_EQ_INT(EZ80_WATCHPOINT_WRITE, result.watchpoint_type, "watchpoint type = write");
}

