static void test_timer_reload_on_overflow(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] Timer reload on overflow\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    emu.cpu.adl_mode = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    ez80_emulator_enable_interrupts(&emu, true);
    emu.cpu.iff1 = false; /* Keep interrupts CPU-disabled so IRQ just pends */

    /* Counter close to overflow, reload enabled */
    emu.hw.timer0_control = EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD | EZ80_TIMER_CONTROL_IRQ_ENABLE;
    emu.hw.timer0_counter = 0xFFF0u;
    ez80_emulator_set_timer_reload(&emu, 0u, 0x8000u);
    emu.hw.irq_mask = EZ80_IRQ_SOURCE_TIMER0;

    /* 32 NOPs to generate enough cycles to overflow */
    {
        uint32_t i;
        for (i = 0u; i < 32u; i++) {
            emu.memory.ram[TEST_RAM_EXEC_OFFSET + i] = 0x00u;
        }
        emu.memory.ram[TEST_RAM_EXEC_OFFSET + 32u] = 0x76u;
    }

    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "reload run");
    /* Timer should have overflowed and reloaded from 0x8000 */
    ASSERT_TRUE(emu.hw.timer0_counter >= 0x8000u, "timer reloaded from 0x8000");
    /* IRQ should be pending */
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_TIMER0) != 0u, "timer0 IRQ pending after overflow");
}

static void test_timer_prescaler_api(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;

    printf("[TEST] Timer prescaler API validation\n");

    ez80_emulator_init(&emu);

    /* Valid prescaler values */
    status = ez80_emulator_set_timer_prescaler(&emu, 0u, EZ80_TIMER_PRESCALER_1);
    ASSERT_EQ_INT(EZ80_OK, status, "prescaler 1x timer0");
    ASSERT_EQ_INT(EZ80_TIMER_PRESCALER_1, emu.hw.timer0_prescaler, "timer0 prescaler = 1x");

    status = ez80_emulator_set_timer_prescaler(&emu, 1u, EZ80_TIMER_PRESCALER_64);
    ASSERT_EQ_INT(EZ80_OK, status, "prescaler 64x timer1");
    ASSERT_EQ_INT(EZ80_TIMER_PRESCALER_64, emu.hw.timer1_prescaler, "timer1 prescaler = 64x");

    /* Invalid prescaler */
    status = ez80_emulator_set_timer_prescaler(&emu, 0u, 4u);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "invalid prescaler value");

    /* Invalid timer ID */
    status = ez80_emulator_set_timer_prescaler(&emu, 2u, EZ80_TIMER_PRESCALER_4);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "invalid timer ID");

    /* MMIO should reflect prescaler */
    ASSERT_EQ_INT(EZ80_TIMER_PRESCALER_1, emu.memory.mmio[EZ80_MMIO_REG_TIMER0_PRESCALER],
                  "MMIO timer0 prescaler");
    ASSERT_EQ_INT(EZ80_TIMER_PRESCALER_64, emu.memory.mmio[EZ80_MMIO_REG_TIMER1_PRESCALER],
                  "MMIO timer1 prescaler");
}

static void test_timer_reload_api(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;

    printf("[TEST] Timer reload API validation\n");

    ez80_emulator_init(&emu);

    status = ez80_emulator_set_timer_reload(&emu, 0u, 0x1234u);
    ASSERT_EQ_INT(EZ80_OK, status, "set reload timer0");
    ASSERT_EQ_U32(0x1234u, emu.hw.timer0_reload, "timer0 reload value");
    ASSERT_EQ_INT(0x34, emu.memory.mmio[EZ80_MMIO_REG_TIMER0_RELOAD_LO], "MMIO reload LO");
    ASSERT_EQ_INT(0x12, emu.memory.mmio[EZ80_MMIO_REG_TIMER0_RELOAD_HI], "MMIO reload HI");

    status = ez80_emulator_set_timer_reload(&emu, 1u, 0xABCDu);
    ASSERT_EQ_INT(EZ80_OK, status, "set reload timer1");
    ASSERT_EQ_U32(0xABCDu, emu.hw.timer1_reload, "timer1 reload value");

    /* Invalid timer ID */
    status = ez80_emulator_set_timer_reload(&emu, 2u, 0x0000u);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "invalid timer ID reload");
}

typedef struct {
    uint16_t counter;
    int overflowed;
} timer_reference_result_t;

typedef struct {
    const char *name;
    uint8_t timer_id;
    uint8_t control;
    uint16_t start_counter;
    uint16_t reload;
    uint8_t prescaler;
    uint32_t cycles;
    int expect_irq_pending;
} timer_halt_progress_case_t;

typedef struct {
    const char *name;
    uint8_t timer_id;
    uint8_t control;
    uint16_t start_counter;
    uint16_t reload;
    uint8_t prescaler;
    uint32_t budget;
    uint8_t irq_mask;
    int cpu_iff1;
    int emulator_irq_enable;
    uint8_t interrupt_mode;
    int adl_mode;
    uint32_t isr_addr;
    int expect_service;
} timer_halt_irq_case_t;

static uint32_t timer_test_prescaler_divisor(uint8_t prescaler)
{
    switch (prescaler & 0x03u) {
    case EZ80_TIMER_PRESCALER_4:  return 4u;
    case EZ80_TIMER_PRESCALER_16: return 16u;
    case EZ80_TIMER_PRESCALER_64: return 64u;
    default:                       return 1u;
    }
}

static timer_reference_result_t timer_reference_run(uint16_t start_counter,
                                                    uint16_t reload,
                                                    uint8_t control,
                                                    uint8_t prescaler,
                                                    uint32_t cycles)
{
    timer_reference_result_t result;
    uint32_t divisor;
    uint32_t ticks;
    uint32_t i;

    result.counter = start_counter;
    result.overflowed = 0;
    if ((control & EZ80_TIMER_CONTROL_ENABLE) == 0u) {
        return result;
    }

    divisor = timer_test_prescaler_divisor(prescaler);
    ticks = cycles / divisor;

    for (i = 0u; i < ticks; i++) {
        if (result.counter == 0xFFFFu) {
            result.overflowed = 1;
            if ((control & EZ80_TIMER_CONTROL_RELOAD) != 0u) {
                result.counter = reload;
            } else {
                result.counter = 0u;
            }
        } else {
            result.counter = (uint16_t)(result.counter + 1u);
        }
    }

    return result;
}

static void test_timer_halt_progress_matrix(void)
{
    static const timer_halt_progress_case_t cases[] = {
        { "t0-basic-1x",              0u, EZ80_TIMER_CONTROL_ENABLE,                                          0x1234u, 0x0000u, EZ80_TIMER_PRESCALER_1,  3u,   0 },
        { "t0-wrap-1x",               0u, EZ80_TIMER_CONTROL_ENABLE,                                          0xFFFEu, 0x0000u, EZ80_TIMER_PRESCALER_1,  4u,   0 },
        { "t0-wrap-irq-1x",           0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,         0xFFFEu, 0x0000u, EZ80_TIMER_PRESCALER_1,  4u,   1 },
        { "t0-reload-single-1x",      0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD,             0xFFFEu, 0x8000u, EZ80_TIMER_PRESCALER_1,  4u,   0 },
        { "t0-reload-multi-1x",       0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD,             0xFFFEu, 0xFFFCu, EZ80_TIMER_PRESCALER_1, 18u,   0 },
        { "t0-reload-rem-1x",         0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD |
                                             EZ80_TIMER_CONTROL_IRQ_ENABLE,                                   0xFFFDu, 0xFFFCu, EZ80_TIMER_PRESCALER_1, 17u,   1 },
        { "t0-reload-ffff-1x",        0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD |
                                             EZ80_TIMER_CONTROL_IRQ_ENABLE,                                   0xFFFFu, 0xFFFFu, EZ80_TIMER_PRESCALER_1,  3u,   1 },
        { "t1-basic-4x",              1u, EZ80_TIMER_CONTROL_ENABLE,                                          0x0100u, 0x0000u, EZ80_TIMER_PRESCALER_4, 14u,   0 },
        { "t1-wrap-4x",               1u, EZ80_TIMER_CONTROL_ENABLE,                                          0xFFFCu, 0x0000u, EZ80_TIMER_PRESCALER_4, 20u,   0 },
        { "t1-reload-single-4x",      1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD |
                                             EZ80_TIMER_CONTROL_IRQ_ENABLE,                                   0xFFFCu, 0x9000u, EZ80_TIMER_PRESCALER_4, 20u,   1 },
        { "t1-reload-multi-4x",       1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD,             0xFFFEu, 0xFFFCu, EZ80_TIMER_PRESCALER_4, 40u,   0 },
        { "t0-wrap-16x",              0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,         0xFFF0u, 0x0000u, EZ80_TIMER_PRESCALER_16, 272u, 1 },
        { "t0-reload-16x",            0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD,             0xFFF0u, 0x8000u, EZ80_TIMER_PRESCALER_16, 272u, 0 },
        { "t0-reload-multi-16x",      0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD |
                                             EZ80_TIMER_CONTROL_IRQ_ENABLE,                                   0xFFFEu, 0xFFF0u, EZ80_TIMER_PRESCALER_16, 288u, 1 },
        { "t1-basic-64x",             1u, EZ80_TIMER_CONTROL_ENABLE,                                          0x1234u, 0x0000u, EZ80_TIMER_PRESCALER_64, 255u, 0 },
        { "t1-wrap-64x",              1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,         0xFFFDu, 0x0000u, EZ80_TIMER_PRESCALER_64, 192u, 1 },
        { "t1-reload-single-64x",     1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD,             0xFFFDu, 0x7000u, EZ80_TIMER_PRESCALER_64, 192u, 0 },
        { "t1-reload-multi-64x",      1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_RELOAD |
                                             EZ80_TIMER_CONTROL_IRQ_ENABLE,                                   0xFFFEu, 0xFFFCu, EZ80_TIMER_PRESCALER_64, 640u, 1 }
    };
    size_t i;

    printf("[TEST] Timer halt-progress matrix\n");

    for (i = 0u; i < (sizeof(cases) / sizeof(cases[0])); i++) {
        ez80_emulator_t emu;
        ez80_run_result_t result;
        ez80_status_t status;
        timer_reference_result_t expected;
        uint16_t actual_counter;
        uint16_t other_counter;
        uint16_t mmio_lo_reg;
        uint16_t mmio_hi_reg;
        uint8_t port_control;
        uint8_t irq_source;
        char message[128];

        memset(&emu, 0, sizeof(emu));
        status = ez80_emulator_init(&emu);
        snprintf(message, sizeof(message), "%s init", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        emu.rom_loaded = true;
        emu.cpu.halted = true;
        emu.cpu.iff1 = false;
        emu.cpu.iff2 = false;
        emu.cpu.pc = TEST_RAM_EXEC_BASE;
        emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

        status = ez80_emulator_set_timer_prescaler(&emu, cases[i].timer_id, cases[i].prescaler);
        snprintf(message, sizeof(message), "%s set prescaler", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        status = ez80_emulator_set_timer_reload(&emu, cases[i].timer_id, cases[i].reload);
        snprintf(message, sizeof(message), "%s set reload", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        if (cases[i].timer_id == 0u) {
            emu.hw.timer0_control = cases[i].control;
            emu.hw.timer0_counter = cases[i].start_counter;
            emu.hw.timer1_control = 0u;
            emu.hw.timer1_counter = 0x2468u;
            actual_counter = emu.hw.timer0_counter;
            other_counter = emu.hw.timer1_counter;
            mmio_lo_reg = EZ80_MMIO_REG_HW_TIMER0_LO;
            mmio_hi_reg = EZ80_MMIO_REG_HW_TIMER0_HI;
            port_control = EZ80_PORT_TIMER0_CONTROL;
            irq_source = EZ80_IRQ_SOURCE_TIMER0;
        } else {
            emu.hw.timer1_control = cases[i].control;
            emu.hw.timer1_counter = cases[i].start_counter;
            emu.hw.timer0_control = 0u;
            emu.hw.timer0_counter = 0x1357u;
            actual_counter = emu.hw.timer1_counter;
            other_counter = emu.hw.timer0_counter;
            mmio_lo_reg = EZ80_MMIO_REG_HW_TIMER1_LO;
            mmio_hi_reg = EZ80_MMIO_REG_HW_TIMER1_HI;
            port_control = EZ80_PORT_TIMER1_CONTROL;
            irq_source = EZ80_IRQ_SOURCE_TIMER1;
        }
        (void)actual_counter;
        (void)other_counter;

        expected = timer_reference_run(cases[i].start_counter,
                                       cases[i].reload,
                                       cases[i].control,
                                       cases[i].prescaler,
                                       cases[i].cycles);

        status = ez80_emulator_run_cycles(&emu, cases[i].cycles, &result);
        snprintf(message, sizeof(message), "%s run", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        snprintf(message, sizeof(message), "%s cycles executed", cases[i].name);
        ASSERT_EQ_U32(cases[i].cycles, result.cycles_executed, message);
        snprintf(message, sizeof(message), "%s remains halted", cases[i].name);
        ASSERT_TRUE(result.hit_halt, message);

        if (cases[i].timer_id == 0u) {
            actual_counter = emu.hw.timer0_counter;
            other_counter = emu.hw.timer1_counter;
        } else {
            actual_counter = emu.hw.timer1_counter;
            other_counter = emu.hw.timer0_counter;
        }

        snprintf(message, sizeof(message), "%s counter", cases[i].name);
        ASSERT_EQ_INT(expected.counter, actual_counter, message);
        snprintf(message, sizeof(message), "%s other timer unchanged", cases[i].name);
        ASSERT_EQ_INT(cases[i].timer_id == 0u ? 0x2468u : 0x1357u, other_counter, message);

        snprintf(message, sizeof(message), "%s control mirror", cases[i].name);
        ASSERT_EQ_INT(cases[i].control, emu.memory.ports[port_control], message);
        snprintf(message, sizeof(message), "%s port low mirror", cases[i].name);
        ASSERT_EQ_INT((int)(actual_counter & 0x00FFu),
                      emu.memory.ports[port_control + 1u],
                      message);
        snprintf(message, sizeof(message), "%s port high mirror", cases[i].name);
        ASSERT_EQ_INT((int)((actual_counter >> 8) & 0x00FFu),
                      emu.memory.ports[port_control + 2u],
                      message);
        snprintf(message, sizeof(message), "%s mmio low mirror", cases[i].name);
        ASSERT_EQ_INT((int)(actual_counter & 0x00FFu),
                      emu.memory.mmio[mmio_lo_reg],
                      message);
        snprintf(message, sizeof(message), "%s mmio high mirror", cases[i].name);
        ASSERT_EQ_INT((int)((actual_counter >> 8) & 0x00FFu),
                      emu.memory.mmio[mmio_hi_reg],
                      message);

        snprintf(message, sizeof(message), "%s irq pending", cases[i].name);
        ASSERT_EQ_INT(cases[i].expect_irq_pending != 0,
                      ((emu.hw.irq_pending & irq_source) != 0u) ? 1 : 0,
                      message);
        snprintf(message, sizeof(message), "%s overflow->irq contract", cases[i].name);
        ASSERT_EQ_INT(((cases[i].control & EZ80_TIMER_CONTROL_IRQ_ENABLE) != 0u &&
                       expected.overflowed != 0) ? 1 : 0,
                      cases[i].expect_irq_pending != 0 ? 1 : 0,
                      message);
    }
}

static void test_timer_halt_irq_dispatch_matrix(void)
{
    static const timer_halt_irq_case_t cases[] = {
        { "t0-im1-service",            0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,
                                        0xFFFCu, 0x0000u, EZ80_TIMER_PRESCALER_1,  21u,
                                        EZ80_IRQ_SOURCE_TIMER0, 1, 1, 1u, 1, 0x0038u, 1 },
        { "t1-im1-service-4x",         1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,
                                        0xFFFCu, 0x0000u, EZ80_TIMER_PRESCALER_4,  33u,
                                        EZ80_IRQ_SOURCE_TIMER1, 1, 1, 1u, 1, 0x0038u, 1 },
        { "t0-im2-z80-service",        0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,
                                        0xFFFCu, 0x0000u, EZ80_TIMER_PRESCALER_4,  39u,
                                        EZ80_IRQ_SOURCE_TIMER0, 1, 1, 2u, 0, 0x0020u, 1 },
        { "t1-im2-adl-service",        1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,
                                        0xFFF0u, 0x0000u, EZ80_TIMER_PRESCALER_16, 279u,
                                        EZ80_IRQ_SOURCE_TIMER1, 1, 1, 2u, 1, TEST_RAM_EXEC_BASE + 0x0200u, 1 },
        { "t0-masked-no-service",      0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,
                                        0xFFFCu, 0x0000u, EZ80_TIMER_PRESCALER_1,  12u,
                                        0u, 1, 1, 1u, 1, 0x0038u, 0 },
        { "t1-iff1-off-no-service",    1u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,
                                        0xFFFCu, 0x0000u, EZ80_TIMER_PRESCALER_1,  12u,
                                        EZ80_IRQ_SOURCE_TIMER1, 0, 1, 1u, 1, 0x0038u, 0 },
        { "t0-emu-off-no-service",     0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE,
                                        0xFFFCu, 0x0000u, EZ80_TIMER_PRESCALER_1,  12u,
                                        EZ80_IRQ_SOURCE_TIMER0, 1, 0, 1u, 1, 0x0038u, 0 },
        { "t0-reload-service",         0u, EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE |
                                             EZ80_TIMER_CONTROL_RELOAD,
                                        0xFFFEu, 0x8000u, EZ80_TIMER_PRESCALER_1,  21u,
                                        EZ80_IRQ_SOURCE_TIMER0, 1, 1, 1u, 1, 0x0038u, 1 }
    };
    size_t i;

    printf("[TEST] Timer halt IRQ-dispatch matrix\n");

    for (i = 0u; i < (sizeof(cases) / sizeof(cases[0])); i++) {
        ez80_emulator_t emu;
        ez80_run_result_t result;
        ez80_status_t status;
        timer_reference_result_t expected;
        uint8_t irq_source;
        uint32_t expected_pc;
        uint16_t actual_counter;
        char message[128];

        memset(&emu, 0, sizeof(emu));
        status = ez80_emulator_init(&emu);
        snprintf(message, sizeof(message), "%s init", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        emu.rom_loaded = true;
        emu.cpu.halted = true;
        emu.cpu.iff1 = cases[i].cpu_iff1 != 0;
        emu.cpu.iff2 = cases[i].cpu_iff1 != 0;
        emu.cpu.interrupt_mode = cases[i].interrupt_mode;
        emu.cpu.adl_mode = cases[i].adl_mode != 0;
        emu.cpu.pc = TEST_RAM_EXEC_BASE;
        emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
        emu.hw.irq_mask = cases[i].irq_mask;

        status = ez80_emulator_enable_interrupts(&emu, cases[i].emulator_irq_enable != 0);
        snprintf(message, sizeof(message), "%s enable interrupts", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        status = ez80_emulator_set_timer_prescaler(&emu, cases[i].timer_id, cases[i].prescaler);
        snprintf(message, sizeof(message), "%s set prescaler", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);
        status = ez80_emulator_set_timer_reload(&emu, cases[i].timer_id, cases[i].reload);
        snprintf(message, sizeof(message), "%s set reload", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        if (cases[i].timer_id == 0u) {
            emu.hw.timer0_control = cases[i].control;
            emu.hw.timer0_counter = cases[i].start_counter;
            irq_source = EZ80_IRQ_SOURCE_TIMER0;
        } else {
            emu.hw.timer1_control = cases[i].control;
            emu.hw.timer1_counter = cases[i].start_counter;
            irq_source = EZ80_IRQ_SOURCE_TIMER1;
        }

        emu.memory.flash_window[0x38] = 0x76u;
        if (cases[i].interrupt_mode == 2u) {
            uint16_t vec_offset = (cases[i].timer_id == 0u)
                ? EZ80_IRQ_VECTOR_OFFSET_TIMER0
                : EZ80_IRQ_VECTOR_OFFSET_TIMER1;
            if (cases[i].adl_mode != 0) {
                emu.cpu.i_reg16 = 0x0000u;
                emu.memory.flash_window[vec_offset + 0u] = (uint8_t)(cases[i].isr_addr & 0xFFu);
                emu.memory.flash_window[vec_offset + 1u] = (uint8_t)((cases[i].isr_addr >> 8) & 0xFFu);
                emu.memory.flash_window[vec_offset + 2u] = (uint8_t)((cases[i].isr_addr >> 16) & 0xFFu);
                emu.memory.ram[(cases[i].isr_addr - EZ80_RAM_BASE)] = 0x76u;
            } else {
                emu.cpu.i_reg = 0x00u;
                emu.memory.flash_window[vec_offset + 0u] = (uint8_t)(cases[i].isr_addr & 0xFFu);
                emu.memory.flash_window[vec_offset + 1u] = (uint8_t)((cases[i].isr_addr >> 8) & 0xFFu);
                emu.memory.flash_window[cases[i].isr_addr & 0xFFFFu] = 0x76u;
            }
        }

        expected = timer_reference_run(cases[i].start_counter,
                                       cases[i].reload,
                                       cases[i].control,
                                       cases[i].prescaler,
                                       cases[i].budget);

        status = ez80_emulator_run_cycles(&emu, cases[i].budget, &result);
        snprintf(message, sizeof(message), "%s run", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);
        snprintf(message, sizeof(message), "%s cycles executed", cases[i].name);
        ASSERT_EQ_U32(cases[i].budget, result.cycles_executed, message);
        snprintf(message, sizeof(message), "%s halts", cases[i].name);
        ASSERT_TRUE(result.hit_halt, message);

        actual_counter = (cases[i].timer_id == 0u) ? emu.hw.timer0_counter : emu.hw.timer1_counter;
        snprintf(message, sizeof(message), "%s counter after run", cases[i].name);
        ASSERT_EQ_INT(expected.counter, actual_counter, message);

        if (cases[i].expect_service) {
            expected_pc = cases[i].isr_addr + 1u;
            snprintf(message, sizeof(message), "%s serviced count", cases[i].name);
            ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, message);
            snprintf(message, sizeof(message), "%s last irq source", cases[i].name);
            ASSERT_EQ_INT(irq_source, emu.hw.last_irq_source, message);
            snprintf(message, sizeof(message), "%s irq cleared", cases[i].name);
            ASSERT_TRUE((emu.hw.irq_pending & irq_source) == 0u, message);
            snprintf(message, sizeof(message), "%s pc", cases[i].name);
            ASSERT_EQ_U32(expected_pc, emu.cpu.pc & 0xFFFFFFu, message);
            snprintf(message, sizeof(message), "%s iff1 cleared", cases[i].name);
            ASSERT_TRUE(!emu.cpu.iff1, message);
            snprintf(message, sizeof(message), "%s vector addr", cases[i].name);
            ASSERT_EQ_U32(cases[i].interrupt_mode == 1u
                              ? 0x0038u
                              : (cases[i].timer_id == 0u
                                    ? EZ80_IRQ_VECTOR_OFFSET_TIMER0
                                    : EZ80_IRQ_VECTOR_OFFSET_TIMER1),
                          emu.hw.last_irq_vector_addr,
                          message);
        } else {
            snprintf(message, sizeof(message), "%s no service count", cases[i].name);
            ASSERT_EQ_U32(0u, emu.hw.total_interrupts_serviced, message);
            snprintf(message, sizeof(message), "%s irq still pending", cases[i].name);
            ASSERT_EQ_INT(expected.overflowed,
                          ((emu.hw.irq_pending & irq_source) != 0u) ? 1 : 0,
                          message);
            snprintf(message, sizeof(message), "%s pc unchanged", cases[i].name);
            ASSERT_EQ_U32(TEST_RAM_EXEC_BASE, emu.cpu.pc & 0xFFFFFFu, message);
            snprintf(message, sizeof(message), "%s still halted", cases[i].name);
            ASSERT_TRUE(emu.cpu.halted, message);
            snprintf(message, sizeof(message), "%s last irq source untouched", cases[i].name);
            ASSERT_EQ_INT(0, emu.hw.last_irq_source, message);
        }
    }
}

static void test_timer_halt_wake_interrupt_mode_matrix(void)
{
    struct {
        const char *name;
        uint8_t timer_id;
        uint8_t interrupt_mode;
        bool adl_mode;
        uint8_t irq_source;
        uint32_t isr_addr;
        uint32_t expected_pc;
        uint32_t expected_vector_addr;
    } cases[] = {
        { "halt-wake-im0-t0", 0u, 0u, false, EZ80_IRQ_SOURCE_TIMER0,
          0x0038u, 0x0038u, 0x0038u },
        { "halt-wake-im1-t1", 1u, 1u, false, EZ80_IRQ_SOURCE_TIMER1,
          0x0038u, 0x0038u, 0x0038u },
        { "halt-wake-im2-adl-t0", 0u, 2u, true, EZ80_IRQ_SOURCE_TIMER0,
          TEST_RAM_EXEC_BASE + 0x0240u, TEST_RAM_EXEC_BASE + 0x0240u,
          EZ80_IRQ_VECTOR_OFFSET_TIMER0 }
    };
    size_t i;

    printf("[TEST] Timer IRQ wakes HALT across IM0/IM1/IM2\n");

    for (i = 0u; i < sizeof(cases) / sizeof(cases[0]); i++) {
        ez80_emulator_t emu;
        ez80_run_result_t result;
        ez80_status_t status;
        char message[128];

        memset(&emu, 0, sizeof(emu));
        status = ez80_emulator_init(&emu);
        snprintf(message, sizeof(message), "%s init", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        emu.rom_loaded = true;
        emu.cpu.halted = true;
        emu.cpu.iff1 = true;
        emu.cpu.iff2 = true;
        emu.cpu.interrupt_mode = cases[i].interrupt_mode;
        emu.cpu.adl_mode = cases[i].adl_mode;
        emu.cpu.pc = TEST_RAM_EXEC_BASE;
        emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
        emu.hw.irq_mask = cases[i].irq_source;

        status = ez80_emulator_enable_interrupts(&emu, true);
        snprintf(message, sizeof(message), "%s enable irqs", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);
        status = ez80_emulator_set_timer_prescaler(&emu, cases[i].timer_id, EZ80_TIMER_PRESCALER_1);
        snprintf(message, sizeof(message), "%s set prescaler", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);
        status = ez80_emulator_set_timer_reload(&emu, cases[i].timer_id, 0u);
        snprintf(message, sizeof(message), "%s set reload", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);

        if (cases[i].timer_id == 0u) {
            emu.hw.timer0_control = EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE;
            emu.hw.timer0_counter = 0xFFFEu;
        } else {
            emu.hw.timer1_control = EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE;
            emu.hw.timer1_counter = 0xFFFEu;
        }

        emu.memory.flash_window[0x38] = 0x76u;
        if (cases[i].interrupt_mode == 2u) {
            emu.cpu.i_reg16 = 0x0000u;
            emu.memory.flash_window[EZ80_IRQ_VECTOR_OFFSET_TIMER0 + 0u] =
                (uint8_t)(cases[i].isr_addr & 0xFFu);
            emu.memory.flash_window[EZ80_IRQ_VECTOR_OFFSET_TIMER0 + 1u] =
                (uint8_t)((cases[i].isr_addr >> 8) & 0xFFu);
            emu.memory.flash_window[EZ80_IRQ_VECTOR_OFFSET_TIMER0 + 2u] =
                (uint8_t)((cases[i].isr_addr >> 16) & 0xFFu);
            emu.memory.ram[cases[i].isr_addr - EZ80_RAM_BASE] = 0x76u;
        }

        memset(&result, 0, sizeof(result));
        status = ez80_emulator_run_cycles(&emu, 17u, &result);
        snprintf(message, sizeof(message), "%s run", cases[i].name);
        ASSERT_EQ_INT(EZ80_OK, status, message);
        snprintf(message, sizeof(message), "%s interrupt serviced", cases[i].name);
        ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, message);
        snprintf(message, sizeof(message), "%s last irq source", cases[i].name);
        ASSERT_EQ_INT(cases[i].irq_source, emu.hw.last_irq_source, message);
        snprintf(message, sizeof(message), "%s irq acknowledged", cases[i].name);
        ASSERT_TRUE((emu.hw.irq_pending & cases[i].irq_source) == 0u, message);
        snprintf(message, sizeof(message), "%s cpu resumed", cases[i].name);
        ASSERT_TRUE(!emu.cpu.halted, message);
        snprintf(message, sizeof(message), "%s pc dispatch target", cases[i].name);
        ASSERT_EQ_U32(cases[i].expected_pc, emu.cpu.pc & 0xFFFFFFu, message);
        snprintf(message, sizeof(message), "%s vector addr", cases[i].name);
        ASSERT_EQ_U32(cases[i].expected_vector_addr, emu.hw.last_irq_vector_addr, message);
    }
}

