static void test_dma_configure_basic(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t dma_status = 0xFFu;
    uint32_t transferred = 0xFFFFu;

    printf("[TEST] DMA configure basic\n");

    ez80_emulator_init(&emu);

    status = ez80_emulator_dma_configure(&emu, 0u,
                                          EZ80_RAM_BASE + 0x100u,
                                          EZ80_RAM_BASE + 0x200u,
                                          64u,
                                          EZ80_DMA_CONTROL_ENABLE |
                                          EZ80_DMA_CONTROL_SRC_INC |
                                          EZ80_DMA_CONTROL_DST_INC);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA configure ch0 status");
    ASSERT_EQ_U32(EZ80_RAM_BASE + 0x100u, emu.hw.dma[0].src_addr, "DMA ch0 src");
    ASSERT_EQ_U32(EZ80_RAM_BASE + 0x200u, emu.hw.dma[0].dst_addr, "DMA ch0 dst");
    ASSERT_EQ_U32(64u, emu.hw.dma[0].length, "DMA ch0 length");
    ASSERT_EQ_INT(EZ80_DMA_STATUS_IDLE, emu.hw.dma[0].status, "DMA ch0 idle after configure");

    status = ez80_emulator_dma_get_status(&emu, 0u, &dma_status, &transferred);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA get status");
    ASSERT_EQ_INT(EZ80_DMA_STATUS_IDLE, dma_status, "DMA status idle");
    ASSERT_EQ_U32(0u, transferred, "DMA 0 bytes transferred");

    /* Invalid channel */
    status = ez80_emulator_dma_configure(&emu, 3u, 0u, 0u, 0u, 0u);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "DMA invalid channel");
}

static void test_dma_byte_transfer(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t dma_status;
    uint32_t transferred;
    uint32_t i;
    uint8_t val;

    printf("[TEST] DMA byte transfer RAM to RAM\n");

    ez80_emulator_init(&emu);

    /* Fill source region with pattern */
    for (i = 0u; i < 32u; i++) {
        emu.memory.ram[0x100u + i] = (uint8_t)(0xA0u + i);
    }

    status = ez80_emulator_dma_configure(&emu, 0u,
                                          EZ80_RAM_BASE + 0x100u,
                                          EZ80_RAM_BASE + 0x200u,
                                          32u,
                                          EZ80_DMA_CONTROL_ENABLE |
                                          EZ80_DMA_CONTROL_SRC_INC |
                                          EZ80_DMA_CONTROL_DST_INC);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA byte xfer configure");

    status = ez80_emulator_dma_start(&emu, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA byte xfer start");

    status = ez80_emulator_dma_get_status(&emu, 0u, &dma_status, &transferred);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA byte xfer get status");
    ASSERT_EQ_INT(EZ80_DMA_STATUS_DONE, dma_status, "DMA byte xfer done");
    ASSERT_EQ_U32(32u, transferred, "DMA byte xfer 32 bytes");

    /* Verify data */
    for (i = 0u; i < 32u; i++) {
        ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x200u + i, &val);
        ASSERT_EQ_INT((int)(0xA0u + i), (int)val, "DMA byte xfer data match");
    }

    ASSERT_EQ_U32(1u, emu.hw.dma_total_transfers, "DMA total transfers 1");
}

static void test_dma_word_transfer(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t dma_status;
    uint32_t transferred;
    uint8_t lo, hi;

    printf("[TEST] DMA 16-bit word transfer\n");

    ez80_emulator_init(&emu);

    /* Write 4 words (8 bytes) to source */
    emu.memory.ram[0x300u] = 0x34u; emu.memory.ram[0x301u] = 0x12u;
    emu.memory.ram[0x302u] = 0x78u; emu.memory.ram[0x303u] = 0x56u;
    emu.memory.ram[0x304u] = 0xBCu; emu.memory.ram[0x305u] = 0x9Au;
    emu.memory.ram[0x306u] = 0xF0u; emu.memory.ram[0x307u] = 0xDEu;

    status = ez80_emulator_dma_configure(&emu, 1u,
                                          EZ80_RAM_BASE + 0x300u,
                                          EZ80_RAM_BASE + 0x400u,
                                          8u,
                                          EZ80_DMA_CONTROL_ENABLE |
                                          EZ80_DMA_CONTROL_SRC_INC |
                                          EZ80_DMA_CONTROL_DST_INC |
                                          EZ80_DMA_CONTROL_WORD_MODE);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA word configure");

    status = ez80_emulator_dma_start(&emu, 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA word start");

    ez80_emulator_dma_get_status(&emu, 1u, &dma_status, &transferred);
    ASSERT_EQ_INT(EZ80_DMA_STATUS_DONE, dma_status, "DMA word done");
    ASSERT_EQ_U32(8u, transferred, "DMA word 8 bytes transferred");

    /* Verify first word */
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x400u, &lo);
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x401u, &hi);
    ASSERT_EQ_INT(0x34, lo, "DMA word[0] lo");
    ASSERT_EQ_INT(0x12, hi, "DMA word[0] hi");

    /* Verify last word */
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x406u, &lo);
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x407u, &hi);
    ASSERT_EQ_INT(0xF0, lo, "DMA word[3] lo");
    ASSERT_EQ_INT(0xDE, hi, "DMA word[3] hi");
}

static void test_dma_no_increment(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val;
    uint32_t i;

    printf("[TEST] DMA no-increment (fill) mode\n");

    ez80_emulator_init(&emu);

    /* Source: single byte at 0x500 */
    emu.memory.ram[0x500u] = 0xAAu;

    /* Configure: no SRC_INC, DST_INC only => fills dst with the same byte */
    status = ez80_emulator_dma_configure(&emu, 2u,
                                          EZ80_RAM_BASE + 0x500u,
                                          EZ80_RAM_BASE + 0x600u,
                                          16u,
                                          EZ80_DMA_CONTROL_ENABLE |
                                          EZ80_DMA_CONTROL_DST_INC);
    ASSERT_EQ_INT(EZ80_OK, status, "DMA fill configure");

    ez80_emulator_dma_start(&emu, 2u);

    /* All 16 dest bytes should be 0xAA */
    for (i = 0u; i < 16u; i++) {
        ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x600u + i, &val);
        ASSERT_EQ_INT(0xAA, val, "DMA fill byte match");
    }
}

