static void test_nmi_basic_dispatch(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] NMI basic dispatch\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    /* HALT at current PC */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x76u;

    /* HALT at NMI vector 0x0066 */
    emu.memory.flash_window[0x66] = 0x76u;

    /* Raise NMI */
    status = ez80_emulator_raise_nmi(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "NMI raise status");
    ASSERT_TRUE(emu.hw.nmi_pending, "NMI pending after raise");

    /* Run - NMI should fire */
    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "NMI run status");
    ASSERT_TRUE(result.hit_halt, "NMI halted at vector");

    /* NMI dispatched */
    ASSERT_EQ_U32(1u, emu.hw.nmi_count, "NMI count 1");
    ASSERT_TRUE(emu.hw.nmi_active, "NMI active flag");
    ASSERT_TRUE(!emu.hw.nmi_pending, "NMI no longer pending");

    /* IFF1 cleared by NMI */
    ASSERT_TRUE(!emu.cpu.iff1, "IFF1 cleared by NMI");
    /* IFF2 preserved (NMI doesn't touch IFF2) */
    ASSERT_TRUE(emu.cpu.iff2, "IFF2 preserved by NMI");

    /* PC at NMI vector + 1 (past HALT) */
    ASSERT_EQ_U32(0x0067u, emu.cpu.pc & 0xFFFFFFu, "PC at NMI vector HALT+1");
}

static void test_nmi_overrides_di(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] NMI fires even when interrupts disabled\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = false; /* interrupts disabled */
    emu.cpu.iff2 = false;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x76u;
    emu.memory.flash_window[0x66] = 0x76u;

    ez80_emulator_raise_nmi(&emu);

    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "NMI+DI run status");
    ASSERT_TRUE(result.hit_halt, "NMI+DI halted");
    ASSERT_EQ_U32(1u, emu.hw.nmi_count, "NMI+DI count 1");
    ASSERT_EQ_U32(0x0067u, emu.cpu.pc & 0xFFFFFFu, "NMI+DI PC at vector");
}

