static void test_nmi_retn_restores_iff1(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] RETN from NMI restores IFF1\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    /* Instruction at current PC: NOP then HALT */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x00u;      /* NOP */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 1u] = 0x76u; /* HALT */

    /* At NMI vector 0x0066: RETN (ED 45) */
    emu.memory.flash_window[0x66] = 0xEDu;
    emu.memory.flash_window[0x67] = 0x45u;

    ez80_emulator_raise_nmi(&emu);

    /* Run: executes NOP, NMI fires, RETN returns, HALT */
    status = ez80_emulator_run_cycles(&emu, 300u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "NMI RETN run");
    ASSERT_TRUE(result.hit_halt, "NMI RETN halted");

    /* After RETN from NMI, IFF1 should be restored to pre-NMI value (true) */
    ASSERT_TRUE(emu.cpu.iff1, "IFF1 restored after NMI RETN");
    ASSERT_TRUE(!emu.hw.nmi_active, "NMI no longer active after RETN");
    ASSERT_EQ_U32(1u, emu.hw.nmi_count, "NMI count still 1");
}

static void test_retn_legacy_nmi_state_without_depth_clears_active(void)
{
    ez80_emulator_t emu;
    ez80_instruction_t decoded;
    ez80_status_t status;
    const uint32_t initial_sp = TEST_RAM_EXEC_BASE + 0x1000u;
    const uint32_t ret_addr = TEST_RAM_EXEC_BASE + 0x123u;

    printf("[TEST] RETN clears legacy single-level NMI state without depth bookkeeping\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = false;
    emu.cpu.iff2 = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = initial_sp - 3u;
    emu.hw.nmi_active = true;
    emu.hw.nmi_nesting_depth = 0u;
    emu.hw.nmi_iff1_saved = true;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0xEDu;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 1u] = 0x45u;
    emu.memory.ram[(initial_sp - 3u) - EZ80_RAM_BASE + 0u] = (uint8_t)(ret_addr & 0xFFu);
    emu.memory.ram[(initial_sp - 3u) - EZ80_RAM_BASE + 1u] = (uint8_t)((ret_addr >> 8) & 0xFFu);
    emu.memory.ram[(initial_sp - 3u) - EZ80_RAM_BASE + 2u] = (uint8_t)((ret_addr >> 16) & 0xFFu);

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "legacy RETN step");
    ASSERT_TRUE(emu.cpu.iff1, "legacy RETN restores saved IFF1");
    ASSERT_TRUE(!emu.hw.nmi_active, "legacy RETN clears active NMI");
    ASSERT_EQ_U32(0u, emu.hw.nmi_nesting_depth, "legacy RETN leaves nesting depth at zero");
    ASSERT_EQ_U32(ret_addr, emu.cpu.pc, "legacy RETN returns to stacked address");
    ASSERT_EQ_U32(initial_sp, emu.cpu.sp, "legacy RETN restores stack pointer");
    ASSERT_EQ_INT(0, emu.memory.mmio[EZ80_MMIO_REG_NMI_ACTIVE], "legacy RETN clears NMI-active MMIO");
}

static void test_nested_nmi_retn_unwinds_outermost_only(void)
{
    ez80_emulator_t emu;
    ez80_instruction_t decoded;
    ez80_status_t status;
    const uint32_t initial_sp = TEST_RAM_EXEC_BASE + 0x1000u;
    const uint32_t inner_ret_addr = TEST_RAM_EXEC_BASE + 0x10u;
    const uint32_t outer_ret_addr = TEST_RAM_EXEC_BASE + 0x20u;

    printf("[TEST] nested NMI RETN keeps outer NMI active until final unwind\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = false;
    emu.cpu.iff2 = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = initial_sp - 6u;
    emu.hw.nmi_active = true;
    emu.hw.nmi_nesting_depth = 2u;
    emu.hw.nmi_iff1_saved = true;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0xEDu;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 1u] = 0x45u;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 0x10u] = 0xEDu;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 0x11u] = 0x45u;
    emu.memory.ram[(initial_sp - 6u) - EZ80_RAM_BASE + 0u] = (uint8_t)(inner_ret_addr & 0xFFu);
    emu.memory.ram[(initial_sp - 6u) - EZ80_RAM_BASE + 1u] = (uint8_t)((inner_ret_addr >> 8) & 0xFFu);
    emu.memory.ram[(initial_sp - 6u) - EZ80_RAM_BASE + 2u] = (uint8_t)((inner_ret_addr >> 16) & 0xFFu);
    emu.memory.ram[(initial_sp - 3u) - EZ80_RAM_BASE + 0u] = (uint8_t)(outer_ret_addr & 0xFFu);
    emu.memory.ram[(initial_sp - 3u) - EZ80_RAM_BASE + 1u] = (uint8_t)((outer_ret_addr >> 8) & 0xFFu);
    emu.memory.ram[(initial_sp - 3u) - EZ80_RAM_BASE + 2u] = (uint8_t)((outer_ret_addr >> 16) & 0xFFu);

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "nested RETN inner step");
    ASSERT_EQ_U32(1u, emu.hw.nmi_nesting_depth, "nested RETN inner leaves one active NMI frame");
    ASSERT_TRUE(emu.hw.nmi_active, "nested RETN inner keeps NMI active");
    ASSERT_TRUE(!emu.cpu.iff1, "nested RETN inner keeps interrupts masked");
    ASSERT_EQ_U32(inner_ret_addr, emu.cpu.pc, "nested RETN inner returns to outer NMI frame");
    ASSERT_EQ_U32(initial_sp - 3u, emu.cpu.sp, "nested RETN inner pops one stacked address");
    ASSERT_EQ_INT(1, emu.memory.mmio[EZ80_MMIO_REG_NMI_ACTIVE], "nested RETN inner keeps NMI-active MMIO set");

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "nested RETN outer step");
    ASSERT_EQ_U32(0u, emu.hw.nmi_nesting_depth, "nested RETN outer clears nesting depth");
    ASSERT_TRUE(!emu.hw.nmi_active, "nested RETN outer clears NMI active");
    ASSERT_TRUE(emu.cpu.iff1, "nested RETN outer restores saved IFF1");
    ASSERT_EQ_U32(outer_ret_addr, emu.cpu.pc, "nested RETN outer returns to interrupted code");
    ASSERT_EQ_U32(initial_sp, emu.cpu.sp, "nested RETN outer restores full stack pointer");
    ASSERT_EQ_INT(0, emu.memory.mmio[EZ80_MMIO_REG_NMI_ACTIVE], "nested RETN outer clears NMI-active MMIO");
}

