static void test_reti_nesting_depth(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] RETI decrements nesting depth\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.interrupt_mode = 1u;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    /* NOP at test PC, then HALT */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x00u;      /* NOP */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 1u] = 0x76u; /* HALT */

    /* ISR at 0x0038: EI (FB), RETI (ED 4D), then next instruction */
    emu.memory.flash_window[0x38] = 0xFBu;             /* EI */
    emu.memory.flash_window[0x39] = 0xEDu;             /* RETI prefix */
    emu.memory.flash_window[0x3A] = 0x4Du;             /* RETI opcode */

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_KEYPAD;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_KEYPAD);

    /* After NOP executes, IRQ fires. ISR: EI, RETI, then returns to HALT. */
    status = ez80_emulator_run_cycles(&emu, 300u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "RETI nesting run");
    ASSERT_TRUE(result.hit_halt, "RETI nesting halted");

    /* Nesting depth should be 0 after RETI */
    ASSERT_EQ_U32(0u, emu.hw.irq_nesting_depth, "nesting depth 0 after RETI");
    ASSERT_EQ_U32(1u, emu.hw.total_reti_count, "RETI count 1");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_KEYPAD, emu.hw.last_reti_source, "RETI source keypad");

    /* MMIO reflects */
    ASSERT_EQ_INT(0, emu.memory.mmio[EZ80_MMIO_REG_IRQ_NESTING_DEPTH], "MMIO nesting 0");
    ASSERT_EQ_INT(1, emu.memory.mmio[EZ80_MMIO_REG_IRQ_TOTAL_RETI], "MMIO RETI count 1");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_KEYPAD,
                  emu.memory.mmio[EZ80_MMIO_REG_IRQ_LAST_RETI_SOURCE],
                  "MMIO RETI source");
}

static void test_irq_nesting_tracks_depth(void)
{
    ez80_emulator_t emu;

    printf("[TEST] IRQ nesting depth tracking\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    /* Manually simulate nested interrupts by directly manipulating state */
    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.interrupt_mode = 1u;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    /* Place a NOP then HALT */
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x00u;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 1u] = 0x76u;

    /* HALT at 0x0038 */
    emu.memory.flash_window[0x38] = 0x76u;

    emu.hw.irq_mask = EZ80_IRQ_SOURCE_KEYPAD;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_KEYPAD);

    {
        ez80_run_result_t result;
        ez80_emulator_run_cycles(&emu, 200u, &result);
    }

    /* After interrupt dispatch, nesting depth should be 1 */
    ASSERT_EQ_U32(1u, emu.hw.irq_nesting_depth, "nesting depth 1 after first IRQ");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_KEYPAD, emu.hw.irq_nesting_stack[0],
                  "nesting stack[0] = keypad");
}

static void test_irq_nesting_max_depth(void)
{
    ez80_emulator_t emu;
    uint8_t i;

    printf("[TEST] IRQ nesting max depth\n");

    ez80_emulator_init(&emu);

    /* Simulate filling the nesting stack */
    for (i = 0u; i < EZ80_IRQ_MAX_NESTING; i++) {
        emu.hw.irq_nesting_stack[i] = (uint8_t)(i + 1u);
        emu.hw.irq_nesting_depth = (uint8_t)(i + 1u);
    }
    ASSERT_EQ_U32(EZ80_IRQ_MAX_NESTING, emu.hw.irq_nesting_depth, "nesting at max");

    /* Verify RETI decrements */
    emu.hw.total_reti_count = 0u;
    /* Manually call the logic that RETI does */
    {
        /* Simulate RETI: decrement depth, pop source */
        emu.hw.total_reti_count++;
        emu.hw.last_reti_source = emu.hw.irq_nesting_stack[emu.hw.irq_nesting_depth - 1u];
        emu.hw.irq_nesting_depth--;
    }
    ASSERT_EQ_U32(EZ80_IRQ_MAX_NESTING - 1u, emu.hw.irq_nesting_depth,
                  "nesting depth after RETI from max");
    ASSERT_EQ_INT(EZ80_IRQ_MAX_NESTING, emu.hw.last_reti_source,
                  "RETI source from top of stack");
}

static void test_reti_vs_retn_distinction(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_instruction_t decoded;

    printf("[TEST] RETI vs RETN distinct behavior\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;

    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = false;
    emu.cpu.iff2 = true;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    /* Manually push a return address */
    {
        uint32_t ret_addr = TEST_RAM_EXEC_BASE + 0x100u;
        uint32_t sp = emu.cpu.sp;
        emu.memory.ram[(sp - 3u) - EZ80_RAM_BASE + 0u] = (uint8_t)(ret_addr & 0xFFu);
        emu.memory.ram[(sp - 3u) - EZ80_RAM_BASE + 1u] = (uint8_t)((ret_addr >> 8) & 0xFFu);
        emu.memory.ram[(sp - 3u) - EZ80_RAM_BASE + 2u] = (uint8_t)((ret_addr >> 16) & 0xFFu);
        emu.cpu.sp = sp - 3u;
    }

    /* Simulate being inside an ISR: set nesting depth */
    emu.hw.irq_nesting_depth = 1u;
    emu.hw.irq_nesting_stack[0] = EZ80_IRQ_SOURCE_TIMER0;

    /* ED 4D = RETI */
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0xEDu;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 1u] = 0x4Du;

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "RETI step");

    /* RETI should have decremented nesting and recorded source */
    ASSERT_EQ_U32(0u, emu.hw.irq_nesting_depth, "RETI nesting depth 0");
    ASSERT_EQ_U32(1u, emu.hw.total_reti_count, "RETI total count 1");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_TIMER0, emu.hw.last_reti_source, "RETI source timer0");

    /* IFF1 should be restored from IFF2 */
    ASSERT_TRUE(emu.cpu.iff1, "RETI restores IFF1 from IFF2");

    /* Now test RETN (ED 45) */
    emu.cpu.iff1 = false;
    emu.cpu.iff2 = true;
    emu.hw.nmi_active = true;
    emu.hw.nmi_iff1_saved = true; /* saved IFF1 was true before NMI */

    {
        uint32_t ret_addr = TEST_RAM_EXEC_BASE + 0x200u;
        uint32_t sp = emu.cpu.sp;
        emu.memory.ram[(sp - 3u) - EZ80_RAM_BASE + 0u] = (uint8_t)(ret_addr & 0xFFu);
        emu.memory.ram[(sp - 3u) - EZ80_RAM_BASE + 1u] = (uint8_t)((ret_addr >> 8) & 0xFFu);
        emu.memory.ram[(sp - 3u) - EZ80_RAM_BASE + 2u] = (uint8_t)((ret_addr >> 16) & 0xFFu);
        emu.cpu.sp = sp - 3u;
    }

    emu.cpu.pc = TEST_RAM_EXEC_BASE + 0x10u;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 0x10u] = 0xEDu;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET + 0x11u] = 0x45u; /* RETN */

    status = ez80_emulator_step(&emu, &decoded);
    ASSERT_EQ_INT(EZ80_OK, status, "RETN step");

    /* RETN from NMI should restore IFF1 from saved value and clear nmi_active */
    ASSERT_TRUE(emu.cpu.iff1, "RETN restores NMI saved IFF1");
    ASSERT_TRUE(!emu.hw.nmi_active, "RETN clears NMI active");
}

