static void test_nmi_priority_over_maskable(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] NMI takes priority over maskable interrupts\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    ez80_emulator_enable_interrupts(&emu, true);

    emu.cpu.adl_mode = true;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.interrupt_mode = 1u;
    emu.cpu.halted = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    /* HALT at IM1 vector */
    emu.memory.flash_window[0x38] = 0x76u;
    /* HALT at NMI vector */
    emu.memory.flash_window[0x66] = 0x76u;

    /* Raise both NMI and maskable at the same time */
    emu.hw.irq_mask = EZ80_IRQ_SOURCE_KEYPAD;
    ez80_emulator_raise_interrupt(&emu, EZ80_IRQ_SOURCE_KEYPAD);
    ez80_emulator_raise_nmi(&emu);

    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "NMI priority run");
    ASSERT_TRUE(result.hit_halt, "NMI priority halted");

    /* NMI should have fired first (PC at NMI vector) */
    ASSERT_EQ_U32(0x0067u, emu.cpu.pc & 0xFFFFFFu, "NMI dispatched first (PC=0x67)");
    ASSERT_EQ_U32(1u, emu.hw.nmi_count, "NMI priority count");
    /* Maskable should NOT have fired yet since NMI disabled IFF1 */
    ASSERT_EQ_U32(0u, emu.hw.total_interrupts_serviced, "maskable not yet serviced");
}

static void test_dma_disabled_channel(void)
{
    ez80_emulator_t emu;
    uint8_t dma_status;

    printf("[TEST] DMA disabled channel does nothing\n");

    ez80_emulator_init(&emu);

    emu.memory.ram[0x100u] = 0xBBu;

    /* Configure WITHOUT enable flag */
    ez80_emulator_dma_configure(&emu, 0u,
                                 EZ80_RAM_BASE + 0x100u,
                                 EZ80_RAM_BASE + 0x200u,
                                 8u,
                                 EZ80_DMA_CONTROL_SRC_INC | EZ80_DMA_CONTROL_DST_INC);
    ez80_emulator_dma_start(&emu, 0u);

    ez80_emulator_dma_get_status(&emu, 0u, &dma_status, NULL);
    /* Should still be idle since enable not set */
    ASSERT_EQ_INT(EZ80_DMA_STATUS_IDLE, dma_status, "DMA disabled stays idle");

    {
        uint8_t val = 0xFFu;
        ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x200u, &val);
        ASSERT_EQ_INT(0x00, val, "DMA disabled no data written");
    }
}

static void test_dma_continuous_mode(void)
{
    ez80_emulator_t emu;
    uint8_t dma_status;
    uint32_t transferred;
    uint8_t val;

    printf("[TEST] DMA continuous mode preserves addresses\n");

    ez80_emulator_init(&emu);

    emu.memory.ram[0x100u] = 0x11u;
    emu.memory.ram[0x101u] = 0x22u;
    emu.memory.ram[0x102u] = 0x33u;
    emu.memory.ram[0x103u] = 0x44u;

    ez80_emulator_dma_configure(&emu, 0u,
                                 EZ80_RAM_BASE + 0x100u,
                                 EZ80_RAM_BASE + 0x200u,
                                 4u,
                                 EZ80_DMA_CONTROL_ENABLE |
                                 EZ80_DMA_CONTROL_SRC_INC |
                                 EZ80_DMA_CONTROL_DST_INC |
                                 EZ80_DMA_CONTROL_CONTINUOUS);

    ez80_emulator_dma_start(&emu, 0u);

    ez80_emulator_dma_get_status(&emu, 0u, &dma_status, &transferred);
    ASSERT_EQ_INT(EZ80_DMA_STATUS_DONE, dma_status, "DMA continuous done");
    ASSERT_EQ_U32(4u, transferred, "DMA continuous 4 bytes");

    /* In continuous mode, src/dst should have advanced for next transfer */
    ASSERT_EQ_U32(EZ80_RAM_BASE + 0x104u, emu.hw.dma[0].src_addr, "DMA continuous src advanced");
    ASSERT_EQ_U32(EZ80_RAM_BASE + 0x204u, emu.hw.dma[0].dst_addr, "DMA continuous dst advanced");

    /* Verify data */
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x200u, &val);
    ASSERT_EQ_INT(0x11, val, "DMA continuous data[0]");
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x203u, &val);
    ASSERT_EQ_INT(0x44, val, "DMA continuous data[3]");
}

static void test_dma_interrupt_dispatch_after_transfer(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] DMA interrupt dispatch after transfer completion\n");

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.cpu.interrupt_mode = 1u;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.cpu.adl_mode = true;
    emu.interrupts_enabled_in_emulator = true;
    emu.memory.ram[TEST_RAM_EXEC_OFFSET] = 0x00u; /* NOP */
    emu.memory.flash_window[0x38] = 0x76u; /* HALT in IM1 vector */
    emu.hw.irq_mask = EZ80_IRQ_SOURCE_DMA;
    emu.memory.ram[0x100u] = 0xA5u;

    status = ez80_emulator_dma_configure(&emu,
                                         0u,
                                         EZ80_RAM_BASE + 0x100u,
                                         EZ80_RAM_BASE + 0x200u,
                                         1u,
                                         EZ80_DMA_CONTROL_ENABLE |
                                         EZ80_DMA_CONTROL_SRC_INC |
                                         EZ80_DMA_CONTROL_DST_INC |
                                         EZ80_DMA_CONTROL_IRQ_ON_DONE);
    ASSERT_EQ_INT(EZ80_OK, status, "dma irq dispatch configure");

    status = ez80_emulator_dma_start(&emu, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "dma irq dispatch start");
    ASSERT_TRUE((emu.hw.irq_pending & EZ80_IRQ_SOURCE_DMA) != 0u,
                "dma irq dispatch pending after transfer");

    status = ez80_emulator_run_cycles(&emu, 100u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "dma irq dispatch run");
    ASSERT_TRUE(result.hit_halt, "dma irq dispatch halts in ISR");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "dma irq dispatch serviced once");
    ASSERT_EQ_INT(EZ80_IRQ_SOURCE_DMA, emu.hw.last_irq_source, "dma irq dispatch source");
    ASSERT_EQ_U32(0x0038u, emu.hw.last_irq_vector_addr, "dma irq dispatch vector");
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x200u, &val);
    ASSERT_EQ_INT(0xA5u, val, "dma irq dispatch copied byte");
}

