    status = ez80_emulator_spi_get_status(&emu, 0u, &spi_status);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI0 get default status");
    ASSERT_TRUE((spi_status & EZ80_SPI_STATUS_TX_EMPTY) != 0u, "SPI0 default TX empty");
    ASSERT_TRUE((spi_status & EZ80_SPI_STATUS_RX_READY) == 0u, "SPI0 default no RX ready");

    /* Configure as master, enabled */
    status = ez80_emulator_spi_configure(&emu, 0u,
        EZ80_SPI_CONTROL_ENABLE | EZ80_SPI_CONTROL_MASTER, 0x04u);
