static void test_spi_transfer_preloaded_rx(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t rx = 0u;

    printf("[TEST] SPI transfer with preloaded RX FIFO\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI preloaded init");

    status = ez80_emulator_spi_configure(&emu, 0u,
        EZ80_SPI_CONTROL_ENABLE | EZ80_SPI_CONTROL_MASTER, 0x02u);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI preloaded configure");

    /* Preload slave response bytes */
    status = ez80_emulator_spi_load_rx(&emu, 0u, 0x42u);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI load RX byte 1");
    status = ez80_emulator_spi_load_rx(&emu, 0u, 0x99u);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI load RX byte 2");

    /* First transfer should consume 0x42 */
    status = ez80_emulator_spi_transfer(&emu, 0u, 0x00u, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI preloaded transfer 1");
    ASSERT_EQ_INT(0x42, rx, "SPI preloaded RX byte 1");

    /* Second transfer should consume 0x99 */
    status = ez80_emulator_spi_transfer(&emu, 0u, 0x00u, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI preloaded transfer 2");
    ASSERT_EQ_INT(0x99, rx, "SPI preloaded RX byte 2");

    /* Third transfer -> no preloaded data -> 0xFF */
    status = ez80_emulator_spi_transfer(&emu, 0u, 0x00u, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI preloaded transfer 3");
    ASSERT_EQ_INT(0xFF, rx, "SPI preloaded RX byte 3 fallback");
}

static void test_spi_rx_fifo_overflow(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t i;

    printf("[TEST] SPI RX FIFO overflow\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI overflow init");

    /* Fill RX FIFO to capacity */
    for (i = 0u; i < EZ80_SPI_FIFO_SIZE; i++) {
        status = ez80_emulator_spi_load_rx(&emu, 0u, i);
        ASSERT_EQ_INT(EZ80_OK, status, "SPI fill RX FIFO");
    }

    /* One more should overflow */
    status = ez80_emulator_spi_load_rx(&emu, 0u, 0xFFu);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "SPI RX FIFO overflow");
    ASSERT_TRUE((emu.hw.spi[0].status & EZ80_SPI_STATUS_OVERRUN) != 0u,
                "SPI overrun flag set");
}

