static void test_spi_reset(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;

    printf("[TEST] SPI reset clears state\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI reset init");

    /* Configure and load some data */
    ez80_emulator_spi_configure(&emu, 0u,
        EZ80_SPI_CONTROL_ENABLE | EZ80_SPI_CONTROL_MASTER, 0x08u);
    ez80_emulator_spi_load_rx(&emu, 0u, 0x42u);
    ASSERT_EQ_INT(1u, emu.hw.spi[0].rx_source_count, "SPI pre-reset source count");

    /* Reset */
    status = ez80_emulator_spi_configure(&emu, 0u, EZ80_SPI_CONTROL_RESET, 0x02u);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI reset configure");
    ASSERT_EQ_INT(0u, emu.hw.spi[0].control, "SPI reset clears control");
    ASSERT_EQ_INT(0u, emu.hw.spi[0].rx_count, "SPI reset clears RX FIFO");
    ASSERT_EQ_INT(0u, emu.hw.spi[0].rx_source_count, "SPI reset clears source FIFO");
    ASSERT_EQ_INT(0u, emu.hw.spi[0].tx_count, "SPI reset clears TX FIFO");
    ASSERT_EQ_INT(0u, emu.hw.spi[0].total_tx_bytes, "SPI reset clears TX counter");
    ASSERT_EQ_INT(0u, emu.hw.spi[0].total_rx_bytes, "SPI reset clears RX counter");
}

