    ASSERT_EQ_INT(EZ80_OK, ez80_emulator_spi_load_rx(&emu, 0u, 0x22u), "SPI edge preload 2");
    ASSERT_EQ_INT(EZ80_OK, ez80_emulator_spi_load_rx(&emu, 0u, 0x77u), "SPI edge preload 3");

    status = ez80_emulator_spi_set_chip_select(&emu, 0u, true);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI edge CS assert");
    status = ez80_emulator_spi_set_chip_select(&emu, 0u, true);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI edge repeated CS assert");
    ASSERT_EQ_U32(1u, emu.hw.spi[0].cs_assert_count, "SPI edge repeated assert should not double-count");

    status = ez80_emulator_spi_transfer(&emu, 0u, 0xA5u, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI edge burst xfer 1");
    ASSERT_EQ_INT(0x11u, rx, "SPI edge burst rx 1");
    status = ez80_emulator_spi_transfer(&emu, 0u, 0x5Au, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "SPI edge burst xfer 2");
