static void test_gpio_port_io(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];

    /* Program: write to GPIO A data port via 16-bit OUT, then read back */
    uint8_t rom_bytes[] = {
        /* Set GPIO A direction to all output */
        0x01, 0x01, 0x30, /* LD BC,0x3001 (GPIO A dir) */
        0x3E, 0xFF,       /* LD A,0xFF */
        0xED, 0x79,       /* OUT (C),A */
        /* Write 0xC3 to GPIO A data */
        0x01, 0x00, 0x30, /* LD BC,0x3000 (GPIO A data) */
        0x3E, 0xC3,       /* LD A,0xC3 */
        0xED, 0x79,       /* OUT (C),A */
        /* Read back GPIO A data */
        0x01, 0x00, 0x30, /* LD BC,0x3000 */
        0xED, 0x78,       /* IN A,(C) */
        0x76              /* HALT */
    };

    printf("[TEST] GPIO port I/O via OUT/IN instructions\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create GPIO port IO ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO port IO init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO port IO ROM load");

    status = ez80_emulator_run_cycles(&emu, 400u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO port IO run");
    ASSERT_TRUE(run_result.hit_halt, "GPIO port IO should halt");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO port IO get state");
    ASSERT_EQ_INT(0xC3, cpu_reg_a(&cpu), "GPIO port IO readback value");

    remove(rom_path);
}

