static void test_gpio_alternate_function_mapping(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] GPIO alternate function mapping overrides GPIO output\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt init");
    status = ez80_emulator_gpio_set_direction(&emu, EZ80_GPIO_USB_PORT, EZ80_GPIO_USB_DETECT_BIT);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt dir");
    status = ez80_emulator_gpio_write(&emu, EZ80_GPIO_USB_PORT, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt clear output");
    status = ez80_emulator_gpio_read(&emu, EZ80_GPIO_USB_PORT, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt read before mux");
    ASSERT_TRUE((val & EZ80_GPIO_USB_DETECT_BIT) == 0u, "GPIO alt raw output low before mux");

    emu.hw.gpio[EZ80_GPIO_USB_PORT].alt0 = EZ80_GPIO_USB_DETECT_BIT;
    status = ez80_emulator_gpio_read(&emu, EZ80_GPIO_USB_PORT, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt read after mux");
    ASSERT_TRUE((val & EZ80_GPIO_USB_DETECT_BIT) != 0u, "GPIO alt mux follows USB detect");

    status = ez80_emulator_usb_set_connected(&emu, false);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt disconnect usb");
    status = ez80_emulator_gpio_read(&emu, EZ80_GPIO_USB_PORT, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt read disconnect");
    ASSERT_TRUE((val & EZ80_GPIO_USB_DETECT_BIT) == 0u, "GPIO alt mux updates after disconnect");

    status = ez80_emulator_gpio_write(&emu, EZ80_GPIO_USB_PORT, EZ80_GPIO_USB_DETECT_BIT);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt write ignored");
    status = ez80_emulator_gpio_read(&emu, EZ80_GPIO_USB_PORT, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO alt read final");
    ASSERT_TRUE((val & EZ80_GPIO_USB_DETECT_BIT) == 0u, "GPIO alt keeps peripheral ownership");
}

static void test_gpio_pull_configuration_and_input_drive(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] GPIO pull-up/pull-down with external input drive\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO pull init");
    status = ez80_emulator_gpio_set_direction(&emu, 0u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO pull inputs");
    emu.hw.gpio[0].pull_up = 0x03u;
    emu.hw.gpio[0].pull_down = 0x04u;

    status = ez80_emulator_gpio_read(&emu, 0u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO pull read defaults");
    ASSERT_EQ_INT(0x03u, val & 0x07u, "GPIO pulls drive default level");

    status = ez80_emulator_gpio_drive_input(&emu, 0u, 0x04u, 0x05u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO drive external input");
    status = ez80_emulator_gpio_read(&emu, 0u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO pull read external");
    ASSERT_EQ_INT(0x06u, val & 0x07u, "GPIO external input overrides pulls");

    status = ez80_emulator_gpio_drive_input(&emu, 0u, 0x00u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO release external input");
    status = ez80_emulator_gpio_read(&emu, 0u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO pull read released");
    ASSERT_EQ_INT(0x03u, val & 0x07u, "GPIO pulls restore released level");
}

static void test_gpio_interrupt_edge_detection_matrix(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t pending = 0u;

    printf("[TEST] GPIO rising/falling/both edge detection\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO edge init");
    status = ez80_emulator_gpio_set_direction(&emu, 1u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO edge inputs");
    status = ez80_emulator_gpio_drive_input(&emu, 1u, 0x02u, 0x07u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO edge baseline");
    emu.hw.gpio[1].irq_rising = 0x05u;
    emu.hw.gpio[1].irq_falling = 0x06u;
    emu.hw.gpio[1].irq_pending = 0u;

    status = ez80_emulator_gpio_drive_input(&emu, 1u, 0x05u, 0x07u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO edge trigger mixed");
    ASSERT_EQ_INT(0x07u, emu.hw.gpio[1].irq_pending, "GPIO edge mixed pending bits");

    pending = emu.hw.gpio[1].irq_pending;
    ASSERT_EQ_INT(0x07u, pending, "GPIO edge pending readback");
    emu.hw.gpio[1].irq_pending &= (uint8_t)~0x07u;
    ASSERT_EQ_INT(0x00u, emu.hw.gpio[1].irq_pending, "GPIO edge pending cleared");

    status = ez80_emulator_gpio_drive_input(&emu, 1u, 0x00u, 0x07u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO edge falling follow-up");
    ASSERT_EQ_INT(0x04u, emu.hw.gpio[1].irq_pending, "GPIO edge both-edge falling pending");
}

static void test_gpio_output_drive_interrupt_interaction(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] GPIO output drive, input masking, and edge IRQ interaction\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge init");
    status = ez80_emulator_gpio_set_direction(&emu, 3u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge input baseline");
    emu.hw.gpio[3].irq_rising = 0x01u;
    emu.hw.gpio[3].irq_falling = 0x01u;

    status = ez80_emulator_gpio_drive_input(&emu, 3u, 0x00u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge low baseline");
    emu.hw.gpio[3].irq_pending = 0u;

    status = ez80_emulator_gpio_drive_input(&emu, 3u, 0x01u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge rising input");
    ASSERT_EQ_INT(0x01u, emu.hw.gpio[3].irq_pending, "GPIO output-edge rising IRQ latched");
    status = ez80_emulator_gpio_read(&emu, 3u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge read rising input");
    ASSERT_TRUE((val & 0x01u) != 0u, "GPIO output-edge input high is readable");

    emu.hw.gpio[3].irq_pending = 0u;
    status = ez80_emulator_gpio_set_direction(&emu, 3u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge switch to output");
    ASSERT_EQ_INT(0x01u, emu.hw.gpio[3].irq_pending, "GPIO output-edge output takeover triggers falling IRQ");
    status = ez80_emulator_gpio_write(&emu, 3u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge drive output low");
    status = ez80_emulator_gpio_read(&emu, 3u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge read driven low");
    ASSERT_TRUE((val & 0x01u) == 0u, "GPIO output-edge output low overrides external high");

    emu.hw.gpio[3].irq_pending = 0u;
    status = ez80_emulator_gpio_drive_input(&emu, 3u, 0x01u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge update external high while output low");
    status = ez80_emulator_gpio_read(&emu, 3u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge read masked external input");
    ASSERT_TRUE((val & 0x01u) == 0u, "GPIO output-edge external input cannot override output driver");
    ASSERT_EQ_INT(0x00u, emu.hw.gpio[3].irq_pending, "GPIO output-edge no IRQ while output masks external changes");

    status = ez80_emulator_gpio_set_direction(&emu, 3u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge release back to input");
    ASSERT_EQ_INT(0x01u, emu.hw.gpio[3].irq_pending, "GPIO output-edge resample to external high raises IRQ");
    status = ez80_emulator_gpio_read(&emu, 3u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO output-edge read released input");
    ASSERT_TRUE((val & 0x01u) != 0u, "GPIO output-edge released pin sees external high again");
}

static void test_gpio_direction_change_during_active_operation(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] GPIO direction changes re-sample active pins\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change init");
    status = ez80_emulator_gpio_set_direction(&emu, 2u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change output");
    status = ez80_emulator_gpio_write(&emu, 2u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change drive high");
    emu.hw.gpio[2].pull_down = 0x01u;

    status = ez80_emulator_gpio_set_direction(&emu, 2u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change input");
    status = ez80_emulator_gpio_read(&emu, 2u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change read pulldown");
    ASSERT_TRUE((val & 0x01u) == 0u, "GPIO dir-change releases to pulldown");

    status = ez80_emulator_gpio_drive_input(&emu, 2u, 0x01u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change external high");
    status = ez80_emulator_gpio_read(&emu, 2u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change read external high");
    ASSERT_TRUE((val & 0x01u) != 0u, "GPIO dir-change sees external input");

    status = ez80_emulator_gpio_set_direction(&emu, 2u, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change output restore");
    status = ez80_emulator_gpio_write(&emu, 2u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change drive low");
    status = ez80_emulator_gpio_read(&emu, 2u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "GPIO dir-change read output low");
    ASSERT_TRUE((val & 0x01u) == 0u, "GPIO dir-change output overrides external input");
}

