/* ---- Pass 27: Flash sector erase tests ---- */

static void test_flash_erase_basic(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[256];

    printf("[TEST] Flash sector erase basic\n");

    /* Create a ROM with known data */
    memset(rom_bytes, 0x42, sizeof(rom_bytes));
    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create flash erase ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase ROM load");

    /* Verify data is there */
    ez80_memory_read8(&emu, 0x000010u, &val);
    ASSERT_EQ_INT(0x42, val, "flash pre-erase data present");

    /* Flash protect must be permissive and sector must be unprotected */
    /* Sector 0 is OS-locked (boot pages), use a sector that's not locked */
    /* The flash window is only 64KB, so sector 0 is the only one we can test with small ROMs */
    /* For this test, set permissive mode and unprotect sector 0 by overriding OS version */
    ez80_emulator_set_os_version(&emu, 5u, 4u, 0u); /* OS 5.4 -> not 5.8+, permissive */

    /* Sector 0 is still OS-locked (boot pages), let's check it gets rejected */
    status = ez80_emulator_flash_erase_sector(&emu, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase sector 0 call succeeds");
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_OS_LOCKED,
                  emu.hw.flash_erase_last_status,
                  "flash erase sector 0 is OS-locked");

    /* Data should still be there */
    ez80_memory_read8(&emu, 0x000010u, &val);
    ASSERT_EQ_INT(0x42, val, "flash data preserved after locked erase attempt");

    remove(rom_path);
}

static void test_flash_erase_locked(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;

    printf("[TEST] Flash sector erase rejected when flash locked\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase locked init");

    /* Set OS 5.8 -> locked mode */
    ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);

    /* Try to erase an unprotected sector */
    status = ez80_emulator_flash_erase_sector(&emu, 10u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase locked call");
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_LOCKED,
                  emu.hw.flash_erase_last_status,
                  "flash erase status is locked");
    ASSERT_EQ_U32(0u, emu.hw.flash_erase_count, "flash erase count still 0");
}

