static void test_flash_erase_protection_transition_sequence(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    char rom_path[L_tmpnam];
    uint8_t value = 0u;
    const uint8_t sector = 10u;
    const uint16_t offset = 0x0234u;
    const uint32_t addr = flash_sector_sample_addr(sector, offset);
    const uint32_t offsets[] = {
        addr
    };
    const uint8_t values[] = {
        flash_sector_pattern_value(sector, 0u)
    };

    printf("[TEST] Flash erase protection transitions lock -> protected -> success\n");

    ASSERT_TRUE(write_temp_sparse_rom(offsets, values, 1u, rom_path, sizeof(rom_path)),
                "create sparse ROM for protection transition test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition load ROM");

    status = ez80_memory_read8(&emu, addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition read seeded byte");
    ASSERT_EQ_INT(values[0], value, "flash transition seeded byte preserved before erase");

    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition set locked OS");
    status = ez80_emulator_flash_erase_sector(&emu, sector);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition locked erase call");
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_LOCKED,
                  emu.hw.flash_erase_last_status,
                  "flash transition locked OS blocks erase first");
    ASSERT_EQ_U32(0u, emu.hw.flash_erase_count, "flash transition locked erase does not increment count");

    status = ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition set permissive OS");
    emu.platform.flash_sector_protected[sector] = 1u;
    status = ez80_emulator_flash_erase_sector(&emu, sector);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition protected erase call");
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_PROTECTED,
                  emu.hw.flash_erase_last_status,
                  "flash transition per-sector protection blocks erase");
    status = ez80_memory_read8(&emu, addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition read after protected erase");
    ASSERT_EQ_INT(values[0], value, "flash transition protected erase preserves byte");

    emu.platform.flash_sector_protected[sector] = 0u;
    status = ez80_emulator_flash_erase_sector(&emu, sector);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition unprotected erase call");
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_SUCCESS,
                  emu.hw.flash_erase_last_status,
                  "flash transition unprotected erase succeeds");
    ASSERT_EQ_U32(1u, emu.hw.flash_erase_count, "flash transition success increments count once");
    status = ez80_memory_read8(&emu, addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition read after successful erase");
    ASSERT_EQ_INT(0xFFu, value, "flash transition successful erase clears byte to 0xFF");

    status = ez80_emulator_set_os_version(&emu, 5u, 8u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition restore locked OS");
    status = ez80_emulator_flash_erase_sector(&emu, sector);
    ASSERT_EQ_INT(EZ80_OK, status, "flash transition re-locked erase call");
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_LOCKED,
                  emu.hw.flash_erase_last_status,
                  "flash transition re-locked OS blocks follow-up erase");
    ASSERT_EQ_U32(1u, emu.hw.flash_erase_count, "flash transition re-lock does not increment count");

    remove(rom_path);
}

static void test_flash_erase_mmio_telemetry(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] Flash sector erase MMIO telemetry\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase MMIO init");

    /* OS 5.4 -> permissive */
    ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);

    /* Erase sector 20 (not OS-locked, not protected, but beyond flash window) */
    status = ez80_emulator_flash_erase_sector(&emu, 20u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase sector 20 call");
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_SUCCESS,
                  emu.hw.flash_erase_last_status,
                  "flash erase sector 20 success");
    ASSERT_EQ_U32(1u, emu.hw.flash_erase_count, "flash erase count 1");

    /* Check MMIO */
    ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_SECTOR, &val);
    ASSERT_EQ_INT(20u, val, "MMIO flash erase sector");
    ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_STATUS, &val);
    ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_SUCCESS, val, "MMIO flash erase status");
    ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_COUNT_LO, &val);
    ASSERT_EQ_INT(1u, val, "MMIO flash erase count");

    /* Erase another sector */
    status = ez80_emulator_flash_erase_sector(&emu, 30u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase sector 30 call");
    ASSERT_EQ_U32(2u, emu.hw.flash_erase_count, "flash erase count 2");
}

