static void run_flash_erase_backing_store_matrix(const char *label, bool via_mmio)
{
    enum {
        FLASH_ERASE_TARGET_COUNT = 8,
        FLASH_ERASE_TARGET_SAMPLE_COUNT = 12,
        FLASH_ERASE_SENTINEL_COUNT = 4,
        FLASH_ERASE_SENTINEL_SAMPLE_COUNT = 6,
        FLASH_ERASE_TOTAL_MARKERS =
            (FLASH_ERASE_TARGET_COUNT * FLASH_ERASE_TARGET_SAMPLE_COUNT) +
            (FLASH_ERASE_SENTINEL_COUNT * FLASH_ERASE_SENTINEL_SAMPLE_COUNT)
    };
    static const uint8_t target_sectors[FLASH_ERASE_TARGET_COUNT] = {
        2u, 3u, 4u, 7u, 10u, 15u, 20u, 31u
    };
    static const uint16_t target_offsets[FLASH_ERASE_TARGET_SAMPLE_COUNT] = {
        0x0000u, 0x0001u, 0x0010u, 0x00AAu, 0x0123u, 0x0F0Fu,
        0x1A2Bu, 0x3C3Cu, 0x5555u, 0x7F00u, 0xBEEFu, 0xFFFEu
    };
    static const uint8_t sentinel_sectors[FLASH_ERASE_SENTINEL_COUNT] = {
        23u, 24u, 41u, 42u
    };
    static const uint16_t sentinel_offsets[FLASH_ERASE_SENTINEL_SAMPLE_COUNT] = {
        0x0002u, 0x0020u, 0x0200u, 0x2000u, 0x8000u, 0xFF00u
    };
    uint32_t rom_offsets[FLASH_ERASE_TOTAL_MARKERS];
    uint8_t rom_values[FLASH_ERASE_TOTAL_MARKERS];
    ez80_emulator_t emu;
    ez80_status_t status;
    char rom_path[L_tmpnam];
    char pre_group[80];
    char post_group[80];
    char sentinel_group[80];
    uint8_t value = 0u;
    size_t rom_index = 0u;
    size_t i;
    size_t j;

    printf("[TEST] %s\n", label);

    for (i = 0u; i < FLASH_ERASE_TARGET_COUNT; i++) {
        for (j = 0u; j < FLASH_ERASE_TARGET_SAMPLE_COUNT; j++) {
            rom_offsets[rom_index] = flash_sector_sample_addr(target_sectors[i], target_offsets[j]);
            rom_values[rom_index] = flash_sector_pattern_value(target_sectors[i], j);
            rom_index++;
        }
    }
    for (i = 0u; i < FLASH_ERASE_SENTINEL_COUNT; i++) {
        for (j = 0u; j < FLASH_ERASE_SENTINEL_SAMPLE_COUNT; j++) {
            rom_offsets[rom_index] = flash_sector_sample_addr(sentinel_sectors[i], sentinel_offsets[j]);
            rom_values[rom_index] = flash_sector_pattern_value(sentinel_sectors[i], j);
            rom_index++;
        }
    }

    ASSERT_EQ_U32(FLASH_ERASE_TOTAL_MARKERS, rom_index, "flash erase matrix marker count");
    ASSERT_TRUE(write_temp_sparse_rom(rom_offsets, rom_values, rom_index, rom_path, sizeof(rom_path)),
                "create flash erase backing-store matrix ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase backing-store init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase backing-store ROM load");
    ASSERT_EQ_U32(EZ80_FLASH_TOTAL_BYTES,
                  emu.memory.flash_bytes_loaded,
                  "flash erase matrix sparse ROM should load full flash span");
    status = ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase matrix set OS 5.4");

    snprintf(pre_group, sizeof(pre_group), "%s pre-erase", label);
    snprintf(post_group, sizeof(post_group), "%s post-erase", label);
    snprintf(sentinel_group, sizeof(sentinel_group), "%s sentinel", label);

    for (i = 0u; i < FLASH_ERASE_TARGET_COUNT; i++) {
        for (j = 0u; j < FLASH_ERASE_TARGET_SAMPLE_COUNT; j++) {
            assert_flash_byte_case(&emu,
                                   pre_group,
                                   (i * FLASH_ERASE_TARGET_SAMPLE_COUNT) + j,
                                   flash_sector_sample_addr(target_sectors[i], target_offsets[j]),
                                   flash_sector_pattern_value(target_sectors[i], j));
        }

        status = trigger_flash_erase_sector(&emu, target_sectors[i], via_mmio);
        assert_case_status(label, i, "erase-call", EZ80_OK, status);
        ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_SUCCESS,
                      emu.hw.flash_erase_last_status,
                      "flash erase matrix status should report success");
        ASSERT_EQ_U32((uint32_t)(i + 1u),
                      emu.hw.flash_erase_count,
                      "flash erase matrix count should increment");

        status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_SECTOR, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "flash erase matrix read MMIO sector");
        ASSERT_EQ_INT((int)target_sectors[i], value, "flash erase matrix MMIO sector tracks last erase");
        status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_STATUS, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "flash erase matrix read MMIO status");
        ASSERT_EQ_INT(EZ80_FLASH_ERASE_STATUS_SUCCESS,
                      value,
                      "flash erase matrix MMIO status reports success");
        status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_COUNT_LO, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "flash erase matrix read MMIO count lo");
        ASSERT_EQ_INT((int)((i + 1u) & 0xFFu), value, "flash erase matrix MMIO count lo");
        status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_COUNT_HI, &value);
        ASSERT_EQ_INT(EZ80_OK, status, "flash erase matrix read MMIO count hi");
        ASSERT_EQ_INT((int)(((i + 1u) >> 8) & 0xFFu), value, "flash erase matrix MMIO count hi");

        for (j = 0u; j < FLASH_ERASE_TARGET_SAMPLE_COUNT; j++) {
            assert_flash_byte_case(&emu,
                                   post_group,
                                   (i * FLASH_ERASE_TARGET_SAMPLE_COUNT) + j,
                                   flash_sector_sample_addr(target_sectors[i], target_offsets[j]),
                                   0xFFu);
        }

        for (j = 0u; j < FLASH_ERASE_SENTINEL_SAMPLE_COUNT; j++) {
            assert_flash_byte_case(&emu,
                                   sentinel_group,
                                   (i * FLASH_ERASE_SENTINEL_SAMPLE_COUNT) + j,
                                   flash_sector_sample_addr(sentinel_sectors[i % FLASH_ERASE_SENTINEL_COUNT],
                                                            sentinel_offsets[j]),
                                   flash_sector_pattern_value(sentinel_sectors[i % FLASH_ERASE_SENTINEL_COUNT], j));
        }

        ASSERT_EQ_U32(EZ80_FLASH_TOTAL_BYTES,
                      emu.memory.flash_bytes_loaded,
                      "flash erase matrix loaded bytes remain full flash span");
    }

    remove(rom_path);
}

static void test_flash_erase_backing_store_api_matrix(void)
{
    run_flash_erase_backing_store_matrix("Flash sector erase updates full flash backing image via API", false);
}

static void test_flash_erase_backing_store_mmio_matrix(void)
{
    run_flash_erase_backing_store_matrix("Flash sector erase updates full flash backing image via MMIO", true);
}

static void test_flash_erase_extends_loaded_range_and_write_cycle(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_dngrade_attempt_result_t attempt;
    uint8_t value = 0u;
    char rom_path[L_tmpnam];
    const uint8_t rom_bytes[] = {
        0x76u, 0x00u, 0x00u, 0x00u
    };
    const uint8_t sector = 20u;
    const uint16_t sector_offset = 0x1234u;
    const uint32_t target_addr = flash_sector_sample_addr(sector, sector_offset);
    const uint32_t expanded_loaded_bytes = ((uint32_t)sector + 1u) * EZ80_FLASH_SECTOR_BYTES;

    printf("[TEST] Flash erase extends loaded range + write cycle on high flash\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create short ROM for flash erase write-cycle test");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase write-cycle init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase write-cycle ROM load");
    status = ez80_emulator_set_os_version(&emu, 5u, 4u, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "flash erase write-cycle set OS 5.4");
    ASSERT_EQ_U32(sizeof(rom_bytes),
                  emu.memory.flash_bytes_loaded,
                  "short ROM should load only its initial bytes");

    status = ez80_memory_read8(&emu, target_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "high flash byte read before erase");
    ASSERT_EQ_INT(0x00, value, "high flash byte should read as zero before erase");

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_PORT28_UNLOCK_THEN_WRITE,
                                                    target_addr,
                                                    0xA6u,
                                                    0u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflash attempt before erase");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_FAILURE,
                  attempt.attempt_status,
                  "writeflash should fail before erase on zero-filled flash");
    ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_FLASH_REQUIRES_ERASE,
                  attempt.failure_reason,
                  "writeflash before erase should require erase");
    ASSERT_EQ_INT(0x00, attempt.observed_before, "pre-erase write sees zero-filled flash");
    ASSERT_EQ_INT(0x00, attempt.observed_after, "pre-erase write should not change flash");

    status = ez80_memory_write8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_SECTOR, sector);
    ASSERT_EQ_INT(EZ80_OK, status, "MMIO flash erase on short ROM");
    ASSERT_EQ_U32(expanded_loaded_bytes,
                  emu.memory.flash_bytes_loaded,
                  "flash erase should expand loaded span to erased sector");
    ASSERT_EQ_U32(1u, emu.hw.flash_erase_count, "flash erase write-cycle count after MMIO erase");

    status = ez80_memory_read8(&emu, target_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "high flash byte read after erase");
    ASSERT_EQ_INT(0xFF, value, "high flash byte should read erased after MMIO erase");

    status = ez80_memory_write8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_SECTOR, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "MMIO invalid flash erase write still completes");
    ASSERT_EQ_U32(1u, emu.hw.flash_erase_count, "invalid MMIO erase should not change erase count");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_FLASH_ERASE_SECTOR, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read MMIO sector after invalid erase request");
    ASSERT_EQ_INT(sector, value, "invalid MMIO erase should preserve last successful sector");

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_PORT28_UNLOCK_THEN_WRITE,
                                                    target_addr,
                                                    0xA6u,
                                                    0u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflash attempt after erase");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_SUCCESS,
                  attempt.attempt_status,
                  "writeflash should succeed after erase");
    ASSERT_TRUE(attempt.write_succeeded, "writeflash after erase reports success");
    ASSERT_EQ_INT(0xFF, attempt.observed_before, "post-erase write sees erased byte");
    ASSERT_EQ_INT(0xA6, attempt.observed_after, "post-erase write programs requested byte");

    status = ez80_memory_read8(&emu, target_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read programmed high flash byte");
    ASSERT_EQ_INT(0xA6, value, "high flash byte should contain programmed value");

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_PORT28_UNLOCK_THEN_WRITE,
                                                    target_addr,
                                                    0xF0u,
                                                    0u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflash second attempt without erase");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_FAILURE,
                  attempt.attempt_status,
                  "second writeflash should fail when bits must flip back to 1");
    ASSERT_EQ_INT(EZ80_DNGRADE_FAILURE_FLASH_REQUIRES_ERASE,
                  attempt.failure_reason,
                  "second writeflash without erase should require erase");
    ASSERT_EQ_INT(0xA6, attempt.observed_before, "second writeflash should see programmed byte");
    ASSERT_EQ_INT(0xA6, attempt.observed_after, "failed second writeflash should preserve byte");

    status = ez80_emulator_flash_erase_sector(&emu, sector);
    ASSERT_EQ_INT(EZ80_OK, status, "API flash erase after failed rewrite");
    ASSERT_EQ_U32(2u, emu.hw.flash_erase_count, "API erase should increment erase count");
    status = ez80_memory_read8(&emu, target_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read high flash byte after second erase");
    ASSERT_EQ_INT(0xFF, value, "second erase should restore erased byte");

    status = ez80_emulator_simulate_dngrade_attempt(&emu,
                                                    EZ80_DNGRADE_STRATEGY_PORT28_UNLOCK_THEN_WRITE,
                                                    target_addr,
                                                    0xF0u,
                                                    0u,
                                                    0u,
                                                    &attempt);
    ASSERT_EQ_INT(EZ80_OK, status, "writeflash after second erase");
    ASSERT_EQ_INT(EZ80_DNGRADE_ATTEMPT_STATUS_SUCCESS,
                  attempt.attempt_status,
                  "writeflash should succeed after second erase");
    ASSERT_EQ_INT(0xF0, attempt.observed_after, "writeflash after second erase programs new byte");

    status = ez80_memory_read8(&emu, target_addr, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "read high flash byte after second program");
    ASSERT_EQ_INT(0xF0, value, "high flash byte should contain second programmed value");

    remove(rom_path);
}

