static void test_i2c_start_write_stop(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t sr = 0u;

    printf("[TEST] I2C start/write/stop sequence\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c sw init");

    /* Enable I2C */
    ez80_emulator_i2c_configure(&emu, 0u, EZ80_I2C_CTL_ENAB, 0x04u);

    /* Start with slave address 0x50, write mode */
    status = ez80_emulator_i2c_start(&emu, 0u, 0x50u, false);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c start");
    ez80_emulator_i2c_get_status(&emu, 0u, &sr);
    ASSERT_EQ_INT(EZ80_I2C_SR_SLA_W_ACK, sr, "i2c SLA+W ACK");

    /* Write a byte */
    status = ez80_emulator_i2c_write(&emu, 0u, 0xABu);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c write");
    ez80_emulator_i2c_get_status(&emu, 0u, &sr);
    ASSERT_EQ_INT(EZ80_I2C_SR_DATA_W_ACK, sr, "i2c data W ACK");
    ASSERT_EQ_U32(1u, emu.hw.i2c[0].total_tx_bytes, "i2c tx count 1");

    /* Write another byte */
    status = ez80_emulator_i2c_write(&emu, 0u, 0xCDu);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c write 2");
    ASSERT_EQ_U32(2u, emu.hw.i2c[0].total_tx_bytes, "i2c tx count 2");

    /* Stop */
    status = ez80_emulator_i2c_stop(&emu, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c stop");
    ez80_emulator_i2c_get_status(&emu, 0u, &sr);
    ASSERT_EQ_INT(EZ80_I2C_SR_IDLE, sr, "i2c idle after stop");
}

static void test_i2c_start_read(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t data = 0u;
    uint8_t sr = 0u;
    uint8_t preload[] = { 0x11u, 0x22u, 0x33u };

    printf("[TEST] I2C start read with preloaded RX\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c rd init");

    ez80_emulator_i2c_configure(&emu, 0u, EZ80_I2C_CTL_ENAB, 0x04u);

    /* Preload RX buffer (simulating slave response) */
    status = ez80_emulator_i2c_load_rx(&emu, 0u, preload, 3u);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c load rx");
    ASSERT_EQ_INT(3u, emu.hw.i2c[0].rx_count, "i2c rx preloaded count");

    /* Start read from slave 0x50 */
    status = ez80_emulator_i2c_start(&emu, 0u, 0x50u, true);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c start read");
    ez80_emulator_i2c_get_status(&emu, 0u, &sr);
    ASSERT_EQ_INT(EZ80_I2C_SR_SLA_R_ACK, sr, "i2c SLA+R ACK");

    /* Read bytes */
    status = ez80_emulator_i2c_read(&emu, 0u, &data, true);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c read 1");
    ASSERT_EQ_INT(0x11u, data, "i2c read byte 1");

    status = ez80_emulator_i2c_read(&emu, 0u, &data, true);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c read 2");
    ASSERT_EQ_INT(0x22u, data, "i2c read byte 2");

    /* Read last byte with NACK */
    status = ez80_emulator_i2c_read(&emu, 0u, &data, false);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c read 3 nack");
    ASSERT_EQ_INT(0x33u, data, "i2c read byte 3");
    ez80_emulator_i2c_get_status(&emu, 0u, &sr);
    ASSERT_EQ_INT(EZ80_I2C_SR_DATA_R_NACK, sr, "i2c data R NACK");
    ASSERT_EQ_U32(3u, emu.hw.i2c[0].total_rx_bytes, "i2c rx count 3");

    ez80_emulator_i2c_stop(&emu, 0u);
}

