static void test_uart_write_read_loopback(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t data = 0u;
    uint8_t lsr = 0u;
    uint8_t preload[] = { 0x41u, 0x42u, 0x43u }; /* ABC */

    printf("[TEST] UART write and read with preloaded RX\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart wr init");

    /* TX some data */
    status = ez80_emulator_uart_write(&emu, 0u, 0x48u); /* H */
    ASSERT_EQ_INT(EZ80_OK, status, "uart write H");
    ASSERT_EQ_U32(1u, emu.hw.uart[0].total_tx_bytes, "uart tx count 1");
    ASSERT_EQ_INT(1u, emu.hw.uart[0].tx_count, "uart tx fifo 1");

    /* Preload RX (simulating received data) */
    status = ez80_emulator_uart_load_rx(&emu, 0u, preload, 3u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart load rx");

    /* Check LSR shows data ready */
    ez80_emulator_uart_get_lsr(&emu, 0u, &lsr);
    ASSERT_TRUE((lsr & EZ80_UART_LSR_DR) != 0u, "uart LSR data ready");

    /* Read data */
    status = ez80_emulator_uart_read(&emu, 0u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart read 1");
    ASSERT_EQ_INT(0x41u, data, "uart read A");

    status = ez80_emulator_uart_read(&emu, 0u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart read 2");
    ASSERT_EQ_INT(0x42u, data, "uart read B");

    status = ez80_emulator_uart_read(&emu, 0u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart read 3");
    ASSERT_EQ_INT(0x43u, data, "uart read C");
    ASSERT_EQ_U32(3u, emu.hw.uart[0].total_rx_bytes, "uart rx count 3");

    /* LSR should show no more data */
    ez80_emulator_uart_get_lsr(&emu, 0u, &lsr);
    ASSERT_TRUE((lsr & EZ80_UART_LSR_DR) == 0u, "uart LSR no data after drain");
}

