static void test_uart_tx_overflow(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t i;

    printf("[TEST] UART TX FIFO overflow\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart overflow init");

    /* Fill TX FIFO */
    for (i = 0u; i < EZ80_UART_FIFO_SIZE; i++) {
        status = ez80_emulator_uart_write(&emu, 0u, (uint8_t)(0x30u + i));
        ASSERT_EQ_INT(EZ80_OK, status, "uart fill tx fifo");
    }
    ASSERT_EQ_INT(EZ80_UART_FIFO_SIZE, emu.hw.uart[0].tx_count, "uart tx fifo full");

    /* One more write causes overrun */
    status = ez80_emulator_uart_write(&emu, 0u, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart overflow write");
    ASSERT_TRUE((emu.hw.uart[0].lsr & EZ80_UART_LSR_OE) != 0u,
                "uart LSR overrun error set");
}

