static void test_uart_port_io(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu;
    char rom_path[L_tmpnam];

    /* Program: write to UART0 THR via 16-bit OUT, then read LSR */
    uint8_t rom_bytes[] = {
        /* Set LCTL via port (reg offset 3) */
        0x01, 0x23, 0x50, /* LD BC,0x5023 (UART0_LCTL) */
        0x3E, 0x03,       /* LD A,0x03 (8N1) */
        0xED, 0x79,       /* OUT (C),A */
        /* Write 'X' to THR (reg offset 0) */
        0x01, 0x20, 0x50, /* LD BC,0x5020 (UART0_THR) */
        0x3E, 0x58,       /* LD A,'X' */
        0xED, 0x79,       /* OUT (C),A */
        /* Read LSR (reg offset 5) */
        0x01, 0x25, 0x50, /* LD BC,0x5025 (UART0_LSR) */
        0xED, 0x78,       /* IN A,(C) */
        0x76              /* HALT */
    };

    printf("[TEST] UART port I/O via OUT/IN instructions\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create UART port IO ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "UART port IO init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "UART port IO ROM load");

    status = ez80_emulator_run_cycles(&emu, 500u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "UART port IO run");
    ASSERT_TRUE(run_result.hit_halt, "UART port IO should halt");

    status = ez80_emulator_get_state(&emu, &cpu);
    ASSERT_EQ_INT(EZ80_OK, status, "UART port IO get state");

    /* LSR should show TX FIFO has data (not empty) */
    /* After writing 'X', tx_count=1, so THRE and TEMT should NOT be set */
    /* Actually our uart_write increments tx_count, then uart_update_lsr
       sets THRE only if tx_count==0. So after write, THRE=0, TEMT=0 */
    /* But the read via IN triggers the read handler which calls uart_update_lsr */
    /* With 1 byte in TX FIFO and 0 in RX, LSR should be 0x00 (no DR, no THRE) */
    /* Actually LSR.DR depends on rx_count. With no RX loaded, DR=0. */
    ASSERT_TRUE((cpu_reg_a(&cpu) & EZ80_UART_LSR_DR) == 0u,
                "UART LSR no data ready");

    remove(rom_path);
}

static void test_uart_dlab_baud_rate(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;

    printf("[TEST] UART DLAB baud rate access\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart dlab init");

    /* Set DLAB bit in LCTL */
    emu.hw.uart[0].lctl = EZ80_UART_LCTL_DLAB | 0x03u;

    /* Simulate writing BRG_L=0x1A and BRG_H=0x00 via port handler */
    /* Writing to port offset 0 with DLAB=1 sets BRG low byte */
    emu.hw.uart[0].brg = (emu.hw.uart[0].brg & 0xFF00u) | 0x1Au;
    ASSERT_EQ_INT(0x1Au, (int)(emu.hw.uart[0].brg & 0xFFu), "uart brg low byte");

    emu.hw.uart[0].brg = (emu.hw.uart[0].brg & 0x00FFu) | (0x01u << 8);
    ASSERT_EQ_INT(0x011Au, (int)emu.hw.uart[0].brg, "uart brg full 0x011A");
}

static void test_mmio_peripheral_config_writes(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;

    printf("[TEST] MMIO writes configure SPI/GPIO/I2C/UART peripherals\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio peripheral init");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_SPI0_CONTROL,
                                EZ80_SPI_CONTROL_ENABLE |
                                EZ80_SPI_CONTROL_MASTER |
                                EZ80_SPI_CONTROL_IRQ_ENABLE);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio spi control");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_SPI0_BAUD,
                                0x0Au);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio spi baud");
    ASSERT_EQ_INT(EZ80_SPI_CONTROL_ENABLE |
                  EZ80_SPI_CONTROL_MASTER |
                  EZ80_SPI_CONTROL_IRQ_ENABLE,
                  emu.hw.spi[0].control,
                  "mmio spi control updates hardware");
    ASSERT_EQ_INT(0x0Au, emu.hw.spi[0].baud_divisor, "mmio spi baud updates hardware");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_GPIO_B_DIR,
                                0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio gpio dir");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_GPIO_B_DATA,
                                0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio gpio data");
    ASSERT_EQ_INT(0xFFu, emu.hw.gpio[1].direction, "mmio gpio direction updates hardware");
    ASSERT_EQ_INT(0xA5u, emu.hw.gpio[1].data, "mmio gpio data updates hardware");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_I2C0_CTL,
                                EZ80_I2C_CTL_ENAB | EZ80_I2C_CTL_IEN);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c ctl");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_I2C0_CCR,
                                0x09u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c ccr");
    ASSERT_EQ_INT(EZ80_I2C_CTL_ENAB | EZ80_I2C_CTL_IEN,
                  emu.hw.i2c[0].control,
                  "mmio i2c control updates hardware");
    ASSERT_EQ_INT(0x09u, emu.hw.i2c[0].clock_control, "mmio i2c ccr updates hardware");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_LCTL,
                                0x03u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart lctl");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_IER,
                                EZ80_UART_IER_RECV | EZ80_UART_IER_THRE);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart ier");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_BRG_LO,
                                0x34u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart brg lo");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_BRG_HI,
                                0x12u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart brg hi");
    ASSERT_EQ_INT(0x03u, emu.hw.uart[0].lctl, "mmio uart lctl updates hardware");
    ASSERT_EQ_INT(EZ80_UART_IER_RECV | EZ80_UART_IER_THRE,
                  emu.hw.uart[0].ier,
                  "mmio uart ier updates hardware");
    ASSERT_EQ_INT(0x1234u, emu.hw.uart[0].brg, "mmio uart brg updates hardware");
}

static void test_mmio_peripheral_data_register_paths(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value = 0u;
    uint8_t i2c_rx[] = { 0x5Au, 0x6Bu };
    uint8_t uart_rx[] = { 0x42u };

    printf("[TEST] MMIO data-register paths for I2C/UART peripherals\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio peripheral data init");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_I2C0_CTL,
                                EZ80_I2C_CTL_ENAB | EZ80_I2C_CTL_IEN);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c data ctl");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_I2C0_SAR,
                                0x52u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c data sar");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_I2C0_XSAR,
                                0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c data xsar");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_I2C0_DATA,
                                0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c data write");
    ASSERT_EQ_INT(0x52u, emu.hw.i2c[0].slave_addr, "mmio i2c sar updates hardware");
    ASSERT_EQ_INT(0x01u, emu.hw.i2c[0].xslave_addr, "mmio i2c xsar updates hardware");
    ASSERT_EQ_INT(1u, emu.hw.i2c[0].tx_count, "mmio i2c data write enqueues TX byte");
    ASSERT_EQ_INT(0xA5u, emu.hw.i2c[0].tx_buf[0], "mmio i2c data write stores payload");
    ASSERT_EQ_INT(EZ80_I2C_SR_DATA_W_ACK, emu.hw.i2c[0].status,
                  "mmio i2c data write updates status");

    status = ez80_emulator_i2c_load_rx(&emu, 0u, i2c_rx, sizeof(i2c_rx));
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c preload rx");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_I2C0_DATA, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio i2c data read");
    ASSERT_EQ_INT(0x5Au, value, "mmio i2c data read returns oldest RX byte");
    ASSERT_EQ_INT(1u, emu.hw.i2c[0].rx_count, "mmio i2c data read consumes one RX byte");
    ASSERT_EQ_INT(1u, emu.hw.i2c[0].total_rx_bytes, "mmio i2c data read updates RX telemetry");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_LCTL,
                                0x03u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart data lctl");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_DATA,
                                0x41u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart data write");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_MCR,
                                0x0Bu);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart data mcr");
    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_SPR,
                                0x77u);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart data spr");
    ASSERT_EQ_INT(1u, emu.hw.uart[0].tx_count, "mmio uart data write enqueues TX byte");
    ASSERT_EQ_INT(0x41u, emu.hw.uart[0].tx_fifo[0], "mmio uart data write stores payload");
    ASSERT_EQ_INT(0x0Bu, emu.hw.uart[0].mcr, "mmio uart mcr updates hardware");
    ASSERT_EQ_INT(0x77u, emu.hw.uart[0].spr, "mmio uart spr updates hardware");

    status = ez80_emulator_uart_load_rx(&emu, 0u, uart_rx, sizeof(uart_rx));
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart preload rx");
    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_DATA, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart data read");
    ASSERT_EQ_INT(0x42u, value, "mmio uart data read returns RX byte");
    ASSERT_EQ_INT(0u, emu.hw.uart[0].rx_count, "mmio uart data read drains RX FIFO");

    status = ez80_memory_write8(&emu,
                                EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_FCTL,
                                EZ80_UART_FCTL_FIFOEN |
                                EZ80_UART_FCTL_CLRRx |
                                EZ80_UART_FCTL_CLRTx);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart data fctl");
    ASSERT_EQ_INT(EZ80_UART_FCTL_FIFOEN |
                  EZ80_UART_FCTL_CLRRx |
                  EZ80_UART_FCTL_CLRTx,
                  emu.hw.uart[0].fctl,
                  "mmio uart fctl updates hardware");
    ASSERT_EQ_INT(0u, emu.hw.uart[0].tx_count, "mmio uart fctl clears TX FIFO");
    ASSERT_EQ_INT(0u, emu.hw.uart[0].rx_count, "mmio uart fctl clears RX FIFO");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_UART0_LSR, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "mmio uart lsr read");
    ASSERT_TRUE((value & EZ80_UART_LSR_THRE) != 0u, "mmio uart lsr reports TX empty after clear");
}

/* ---- Pass 28: Execution trace tests ---- */

static void test_trace_enable_disable(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint32_t count = 0u;

    printf("[TEST] Execution trace enable/disable\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "trace init");

    /* Default: disabled */
    ASSERT_TRUE(!emu.hw.trace_enabled, "trace default disabled");

    /* Enable */
    status = ez80_emulator_trace_enable(&emu, true);
    ASSERT_EQ_INT(EZ80_OK, status, "trace enable");
    ASSERT_TRUE(emu.hw.trace_enabled, "trace enabled");

    /* Count should be 0 */
    status = ez80_emulator_trace_get_count(&emu, &count);
    ASSERT_EQ_INT(EZ80_OK, status, "trace get count");
    ASSERT_EQ_U32(0u, count, "trace count 0");

    /* Disable */
    status = ez80_emulator_trace_enable(&emu, false);
    ASSERT_EQ_INT(EZ80_OK, status, "trace disable");
    ASSERT_TRUE(!emu.hw.trace_enabled, "trace disabled");
}

static void test_trace_records_instructions(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    uint32_t count = 0u;
    ez80_trace_entry_t entry;
    char rom_path[L_tmpnam];

    /* Simple program: LD A,0x42; LD B,0x43; HALT */
    uint8_t rom_bytes[] = {
        0x3E, 0x42,  /* LD A,0x42 */
        0x06, 0x43,  /* LD B,0x43 */
        0x76         /* HALT */
    };

    printf("[TEST] Execution trace records instructions\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create trace ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "trace rec init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "trace rec ROM load");

    /* Enable trace before running */
    ez80_emulator_trace_enable(&emu, true);

    status = ez80_emulator_run_cycles(&emu, 100u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "trace rec run");
    ASSERT_TRUE(run_result.hit_halt, "trace rec halt");

    /* Should have recorded 3 instructions: LD A, LD B, HALT */
    status = ez80_emulator_trace_get_count(&emu, &count);
    ASSERT_EQ_INT(EZ80_OK, status, "trace rec get count");
    ASSERT_EQ_U32(3u, count, "trace rec 3 instructions");

    /* Check first entry: LD A,0x42 at PC=0 */
    status = ez80_emulator_trace_get_entry(&emu, 0u, &entry);
    ASSERT_EQ_INT(EZ80_OK, status, "trace entry 0");
    ASSERT_EQ_U32(0u, entry.pc, "trace entry 0 PC");
    ASSERT_EQ_INT(0x3Eu, entry.opcode, "trace entry 0 opcode");
    ASSERT_EQ_INT(2u, entry.length, "trace entry 0 length");

    /* Check second entry: LD B,0x43 at PC=2 */
    status = ez80_emulator_trace_get_entry(&emu, 1u, &entry);
    ASSERT_EQ_INT(EZ80_OK, status, "trace entry 1");
    ASSERT_EQ_U32(2u, entry.pc, "trace entry 1 PC");
    ASSERT_EQ_INT(0x06u, entry.opcode, "trace entry 1 opcode");

    /* Check third entry: HALT at PC=4 */
    status = ez80_emulator_trace_get_entry(&emu, 2u, &entry);
    ASSERT_EQ_INT(EZ80_OK, status, "trace entry 2");
    ASSERT_EQ_U32(4u, entry.pc, "trace entry 2 PC");
    ASSERT_EQ_INT(0x76u, entry.opcode, "trace entry 2 opcode");

    remove(rom_path);
}

