static void test_trace_ring_buffer_overflow(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    uint32_t count = 0u;
    ez80_trace_entry_t entry;
    char rom_path[L_tmpnam];
    uint8_t rom_bytes[130];
    uint32_t i;

    printf("[TEST] Execution trace ring buffer overflow\n");

    /* Create a program with many NOPs followed by HALT */
    for (i = 0u; i < 129u; i++) rom_bytes[i] = 0x00u; /* NOP */
    rom_bytes[129] = 0x76u; /* HALT */

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create trace overflow ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "trace overflow init");
    ez80_emulator_load_rom(&emu, rom_path);
    ez80_emulator_trace_enable(&emu, true);

    status = ez80_emulator_run_cycles(&emu, 2000u, &run_result);
    ASSERT_EQ_INT(EZ80_OK, status, "trace overflow run");

    ez80_emulator_trace_get_count(&emu, &count);
    /* Should be capped at EZ80_TRACE_BUFFER_SIZE */
    ASSERT_EQ_U32(EZ80_TRACE_BUFFER_SIZE, count, "trace capped at buffer size");

    /* Oldest entry should NOT be PC=0 (it was overwritten) */
    /* The last entry (index count-1) should be the most recent */
    status = ez80_emulator_trace_get_entry(&emu, count - 1u, &entry);
    ASSERT_EQ_INT(EZ80_OK, status, "trace last entry");
    /* Last instruction executed was HALT at PC=129 */
    ASSERT_EQ_INT(0x76u, entry.opcode, "trace last is HALT");

    /* Out of bounds access should fail */
    status = ez80_emulator_trace_get_entry(&emu, count, &entry);
    ASSERT_EQ_INT(EZ80_ERR_OUT_OF_BOUNDS, status, "trace out of bounds");

    remove(rom_path);
}

