/* ---- Pass 28: Memory snapshot/restore tests ---- */

static void test_snapshot_save_restore(void)
{
    static ez80_snapshot_t snap;
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t run_result;
    ez80_cpu_state_t cpu_before;
    ez80_cpu_state_t cpu_after;
    char rom_path[L_tmpnam];

    /* Program: LD A,0x42; LD B,0x99; HALT */
    uint8_t rom_bytes[] = {
        0x3E, 0x42,  /* LD A,0x42 */
        0x06, 0x99,  /* LD B,0x99 */
        0x76         /* HALT */
    };

    printf("[TEST] Memory snapshot save and restore\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "create snapshot ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "snap init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "snap ROM load");

    /* Run to completion */
    ez80_emulator_run_cycles(&emu, 100u, &run_result);
    ASSERT_TRUE(run_result.hit_halt, "snap run halt");

    /* Save snapshot after execution */
    ez80_emulator_get_state(&emu, &cpu_before);
    status = ez80_emulator_snapshot_save(&emu, &snap);
    ASSERT_EQ_INT(EZ80_OK, status, "snap save");
    ASSERT_TRUE(snap.snapshot_id > 0u, "snap id > 0");

    /* Modify state */
    emu.cpu.af = 0u;
    emu.cpu.bc = 0u;
    emu.cpu.pc = 0u;
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x1000u, 0xFFu);

    /* Restore */
    status = ez80_emulator_snapshot_restore(&emu, &snap);
    ASSERT_EQ_INT(EZ80_OK, status, "snap restore");

    ez80_emulator_get_state(&emu, &cpu_after);
    ASSERT_EQ_U32(cpu_before.af, cpu_after.af, "snap restore AF");
    ASSERT_EQ_U32(cpu_before.bc, cpu_after.bc, "snap restore BC");
    ASSERT_EQ_U32(cpu_before.pc, cpu_after.pc, "snap restore PC");

    remove(rom_path);
}

static void test_snapshot_ram_preserved(void)
{
    static ez80_snapshot_t snap;
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] Snapshot preserves RAM content\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "snap ram init");

    /* Write distinctive pattern to RAM */
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x100u, 0xABu);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x200u, 0xCDu);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x300u, 0xEFu);

    /* Save */
    status = ez80_emulator_snapshot_save(&emu, &snap);
    ASSERT_EQ_INT(EZ80_OK, status, "snap ram save");

    /* Overwrite RAM */
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x100u, 0x00u);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x200u, 0x00u);
    ez80_memory_write8(&emu, EZ80_RAM_BASE + 0x300u, 0x00u);

    /* Restore */
    status = ez80_emulator_snapshot_restore(&emu, &snap);
    ASSERT_EQ_INT(EZ80_OK, status, "snap ram restore");

    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x100u, &val);
    ASSERT_EQ_INT(0xABu, val, "snap ram 0x100 restored");
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x200u, &val);
    ASSERT_EQ_INT(0xCDu, val, "snap ram 0x200 restored");
    ez80_memory_read8(&emu, EZ80_RAM_BASE + 0x300u, &val);
    ASSERT_EQ_INT(0xEFu, val, "snap ram 0x300 restored");
}

static void test_snapshot_invalid_args(void)
{
    ez80_emulator_t emu;
    static ez80_snapshot_t snap;
    ez80_status_t status;

    printf("[TEST] Snapshot invalid arguments\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "snap invalid init");

    /* NULL args */
    status = ez80_emulator_snapshot_save(NULL, &snap);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "snap save NULL emu");

    status = ez80_emulator_snapshot_save(&emu, NULL);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "snap save NULL snap");

    status = ez80_emulator_snapshot_restore(NULL, &snap);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "snap restore NULL emu");

    status = ez80_emulator_snapshot_restore(&emu, NULL);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "snap restore NULL snap");

    /* Uninitialized snapshot (id=0) */
    memset(&snap, 0, sizeof(snap));
    status = ez80_emulator_snapshot_restore(&emu, &snap);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "snap restore uninitialized");
}

