static void test_agent_format_cpu_state(void)
{
    ez80_cpu_state_t cpu;
    char buf[1024];
    int len;

    printf("[TEST] Agent format CPU state\n");

    memset(&cpu, 0, sizeof(cpu));
    cpu.pc = 0x020000u;
    cpu.sp = 0xD40000u;
    cpu.af = 0x0044u;
    cpu.bc = 0x001234u;
    cpu.adl_mode = true;
    cpu.iff1 = true;

    len = agent_format_cpu_state(&cpu, buf, sizeof(buf));
    ASSERT_TRUE(len > 0, "agent format cpu len>0");
    ASSERT_TRUE(strstr(buf, "0x020000") != NULL, "agent format cpu has PC");
    ASSERT_TRUE(strstr(buf, "0xD40000") != NULL, "agent format cpu has SP");
    ASSERT_TRUE(strstr(buf, "\"adl\":true") != NULL, "agent format cpu has adl");
    ASSERT_TRUE(strstr(buf, "\"iff1\":true") != NULL, "agent format cpu has iff1");
}

