static void test_agent_execute_ping(void)
{
    ez80_emulator_t emu;
    agent_session_t session;
    agent_command_t cmd;
    char output_buf[4096];
    FILE *output;

    printf("[TEST] Agent execute ping command\n");

    ez80_emulator_init(&emu);

    /* Use tmpfile for output capture */
    output = tmpfile();
    ASSERT_TRUE(output != NULL, "agent exec ping: tmpfile ok");
    if (!output) return;

    agent_session_init(&session, &emu, NULL, output);

    memset(&cmd, 0, sizeof(cmd));
    cmd.type = AGENT_CMD_PING;
    cmd.id = 123;

    agent_execute_command(&session, &cmd);

    /* Read back output */
    fseek(output, 0, SEEK_SET);
    memset(output_buf, 0, sizeof(output_buf));
    fread(output_buf, 1, sizeof(output_buf) - 1, output);
    fclose(output);

    ASSERT_TRUE(strstr(output_buf, "\"status\":\"ok\"") != NULL,
                "agent exec ping: status ok");
    ASSERT_TRUE(strstr(output_buf, "\"id\":123") != NULL,
                "agent exec ping: id=123");
    ASSERT_TRUE(strstr(output_buf, "\"pong\":true") != NULL,
                "agent exec ping: pong=true");
}

