static void test_agent_execute_step(void)
{
    ez80_emulator_t emu;
    agent_session_t session;
    agent_command_t cmd;
    char output_buf[4096];
    char rom_path[L_tmpnam];
    FILE *output;
    ez80_status_t status;
    uint8_t rom_bytes[2] = { 0xF3u, 0x76u };

    printf("[TEST] Agent execute step command\n");

    ASSERT_TRUE(write_temp_file(rom_bytes, sizeof(rom_bytes), rom_path, sizeof(rom_path)),
                "agent exec step: create temp ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "agent exec step: emulator init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "agent exec step: load temp ROM");

    output = tmpfile();
    ASSERT_TRUE(output != NULL, "agent exec step: tmpfile ok");
    if (!output) {
        remove(rom_path);
        return;
    }

    agent_session_init(&session, &emu, NULL, output);

    memset(&cmd, 0, sizeof(cmd));
    cmd.type = AGENT_CMD_STEP;
    cmd.id = 210;

    agent_execute_command(&session, &cmd);

    fseek(output, 0, SEEK_SET);
    memset(output_buf, 0, sizeof(output_buf));
    fread(output_buf, 1, sizeof(output_buf) - 1, output);
    fclose(output);
    remove(rom_path);

    ASSERT_TRUE(strstr(output_buf, "\"status\":\"ok\"") != NULL,
                "agent exec step: status ok");
    ASSERT_TRUE(strstr(output_buf, "\"pc\":\"0x000000\"") != NULL,
                "agent exec step: reports pre-step pc");
    ASSERT_TRUE(strstr(output_buf, "\"next_pc\":\"0x000001\"") != NULL,
                "agent exec step: reports post-step pc");
    ASSERT_TRUE(strstr(output_buf, "\"mnemonic\":\"DI\"") != NULL,
                "agent exec step: mnemonic DI");
}

