static void test_agent_execute_load_8xp(void)
{
    ez80_emulator_t emu;
    agent_session_t session;
    agent_command_t cmd;
    ez80_os_var_info_t info;
    char output_buf[4096];
    char xp_path[L_tmpnam];
    FILE *xp_file = NULL;
    FILE *output;
    uint8_t file_buf[128];
    uint16_t checksum;
    uint16_t data_len;
    size_t pos;
    size_t j;
    uint8_t program_data[] = { 0x3E, 0x42, 0x76 };

    printf("[TEST] Agent execute load_8xp command\n");

    memset(file_buf, 0, sizeof(file_buf));
    memcpy(file_buf, "**TI83F*", 8);
    file_buf[8] = 0x1A;
    file_buf[9] = 0x0A;
    file_buf[10] = 0x00;

    data_len = (uint16_t)(sizeof(program_data) + 2u);
    pos = 55u;
    file_buf[pos++] = 0x0D; file_buf[pos++] = 0x00;
    file_buf[pos++] = (uint8_t)(data_len & 0xFFu);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFFu);
    file_buf[pos++] = 0x05u;
    memcpy(file_buf + pos, "CALCENG\0", 8u); pos += 8u;
    file_buf[pos++] = 0x00u;
    file_buf[pos++] = 0x00u;
    file_buf[pos++] = (uint8_t)(data_len & 0xFFu);
    file_buf[pos++] = (uint8_t)((data_len >> 8) & 0xFFu);
    file_buf[pos++] = (uint8_t)(sizeof(program_data) & 0xFFu);
    file_buf[pos++] = (uint8_t)((sizeof(program_data) >> 8) & 0xFFu);
    memcpy(file_buf + pos, program_data, sizeof(program_data));
    pos += sizeof(program_data);
    file_buf[53] = (uint8_t)((pos - 55u) & 0xFFu);
    file_buf[54] = (uint8_t)(((pos - 55u) >> 8) & 0xFFu);
    checksum = 0u;
    for (j = 55u; j < pos; j++) {
        checksum = (uint16_t)(checksum + file_buf[j]);
    }
    file_buf[pos++] = (uint8_t)(checksum & 0xFFu);
    file_buf[pos++] = (uint8_t)((checksum >> 8) & 0xFFu);

    ASSERT_TRUE(create_temp_path(xp_path, sizeof(xp_path)),
                "agent exec load_8xp create path");
    xp_file = fopen(xp_path, "wb");
    ASSERT_TRUE(xp_file != NULL, "agent exec load_8xp open temp file");
    if (!xp_file) {
        remove(xp_path);
        return;
    }
    fwrite(file_buf, 1u, pos, xp_file);
    fclose(xp_file);

    ez80_emulator_init(&emu);
    emu.rom_loaded = true;

    output = tmpfile();
    ASSERT_TRUE(output != NULL, "agent exec load_8xp: tmpfile ok");
    if (!output) {
        remove(xp_path);
        return;
    }

    agent_session_init(&session, &emu, NULL, output);

    memset(&cmd, 0, sizeof(cmd));
    cmd.type = AGENT_CMD_LOAD_8XP;
    cmd.id = 607;
    strcpy(cmd.str_args[0], xp_path);
    cmd.str_arg_count = 1;
    cmd.int_args[0] = 1u;
    cmd.int_arg_count = 1;
    agent_execute_command(&session, &cmd);

    fseek(output, 0, SEEK_SET);
    memset(output_buf, 0, sizeof(output_buf));
    fread(output_buf, 1, sizeof(output_buf) - 1, output);
    fclose(output);

    remove(xp_path);

    ASSERT_TRUE(strstr(output_buf, "\"entries\":1") != NULL,
                "agent exec load_8xp should report 1 loaded entry");
    ASSERT_EQ_INT(EZ80_OK,
                  ez80_emulator_os_var_get_info(&emu, "CALCENG", EZ80_OS_VAR_PROGRAM, &info),
                  "agent exec load_8xp var info status");
    ASSERT_TRUE(info.exists, "agent exec load_8xp should load CALCENG");
    ASSERT_TRUE(info.archived, "agent exec load_8xp archived flag");
}

