static void test_wdt_basic_configure(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint16_t counter;

    printf("[TEST] Hardware watchdog basic configure\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_basic: init");

    /* Configure watchdog: enabled, reset on timeout, timeout=100 */
    status = ez80_emulator_wdt_configure(&emu,
                                          EZ80_WDT_CONTROL_ENABLE | EZ80_WDT_CONTROL_RESET_ON_TIMEOUT,
                                          100u);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_basic: configure");
    ASSERT_EQ_INT(EZ80_WDT_CONTROL_ENABLE | EZ80_WDT_CONTROL_RESET_ON_TIMEOUT,
                  emu.hw.wdt_control, "wdt_basic: control");
    ASSERT_EQ_INT(100u, emu.hw.wdt_timeout, "wdt_basic: timeout");

    /* Counter should start at 0 */
    status = ez80_emulator_wdt_get_counter(&emu, &counter);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_basic: get_counter");
    ASSERT_EQ_INT(0u, counter, "wdt_basic: counter=0");

    /* Invalid args */
    status = ez80_emulator_wdt_configure(NULL, 0u, 100u);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "wdt_basic: NULL");
    status = ez80_emulator_wdt_configure(&emu, 0u, 0u);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "wdt_basic: zero timeout");
    status = ez80_emulator_wdt_feed(NULL);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "wdt_basic: feed NULL");
    status = ez80_emulator_wdt_get_counter(NULL, &counter);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "wdt_basic: counter NULL emu");
    status = ez80_emulator_wdt_get_counter(&emu, NULL);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "wdt_basic: counter NULL out");
}

static void test_wdt_feed_resets_counter(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint16_t counter;

    printf("[TEST] Watchdog feed resets counter\n");

    ez80_emulator_init(&emu);

    /* Configure and enable */
    ez80_emulator_wdt_configure(&emu,
                                 EZ80_WDT_CONTROL_ENABLE,
                                 1000u);

    /* Manually advance counter */
    emu.hw.wdt_counter = 500u;

    /* Feed */
    status = ez80_emulator_wdt_feed(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_feed: success");

    ez80_emulator_wdt_get_counter(&emu, &counter);
    ASSERT_EQ_INT(0u, counter, "wdt_feed: counter reset to 0");
    ASSERT_EQ_U32(0u, emu.hw.wdt_prescaler_accum, "wdt_feed: prescaler reset");
}

static void test_wdt_timeout_reset(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] Watchdog timeout triggers reset\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_timeout: init");

    emu.rom_loaded = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE + 0x123u;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;

    /* Configure: enabled + reset on timeout, short timeout */
    status = ez80_emulator_wdt_configure(&emu,
                                         EZ80_WDT_CONTROL_ENABLE | EZ80_WDT_CONTROL_RESET_ON_TIMEOUT,
                                         2u);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_timeout: configure");

    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_SLEEP);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_timeout: sleep");

    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 8u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_timeout: run");
    ASSERT_EQ_U32(8u, result.cycles_executed, "wdt_timeout: cycles executed");

    ASSERT_EQ_U32(1u, emu.hw.wdt_reset_count, "wdt_timeout: reset count=1");
    ASSERT_EQ_INT(0u, emu.hw.wdt_counter, "wdt_timeout: counter reset");
    ASSERT_EQ_INT(EZ80_PM_MODE_ACTIVE, emu.hw.pm_mode, "wdt_timeout: wake returns active");
    ASSERT_EQ_INT(EZ80_PM_WAKE_WATCHDOG, emu.hw.pm_wake_source,
                  "wdt_timeout: wake source watchdog");
    ASSERT_EQ_U32(8u, emu.hw.pm_total_sleep_cycles, "wdt_timeout: sleep cycles recorded");
    ASSERT_TRUE(!emu.cpu.halted, "wdt_timeout: cpu resumed");
    ASSERT_EQ_U32(0u, emu.cpu.pc, "wdt_timeout: cpu reset pc");
}

