static void test_pm_mode_api(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t mode;

    printf("[TEST] Power management mode API\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "pm: init");

    /* Default mode is active */
    status = ez80_emulator_pm_get_mode(&emu, &mode);
    ASSERT_EQ_INT(EZ80_OK, status, "pm: get mode");
    ASSERT_EQ_INT(EZ80_PM_MODE_ACTIVE, mode, "pm: default active");

    /* Set idle mode */
    emu.cpu.halted = false;
    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_IDLE);
    ASSERT_EQ_INT(EZ80_OK, status, "pm: set idle");
    ez80_emulator_pm_get_mode(&emu, &mode);
    ASSERT_EQ_INT(EZ80_PM_MODE_IDLE, mode, "pm: idle");
    ASSERT_TRUE(emu.cpu.halted, "pm: idle halts CPU");

    /* Set standby — halts CPU */
    emu.cpu.halted = false;
    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_STANDBY);
    ASSERT_EQ_INT(EZ80_OK, status, "pm: set standby");
    ASSERT_TRUE(emu.cpu.halted, "pm: standby halts CPU");
    ASSERT_EQ_U32(1u, emu.hw.pm_sleep_count, "pm: sleep count=1");

    /* Set sleep — also halts */
    emu.cpu.halted = false;
    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_SLEEP);
    ASSERT_EQ_INT(EZ80_OK, status, "pm: set sleep");
    ASSERT_TRUE(emu.cpu.halted, "pm: sleep halts CPU");
    ASSERT_EQ_U32(2u, emu.hw.pm_sleep_count, "pm: sleep count=2");

    /* Back to active */
    emu.hw.pm_wake_source = EZ80_PM_WAKE_TIMER;
    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_ACTIVE);
    ASSERT_EQ_INT(EZ80_OK, status, "pm: back to active");
    ASSERT_TRUE(!emu.cpu.halted, "pm: active resumes CPU");
    ASSERT_EQ_INT(EZ80_PM_WAKE_NONE, emu.hw.pm_wake_source, "pm: active clears wake source");

    /* Invalid args */
    status = ez80_emulator_pm_set_mode(NULL, EZ80_PM_MODE_ACTIVE);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "pm: NULL emu");
    status = ez80_emulator_pm_set_mode(&emu, 99u);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "pm: invalid mode");
    status = ez80_emulator_pm_get_mode(NULL, &mode);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "pm: get NULL emu");
    status = ez80_emulator_pm_get_mode(&emu, NULL);
    ASSERT_EQ_INT(EZ80_ERR_INVALID_ARG, status, "pm: get NULL out");
}

