static void test_pm_mmio_mode_write_authoritative(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val;

    printf("[TEST] Power management MMIO mode writes are authoritative\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_mmio_mode: init");

    status = ez80_memory_write8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_PM_MODE, EZ80_PM_MODE_STANDBY);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_mmio_mode: write standby");
    ASSERT_EQ_INT(EZ80_PM_MODE_STANDBY, emu.hw.pm_mode, "pm_mmio_mode: standby mode");
    ASSERT_TRUE(emu.cpu.halted, "pm_mmio_mode: standby halts cpu");
    ASSERT_EQ_U32(1u, emu.hw.pm_sleep_count, "pm_mmio_mode: sleep count increments");

    status = ez80_memory_write8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_PM_MODE, EZ80_PM_MODE_ACTIVE);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_mmio_mode: write active");
    ASSERT_EQ_INT(EZ80_PM_MODE_ACTIVE, emu.hw.pm_mode, "pm_mmio_mode: active mode");
    ASSERT_TRUE(!emu.cpu.halted, "pm_mmio_mode: active resumes cpu");

    status = ez80_memory_write8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_PM_MODE, 99u);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_mmio_mode: invalid write ignored");
    ASSERT_EQ_INT(EZ80_PM_MODE_ACTIVE, emu.hw.pm_mode, "pm_mmio_mode: invalid write keeps mode");

    status = ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_PM_MODE, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_mmio_mode: read mode");
    ASSERT_EQ_INT(EZ80_PM_MODE_ACTIVE, val, "pm_mmio_mode: readback active");
}

static void test_pm_idle_timer_wake_transition(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] Power management idle wake on timer IRQ\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_idle_wake: init");

    emu.rom_loaded = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.cpu.iff1 = true;
    emu.cpu.iff2 = true;
    emu.interrupts_enabled_in_emulator = true;
    emu.hw.irq_mask = EZ80_IRQ_SOURCE_TIMER0;
    emu.hw.timer0_control = EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE;
    emu.hw.timer0_counter = 0xFFFEu;
    emu.hw.timer0_reload = 0u;
    emu.hw.timer0_prescaler = EZ80_TIMER_PRESCALER_1;
    emu.hw.timer0_prescaler_accum = 0u;

    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_IDLE);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_idle_wake: set idle");

    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 17u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_idle_wake: run");
    ASSERT_EQ_U32(17u, result.cycles_executed, "pm_idle_wake: cycles executed");
    ASSERT_EQ_U32(1u, emu.hw.total_interrupts_serviced, "pm_idle_wake: timer IRQ serviced");
    ASSERT_EQ_INT(EZ80_PM_MODE_ACTIVE, emu.hw.pm_mode, "pm_idle_wake: active after wake");
    ASSERT_EQ_INT(EZ80_PM_WAKE_TIMER, emu.hw.pm_wake_source, "pm_idle_wake: timer wake source");
    ASSERT_TRUE(!emu.cpu.halted, "pm_idle_wake: cpu resumed");
    ASSERT_EQ_U32(0x0038u, emu.cpu.pc & 0xFFFFFFu, "pm_idle_wake: pc at IM1 vector");
}

static void test_pm_sleep_blocks_timer_and_usb_but_advances_watchdog(void)
{
    ez80_emulator_t emu;
    ez80_run_result_t result;
    ez80_status_t status;

    printf("[TEST] Power management sleep gates timer/USB but advances watchdog\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_sleep_gate: init");

    emu.rom_loaded = true;
    emu.cpu.pc = TEST_RAM_EXEC_BASE;
    emu.cpu.sp = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.hw.timer0_control = EZ80_TIMER_CONTROL_ENABLE | EZ80_TIMER_CONTROL_IRQ_ENABLE;
    emu.hw.timer0_counter = 0xFFFEu;
    emu.hw.timer0_reload = 0u;
    emu.hw.timer0_prescaler = EZ80_TIMER_PRESCALER_1;
    status = ez80_emulator_wdt_configure(&emu, EZ80_WDT_CONTROL_ENABLE, 100u);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_sleep_gate: configure watchdog");
    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_USB_CONTROL,
                                EZ80_USB_CONTROL_ENABLE | EZ80_USB_CONTROL_TX_IRQ_ENABLE);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_sleep_gate: enable usb");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_USB_TX, 0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_sleep_gate: queue usb tx");

    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_SLEEP);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_sleep_gate: set sleep");

    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 4u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "pm_sleep_gate: run");
    ASSERT_EQ_U32(4u, result.cycles_executed, "pm_sleep_gate: cycles executed");
    ASSERT_TRUE(result.hit_halt, "pm_sleep_gate: cpu remains halted");
    ASSERT_EQ_INT(0xFFFEu, emu.hw.timer0_counter, "pm_sleep_gate: timer paused");
    ASSERT_EQ_U32(1u, emu.hw.usb_tx_count, "pm_sleep_gate: usb tx not drained");
    ASSERT_EQ_U32(1u, emu.hw.usb_total_tx_bytes, "pm_sleep_gate: usb byte still queued");
    ASSERT_EQ_INT(1u, emu.hw.wdt_counter, "pm_sleep_gate: watchdog advanced");
    ASSERT_EQ_INT(EZ80_PM_MODE_SLEEP, emu.hw.pm_mode, "pm_sleep_gate: still sleeping");
    ASSERT_EQ_U32(4u, emu.hw.pm_total_sleep_cycles, "pm_sleep_gate: sleep cycles tracked");
}

static void test_wdt_port_io(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t value;

    printf("[TEST] Watchdog port I/O\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: init");

    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_WDT_TIMEOUT_LO, 0x50u);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: write timeout_lo");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_WDT_TIMEOUT_HI, 0x01u);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: write timeout_hi");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_WDT_CONTROL, EZ80_WDT_CONTROL_ENABLE);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: write control");
    ASSERT_TRUE((emu.hw.wdt_control & EZ80_WDT_CONTROL_ENABLE) != 0u,
                "wdt_port: enabled via port");
    ASSERT_EQ_INT(0x50u, emu.hw.wdt_timeout & 0xFFu, "wdt_port: timeout_lo");
    ASSERT_EQ_INT(0x0150u, emu.hw.wdt_timeout, "wdt_port: timeout=0x150");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_WDT_CONTROL, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: read control");
    ASSERT_EQ_INT(EZ80_WDT_CONTROL_ENABLE, value, "wdt_port: control readback");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_WDT_TIMEOUT_LO, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: read timeout_lo");
    ASSERT_EQ_INT(0x50u, value, "wdt_port: timeout_lo readback");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_WDT_TIMEOUT_HI, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: read timeout_hi");
    ASSERT_EQ_INT(0x01u, value, "wdt_port: timeout_hi readback");

    /* Feed via magic byte */
    emu.hw.wdt_counter = 100u;
    emu.hw.wdt_prescaler_accum = 3u;
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_WDT_FEED, EZ80_WDT_FEED_MAGIC);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_port: write feed");
    ASSERT_EQ_INT(0u, emu.hw.wdt_counter, "wdt_port: feed resets counter");
    ASSERT_EQ_U32(0u, emu.hw.wdt_prescaler_accum, "wdt_port: feed resets prescaler");
}

