    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_ALARM_SECONDS, 30u);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_port: write seconds");
    status = ez80_memory_write8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_ALARM_MINUTES, 15u);
