    ASSERT_EQ_INT(30u, emu.hw.rtc_alarm_seconds, "rtc_port: seconds");
    ASSERT_EQ_INT(15u, emu.hw.rtc_alarm_minutes, "rtc_port: minutes");
    ASSERT_EQ_INT(8u, emu.hw.rtc_alarm_hours, "rtc_port: hours");
    ASSERT_TRUE((emu.hw.rtc_alarm_control & EZ80_RTC_ALARM_CONTROL_ENABLE) != 0u,
                "rtc_port: enabled");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_ALARM_SECONDS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_port: read seconds");
    ASSERT_EQ_INT(30u, value, "rtc_port: seconds readback");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_ALARM_MINUTES, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_port: read minutes");
    ASSERT_EQ_INT(15u, value, "rtc_port: minutes readback");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_ALARM_HOURS, &value);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_port: read hours");
    ASSERT_EQ_INT(8u, value, "rtc_port: hours readback");
    status = ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_RTC_ALARM_CONTROL, &value);
