static void test_uart_thre_temt_lsr_bits(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t lsr;

    printf("[TEST] UART THRE and TEMT LSR bits: idle vs. TX-occupied\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_thre: init");

    status = ez80_emulator_uart_configure(&emu, 0u, EZ80_UART_LCTL_CHAR_MASK, 9600u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_thre: configure");

    /* Initially TX FIFO is empty: THRE=1 (TX can accept data), TEMT=1 (shift idle) */
    status = ez80_emulator_uart_get_lsr(&emu, 0u, &lsr);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_thre: get lsr initial");
    ASSERT_TRUE((lsr & EZ80_UART_LSR_THRE) != 0u,
                "uart_thre: THRE=1 initially (TX empty)");
    ASSERT_TRUE((lsr & EZ80_UART_LSR_TEMT) != 0u,
                "uart_thre: TEMT=1 initially (TX idle)");
    ASSERT_TRUE((lsr & EZ80_UART_LSR_DR) == 0u,
                "uart_thre: DR=0 initially (RX empty)");

    /* After one TX write: tx_count=1 → THRE=0, TEMT=0 */
    status = ez80_emulator_uart_write(&emu, 0u, 0x41u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_thre: write byte");
    ASSERT_EQ_INT(1, (int)emu.hw.uart[0].tx_count, "uart_thre: tx_count=1");

    status = ez80_emulator_uart_get_lsr(&emu, 0u, &lsr);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_thre: get lsr after write");
    ASSERT_TRUE((lsr & EZ80_UART_LSR_THRE) == 0u,
                "uart_thre: THRE=0 when TX FIFO occupied");
    ASSERT_TRUE((lsr & EZ80_UART_LSR_TEMT) == 0u,
                "uart_thre: TEMT=0 when TX FIFO occupied");

    /* total_tx_bytes accumulates on each write */
    ASSERT_EQ_U32(1u, emu.hw.uart[0].total_tx_bytes,
                  "uart_thre: total_tx_bytes=1 after one write");

    /* Two more writes — total should be 3 */
    ez80_emulator_uart_write(&emu, 0u, 0x42u);
    ez80_emulator_uart_write(&emu, 0u, 0x43u);
    ASSERT_EQ_U32(3u, emu.hw.uart[0].total_tx_bytes,
                  "uart_thre: total_tx_bytes=3 after three writes");
    ASSERT_EQ_INT(3, (int)emu.hw.uart[0].tx_count, "uart_thre: tx_count=3");
}

static void test_uart_spr_scratchpad_port_io(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] UART SPR scratchpad register: ch0 and ch1 independent\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_spr: init");

    /* Write distinct value to UART0 SPR */
    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_UART0_SPR,
                                0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_spr: write ch0 0xA5");

    status = ez80_memory_read8(&emu,
                               EZ80_PORT_BASE + EZ80_PORT_UART0_SPR,
                               &val);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_spr: read ch0 after write");
    ASSERT_EQ_INT(0xA5, (int)val, "uart_spr: ch0 SPR stores 0xA5");

    /* Overwrite with different value */
    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_UART0_SPR,
                                0x5Au);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_spr: overwrite ch0 0x5A");
    ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_UART0_SPR, &val);
    ASSERT_EQ_INT(0x5A, (int)val, "uart_spr: ch0 SPR overwrite to 0x5A");

    /* Write to UART1 SPR — must not alias UART0 SPR */
    status = ez80_memory_write8(&emu,
                                EZ80_PORT_BASE + EZ80_PORT_UART1_SPR,
                                0xBBu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart_spr: write ch1 0xBB");
    ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_UART1_SPR, &val);
    ASSERT_EQ_INT(0xBB, (int)val, "uart_spr: ch1 SPR stores 0xBB");

    /* UART0 SPR must remain 0x5A after writing UART1 */
    ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_UART0_SPR, &val);
    ASSERT_EQ_INT(0x5A, (int)val, "uart_spr: ch0 SPR not contaminated by ch1 write");

    /* UART1 SPR still 0xBB after reading UART0 */
    ez80_memory_read8(&emu, EZ80_PORT_BASE + EZ80_PORT_UART1_SPR, &val);
    ASSERT_EQ_INT(0xBB, (int)val, "uart_spr: ch1 SPR unaffected by ch0 read");
}

static void test_spi_n_transfers_count_accumulation(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t rx = 0u;
    uint32_t i;

    printf("[TEST] SPI transfer_complete_count accumulates over N transfers\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "spi_acc: init");

    status = ez80_emulator_spi_configure(&emu, 0u,
                                          EZ80_SPI_CONTROL_ENABLE |
                                          EZ80_SPI_CONTROL_MASTER,
                                          2u);
    ASSERT_EQ_INT(EZ80_OK, status, "spi_acc: configure ch0");

    /* Verify clean state before any transfers */
    ASSERT_EQ_U32(0u, emu.hw.spi[0].transfer_complete_count, "spi_acc: count=0 initially");
    ASSERT_EQ_U32(0u, emu.hw.spi[0].total_tx_bytes, "spi_acc: tx_bytes=0 initially");
    ASSERT_EQ_U32(0u, emu.hw.spi[0].total_rx_bytes, "spi_acc: rx_bytes=0 initially");

    /* Perform 6 loopback transfers (no preloaded RX → returns 0xFF each time) */
    for (i = 0u; i < 6u; i++) {
        status = ez80_emulator_spi_transfer(&emu, 0u, (uint8_t)(0x10u + i), &rx);
        ASSERT_EQ_INT(EZ80_OK, status, "spi_acc: transfer ok");
        ASSERT_EQ_INT(0xFF, (int)rx, "spi_acc: loopback rx=0xFF");
    }

    ASSERT_EQ_U32(6u, emu.hw.spi[0].transfer_complete_count,
                  "spi_acc: transfer_complete_count=6");
    ASSERT_EQ_U32(6u, emu.hw.spi[0].total_tx_bytes,
                  "spi_acc: total_tx_bytes=6");
    ASSERT_EQ_U32(6u, emu.hw.spi[0].total_rx_bytes,
                  "spi_acc: total_rx_bytes=6");

    /* Last TX byte should be 0x15 (0x10 + 5) */
    ASSERT_EQ_INT(0x15, (int)emu.hw.spi[0].last_tx_byte,
                  "spi_acc: last_tx_byte=0x15");
}

static void test_i2c_dual_channel_slave_addr_independence(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t sr0 = 0u, sr1 = 0u;
    uint8_t data = 0u;
    uint8_t preload0[] = { 0xAAu };
    uint8_t preload1[] = { 0x55u };

    printf("[TEST] I2C ch0 and ch1 slave addresses are fully independent\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c_dual: init");

    ez80_emulator_i2c_configure(&emu, 0u, EZ80_I2C_CTL_ENAB, 0x04u);
    ez80_emulator_i2c_configure(&emu, 1u, EZ80_I2C_CTL_ENAB, 0x08u);

    /* Start ch0 in write mode to address 0x50.
     * I2C hardware stores the 8-bit bus format: 7-bit addr << 1 | R/W bit.
     * write = 0  → slave_addr = 0x50 << 1 | 0 = 0xA0 */
    status = ez80_emulator_i2c_start(&emu, 0u, 0x50u, false);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c_dual: ch0 start write 0x50");
    ASSERT_EQ_INT(0xA0u, emu.hw.i2c[0].slave_addr, "i2c_dual: ch0 slave_addr=0x50");

    /* Start ch1 in read mode to address 0x72.
     * read = 1  → slave_addr = 0x72 << 1 | 1 = 0xE5 */
    ez80_emulator_i2c_load_rx(&emu, 1u, preload1, 1u);
    status = ez80_emulator_i2c_start(&emu, 1u, 0x72u, true);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c_dual: ch1 start read 0x72");
    ASSERT_EQ_INT(0xE5u, emu.hw.i2c[1].slave_addr, "i2c_dual: ch1 slave_addr=0x72");

    /* Verify ch0 slave_addr was NOT changed by ch1's start */
    ASSERT_EQ_INT(0xA0u, emu.hw.i2c[0].slave_addr,
                  "i2c_dual: ch0 slave_addr unchanged after ch1 start");

    /* Write a byte via ch0 */
    status = ez80_emulator_i2c_write(&emu, 0u, 0xABu);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c_dual: ch0 write byte");
    ez80_emulator_i2c_get_status(&emu, 0u, &sr0);
    ASSERT_EQ_INT(EZ80_I2C_SR_DATA_W_ACK, sr0, "i2c_dual: ch0 status W_ACK");

    /* Read a byte via ch1 — must not affect ch0's status */
    status = ez80_emulator_i2c_read(&emu, 1u, &data, true);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c_dual: ch1 read byte");
    ASSERT_EQ_INT(0x55u, data, "i2c_dual: ch1 preloaded byte");

    /* ch0 status still DATA_W_ACK */
    ez80_emulator_i2c_get_status(&emu, 0u, &sr0);
    ASSERT_EQ_INT(EZ80_I2C_SR_DATA_W_ACK, sr0, "i2c_dual: ch0 status unaffected by ch1 read");

    /* ch0 total_tx=1, ch1 total_rx=1 — independent counters */
    ASSERT_EQ_U32(1u, emu.hw.i2c[0].total_tx_bytes, "i2c_dual: ch0 tx=1");
    ASSERT_EQ_U32(1u, emu.hw.i2c[1].total_rx_bytes, "i2c_dual: ch1 rx=1");
    ASSERT_EQ_U32(0u, emu.hw.i2c[1].total_tx_bytes, "i2c_dual: ch1 tx=0");
    ASSERT_EQ_U32(0u, emu.hw.i2c[0].total_rx_bytes, "i2c_dual: ch0 rx=0");

    /* Stop both channels */
    ez80_emulator_i2c_stop(&emu, 0u);
    ez80_emulator_i2c_stop(&emu, 1u);
    ez80_emulator_i2c_get_status(&emu, 0u, &sr0);
    ez80_emulator_i2c_get_status(&emu, 1u, &sr1);
    ASSERT_EQ_INT(EZ80_I2C_SR_IDLE, sr0, "i2c_dual: ch0 idle after stop");
    ASSERT_EQ_INT(EZ80_I2C_SR_IDLE, sr1, "i2c_dual: ch1 idle after stop");
    (void)preload0;
}

static void test_gpio_port_e_power_port_io(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] GPIO port E (power/charging port) basic I/O\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_porte: init");

    /* Port E is the power button / charging port (EZ80_GPIO_POWER_PORT = 4).
     * By default it is all-input (direction=0). Set bits 2-7 as output
     * while leaving bits 0 (power button) and 1 (charging status) as input
     * so we do not interfere with peripheral semantics. */
    status = ez80_emulator_gpio_set_direction(&emu, EZ80_GPIO_POWER_PORT, 0xFCu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_porte: set direction");
    ASSERT_EQ_INT(0xFCu, emu.hw.gpio[EZ80_GPIO_POWER_PORT].direction,
                  "gpio_porte: direction=0xFC");

    /* Write a pattern to the output bits */
    status = ez80_emulator_gpio_write(&emu, EZ80_GPIO_POWER_PORT, 0x5Cu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_porte: write 0x5C");

    /* Read back: output bits (0xFC mask) should reflect written value */
    status = ez80_emulator_gpio_read(&emu, EZ80_GPIO_POWER_PORT, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_porte: read after write");
    ASSERT_EQ_INT(0x5Cu & 0xFCu, (int)(val & 0xFCu),
                  "gpio_porte: output bits match written value");

    /* Overwrite with all-zeros on output bits */
    ez80_emulator_gpio_write(&emu, EZ80_GPIO_POWER_PORT, 0x00u);
    ez80_emulator_gpio_read(&emu, EZ80_GPIO_POWER_PORT, &val);
    ASSERT_EQ_INT(0, (int)(val & 0xFCu),
                  "gpio_porte: output bits cleared");

    /* MMIO register for port E data should reflect state */
    ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_GPIO_E_DATA, &val);
    ASSERT_EQ_INT(0, (int)(val & 0xFCu),
                  "gpio_porte: MMIO E data=0 after clear");

    /* Verify port E does not alias port D (backlight port, index 3) */
    {
        uint8_t portd_val = 0u;
        ez80_emulator_gpio_write(&emu, EZ80_GPIO_POWER_PORT, 0xA0u);
        ez80_emulator_gpio_read(&emu, 3u, &portd_val);
        ez80_emulator_gpio_read(&emu, EZ80_GPIO_POWER_PORT, &val);
        ASSERT_EQ_INT(0xA0u & 0xFCu, (int)(val & 0xFCu),
                      "gpio_porte: E output correct after write");
        ASSERT_TRUE((portd_val & 0x20u) != 0u,
                    "gpio_porte: port D backlight bit unaffected by port E write");
    }
}

static void test_gpio_port_f_non_usb_bits(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] GPIO port F non-USB bits as general-purpose output\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_portf: init");

    /* Port F = EZ80_GPIO_USB_PORT (index 5).
     * Bit 0 = USB detect (EZ80_GPIO_USB_DETECT_BIT), alt0-controlled.
     * Bits 1-7 are unreserved general-purpose outputs in the stub. */
    status = ez80_emulator_gpio_set_direction(&emu, EZ80_GPIO_USB_PORT, 0xFEu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_portf: set direction bits 1-7 output");
    ASSERT_EQ_INT(0xFEu, emu.hw.gpio[EZ80_GPIO_USB_PORT].direction,
                  "gpio_portf: direction register");

    /* Write pattern to bits 1-7 */
    status = ez80_emulator_gpio_write(&emu, EZ80_GPIO_USB_PORT, 0xB4u);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_portf: write 0xB4 to port F");

    /* Read back the output bits (mask out bit 0 which is alt-controlled) */
    status = ez80_emulator_gpio_read(&emu, EZ80_GPIO_USB_PORT, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_portf: read after write");
    ASSERT_EQ_INT(0xB4u & 0xFEu, (int)(val & 0xFEu),
                  "gpio_portf: bits 1-7 reflect written value");

    /* MMIO register for port F data */
    ez80_memory_read8(&emu, EZ80_MMIO_BASE + EZ80_MMIO_REG_GPIO_F_DATA, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio_portf: MMIO F read");
    ASSERT_EQ_INT(0xB4u & 0xFEu, (int)(val & 0xFEu),
                  "gpio_portf: MMIO port F data bits 1-7");

    /* Overwrite and verify port E (index 4) is not aliased */
    {
        uint8_t porte_val = 0u;
        ez80_emulator_gpio_set_direction(&emu, EZ80_GPIO_POWER_PORT, 0xFFu);
        ez80_emulator_gpio_write(&emu, EZ80_GPIO_POWER_PORT, 0x3Cu);
        ez80_emulator_gpio_write(&emu, EZ80_GPIO_USB_PORT, 0x00u);
        ez80_emulator_gpio_read(&emu, EZ80_GPIO_POWER_PORT, &porte_val);
        ASSERT_EQ_INT(0x3Cu, (int)porte_val,
                      "gpio_portf: port E unchanged by port F write");
    }
}

static void test_snapshot_port_space_high_preserved(void)
{
    static ez80_snapshot_t snap;
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t val = 0u;

    printf("[TEST] Snapshot: high port_space entries preserved\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "snap_hps: init");

    /* Write known values directly to port_space (bypasses MMIO routing which
     * would route UART port addresses through the UART hardware model instead
     * of updating port_space[]. The snapshot saves/restores port_space[]
     * directly, so we write to port_space[] directly here too.) */
    emu.memory.port_space[EZ80_PORT_UART0_SPR] = 0xC7u;
    emu.memory.port_space[EZ80_PORT_UART1_SPR] = 0x3Eu;

    /* Save snapshot */
    status = ez80_emulator_snapshot_save(&emu, &snap);
    ASSERT_EQ_INT(EZ80_OK, status, "snap_hps: save");
    ASSERT_TRUE(snap.snapshot_id > 0u, "snap_hps: snapshot_id > 0");

    /* Snapshot struct should hold the saved values */
    ASSERT_EQ_INT(0xC7, (int)snap.port_space[EZ80_PORT_UART0_SPR],
                  "snap_hps: snap.port_space[UART0_SPR] = 0xC7");
    ASSERT_EQ_INT(0x3E, (int)snap.port_space[EZ80_PORT_UART1_SPR],
                  "snap_hps: snap.port_space[UART1_SPR] = 0x3E");

    /* Corrupt the port_space in emulator */
    emu.memory.port_space[EZ80_PORT_UART0_SPR] = 0xFFu;
    emu.memory.port_space[EZ80_PORT_UART1_SPR] = 0x00u;

    /* Restore and verify recovery via direct struct read */
    status = ez80_emulator_snapshot_restore(&emu, &snap);
    ASSERT_EQ_INT(EZ80_OK, status, "snap_hps: restore");

    val = emu.memory.port_space[EZ80_PORT_UART0_SPR];
    ASSERT_EQ_INT(0xC7, (int)val, "snap_hps: UART0 SPR restored to 0xC7");
    val = emu.memory.port_space[EZ80_PORT_UART1_SPR];
    ASSERT_EQ_INT(0x3E, (int)val, "snap_hps: UART1 SPR restored to 0x3E");
}

static void test_dma_all_three_channels_sequential(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    uint8_t st0, st1, st2;
    uint32_t bt0, bt1, bt2;
    uint32_t i;
    uint32_t src0, dst0, src1, dst1, src2, dst2;

    printf("[TEST] DMA: all three channels transfer distinct patterns sequentially\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: init");
    emu.rom_loaded = true;

    /* Non-overlapping RAM regions for each channel's source and destination */
    src0 = EZ80_RAM_BASE + 0x20000u;
    dst0 = EZ80_RAM_BASE + 0x21000u;
    src1 = EZ80_RAM_BASE + 0x22000u;
    dst1 = EZ80_RAM_BASE + 0x23000u;
    src2 = EZ80_RAM_BASE + 0x24000u;
    dst2 = EZ80_RAM_BASE + 0x25000u;

    /* Initialise source patterns */
    for (i = 0u; i < 8u; i++) {
        ez80_memory_write8(&emu, src0 + i, (uint8_t)(0xA0u + i));
        ez80_memory_write8(&emu, src1 + i, (uint8_t)(0xB0u + i));
        ez80_memory_write8(&emu, src2 + i, (uint8_t)(0xC0u + i));
    }

    /* Configure and run channel 0 */
    status = ez80_emulator_dma_configure(&emu, 0u, src0, dst0, 8u,
                                          EZ80_DMA_CONTROL_ENABLE |
                                          EZ80_DMA_CONTROL_SRC_INC |
                                          EZ80_DMA_CONTROL_DST_INC);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch0 configure");
    status = ez80_emulator_dma_start(&emu, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch0 start");
    status = ez80_emulator_dma_get_status(&emu, 0u, &st0, &bt0);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch0 status");
    ASSERT_EQ_U32(8u, bt0, "dma3: ch0 transferred 8 bytes");

    /* Configure and run channel 1 */
    status = ez80_emulator_dma_configure(&emu, 1u, src1, dst1, 8u,
                                          EZ80_DMA_CONTROL_ENABLE |
                                          EZ80_DMA_CONTROL_SRC_INC |
                                          EZ80_DMA_CONTROL_DST_INC);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch1 configure");
    status = ez80_emulator_dma_start(&emu, 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch1 start");
    status = ez80_emulator_dma_get_status(&emu, 1u, &st1, &bt1);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch1 status");
    ASSERT_EQ_U32(8u, bt1, "dma3: ch1 transferred 8 bytes");

    /* Configure and run channel 2 */
    status = ez80_emulator_dma_configure(&emu, 2u, src2, dst2, 8u,
                                          EZ80_DMA_CONTROL_ENABLE |
                                          EZ80_DMA_CONTROL_SRC_INC |
                                          EZ80_DMA_CONTROL_DST_INC);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch2 configure");
    status = ez80_emulator_dma_start(&emu, 2u);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch2 start");
    status = ez80_emulator_dma_get_status(&emu, 2u, &st2, &bt2);
    ASSERT_EQ_INT(EZ80_OK, status, "dma3: ch2 status");
    ASSERT_EQ_U32(8u, bt2, "dma3: ch2 transferred 8 bytes");

    /* Verify each destination contains the correct pattern */
    for (i = 0u; i < 8u; i++) {
        uint8_t v0 = 0u, v1 = 0u, v2 = 0u;
        ez80_memory_read8(&emu, dst0 + i, &v0);
        ez80_memory_read8(&emu, dst1 + i, &v1);
        ez80_memory_read8(&emu, dst2 + i, &v2);
        ASSERT_EQ_INT((int)(0xA0u + i), (int)v0, "dma3: ch0 dst byte correct");
        ASSERT_EQ_INT((int)(0xB0u + i), (int)v1, "dma3: ch1 dst byte correct");
        ASSERT_EQ_INT((int)(0xC0u + i), (int)v2, "dma3: ch2 dst byte correct");
    }

    /* Verify global dma_total_transfers accumulated all three */
    ASSERT_EQ_U32(3u, emu.hw.dma_total_transfers, "dma3: global total_transfers=3");
}

static void test_rtc_alarm_refire_after_clear_reenable(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    ez80_run_result_t result;
    bool fired = false;
    uint8_t fire_count_lo = 0u;

    printf("[TEST] RTC alarm fires twice when cleared and re-enabled\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: init");

    /* Prepare for run_cycles: rom_loaded, valid PC/SP in RAM exec range */
    emu.rom_loaded = true;
    emu.cpu.pc     = TEST_RAM_EXEC_BASE;
    emu.cpu.sp     = TEST_RAM_EXEC_BASE + 0x1000u;

    /* ── First fire ────────────────────────────────────────── */
    /* RTC at t=0, alarm at 00:00:01 (1 second of day) */
    emu.hw.rtc_cycle_accumulator = 0u;
    emu.hw.rtc_seconds_of_day    = 0u;
    status = ez80_emulator_rtc_alarm_set(&emu, 0u, 0u, 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: set alarm 1s");
    emu.hw.rtc_alarm_control |= EZ80_RTC_ALARM_CONTROL_IRQ_ENABLE;
    status = ez80_emulator_rtc_alarm_enable(&emu, true);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: enable first time");

    /* Put in STANDBY so run_cycles ticks the RTC without executing code.
     * 32768 cycles = one RTC tick (one second). Time advances to 1s = alarm. */
    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_STANDBY);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: standby first");

    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 32768u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: run first");

    status = ez80_emulator_rtc_alarm_get_status(&emu, &fired);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: get status first fire");
    ASSERT_TRUE(fired, "rtc_refire: alarm fired first time");
    ASSERT_EQ_U32(1u, emu.hw.rtc_alarm_fire_count, "rtc_refire: fire_count=1");

    /* ── Disable and re-arm ────────────────────────────────── */
    status = ez80_emulator_rtc_alarm_enable(&emu, false);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: disable");
    emu.hw.rtc_alarm_fired = false;

    /* ── Second fire ───────────────────────────────────────── */
    /* RTC is now at 1s. Set alarm to 2s (one more tick). */
    emu.hw.rtc_cycle_accumulator = 0u;
    status = ez80_emulator_rtc_alarm_set(&emu, 0u, 0u, 2u);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: set alarm 2s");
    emu.hw.rtc_alarm_control |= EZ80_RTC_ALARM_CONTROL_IRQ_ENABLE;
    status = ez80_emulator_rtc_alarm_enable(&emu, true);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: enable second time");

    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_STANDBY);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: standby second");

    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 32768u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: run second");

    status = ez80_emulator_rtc_alarm_get_status(&emu, &fired);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc_refire: get status second fire");
    ASSERT_TRUE(fired, "rtc_refire: alarm fired second time");
    ASSERT_EQ_U32(2u, emu.hw.rtc_alarm_fire_count, "rtc_refire: fire_count=2");

    /* Verify MMIO fire-count register reflects cumulative count */
    ez80_memory_read8(&emu,
                      EZ80_MMIO_BASE + EZ80_MMIO_REG_RTC_ALARM_FIRE_COUNT,
                      &fire_count_lo);
    ASSERT_EQ_INT(2, (int)fire_count_lo, "rtc_refire: MMIO fire_count=2");
}

static void test_wdt_counter_advances_in_active_mode(void)
{
    ez80_emulator_t emu;
    ez80_status_t status;
    ez80_run_result_t result;
    uint16_t counter_before = 0u, counter_after = 0u;
    char rom_path[L_tmpnam];

    /* NOP sled: 100 NOP instructions so we have cycles to run */
    uint8_t nops[102];
    uint32_t i;
    for (i = 0u; i < 100u; i++) {
        nops[i] = 0x00u; /* NOP */
    }
    nops[100] = 0x76u; /* HALT */
    nops[101] = 0x00u; /* padding */

    printf("[TEST] WDT counter advances during run_cycles in active mode\n");

    ASSERT_TRUE(write_temp_file(nops, sizeof(nops), rom_path, sizeof(rom_path)),
                "wdt_active: write ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_active: init");
    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_active: load rom");

    /* Configure WDT with a very long timeout so it won't fire */
    status = ez80_emulator_wdt_configure(&emu,
                                          EZ80_WDT_CONTROL_ENABLE,
                                          60000u);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_active: configure");

    /* Counter starts at 0 */
    status = ez80_emulator_wdt_get_counter(&emu, &counter_before);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_active: get counter before");
    ASSERT_EQ_INT(0u, counter_before, "wdt_active: counter=0 before run");

    /* Run some cycles in active (non-sleep) mode */
    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_active: run_cycles");

    /* WDT should not have fired (timeout=60000 >> cycles executed) */
    ASSERT_EQ_U32(0u, emu.hw.wdt_reset_count, "wdt_active: no reset yet");

    /* Counter must have advanced from 0 */
    status = ez80_emulator_wdt_get_counter(&emu, &counter_after);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt_active: get counter after");
    ASSERT_TRUE(counter_after > counter_before,
                "wdt_active: counter increased after running cycles");

    remove(rom_path);
}

