/* ── 1. LCD get_pixel: OOB coordinates return EZ80_ERR_OUT_OF_BOUNDS ─────── */
static void test_pass42_lcd_pixel_oob(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    uint16_t        pixel = 0xFFFFu;

    printf("[TEST] Pass42: LCD get_pixel out-of-bounds returns error\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-oob: init");

    /* x == 320 (one past the last valid column 319) */
    status = ez80_emulator_lcd_get_pixel(&emu, 320u, 0u, &pixel);
    ASSERT_TRUE(status != EZ80_OK, "lcd-oob: x=320 returns error");

    /* y == 240 (one past the last valid row 239) */
    status = ez80_emulator_lcd_get_pixel(&emu, 0u, 240u, &pixel);
    ASSERT_TRUE(status != EZ80_OK, "lcd-oob: y=240 returns error");

    /* Both out of bounds */
    status = ez80_emulator_lcd_get_pixel(&emu, 320u, 240u, &pixel);
    ASSERT_TRUE(status != EZ80_OK, "lcd-oob: x=320 y=240 returns error");

    /* Large coordinates */
    status = ez80_emulator_lcd_get_pixel(&emu, 1000u, 1000u, &pixel);
    ASSERT_TRUE(status != EZ80_OK, "lcd-oob: x=1000 y=1000 returns error");

    /* In-bounds coordinates: (0, 0) must succeed */
    status = ez80_emulator_lcd_get_pixel(&emu, 0u, 0u, &pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-oob: (0,0) ok");

    /* In-bounds: last valid pixel (319, 239) */
    status = ez80_emulator_lcd_get_pixel(&emu, 319u, 239u, &pixel);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-oob: (319,239) ok");
}

/* ── 2. RTC alarm: disable before tick prevents fire ─────────────────────── */
static void test_pass42_rtc_alarm_disable_before_tick(void)
{
    ez80_emulator_t   emu;
    ez80_status_t     status;
    ez80_run_result_t result;
    bool              fired = false;

    printf("[TEST] Pass42: RTC alarm disabled before tick does not fire\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc-dis: init");

    emu.rom_loaded               = true;
    emu.cpu.pc                   = TEST_RAM_EXEC_BASE;
    emu.cpu.sp                   = TEST_RAM_EXEC_BASE + 0x1000u;
    emu.hw.rtc_cycle_accumulator = 0u;
    emu.hw.rtc_seconds_of_day    = 0u;

    /* Set alarm at 1 second */
    status = ez80_emulator_rtc_alarm_set(&emu, 0u, 0u, 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc-dis: set alarm 1s");

    /* Enable alarm */
    emu.hw.rtc_alarm_control |= EZ80_RTC_ALARM_CONTROL_IRQ_ENABLE;
    status = ez80_emulator_rtc_alarm_enable(&emu, true);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc-dis: enable");
    ASSERT_TRUE(emu.hw.rtc_alarm_control & EZ80_RTC_ALARM_CONTROL_ENABLE, "rtc-dis: enabled flag set");

    /* Immediately disable before any cycles run */
    status = ez80_emulator_rtc_alarm_enable(&emu, false);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc-dis: disable");
    ASSERT_TRUE(!(emu.hw.rtc_alarm_control & EZ80_RTC_ALARM_CONTROL_ENABLE), "rtc-dis: enabled flag cleared");

    /* Run 32768 cycles (one full RTC tick) in standby */
    status = ez80_emulator_pm_set_mode(&emu, EZ80_PM_MODE_STANDBY);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc-dis: standby mode");

    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 32768u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc-dis: run_cycles ok");

    /* Alarm must NOT have fired */
    status = ez80_emulator_rtc_alarm_get_status(&emu, &fired);
    ASSERT_EQ_INT(EZ80_OK, status, "rtc-dis: get_status ok");
    ASSERT_TRUE(!fired, "rtc-dis: alarm did NOT fire after disable");
    ASSERT_EQ_U32(0u, emu.hw.rtc_alarm_fire_count, "rtc-dis: fire_count = 0");
}

/* ── 3. SPI ch1 reset leaves ch0 state intact ────────────────────────────── */
static void test_pass42_spi_ch1_reset_ch0_unaffected(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    uint8_t         rx = 0u;

    printf("[TEST] Pass42: SPI ch1 reset does not corrupt ch0 state\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: init");

    /* Configure and use ch0 */
    status = ez80_emulator_spi_configure(&emu, 0u,
                                          EZ80_SPI_CONTROL_ENABLE |
                                          EZ80_SPI_CONTROL_MASTER,
                                          4u);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: ch0 configure");

    /* Preload ch0 RX FIFO with a known byte */
    status = ez80_emulator_spi_load_rx(&emu, 0u, 0xA5u);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: ch0 load_rx");
    ASSERT_EQ_INT(1, (int)emu.hw.spi[0].rx_source_count, "spi-iso: ch0 source_count=1");

    /* Perform 3 transfers on ch0 */
    status = ez80_emulator_spi_transfer(&emu, 0u, 0x01u, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: ch0 transfer 1");
    status = ez80_emulator_spi_transfer(&emu, 0u, 0x02u, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: ch0 transfer 2");
    status = ez80_emulator_spi_transfer(&emu, 0u, 0x03u, &rx);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: ch0 transfer 3");
    ASSERT_EQ_U32(3u, emu.hw.spi[0].transfer_complete_count,
                  "spi-iso: ch0 transfer_complete_count=3 before ch1 reset");
    ASSERT_EQ_U32(3u, emu.hw.spi[0].total_tx_bytes,
                  "spi-iso: ch0 total_tx_bytes=3 before ch1 reset");

    /* Configure ch1 with some data */
    status = ez80_emulator_spi_configure(&emu, 1u,
                                          EZ80_SPI_CONTROL_ENABLE |
                                          EZ80_SPI_CONTROL_MASTER,
                                          2u);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: ch1 configure");
    ez80_emulator_spi_load_rx(&emu, 1u, 0xBBu);

    /* Reset ch1 */
    status = ez80_emulator_spi_configure(&emu, 1u, EZ80_SPI_CONTROL_RESET, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-iso: ch1 reset");
    ASSERT_EQ_INT(0, (int)emu.hw.spi[1].rx_source_count, "spi-iso: ch1 rx_source cleared");

    /* Ch0 must be completely unchanged */
    ASSERT_EQ_U32(3u, emu.hw.spi[0].transfer_complete_count,
                  "spi-iso: ch0 transfer_count unaffected by ch1 reset");
    ASSERT_EQ_U32(3u, emu.hw.spi[0].total_tx_bytes,
                  "spi-iso: ch0 total_tx_bytes unaffected by ch1 reset");
    ASSERT_EQ_INT(0x03, (int)emu.hw.spi[0].last_tx_byte,
                  "spi-iso: ch0 last_tx_byte=0x03 unaffected");
    /* ch0 control register still configured (not reset) */
    ASSERT_TRUE((emu.hw.spi[0].control & EZ80_SPI_CONTROL_ENABLE) != 0u,
                "spi-iso: ch0 still enabled after ch1 reset");
}

/* ── 4. DMA word-mode fill: all destinations get the same 2-byte fill ──────  */
static void test_pass42_dma_word_fill_dst_pattern(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    uint8_t         st  = 0u;
    uint32_t        bt  = 0u;
    uint32_t        src, dst, i;

    printf("[TEST] Pass42: DMA word-mode fill copies same 2 bytes to all destinations\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "dma-wfill: init");
    emu.rom_loaded = true;

    src = EZ80_RAM_BASE + 0x20000u;
    dst = EZ80_RAM_BASE + 0x21000u;

    /* Write 2-byte fill value {0xBE, 0xEF} at src */
    ez80_memory_write8(&emu, src,     0xBEu);
    ez80_memory_write8(&emu, src + 1, 0xEFu);

    /* Configure DMA ch0: word fill mode (DST_INC, no SRC_INC, WORD_MODE), len=8 bytes (4 words) */
    status = ez80_emulator_dma_configure(&emu, 0u, src, dst, 8u,
                                          EZ80_DMA_CONTROL_ENABLE    |
                                          EZ80_DMA_CONTROL_DST_INC   |
                                          EZ80_DMA_CONTROL_WORD_MODE);
    ASSERT_EQ_INT(EZ80_OK, status, "dma-wfill: configure");

    status = ez80_emulator_dma_start(&emu, 0u);
    ASSERT_EQ_INT(EZ80_OK, status, "dma-wfill: start");

    status = ez80_emulator_dma_get_status(&emu, 0u, &st, &bt);
    ASSERT_EQ_INT(EZ80_OK, status, "dma-wfill: get_status");
    ASSERT_EQ_U32(8u, bt, "dma-wfill: transferred 8 bytes");

    /* All 4 word positions in dst should have {0xBE, 0xEF} */
    for (i = 0u; i < 4u; i++) {
        uint8_t lo = 0u, hi = 0u;
        ez80_memory_read8(&emu, dst + i * 2u,     &lo);
        ez80_memory_read8(&emu, dst + i * 2u + 1, &hi);
        ASSERT_EQ_INT(0xBE, (int)lo, "dma-wfill: dst word lo = 0xBE");
        ASSERT_EQ_INT(0xEF, (int)hi, "dma-wfill: dst word hi = 0xEF");
    }
}

/* ── 5. GPIO: drive_input with mask=0xFF drives all 8 bits ──────────────── */
static void test_pass42_gpio_full_byte_input_drive(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    uint8_t         val = 0u;

    printf("[TEST] Pass42: GPIO drive_input with mask=0xFF drives all bits\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: init");

    /* Set port 0 (A) as all-input */
    status = ez80_emulator_gpio_set_direction(&emu, 0u, 0x00u);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: set all-input direction");

    /* Drive all 8 bits high (value=0xFF, mask=0xFF) */
    status = ez80_emulator_gpio_drive_input(&emu, 0u, 0xFFu, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: drive 0xFF mask=0xFF");

    status = ez80_emulator_gpio_read(&emu, 0u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: read after full drive");
    ASSERT_EQ_INT(0xFF, (int)val, "gpio-full: all bits driven high = 0xFF");

    /* Drive alternating pattern 0x55 with full mask */
    status = ez80_emulator_gpio_drive_input(&emu, 0u, 0x55u, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: drive 0x55 mask=0xFF");

    status = ez80_emulator_gpio_read(&emu, 0u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: read 0x55 pattern");
    ASSERT_EQ_INT(0x55, (int)val, "gpio-full: alternating pattern 0x55");

    /* Drive 0xAA (complement pattern) */
    status = ez80_emulator_gpio_drive_input(&emu, 0u, 0xAAu, 0xFFu);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: drive 0xAA mask=0xFF");

    status = ez80_emulator_gpio_read(&emu, 0u, &val);
    ASSERT_EQ_INT(EZ80_OK, status, "gpio-full: read 0xAA pattern");
    ASSERT_EQ_INT(0xAA, (int)val, "gpio-full: complement pattern 0xAA");
}

/* ── 6. UART ch0 and ch1: independent RX FIFOs ──────────────────────────── */
static void test_pass42_uart_ch0_ch1_rx_independence(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    uint8_t preload0[] = { 0x11u, 0x22u, 0x33u };
    uint8_t preload1[] = { 0xAAu, 0xBBu };
    uint8_t data = 0u;

    printf("[TEST] Pass42: UART ch0 RX drain does not affect ch1 RX FIFO\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: init");

    /* Configure both channels */
    ez80_emulator_uart_configure(&emu, 0u, 0x03u, 12u);
    ez80_emulator_uart_configure(&emu, 1u, 0x07u, 24u);

    /* Load 3 bytes into ch0, 2 bytes into ch1 */
    status = ez80_emulator_uart_load_rx(&emu, 0u, preload0, 3u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: ch0 load_rx 3 bytes");
    status = ez80_emulator_uart_load_rx(&emu, 1u, preload1, 2u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: ch1 load_rx 2 bytes");

    ASSERT_EQ_INT(3, (int)emu.hw.uart[0].rx_count, "uart-rxind: ch0 rx_count=3");
    ASSERT_EQ_INT(2, (int)emu.hw.uart[1].rx_count, "uart-rxind: ch1 rx_count=2");

    /* Drain ch0 completely (read all 3 bytes) */
    status = ez80_emulator_uart_read(&emu, 0u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: ch0 read #1");
    ASSERT_EQ_INT(0x11, (int)data, "uart-rxind: ch0 byte[0]=0x11");

    status = ez80_emulator_uart_read(&emu, 0u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: ch0 read #2");
    ASSERT_EQ_INT(0x22, (int)data, "uart-rxind: ch0 byte[1]=0x22");

    status = ez80_emulator_uart_read(&emu, 0u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: ch0 read #3");
    ASSERT_EQ_INT(0x33, (int)data, "uart-rxind: ch0 byte[2]=0x33");

    /* ch0 FIFO now empty; ch1 must still have 2 bytes */
    ASSERT_EQ_INT(0, (int)emu.hw.uart[0].rx_count, "uart-rxind: ch0 empty after drain");
    ASSERT_EQ_INT(2, (int)emu.hw.uart[1].rx_count, "uart-rxind: ch1 still 2 bytes");

    /* Read ch1 bytes — must match preloaded values */
    status = ez80_emulator_uart_read(&emu, 1u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: ch1 read #1");
    ASSERT_EQ_INT(0xAA, (int)data, "uart-rxind: ch1 byte[0]=0xAA");

    status = ez80_emulator_uart_read(&emu, 1u, &data);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-rxind: ch1 read #2");
    ASSERT_EQ_INT(0xBB, (int)data, "uart-rxind: ch1 byte[1]=0xBB");

    ASSERT_EQ_INT(0, (int)emu.hw.uart[1].rx_count, "uart-rxind: ch1 empty after drain");
}

/* ── 7. I2C: read one preloaded byte; second read from empty FIFO errors ── */
static void test_pass42_i2c_preloaded_then_empty_read(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    uint8_t preload[] = { 0xC3u };
    uint8_t data = 0u;
    uint8_t sr   = 0u;

    printf("[TEST] Pass42: I2C read preloaded byte then attempt second read on empty FIFO\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c-empty: init");

    ez80_emulator_i2c_configure(&emu, 0u, EZ80_I2C_CTL_ENAB, 0x04u);

    /* Preload exactly 1 byte */
    status = ez80_emulator_i2c_load_rx(&emu, 0u, preload, 1u);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c-empty: load_rx 1 byte");

    /* Start a read transaction */
    status = ez80_emulator_i2c_start(&emu, 0u, 0x30u, true);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c-empty: start read");

    /* First read: must succeed and return 0xC3 */
    status = ez80_emulator_i2c_read(&emu, 0u, &data, true);
    ASSERT_EQ_INT(EZ80_OK, status, "i2c-empty: first read ok");
    ASSERT_EQ_INT(0xC3, (int)data, "i2c-empty: first byte = 0xC3");

    /* Second read: FIFO is now empty — should NOT succeed normally */
    data   = 0u;
    status = ez80_emulator_i2c_read(&emu, 0u, &data, true);
    /* Either returns an error or returns 0xFF (phantom/empty byte) */
    ASSERT_TRUE(status != EZ80_OK || data == 0xFFu,
                "i2c-empty: empty FIFO read fails or returns 0xFF");

    /* Cumulative RX counter should only reflect the 1 preloaded byte that was consumed */
    ASSERT_EQ_U32(1u, emu.hw.i2c[0].total_rx_bytes,
                  "i2c-empty: total_rx_bytes=1 after one successful read");

    /* Stop and verify idle */
    ez80_emulator_i2c_stop(&emu, 0u);
    ez80_emulator_i2c_get_status(&emu, 0u, &sr);
    ASSERT_EQ_INT(EZ80_I2C_SR_IDLE, sr, "i2c-empty: idle after stop");
}

/* ── 8. SPI ch0 and ch1 transfer counts are independent ─────────────────── */
static void test_pass42_spi_ch0_ch1_count_independence(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;
    uint8_t rx = 0u;
    uint32_t i;

    printf("[TEST] Pass42: SPI ch0 and ch1 transfer_complete_count are independent\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "spi-cnt: init");

    /* Configure both channels */
    ez80_emulator_spi_configure(&emu, 0u,
                                 EZ80_SPI_CONTROL_ENABLE | EZ80_SPI_CONTROL_MASTER, 4u);
    ez80_emulator_spi_configure(&emu, 1u,
                                 EZ80_SPI_CONTROL_ENABLE | EZ80_SPI_CONTROL_MASTER, 8u);

    /* Both start at 0 */
    ASSERT_EQ_U32(0u, emu.hw.spi[0].transfer_complete_count, "spi-cnt: ch0 starts at 0");
    ASSERT_EQ_U32(0u, emu.hw.spi[1].transfer_complete_count, "spi-cnt: ch1 starts at 0");

    /* 5 transfers on ch0 only */
    for (i = 0u; i < 5u; i++) {
        ez80_emulator_spi_transfer(&emu, 0u, (uint8_t)(0x10u + i), &rx);
    }
    ASSERT_EQ_U32(5u, emu.hw.spi[0].transfer_complete_count, "spi-cnt: ch0 count=5");
    ASSERT_EQ_U32(0u, emu.hw.spi[1].transfer_complete_count, "spi-cnt: ch1 still 0");

    /* 3 transfers on ch1 only */
    for (i = 0u; i < 3u; i++) {
        ez80_emulator_spi_transfer(&emu, 1u, (uint8_t)(0x20u + i), &rx);
    }
    ASSERT_EQ_U32(5u, emu.hw.spi[0].transfer_complete_count, "spi-cnt: ch0 still 5");
    ASSERT_EQ_U32(3u, emu.hw.spi[1].transfer_complete_count, "spi-cnt: ch1 count=3");

    /* Totals also independent */
    ASSERT_EQ_U32(5u, emu.hw.spi[0].total_tx_bytes, "spi-cnt: ch0 tx_bytes=5");
    ASSERT_EQ_U32(3u, emu.hw.spi[1].total_tx_bytes, "spi-cnt: ch1 tx_bytes=3");
    ASSERT_EQ_U32(5u, emu.hw.spi[0].total_rx_bytes, "spi-cnt: ch0 rx_bytes=5");
    ASSERT_EQ_U32(3u, emu.hw.spi[1].total_rx_bytes, "spi-cnt: ch1 rx_bytes=3");

    /* Last TX bytes differ */
    ASSERT_EQ_INT(0x14, (int)emu.hw.spi[0].last_tx_byte, "spi-cnt: ch0 last_tx=0x14");
    ASSERT_EQ_INT(0x22, (int)emu.hw.spi[1].last_tx_byte, "spi-cnt: ch1 last_tx=0x22");
}

/* ── 9. UART ch1 lctl and brg independent from ch0 ──────────────────────── */
static void test_pass42_uart_ch1_lctl_brg_independent(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;

    printf("[TEST] Pass42: UART ch1 lctl/brg independent from ch0 configuration\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-ch1: init");

    /* Configure ch0: 8N1, baud divisor=12 */
    status = ez80_emulator_uart_configure(&emu, 0u, 0x03u, 12u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-ch1: ch0 configure");
    ASSERT_EQ_INT(0x03u, (int)emu.hw.uart[0].lctl, "uart-ch1: ch0 lctl=0x03");
    ASSERT_EQ_INT(12u,   (int)emu.hw.uart[0].brg,  "uart-ch1: ch0 brg=12");

    /* Configure ch1: 7E1, baud divisor=48 */
    status = ez80_emulator_uart_configure(&emu, 1u, 0x1Au, 48u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-ch1: ch1 configure");
    ASSERT_EQ_INT(0x1Au, (int)emu.hw.uart[1].lctl, "uart-ch1: ch1 lctl=0x1A");
    ASSERT_EQ_INT(48u,   (int)emu.hw.uart[1].brg,  "uart-ch1: ch1 brg=48");

    /* ch0 must be unchanged after ch1 configure */
    ASSERT_EQ_INT(0x03u, (int)emu.hw.uart[0].lctl, "uart-ch1: ch0 lctl unchanged");
    ASSERT_EQ_INT(12u,   (int)emu.hw.uart[0].brg,  "uart-ch1: ch0 brg unchanged");

    /* Reconfigure ch1 with different baud rate */
    status = ez80_emulator_uart_configure(&emu, 1u, 0x1Au, 96u);
    ASSERT_EQ_INT(EZ80_OK, status, "uart-ch1: ch1 reconfigure brg=96");
    ASSERT_EQ_INT(96u,   (int)emu.hw.uart[1].brg, "uart-ch1: ch1 brg=96");

    /* ch0 brg must still be 12 */
    ASSERT_EQ_INT(12u,   (int)emu.hw.uart[0].brg, "uart-ch1: ch0 brg still 12 after ch1 reconf");

    /* Write a byte to ch0: ch1 TX FIFO must remain empty */
    {
        uint8_t data = 0u;
        status = ez80_emulator_uart_write(&emu, 0u, 0x41u);
        ASSERT_EQ_INT(EZ80_OK, status, "uart-ch1: ch0 write ok");
        /* ch1 tx_count must remain 0 */
        ASSERT_EQ_INT(0, (int)emu.hw.uart[1].tx_count, "uart-ch1: ch1 tx_count=0 after ch0 write");
        /* ch0 has 1 pending byte */
        ASSERT_EQ_INT(1, (int)emu.hw.uart[0].tx_count, "uart-ch1: ch0 tx_count=1");
        (void)data;
    }
}

/* ── 10. WDT: disabled state — counter stays 0 after run_cycles ──────────── */
static void test_pass42_wdt_disabled_counter_zero(void)
{
    ez80_emulator_t   emu;
    ez80_status_t     status;
    ez80_run_result_t result;
    uint16_t          counter = 0xFFFFu;
    uint8_t           nops[102];
    uint32_t          i;
    char              rom_path[L_tmpnam];

    /* Build NOP sled + HALT for execution */
    for (i = 0u; i < 100u; i++) {
        nops[i] = 0x00u; /* NOP */
    }
    nops[100] = 0x76u; /* HALT */
    nops[101] = 0x00u;

    printf("[TEST] Pass42: WDT disabled — counter remains 0 after run_cycles\n");

    ASSERT_TRUE(write_temp_file(nops, sizeof(nops), rom_path, sizeof(rom_path)),
                "wdt-dis: write ROM");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt-dis: init");

    status = ez80_emulator_load_rom(&emu, rom_path);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt-dis: load rom");

    /* Configure WDT with control=0 (disabled) */
    status = ez80_emulator_wdt_configure(&emu, 0u, 10000u);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt-dis: configure disabled");
    ASSERT_TRUE((emu.hw.wdt_control & EZ80_WDT_CONTROL_ENABLE) == 0u,
                "wdt-dis: WDT_ENABLE bit cleared");

    /* Counter should be 0 before run */
    status = ez80_emulator_wdt_get_counter(&emu, &counter);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt-dis: get_counter before run");
    ASSERT_EQ_INT(0u, (int)counter, "wdt-dis: counter=0 before run");

    /* Run cycles in active mode */
    memset(&result, 0, sizeof(result));
    status = ez80_emulator_run_cycles(&emu, 200u, &result);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt-dis: run_cycles");

    /* WDT disabled → counter must still be 0 */
    status = ez80_emulator_wdt_get_counter(&emu, &counter);
    ASSERT_EQ_INT(EZ80_OK, status, "wdt-dis: get_counter after run");
    ASSERT_EQ_INT(0u, (int)counter, "wdt-dis: disabled WDT counter stays 0");

    /* No watchdog resets should have occurred */
    ASSERT_EQ_U32(0u, emu.hw.wdt_reset_count, "wdt-dis: no WDT resets");

    remove(rom_path);
}

/* ═══════════════════════════════════════════════════════════════════════════
 * Pass 50: Emulator-vs-hardware parity proof
 *   Enter-path stability, keypad fidelity, LCD/visual fidelity,
 *   archive↔RAM behavior
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * Key-code encoding: key_code = (group_index << 3) | bit_position
 *   where group maps to CE sdk kb_Data[] group index (1-7).
 *
 *   Digits:
 *     0 = group3 bit0 = 0x18   1 = group3 bit1 = 0x19
 *     2 = group4 bit1 = 0x21   3 = group5 bit1 = 0x29
 *     4 = group3 bit2 = 0x1A   5 = group4 bit2 = 0x22
 *     6 = group5 bit2 = 0x2A   7 = group3 bit3 = 0x1B
 *     8 = group4 bit3 = 0x23   9 = group5 bit3 = 0x2B
 *   Decimal point = group4 bit0 = 0x20
 *   Chs (negate)  = group5 bit0 = 0x28
 *   LParen = group4 bit4 = 0x24   RParen = group5 bit4 = 0x2C
 *   Operators:
 *     Enter = group6 bit0 = 0x30   Add   = group6 bit1 = 0x31
 *     Sub   = group6 bit2 = 0x32   Mul   = group6 bit3 = 0x33
 *     Div   = group6 bit4 = 0x34   Power = group6 bit5 = 0x35
 *     Clear = group6 bit6 = 0x36
 *   Navigation:
 *     Down = group7 bit0 = 0x38   Left  = group7 bit1 = 0x39
 *     Right= group7 bit2 = 0x3A   Up    = group7 bit3 = 0x3B
 *   Modifiers:
 *     2nd  = group1 bit0 = 0x08   Alpha = group2 bit5 = 0x15
 */

/* Helper: write expression string to homescreen at current cursor position */
static void enterpath_putstr(ez80_emulator_t *emu, const char *s)
{
    while (*s) {
        ez80_emulator_bcall(emu, EZ80_BCALL_HOME_PUTC, (uint32_t)(uint8_t)*s, 0u, 0u, 0u, NULL);
        s++;
    }
}

/* ── 1. Enter-path: 2+3 → 5 ─────────────────────────────────────────────── */
static void test_pass50_enterpath_simple_addition(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;

    printf("[TEST] Pass50: enter-path 2+3=5 homescreen simulation\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-add: init");

    /* Clear homescreen, write input expression on row 0 */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "2+3");

    /* Verify input line before Enter */
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-add: state before enter");
    ASSERT_TRUE(state.homescreen_active, "ep-add: homescreen active before enter");
    ASSERT_EQ_INT(0, state.cursor_row, "ep-add: cursor on row 0 before enter");
    ASSERT_EQ_INT(3, state.cursor_col, "ep-add: cursor col=3 after typing 2+3");
    ASSERT_TRUE(strncmp(state.input_line, "2+3", 3u) == 0,
                "ep-add: input_line = '2+3' before enter");
    ASSERT_EQ_INT(0, state.step_line_count, "ep-add: no prior step lines");

    /* Inject Enter key (group6 bit0 = 0x30) */
    status = ez80_emulator_inject_key(&emu, 0x30u);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-add: inject Enter key");
    /* Enter key is registered: row6 bit0 should be cleared */
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x01u) == 0u,
                "ep-add: row6 bit0 cleared after Enter inject");

    /* Release Enter */
    status = ez80_emulator_release_key(&emu, 0x30u);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-add: release Enter key");
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x01u) != 0u,
                "ep-add: row6 bit0 restored after Enter release");

    /* Simulate: evaluation done, advance to row 1, write result "5" */
    emu.os.home_row = 1u;
    emu.os.home_col = 0u;
    enterpath_putstr(&emu, "5");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-add: state with result");
    ASSERT_EQ_INT(1, state.cursor_row, "ep-add: cursor advances to row 1 for result");
    ASSERT_EQ_INT(1, state.cursor_col, "ep-add: cursor col=1 after writing '5'");
    ASSERT_EQ_INT(1, state.step_line_count, "ep-add: one step line (the expression)");
    ASSERT_TRUE(strncmp(state.step_lines[0], "2+3", 3u) == 0,
                "ep-add: step_lines[0] = expression");
    ASSERT_TRUE(strncmp(state.input_line, "5", 1u) == 0,
                "ep-add: input_line = result '5'");

    /* Advance to row 2 — return to prompt */
    emu.os.home_row = 2u;
    emu.os.home_col = 0u;
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-add: state at return-to-prompt");
    ASSERT_EQ_INT(2, state.cursor_row, "ep-add: cursor at row 2 for new prompt");
    ASSERT_EQ_INT(2, state.step_line_count, "ep-add: two step lines after return to prompt");
    ASSERT_TRUE(strncmp(state.step_lines[1], "5", 1u) == 0,
                "ep-add: step_lines[1] = result line");
    /* input_line for blank prompt row should be empty */
    ASSERT_TRUE(state.input_line[0] == '\0' || state.input_line[0] == ' ',
                "ep-add: input_line empty at new prompt row");
}

/* ── 2. Enter-path: expression battery (6*7, -5+10, 3.14*2) ─────────────── */
static void test_pass50_enterpath_expression_battery(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;
    char                     line[EZ80_HOME_COLS + 1u];

    printf("[TEST] Pass50: enter-path expression battery (6*7, -5+10, 3.14*2)\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: init");

    /* ── Expression 1: 6*7 ── */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "6*7");

    /* Inject Mul key (group6 bit3 = 0x33 is Mul, already in string above) */
    /* Inject Enter */
    status = ez80_emulator_inject_key(&emu, 0x30u); /* Enter */
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: 6*7 Enter inject");
    ez80_emulator_release_key(&emu, 0x30u);

    emu.os.home_row = 1u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "42");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: 6*7 state");
    ASSERT_TRUE(strncmp(state.step_lines[0], "6*7", 3u) == 0,
                "ep-bat: 6*7 step line");
    ASSERT_TRUE(strncmp(state.input_line, "42", 2u) == 0,
                "ep-bat: 6*7 result");

    /* Verify via home_get_line */
    status = ez80_emulator_home_get_line(&emu, 0u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: 6*7 home_get_line row0");
    ASSERT_TRUE(strncmp(line, "6*7", 3u) == 0, "ep-bat: 6*7 home_get_line matches");

    /* ── Expression 2: -5+10 ── */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "-5+10");

    status = ez80_emulator_inject_key(&emu, 0x30u);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: -5+10 Enter inject");
    ez80_emulator_release_key(&emu, 0x30u);

    emu.os.home_row = 1u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "5");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: -5+10 state");
    ASSERT_TRUE(strncmp(state.step_lines[0], "-5+10", 5u) == 0,
                "ep-bat: -5+10 step line");
    ASSERT_TRUE(strncmp(state.input_line, "5", 1u) == 0,
                "ep-bat: -5+10 result");

    /* ── Expression 3: 3.14*2 ── */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "3.14*2");

    status = ez80_emulator_inject_key(&emu, 0x30u);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: 3.14*2 Enter inject");
    ez80_emulator_release_key(&emu, 0x30u);

    emu.os.home_row = 1u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "6.28");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-bat: 3.14*2 state");
    ASSERT_TRUE(strncmp(state.step_lines[0], "3.14*2", 6u) == 0,
                "ep-bat: 3.14*2 step line");
    ASSERT_TRUE(strncmp(state.input_line, "6.28", 4u) == 0,
                "ep-bat: 3.14*2 result");
}

/* ── 3. Enter-path: paren and power expressions ─────────────────────────── */
static void test_pass50_enterpath_paren_and_power(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;

    printf("[TEST] Pass50: enter-path (4+5)*3 and 2^8 simulation\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-pwr: init");

    /* ── (4+5)*3 ── */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "(4+5)*3");

    status = ez80_emulator_inject_key(&emu, 0x30u); /* Enter */
    ASSERT_EQ_INT(EZ80_OK, status, "ep-pwr: (4+5)*3 Enter inject");
    ez80_emulator_release_key(&emu, 0x30u);

    emu.os.home_row = 1u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "27");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-pwr: (4+5)*3 state");
    ASSERT_TRUE(strncmp(state.step_lines[0], "(4+5)*3", 7u) == 0,
                "ep-pwr: (4+5)*3 step line");
    ASSERT_TRUE(strncmp(state.input_line, "27", 2u) == 0,
                "ep-pwr: (4+5)*3 result");
    ASSERT_EQ_INT(1, state.step_line_count, "ep-pwr: (4+5)*3 one step");

    /* ── 2^8 ── */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "2^8");

    /* Inject Power key (group6 bit5 = 0x35) to verify matrix state */
    status = ez80_emulator_inject_key(&emu, 0x35u);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-pwr: inject Power key for matrix check");
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x20u) == 0u,
                "ep-pwr: row6 bit5 cleared for Power key");
    ez80_emulator_release_key(&emu, 0x35u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x20u) != 0u,
                "ep-pwr: row6 bit5 restored after release");

    /* Now inject Enter to complete the sequence */
    ez80_emulator_inject_key(&emu, 0x30u);
    ez80_emulator_release_key(&emu, 0x30u);

    emu.os.home_row = 1u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "256");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-pwr: 2^8 state");
    ASSERT_TRUE(strncmp(state.step_lines[0], "2^8", 3u) == 0,
                "ep-pwr: 2^8 step line");
    ASSERT_TRUE(strncmp(state.input_line, "256", 3u) == 0,
                "ep-pwr: 2^8 result");

    /* Advance to row 2 and verify return-to-prompt state */
    emu.os.home_row = 2u; emu.os.home_col = 0u;
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-pwr: return to prompt state");
    ASSERT_EQ_INT(2, state.step_line_count, "ep-pwr: two step lines at prompt");
    ASSERT_EQ_INT(2, state.cursor_row, "ep-pwr: cursor at row 2");
    ASSERT_TRUE(state.visible_lines[0][0] == '2' && state.visible_lines[0][1] == '^',
                "ep-pwr: visible row0 preserved");
    ASSERT_TRUE(state.visible_lines[1][0] == '2' && state.visible_lines[1][1] == '5',
                "ep-pwr: visible row1 has result 256");
}

/* ── 4. Enter-path: divide-by-zero — error string, no crash ─────────────── */
static void test_pass50_enterpath_divide_by_zero(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;

    printf("[TEST] Pass50: enter-path divide-by-zero produces error, no crash\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-dbz: init");

    /* Write the expression "1/0" */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "1/0");

    /* Inject Div key (group6 bit4 = 0x34) for matrix verification */
    status = ez80_emulator_inject_key(&emu, 0x34u);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-dbz: inject Div key");
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x10u) == 0u,
                "ep-dbz: row6 bit4 cleared for Div key");
    ez80_emulator_release_key(&emu, 0x34u);

    /* Inject Enter */
    ez80_emulator_inject_key(&emu, 0x30u);
    ez80_emulator_release_key(&emu, 0x30u);

    /* Simulate: error message written to result row */
    emu.os.home_row = 1u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "ERR:DIV0");

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-dbz: state after error");
    ASSERT_TRUE(state.homescreen_active, "ep-dbz: homescreen still active after error");
    ASSERT_EQ_INT(1, state.step_line_count, "ep-dbz: expression row became step line");
    ASSERT_TRUE(strncmp(state.step_lines[0], "1/0", 3u) == 0,
                "ep-dbz: expression in step_lines");
    ASSERT_TRUE(strncmp(state.input_line, "ERR:DIV0", 8u) == 0,
                "ep-dbz: error string on result row");

    /* Advance to row 2 — return to prompt */
    emu.os.home_row = 2u; emu.os.home_col = 0u;
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-dbz: return-to-prompt state");
    ASSERT_EQ_INT(2, state.cursor_row, "ep-dbz: cursor at row 2 after error recovery");
    ASSERT_EQ_INT(2, state.step_line_count, "ep-dbz: two step lines at prompt after error");
    /* Verify emulator state is fully intact — init, keypad, homescreen all consistent */
    ASSERT_TRUE(emu.initialized, "ep-dbz: emulator still initialized after div-by-zero");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[6], "ep-dbz: all row6 keys fully released");
}

/* ── 5. Enter-path: Clear key clears input, homescreen row stays same ────── */
static void test_pass50_enterpath_clear_key_clears_input(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;

    printf("[TEST] Pass50: enter-path Clear key behavior — input cleared, cursor row preserved\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-clr: init");

    /* Write partial expression */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);
    enterpath_putstr(&emu, "42+");

    /* Verify partial expression visible */
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-clr: state with partial expr");
    ASSERT_TRUE(strncmp(state.input_line, "42+", 3u) == 0,
                "ep-clr: partial expression in input_line");
    ASSERT_EQ_INT(0, state.cursor_row, "ep-clr: cursor on row 0");
    ASSERT_EQ_INT(3, state.cursor_col, "ep-clr: cursor col=3 after 3 chars");

    /* Inject Clear key (group6 bit6 = 0x36) */
    status = ez80_emulator_inject_key(&emu, 0x36u);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-clr: inject Clear key");
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x40u) == 0u,
                "ep-clr: row6 bit6 cleared for Clear key");
    ez80_emulator_release_key(&emu, 0x36u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x40u) != 0u,
                "ep-clr: row6 bit6 restored after Clear release");

    /* Simulate: CalcEngine clears the current input row */
    emu.os.home_col = 0u;
    /* Overwrite row 0 with spaces to clear it, then reset col */
    {
        size_t i;
        for (i = 0u; i < 3u; i++) {
            ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)' ', 0u, 0u, 0u, NULL);
        }
    }
    emu.os.home_col = 0u; /* cursor back to start of same row */

    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "ep-clr: state after clear simulation");
    ASSERT_EQ_INT(0, state.cursor_row, "ep-clr: cursor row unchanged after clear");
    ASSERT_EQ_INT(0, state.step_line_count, "ep-clr: no step lines (still on row 0)");
}

