/* ── 6. Keypad fidelity: digit keys 0-9 encode correct row/col ───────────── */
static void test_pass50_keypad_digit_key_matrix(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;

    printf("[TEST] Pass50: keypad digit keys 0-9 set correct row/col matrix bits\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: init");

    /* Key 0: group3 bit0 = code 0x18 → row3 bit0 */
    status = ez80_emulator_inject_key(&emu, 0x18u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '0'");
    ASSERT_TRUE((emu.hw.keypad_rows[3] & 0x01u) == 0u, "kp-dig: key0 clears row3 bit0");
    ez80_emulator_release_key(&emu, 0x18u);
    ASSERT_TRUE((emu.hw.keypad_rows[3] & 0x01u) != 0u, "kp-dig: key0 release restores row3 bit0");

    /* Key 1: group3 bit1 = code 0x19 → row3 bit1 */
    status = ez80_emulator_inject_key(&emu, 0x19u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '1'");
    ASSERT_TRUE((emu.hw.keypad_rows[3] & 0x02u) == 0u, "kp-dig: key1 clears row3 bit1");
    ez80_emulator_release_key(&emu, 0x19u);

    /* Key 2: group4 bit1 = code 0x21 → row4 bit1 */
    status = ez80_emulator_inject_key(&emu, 0x21u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '2'");
    ASSERT_TRUE((emu.hw.keypad_rows[4] & 0x02u) == 0u, "kp-dig: key2 clears row4 bit1");
    ez80_emulator_release_key(&emu, 0x21u);

    /* Key 3: group5 bit1 = code 0x29 → row5 bit1 */
    status = ez80_emulator_inject_key(&emu, 0x29u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '3'");
    ASSERT_TRUE((emu.hw.keypad_rows[5] & 0x02u) == 0u, "kp-dig: key3 clears row5 bit1");
    ez80_emulator_release_key(&emu, 0x29u);

    /* Key 4: group3 bit2 = code 0x1A → row3 bit2 */
    status = ez80_emulator_inject_key(&emu, 0x1Au);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '4'");
    ASSERT_TRUE((emu.hw.keypad_rows[3] & 0x04u) == 0u, "kp-dig: key4 clears row3 bit2");
    ez80_emulator_release_key(&emu, 0x1Au);

    /* Key 5: group4 bit2 = code 0x22 → row4 bit2 */
    status = ez80_emulator_inject_key(&emu, 0x22u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '5'");
    ASSERT_TRUE((emu.hw.keypad_rows[4] & 0x04u) == 0u, "kp-dig: key5 clears row4 bit2");
    ez80_emulator_release_key(&emu, 0x22u);

    /* Key 6: group5 bit2 = code 0x2A → row5 bit2 */
    status = ez80_emulator_inject_key(&emu, 0x2Au);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '6'");
    ASSERT_TRUE((emu.hw.keypad_rows[5] & 0x04u) == 0u, "kp-dig: key6 clears row5 bit2");
    ez80_emulator_release_key(&emu, 0x2Au);

    /* Key 7: group3 bit3 = code 0x1B → row3 bit3 */
    status = ez80_emulator_inject_key(&emu, 0x1Bu);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '7'");
    ASSERT_TRUE((emu.hw.keypad_rows[3] & 0x08u) == 0u, "kp-dig: key7 clears row3 bit3");
    ez80_emulator_release_key(&emu, 0x1Bu);

    /* Key 8: group4 bit3 = code 0x23 → row4 bit3 */
    status = ez80_emulator_inject_key(&emu, 0x23u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '8'");
    ASSERT_TRUE((emu.hw.keypad_rows[4] & 0x08u) == 0u, "kp-dig: key8 clears row4 bit3");
    ez80_emulator_release_key(&emu, 0x23u);

    /* Key 9: group5 bit3 = code 0x2B → row5 bit3 */
    status = ez80_emulator_inject_key(&emu, 0x2Bu);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject '9'");
    ASSERT_TRUE((emu.hw.keypad_rows[5] & 0x08u) == 0u, "kp-dig: key9 clears row5 bit3");
    ez80_emulator_release_key(&emu, 0x2Bu);

    /* Decimal point: group4 bit0 = code 0x20 → row4 bit0 */
    status = ez80_emulator_inject_key(&emu, 0x20u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject decimal point");
    ASSERT_TRUE((emu.hw.keypad_rows[4] & 0x01u) == 0u, "kp-dig: DecPnt clears row4 bit0");
    ez80_emulator_release_key(&emu, 0x20u);

    /* Chs (negate): group5 bit0 = code 0x28 → row5 bit0 */
    status = ez80_emulator_inject_key(&emu, 0x28u);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-dig: inject Chs");
    ASSERT_TRUE((emu.hw.keypad_rows[5] & 0x01u) == 0u, "kp-dig: Chs clears row5 bit0");
    ez80_emulator_release_key(&emu, 0x28u);

    /* All rows must be fully restored after all releases */
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[3], "kp-dig: row3 fully restored");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[4], "kp-dig: row4 fully restored");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[5], "kp-dig: row5 fully restored");
}

/* ── 7. Keypad fidelity: operator keys row/col encoding ─────────────────── */
static void test_pass50_keypad_operator_key_matrix(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;

    printf("[TEST] Pass50: keypad operator keys (+,-,*,/,^,Enter,Clear,LParen,RParen) matrix\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-op: init");

    /* Enter: group6 bit0 = 0x30 → row6 bit0 */
    ez80_emulator_inject_key(&emu, 0x30u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x01u) == 0u, "kp-op: Enter clears row6 bit0");
    ez80_emulator_release_key(&emu, 0x30u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x01u) != 0u, "kp-op: Enter release restores");

    /* Add: group6 bit1 = 0x31 → row6 bit1 */
    ez80_emulator_inject_key(&emu, 0x31u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x02u) == 0u, "kp-op: Add clears row6 bit1");
    ez80_emulator_release_key(&emu, 0x31u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x02u) != 0u, "kp-op: Add release restores");

    /* Sub: group6 bit2 = 0x32 → row6 bit2 */
    ez80_emulator_inject_key(&emu, 0x32u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x04u) == 0u, "kp-op: Sub clears row6 bit2");
    ez80_emulator_release_key(&emu, 0x32u);

    /* Mul: group6 bit3 = 0x33 → row6 bit3 */
    ez80_emulator_inject_key(&emu, 0x33u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x08u) == 0u, "kp-op: Mul clears row6 bit3");
    ez80_emulator_release_key(&emu, 0x33u);

    /* Div: group6 bit4 = 0x34 → row6 bit4 */
    ez80_emulator_inject_key(&emu, 0x34u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x10u) == 0u, "kp-op: Div clears row6 bit4");
    ez80_emulator_release_key(&emu, 0x34u);

    /* Power: group6 bit5 = 0x35 → row6 bit5 */
    ez80_emulator_inject_key(&emu, 0x35u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x20u) == 0u, "kp-op: Power clears row6 bit5");
    ez80_emulator_release_key(&emu, 0x35u);

    /* Clear: group6 bit6 = 0x36 → row6 bit6 */
    ez80_emulator_inject_key(&emu, 0x36u);
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x40u) == 0u, "kp-op: Clear clears row6 bit6");
    ez80_emulator_release_key(&emu, 0x36u);

    /* LParen: group4 bit4 = 0x24 → row4 bit4 */
    ez80_emulator_inject_key(&emu, 0x24u);
    ASSERT_TRUE((emu.hw.keypad_rows[4] & 0x10u) == 0u, "kp-op: LParen clears row4 bit4");
    ez80_emulator_release_key(&emu, 0x24u);

    /* RParen: group5 bit4 = 0x2C → row5 bit4 */
    ez80_emulator_inject_key(&emu, 0x2Cu);
    ASSERT_TRUE((emu.hw.keypad_rows[5] & 0x10u) == 0u, "kp-op: RParen clears row5 bit4");
    ez80_emulator_release_key(&emu, 0x2Cu);

    /* Verify all operator rows fully restored */
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[4], "kp-op: row4 fully restored");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[5], "kp-op: row5 fully restored");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[6], "kp-op: row6 fully restored");
}

/* ── 8. Keypad fidelity: simultaneous multi-key press and release_all ─────── */
static void test_pass50_keypad_simultaneous_and_release_all(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;

    printf("[TEST] Pass50: keypad simultaneous multi-key press and release_all\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-sim: init");

    /* Press 3 keys from different rows simultaneously */
    ez80_emulator_inject_key(&emu, 0x19u); /* key 1: row3 bit1 */
    ez80_emulator_inject_key(&emu, 0x31u); /* Add:  row6 bit1 */
    ez80_emulator_inject_key(&emu, 0x21u); /* key 2: row4 bit1 */

    ASSERT_TRUE((emu.hw.keypad_rows[3] & 0x02u) == 0u, "kp-sim: key1 row3 bit1 cleared");
    ASSERT_TRUE((emu.hw.keypad_rows[4] & 0x02u) == 0u, "kp-sim: key2 row4 bit1 cleared");
    ASSERT_TRUE((emu.hw.keypad_rows[6] & 0x02u) == 0u, "kp-sim: Add row6 bit1 cleared");

    /* Other rows unaffected */
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[0], "kp-sim: row0 untouched");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[1], "kp-sim: row1 untouched");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[2], "kp-sim: row2 untouched");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[5], "kp-sim: row5 untouched");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[7], "kp-sim: row7 untouched");

    /* Release all — every row must return to 0xFF */
    status = ez80_emulator_release_all_keys(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-sim: release_all_keys status");
    {
        int row;
        for (row = 0; row < 8; row++) {
            ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[row],
                          "kp-sim: row fully restored after release_all");
        }
    }
}

/* ── 9. Keypad fidelity: navigation keys and 2nd/Alpha modifier row/col ───── */
static void test_pass50_keypad_nav_and_modifier_keys(void)
{
    ez80_emulator_t emu;
    ez80_status_t   status;

    printf("[TEST] Pass50: keypad navigation (Up/Down/Left/Right) and modifier (2nd/Alpha) keys\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "kp-nav: init");

    /* Down: group7 bit0 = 0x38 → row7 bit0 */
    ez80_emulator_inject_key(&emu, 0x38u);
    ASSERT_TRUE((emu.hw.keypad_rows[7] & 0x01u) == 0u, "kp-nav: Down clears row7 bit0");
    ez80_emulator_release_key(&emu, 0x38u);
    ASSERT_TRUE((emu.hw.keypad_rows[7] & 0x01u) != 0u, "kp-nav: Down release restores row7 bit0");

    /* Left: group7 bit1 = 0x39 → row7 bit1 */
    ez80_emulator_inject_key(&emu, 0x39u);
    ASSERT_TRUE((emu.hw.keypad_rows[7] & 0x02u) == 0u, "kp-nav: Left clears row7 bit1");
    ez80_emulator_release_key(&emu, 0x39u);

    /* Right: group7 bit2 = 0x3A → row7 bit2 */
    ez80_emulator_inject_key(&emu, 0x3Au);
    ASSERT_TRUE((emu.hw.keypad_rows[7] & 0x04u) == 0u, "kp-nav: Right clears row7 bit2");
    ez80_emulator_release_key(&emu, 0x3Au);

    /* Up: group7 bit3 = 0x3B → row7 bit3 */
    ez80_emulator_inject_key(&emu, 0x3Bu);
    ASSERT_TRUE((emu.hw.keypad_rows[7] & 0x08u) == 0u, "kp-nav: Up clears row7 bit3");
    ez80_emulator_release_key(&emu, 0x3Bu);

    /* 2nd modifier: group1 bit0 = 0x08 → row1 bit0 */
    ez80_emulator_inject_key(&emu, 0x08u);
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x01u) == 0u, "kp-nav: 2nd clears row1 bit0");

    /* Hold 2nd + press Right — both rows modified simultaneously */
    ez80_emulator_inject_key(&emu, 0x3Au);
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x01u) == 0u, "kp-nav: 2nd still held during Right");
    ASSERT_TRUE((emu.hw.keypad_rows[7] & 0x04u) == 0u, "kp-nav: Right also pressed while 2nd held");

    ez80_emulator_release_key(&emu, 0x3Au);
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x01u) == 0u, "kp-nav: 2nd still held after Right release");
    ASSERT_TRUE((emu.hw.keypad_rows[7] & 0x04u) != 0u, "kp-nav: Right released, bit restored");

    ez80_emulator_release_key(&emu, 0x08u);
    ASSERT_TRUE((emu.hw.keypad_rows[1] & 0x01u) != 0u, "kp-nav: 2nd released, bit restored");

    /* Alpha: group2 bit5 = 0x15 → row2 bit5 */
    ez80_emulator_inject_key(&emu, 0x15u);
    ASSERT_TRUE((emu.hw.keypad_rows[2] & 0x20u) == 0u, "kp-nav: Alpha clears row2 bit5");
    ez80_emulator_release_key(&emu, 0x15u);
    ASSERT_TRUE((emu.hw.keypad_rows[2] & 0x20u) != 0u, "kp-nav: Alpha released");

    /* All rows fully restored */
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[1], "kp-nav: row1 fully restored");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[2], "kp-nav: row2 fully restored");
    ASSERT_EQ_INT(0xFF, (int)emu.hw.keypad_rows[7], "kp-nav: row7 fully restored");
}

