/* ── 10. LCD fidelity: cursor col tracks each HOME_PUTC ──────────────────── */
static void test_pass50_lcd_cursor_col_tracks_putc(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;

    printf("[TEST] Pass50: LCD cursor col advances after each HOME_PUTC\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-col: init");

    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);

    /* After HOME_CLEAR, cursor should be at (0,0) */
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-col: state after clear");
    ASSERT_EQ_INT(0, state.cursor_row, "lcd-col: row=0 after clear");
    ASSERT_EQ_INT(0, state.cursor_col, "lcd-col: col=0 after clear");

    /* Write 5 characters, verify col increments each time */
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'x', 0u, 0u, 0u, NULL);
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(0, state.cursor_row, "lcd-col: row=0 after 1 char");
    ASSERT_EQ_INT(1, state.cursor_col, "lcd-col: col=1 after 1 char");

    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'+', 0u, 0u, 0u, NULL);
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(2, state.cursor_col, "lcd-col: col=2 after 2 chars");

    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'y', 0u, 0u, 0u, NULL);
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'=', 0u, 0u, 0u, NULL);
    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_PUTC, (uint32_t)'5', 0u, 0u, 0u, NULL);
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-col: state after 5 chars");
    ASSERT_EQ_INT(0, state.cursor_row, "lcd-col: still row 0 after 5 chars");
    ASSERT_EQ_INT(5, state.cursor_col, "lcd-col: col=5 after 5 chars");

    /* input_line must contain all 5 chars */
    ASSERT_TRUE(strncmp(state.input_line, "x+y=5", 5u) == 0,
                "lcd-col: input_line = x+y=5");
}

/* ── 11. LCD fidelity: visible_lines matches home_get_line per row ────────── */
static void test_pass50_lcd_visible_lines_match_home_get_line(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;
    char                     line[EZ80_HOME_COLS + 1u];

    printf("[TEST] Pass50: LCD visible_lines[] matches ez80_emulator_home_get_line() for each row\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-vis: init");

    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);

    /* Write 3 rows of content */
    emu.os.home_row = 0u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "sin(x)");

    emu.os.home_row = 1u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "0.5");

    emu.os.home_row = 2u; emu.os.home_col = 0u;
    enterpath_putstr(&emu, "DONE");

    /* Get screen state with cursor at row 2 */
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-vis: get screen state");

    /* Cross-check each row: visible_lines vs home_get_line */
    status = ez80_emulator_home_get_line(&emu, 0u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-vis: home_get_line row0");
    ASSERT_TRUE(strncmp(line, "sin(x)", 6u) == 0,
                "lcd-vis: home_get_line row0 = sin(x)");
    ASSERT_TRUE(strncmp(state.visible_lines[0], "sin(x)", 6u) == 0,
                "lcd-vis: visible_lines[0] = sin(x)");
    ASSERT_TRUE(strncmp(line, state.visible_lines[0], 6u) == 0,
                "lcd-vis: visible_lines[0] matches home_get_line row0");

    status = ez80_emulator_home_get_line(&emu, 1u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-vis: home_get_line row1");
    ASSERT_TRUE(strncmp(line, "0.5", 3u) == 0,
                "lcd-vis: home_get_line row1 = 0.5");
    ASSERT_TRUE(strncmp(state.visible_lines[1], "0.5", 3u) == 0,
                "lcd-vis: visible_lines[1] = 0.5");

    status = ez80_emulator_home_get_line(&emu, 2u, line, sizeof(line));
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-vis: home_get_line row2");
    ASSERT_TRUE(strncmp(line, "DONE", 4u) == 0,
                "lcd-vis: home_get_line row2 = DONE");
    ASSERT_TRUE(strncmp(state.input_line, "DONE", 4u) == 0,
                "lcd-vis: input_line = DONE (cursor row)");

    /* Step lines must capture rows 0 and 1 */
    ASSERT_EQ_INT(2, state.step_line_count, "lcd-vis: two step lines");
    ASSERT_TRUE(strncmp(state.step_lines[0], "sin(x)", 6u) == 0,
                "lcd-vis: step_lines[0] = sin(x)");
    ASSERT_TRUE(strncmp(state.step_lines[1], "0.5", 3u) == 0,
                "lcd-vis: step_lines[1] = 0.5");
}

/* ── 12. LCD fidelity: step_lines accumulate prior rows correctly ─────────── */
static void test_pass50_lcd_step_lines_accumulate_correctly(void)
{
    ez80_emulator_t          emu;
    ez80_screen_text_state_t state;
    ez80_status_t            status;
    uint8_t                  r;

    printf("[TEST] Pass50: LCD step_lines accumulate as cursor advances through rows\n");

    status = ez80_emulator_init(&emu);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-step: init");

    ez80_emulator_bcall(&emu, EZ80_BCALL_HOME_CLEAR, 0u, 0u, 0u, 0u, NULL);

    /* Write 5 rows: expr0..expr4 */
    for (r = 0u; r < 5u; r++) {
        char payload[8];
        emu.os.home_row = r;
        emu.os.home_col = 0u;
        payload[0] = 'E'; payload[1] = (char)('0' + r); payload[2] = '\0';
        enterpath_putstr(&emu, payload);
    }

    /* Cursor is now on row 4 */
    status = ez80_emulator_get_screen_text_state(&emu, &state);
    ASSERT_EQ_INT(EZ80_OK, status, "lcd-step: state at row4");
    ASSERT_EQ_INT(4, state.cursor_row,       "lcd-step: cursor at row 4");
    ASSERT_EQ_INT(4, state.step_line_count,  "lcd-step: 4 step lines (rows 0-3)");
    ASSERT_TRUE(strncmp(state.step_lines[0], "E0", 2u) == 0, "lcd-step: step_lines[0]=E0");
    ASSERT_TRUE(strncmp(state.step_lines[1], "E1", 2u) == 0, "lcd-step: step_lines[1]=E1");
    ASSERT_TRUE(strncmp(state.step_lines[2], "E2", 2u) == 0, "lcd-step: step_lines[2]=E2");
    ASSERT_TRUE(strncmp(state.step_lines[3], "E3", 2u) == 0, "lcd-step: step_lines[3]=E3");
    ASSERT_TRUE(strncmp(state.input_line, "E4", 2u) == 0,    "lcd-step: input_line=E4");

    /* visible_lines[0..4] must match */
    ASSERT_TRUE(strncmp(state.visible_lines[0], "E0", 2u) == 0, "lcd-step: visible[0]=E0");
    ASSERT_TRUE(strncmp(state.visible_lines[4], "E4", 2u) == 0, "lcd-step: visible[4]=E4");
}

